def _attachment_hash(attachment: discord.Attachment) -> str:
    raw = f"{attachment.filename}|{attachment.size}|{attachment.content_type or ''}|{attachment.url}"
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


