def _season_get_top3() -> list[tuple[int, int]]:
    ranked = sorted(
        _rsvp_leaderboard.values(),
        key=lambda x: int(x.get("attendance_count", 0)),
        reverse=True,
    )[:3]
    return [(int(e["user_id"]), int(e.get("attendance_count", 0))) for e in ranked]


def _season_build_embed(winners: list[tuple[int, int]], month_label: str) -> discord.Embed:
    medals = ["🥇", "🥈", "🥉"]
    lines = [f"{medals[i]} <@{uid}> — **{score}** meet(s)" for i, (uid, score) in enumerate(winners)]
    embed = discord.Embed(
        title=f"🏁 DIFF Season Results — {month_label}",
        description="\n".join(lines) + "\n\nTop performers of the month. Stay active. Stay consistent.",
        color=discord.Color.gold(),
        timestamp=utc_now(),
    )
    embed.set_footer(text="Different Meets • Monthly Season Results")
    return embed


async def _season_give_rewards(guild: discord.Guild, winners: list[tuple[int, int]]) -> None:
    top_role_ids = [TOP1_ROLE_ID, TOP2_ROLE_ID, TOP3_ROLE_ID]
    all_reward_roles = [guild.get_role(rid) for rid in top_role_ids if rid]

    for i, (uid, _) in enumerate(winners):
        member = guild.get_member(uid)
        if not member:
            continue
        try:
            existing = [r for r in all_reward_roles if r and r in member.roles]
            if existing:
                await member.remove_roles(*existing, reason="DIFF season reset")
        except Exception:
            pass
        role = guild.get_role(top_role_ids[i]) if i < len(top_role_ids) else None
        if role:
            try:
                await member.add_roles(role, reason="DIFF season winner")
            except Exception:
                pass


def _season_reset_attendance() -> None:
    for entry in _rsvp_leaderboard.values():
        entry["last_attendance_count"] = int(entry.get("attendance_count", 0))
        entry["attendance_count"] = 0
    _rsvp_save_all()


async def _season_run(guild: discord.Guild) -> None:
    winners = _season_get_top3()
    if not winners:
        return

    now = datetime.now(timezone.utc)
    month_label = now.strftime("%B %Y")

    post_ch_id = SEASON_CHANNEL_ID or LEADERBOARD_CHANNEL_ID
    post_ch = guild.get_channel(post_ch_id)
    if isinstance(post_ch, discord.TextChannel):
        try:
            await post_ch.send(embed=_season_build_embed(winners, month_label))
        except Exception:
            pass

    await _season_give_rewards(guild, winners)

    await _season_post_ig_content(guild, winners, month_label)

    season_data = _season_load()
    season_data.setdefault("history", []).append({
        "month": month_label,
        "date": now.isoformat(),
        "winners": [{"user_id": uid, "score": score} for uid, score in winners],
    })
    season_data["last_ran_month"] = now.strftime("%Y-%m")
    _season_save(season_data)

    _season_reset_attendance()


async def _season_loop() -> None:
    await bot.wait_until_ready()
    while not bot.is_closed():
        await asyncio.sleep(3600)
        try:
            now = datetime.now(timezone.utc)
            if now.day == 1 and now.hour == 12:
                season_data = _season_load()
                current_month = now.strftime("%Y-%m")
                if season_data.get("last_ran_month") != current_month:
                    guild = bot.get_guild(GUILD_ID)
                    if guild:
                        await _season_run(guild)
        except Exception as e:
            print(f"[Season] Loop error: {e}")


# =========================
# HOST RSVP SYSTEM
# =========================

_HRSVP_FILE = os.path.join("diff_data", "diff_host_rsvp.json")
_HRSVP_DAYS = ["Meet 1", "Meet 2", "Meet 3"]


def _hrsvp_repair_entries(data: dict) -> dict:
    """Convert any string-dict entries back to proper dicts (fixes legacy corruption)."""
    import re as _re
    changed = False
    for day in _HRSVP_DAYS:
        slot = data.get(day, {})
        for key in ("yes", "maybe", "no"):
            fixed = []
            for entry in slot.get(key, []):
                if isinstance(entry, str) and entry.startswith("{"):
                    # Extract fields with regex — handles apostrophes in values
                    uid_m   = _re.search(r"'uid'\s*:\s*'([^']+)'", entry)
                    day_m   = _re.search(r"'day'\s*:\s*'([^']+)'", entry)
                    time_m  = _re.search(r"'time'\s*:\s*'([^']+)'", entry)
                    theme_m = _re.search(r"'theme'\s*:\s*'(.*?)'(?:\s*[,}])", entry)
                    if uid_m:
                        entry = {
                            "uid":   uid_m.group(1),
                            "day":   day_m.group(1)   if day_m   else "TBD",
                            "time":  time_m.group(1)  if time_m  else "TBD",
                            "theme": theme_m.group(1) if theme_m else "TBD",
                        }
                        changed = True
                fixed.append(entry)
            slot[key] = fixed
        data[day] = slot
    if changed:
        _hrsvp_save(data)
    return data


def _hrsvp_load() -> dict:
    if os.path.exists(_HRSVP_FILE):
        try:
            with open(_HRSVP_FILE, "r") as f:
                raw = json.load(f)
            return _hrsvp_repair_entries(raw)
        except Exception:
            pass
    return {day: {"yes": [], "no": [], "maybe": []} for day in _HRSVP_DAYS}


def _hrsvp_save(data: dict) -> None:
    _atomic_json_save(_HRSVP_FILE, data)


def _hrsvp_reset() -> dict:
    prev = _hrsvp_load()
    data = {day: {"yes": [], "no": [], "maybe": []} for day in _HRSVP_DAYS}
    # Preserve the posted layout's message ids so the weekly reset edits the existing
    # cards in place (no duplicate role ping in the panel channel).
    if prev.get("panel_message_ids"):
        data["panel_message_ids"] = prev["panel_message_ids"]
    _hrsvp_save(data)
    return data


def _hrsvp_uid(entry) -> str:
    """Return UID string from either a plain string or a dict entry."""
    return entry if isinstance(entry, str) else entry.get("uid", "")


# ── Host Reliability Tracking ────────────────────────────────────────────────
_HREL_FILE = os.path.join("diff_data", "diff_host_reliability.json")


def _hrel_load() -> dict:
    if os.path.exists(_HREL_FILE):
        try:
            with open(_HREL_FILE) as f:
                return json.load(f)
        except Exception:
            pass
    return {}


def _hrel_save(data: dict) -> None:
    _atomic_json_save(_HREL_FILE, data)


def _hrel_entry(data: dict, uid: str) -> dict:
    return data.setdefault(uid, {
        "rsvp_count": 0, "confirmed_count": 0,
        "last_rsvp": None, "last_confirmed": None,
    })


def _hrel_track_rsvp(uid: str) -> None:
    data = _hrel_load()
    e = _hrel_entry(data, uid)
    e["rsvp_count"] += 1
    e["last_rsvp"] = utc_now().isoformat()
    _hrel_save(data)


def _hrel_track_confirmed(uid: str) -> None:
    data = _hrel_load()
    e = _hrel_entry(data, uid)
    e["confirmed_count"] += 1
    e["last_confirmed"] = utc_now().isoformat()
    _hrel_save(data)


# ── HRSVP weekly auto-reset state ────────────────────────────────────────────
_HRSVP_RESET_FILE = os.path.join("diff_data", "diff_hrsvp_reset.json")


def _hrsvp_reset_ts_load() -> str | None:
    if os.path.exists(_HRSVP_RESET_FILE):
        try:
            with open(_HRSVP_RESET_FILE) as f:
                return json.load(f).get("last_reset")
        except Exception:
            pass
    return None


def _hrsvp_reset_ts_save(date_str: str) -> None:
    _atomic_json_save(_HRSVP_RESET_FILE, {"last_reset": date_str})


def _hrsvp_build_embed() -> discord.Embed:
    data = _hrsvp_load()
    _DIV = "─" * 30

    # ── Week range + reset countdown ─────────────────────────
    from datetime import timedelta as _td
    _now_et = datetime.now(_EST_TZ)
    _monday = _now_et - _td(days=_now_et.weekday())
    _sunday = _monday + _td(days=6)
    _week_str = f"{_monday.strftime('%b %d')} – {_sunday.strftime('%b %d, %Y')}"
    _next_monday = (_monday + _td(days=7)).replace(hour=0, minute=0, second=0, microsecond=0)
    _reset_ts = int(_next_monday.timestamp())
    _now_ts   = int(_now_et.timestamp())

    # ── Response summary counts ───────────────────────────────
    all_responded_uids: set = set()
    for day in _HRSVP_DAYS:
        d = data.get(day, {})
        for bucket in ("yes", "no", "maybe"):
            for e in d.get(bucket, []):
                all_responded_uids.add(_hrsvp_uid(e))
    total_responders = len(all_responded_uids)
    slots_with_host  = sum(1 for day in _HRSVP_DAYS if data.get(day, {}).get("yes", []))
    slots_needed     = len(_HRSVP_DAYS)
    slot_bar         = "🟩" * slots_with_host + "⬜" * (slots_needed - slots_with_host)

    embed = discord.Embed(
        title="📋 DIFF Host Availability — Meet Schedule",
        description=(
            f"📅 **Week of {_week_str}**  •  🔄 Resets <t:{_reset_ts}:R>\n\n"
            f"**Hosts, mark your availability for each meet slot below.**\n\n"
            f"📊 {slot_bar}  **{slots_with_host}/{slots_needed} slots have a confirmed host**\n"
            f"👥 **{total_responders} host{'s' if total_responders != 1 else ''}** have responded so far\n\n"
            "• ✅ **Available** — opens a form for your day, time & class\n"
            "• ❓ **Maybe** — opens a form to note your preferred day\n"
            "• ❌ **Unavailable** — marks you as unable to host\n"
            "• 👤 **My Status** — shows what you've submitted so far\n\n"
            f"{_DIV}"
        ),
        color=0x5865F2,
        timestamp=utc_now(),
    )
    if DIFF_LOGO_URL:
        embed.set_thumbnail(url=DIFF_LOGO_URL)

    for day in _HRSVP_DAYS:
        d             = data.get(day, {"yes": [], "no": [], "maybe": []})
        yes_entries   = d.get("yes", [])
        no_entries    = d.get("no", [])
        maybe_entries = d.get("maybe", [])

        # Slot status badge
        if yes_entries:
            slot_status = f"🟢 **{len(yes_entries)} host{'s' if len(yes_entries) != 1 else ''} available**"
        elif maybe_entries:
            slot_status = f"🟡 **{len(maybe_entries)} maybe** — still needs a host"
        else:
            slot_status = "🔴 **Open — no hosts yet**"

        lines = [slot_status]

        if yes_entries:
            for e in yes_entries:
                uid = _hrsvp_uid(e)
                if isinstance(e, dict):
                    dv = e.get('day', 'TBD')
                    tv = e.get('time', 'TBD')
                    ts = _parse_meet_ts(dv, tv) if not tv.startswith("<t:") else None
                    if ts:
                        when_display = f"<t:{ts}:F>  (<t:{ts}:R>)"
                    elif tv.startswith("<t:"):
                        when_display = tv
                    else:
                        when_display = f"📅 {dv}  🕒 {tv}"
                    lines.append(
                        f"✅ <@{uid}>\n"
                        f"　{when_display}  🎮 {e.get('theme', 'TBD')}"
                    )
                else:
                    lines.append(f"✅ <@{uid}>")
        else:
            lines.append("✅ *No confirmed hosts yet*")

        if maybe_entries:
            for e in maybe_entries:
                uid = _hrsvp_uid(e)
                day_pref = e.get("day", "") if isinstance(e, dict) else ""
                lines.append(f"❓ <@{uid}>" + (f" — prefers {day_pref}" if day_pref else ""))

        if no_entries:
            no_tags = "  ".join(f"<@{_hrsvp_uid(u)}>" for u in no_entries)
            lines.append(f"❌ Unavailable: {no_tags}")

        embed.add_field(name=day, value="\n".join(lines) or "*No responses yet*", inline=False)

    embed.set_footer(text=f"Different Meets • Host Availability  •  Updated {_now_et.strftime('%-m/%-d/%Y %-I:%M %p')}  •  Times shown in your local timezone")
    return embed


# ── Split layout: slim header card + one roomy availability card per meet ───────
def _hrsvp_build_header_embed() -> discord.Embed:
    """Header card: week range, reset countdown, progress + legend. No per-meet lists."""
    data = _hrsvp_load()
    from datetime import timedelta as _td
    _now_et = datetime.now(_EST_TZ)
    _monday = _now_et - _td(days=_now_et.weekday())
    _sunday = _monday + _td(days=6)
    _week_str = f"{_monday.strftime('%b %d')} – {_sunday.strftime('%b %d, %Y')}"
    _next_monday = (_monday + _td(days=7)).replace(hour=0, minute=0, second=0, microsecond=0)
    _reset_ts = int(_next_monday.timestamp())

    all_responded_uids: set = set()
    for day in _HRSVP_DAYS:
        d = data.get(day, {})
        for bucket in ("yes", "no", "maybe"):
            for e in d.get(bucket, []):
                all_responded_uids.add(_hrsvp_uid(e))
    total_responders = len(all_responded_uids)
    slots_with_host  = sum(1 for day in _HRSVP_DAYS if data.get(day, {}).get("yes", []))
    slots_needed     = len(_HRSVP_DAYS)
    slot_bar         = "🟩" * slots_with_host + "⬜" * (slots_needed - slots_with_host)
    slots_open       = slots_needed - slots_with_host
    if slots_open > 0:
        urgency_line = (
            f"⏳ **{slots_open} slot{'s' if slots_open != 1 else ''} still need a host** — "
            f"leadership builds the schedule from your replies, so respond before reset!"
        )
    else:
        urgency_line = "✅ **All slots have a confirmed host — thank you!**"

    embed = discord.Embed(
        title="📋 DIFF Host Availability — Meet Schedule",
        description=(
            f"📅 **Week of {_week_str}**  •  🔄 Resets <t:{_reset_ts}:R>\n\n"
            f"**Hosts, mark your availability on each meet card below.**\n\n"
            f"📊 {slot_bar}  **{slots_with_host}/{slots_needed} slots have a confirmed host**\n"
            f"👥 **{total_responders} host{'s' if total_responders != 1 else ''}** have responded so far\n"
            f"{urgency_line}\n\n"
            "• ✅ **Available** — opens a form for your day, time & class\n"
            "• ❓ **Maybe** — opens a form to note your preferred day\n"
            "• ❌ **Unavailable** — marks you as unable to host\n"
            "• 👤 **My Status** — shows what you've submitted so far"
        ),
        color=0x5865F2,
        timestamp=utc_now(),
    )
    if DIFF_LOGO_URL:
        embed.set_thumbnail(url=DIFF_LOGO_URL)
    embed.set_footer(text="Different Meets • Host Availability  •  Times shown in your local timezone")
    return embed


def _hrsvp_build_meet_embed(day: str) -> discord.Embed:
    """One roomy availability card for a single meet slot."""
    data          = _hrsvp_load()
    d             = data.get(day, {"yes": [], "no": [], "maybe": []})
    yes_entries   = d.get("yes", [])
    no_entries    = d.get("no", [])
    maybe_entries = d.get("maybe", [])
    _MAX = 12

    if yes_entries:
        slot_status = f"🟢 **{len(yes_entries)} host{'s' if len(yes_entries) != 1 else ''} available**"
        color = 0x57F287
    elif maybe_entries:
        slot_status = f"🟡 **{len(maybe_entries)} maybe** — still needs a host"
        color = 0xFEE75C
    else:
        slot_status = "🔴 **Open — no hosts yet**"
        color = 0xED4245

    # Scheduled date/time for this slot, once leadership has built it.
    when_sub = "🗓️ *Date is set once a host signs up*"
    try:
        sched_entry = _asched_load().get("days", {}).get(day, {})
        s_day  = sched_entry.get("day", "TBD")
        s_time = sched_entry.get("time", "TBD")
        _known = s_day not in ("TBD", "-", None, "") and s_time not in ("TBD", "-", None, "")
        s_ts   = _parse_meet_ts(s_day, s_time) if _known else None
        if s_ts:
            when_sub = f"🗓️ <t:{s_ts}:F>  (<t:{s_ts}:R>)"
        elif _known:
            when_sub = f"🗓️ {s_day} · {s_time}"
    except Exception:
        pass

    lines = [slot_status, when_sub, ""]
    if yes_entries:
        for e in yes_entries[:_MAX]:
            uid = _hrsvp_uid(e)
            if isinstance(e, dict):
                dv = e.get('day', 'TBD')
                tv = e.get('time', 'TBD')
                ts = _parse_meet_ts(dv, tv) if not tv.startswith("<t:") else None
                if ts:
                    when_display = f"<t:{ts}:F>  (<t:{ts}:R>)"
                elif tv.startswith("<t:"):
                    when_display = tv
                else:
                    when_display = f"📅 {dv}  🕒 {tv}"
                lines.append(f"✅ <@{uid}>\n　{when_display}  🎮 {e.get('theme', 'TBD')}")
            else:
                lines.append(f"✅ <@{uid}>")
        if len(yes_entries) > _MAX:
            lines.append(f"-# +{len(yes_entries) - _MAX} more available")

    if maybe_entries:
        for e in maybe_entries[:_MAX]:
            uid = _hrsvp_uid(e)
            day_pref = e.get("day", "") if isinstance(e, dict) else ""
            lines.append(f"❓ <@{uid}>" + (f" — prefers {day_pref}" if day_pref else ""))
        if len(maybe_entries) > _MAX:
            lines.append(f"-# +{len(maybe_entries) - _MAX} more maybe")

    if no_entries:
        no_tags = "  ".join(f"<@{_hrsvp_uid(u)}>" for u in no_entries[:_MAX])
        extra   = f"  +{len(no_entries) - _MAX}" if len(no_entries) > _MAX else ""
        lines.append(f"❌ Unavailable: {no_tags}{extra}")

    desc = "\n".join(lines)
    if len(desc) > 4000:
        desc = desc[:3990] + "\n-# …"
    embed = discord.Embed(title=f"🏁 {day}", description=desc, color=color)
    embed.set_footer(text=f"{day} • mark your availability below")
    return embed


