class _HrsvpResetConfirmModal(discord.ui.Modal, title="Confirm Reset"):
    confirm = discord.ui.TextInput(
        label='Type RESET to confirm clearing all responses',
        placeholder="RESET",
        required=True,
        max_length=10,
    )

    async def on_submit(self, interaction: discord.Interaction) -> None:
        if str(self.confirm).strip().upper() != "RESET":
            return await interaction.response.send_message(
                "❌ Reset cancelled — you didn't type RESET.", ephemeral=True
            )
        await interaction.response.defer(ephemeral=True)
        try:
            _hrsvp_reset()
            await _hrsvp_update_panel(interaction.client)
            await interaction.followup.send(
                "🗑️ All host availability responses have been cleared for the new week.", ephemeral=True
            )
        except Exception as _e:
            print(f"[HRSVP] Reset on_submit error: {_e}")
            try:
                await interaction.followup.send("❌ Reset failed. Try again.", ephemeral=True)
            except Exception:
                pass


class _HrsvpResetBtn(discord.ui.Button):
    def __init__(self):
        super().__init__(
            label="Reset Responses",
            emoji="🗑️",
            style=discord.ButtonStyle.danger,
            custom_id="hrsvp_reset_all",
            row=4,
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        is_staff = any(
            r.id in _LEADERSHIP_ROLE_IDS
            for r in getattr(interaction.user, "roles", [])
        )
        if not getattr(getattr(interaction.user, "guild_permissions", None), "administrator", False) and not is_staff:
            return await interaction.response.send_message(
                "Only leadership can reset availability responses.", ephemeral=True
            )
        await interaction.response.send_modal(_HrsvpResetConfirmModal())


class _HrsvpMyStatusBtn(discord.ui.Button):
    def __init__(self):
        super().__init__(
            label="My Status",
            emoji="👤",
            style=discord.ButtonStyle.secondary,
            custom_id="hrsvp_my_status",
            row=3,
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        uid  = str(interaction.user.id)
        data = _hrsvp_load()
        lines = []
        missing = []
        for day in _HRSVP_DAYS:
            slot = data.get(day, {})
            found = False
            for e in slot.get("yes", []):
                if _hrsvp_uid(e) == uid:
                    if isinstance(e, dict):
                        dv = e.get('day', 'TBD')
                        tv = e.get('time', 'TBD')
                        ts = _parse_meet_ts(dv, tv) if dv and tv != 'TBD' else None
                        when_str = f"<t:{ts}:F>" if ts else f"{dv} · {tv}"
                        lines.append(
                            f"✅ **{day}** — {when_str} · 🎮 {e.get('theme','TBD')}"
                        )
                    else:
                        lines.append(f"✅ **{day}** — Available")
                    found = True
            for e in slot.get("maybe", []):
                if _hrsvp_uid(e) == uid:
                    day_pref = e.get("day","") if isinstance(e, dict) else ""
                    lines.append(f"❓ **{day}** — Maybe" + (f" (prefers {day_pref})" if day_pref else ""))
                    found = True
            for e in slot.get("no", []):
                if _hrsvp_uid(e) == uid:
                    lines.append(f"❌ **{day}** — Unavailable")
                    found = True
            if not found:
                lines.append(f"⬜ **{day}** — No response yet")
                missing.append(day)

        if missing:
            summary = f"⚠️ **Still need your answer for:** {', '.join(missing)}"
        else:
            summary = "✅ **You've responded to every meet — thank you!**"

        await interaction.response.send_message(
            "**Your current availability:**\n" + summary + "\n\n" + "\n".join(lines),
            ephemeral=True,
        )


class HostRSVPView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)
        for day in _HRSVP_DAYS:
            self.add_item(_HostRSVPBtn(day, "yes",   "✅", discord.ButtonStyle.success))
            self.add_item(_HostRSVPBtn(day, "no",    "❌", discord.ButtonStyle.danger))
            self.add_item(_HostRSVPBtn(day, "maybe", "❓", discord.ButtonStyle.secondary))
        self.add_item(_HrsvpMyStatusBtn())
        self.add_item(_HrsvpResetBtn())


class _HostAvailModal(discord.ui.Modal):
    day_time_input = discord.ui.TextInput(
        label="Day & Time you want to host",
        placeholder="e.g. Sunday 8:00 PM ET  or  <t:1234567890:F>",
        required=True,
        max_length=60,
    )
    theme_input = discord.ui.TextInput(
        label="Starting Class / Theme",
        placeholder="e.g. JDM  |  Muscle  |  Open Class  |  Euro",
        required=False,
        max_length=100,
        default="Open Class",
    )

    def __init__(self, day: str):
        super().__init__(title=f"✅ Available for {day}")
        self.day = day

    async def on_submit(self, interaction: discord.Interaction):
        if not interaction.user:
            await interaction.response.defer()
            return
        await interaction.response.defer(ephemeral=True)
        try:
            uid       = str(interaction.user.id)
            raw_dt    = str(self.day_time_input).strip()
            theme_val = str(self.theme_input).strip() or "Open Class"

            # Split "Sunday 8:00 PM EST" → day_val + time_val (store plain text)
            parts    = raw_dt.split(None, 1)
            day_val  = parts[0].capitalize() if parts else raw_dt
            time_raw = parts[1] if len(parts) > 1 else raw_dt
            time_val = time_raw.strip()

            data = _hrsvp_load()
            slot = data.setdefault(self.day, {"yes": [], "no": [], "maybe": []})
            for c in ("yes", "no", "maybe"):
                slot[c] = [e for e in slot.get(c, []) if _hrsvp_uid(e) != uid]
            slot["yes"].append({"uid": uid, "day": day_val, "time": time_val, "theme": theme_val})
            _hrsvp_save(data)
            _hrel_track_rsvp(uid)
            await _hrsvp_update_panel(interaction.client)
            ts = _parse_meet_ts(day_val, time_val)
            time_display = f"<t:{ts}:F>  (<t:{ts}:R>)" if ts else time_val
            await interaction.followup.send(
                f"✅ **{self.day}** — you're marked available!\n"
                f"📅 **Day:** {day_val}  🕒 **Time:** {time_display}  🎮 **Class:** {theme_val}\n\n"
                f"*You can update this anytime by clicking the button again.*",
                ephemeral=True,
            )
        except Exception as _e:
            print(f"[HRSVP] AvailModal on_submit error: {_e}")
            try:
                await interaction.followup.send("❌ Something went wrong saving your response. Try again.", ephemeral=True)
            except Exception:
                pass


class _HostMaybeModal(discord.ui.Modal):
    day_pref = discord.ui.TextInput(
        label="What day(s) could you host?",
        placeholder="e.g. Saturday or Sunday — leave blank if unsure",
        required=False,
        max_length=60,
    )

    def __init__(self, day: str):
        super().__init__(title=f"❓ Maybe for {day}")
        self.day = day

    async def on_submit(self, interaction: discord.Interaction):
        if not interaction.user:
            await interaction.response.defer()
            return
        await interaction.response.defer(ephemeral=True)
        try:
            uid      = str(interaction.user.id)
            day_pref = str(self.day_pref).strip()
            data     = _hrsvp_load()
            slot     = data.setdefault(self.day, {"yes": [], "no": [], "maybe": []})
            for c in ("yes", "no", "maybe"):
                slot[c] = [e for e in slot.get(c, []) if _hrsvp_uid(e) != uid]
            slot["maybe"].append({"uid": uid, "day": day_pref})
            _hrsvp_save(data)
            await _hrsvp_update_panel(interaction.client)
            pref_str = f" — preference: **{day_pref}**" if day_pref else ""
            await interaction.followup.send(
                f"❓ **{self.day}** — marked as Maybe{pref_str}.\n*Leadership will follow up if needed.*",
                ephemeral=True,
            )
        except Exception as _e:
            print(f"[HRSVP] MaybeModal on_submit error: {_e}")
            try:
                await interaction.followup.send("❌ Something went wrong saving your response. Try again.", ephemeral=True)
            except Exception:
                pass


class _HostRSVPBtn(discord.ui.Button):
    def __init__(self, day: str, choice: str, emoji: str, style: discord.ButtonStyle, label: str | None = None):
        super().__init__(
            label=label or day,
            emoji=emoji,
            style=style,
            custom_id=f"hrsvp_{day.replace(' ', '_')}_{choice}",
        )
        self.day = day
        self.choice = choice

    async def callback(self, interaction: discord.Interaction):
        if not interaction.user:
            await interaction.response.defer()
            return
        has_host = any(r.id == HOST_ROLE_ID for r in getattr(interaction.user, "roles", []))
        if not has_host:
            await interaction.response.send_message("Only hosts can use this panel.", ephemeral=True)
            return
        # "yes" → modal for day/time/class
        if self.choice == "yes":
            await interaction.response.send_modal(_HostAvailModal(self.day))
            return
        # "maybe" → modal to note day preference
        if self.choice == "maybe":
            await interaction.response.send_modal(_HostMaybeModal(self.day))
            return
        # "no" → toggle: first click marks unavailable, second click clears the response
        await interaction.response.defer(ephemeral=True)
        try:
            uid  = str(interaction.user.id)
            data = _hrsvp_load()
            slot = data.setdefault(self.day, {"yes": [], "no": [], "maybe": []})
            already_no = any(_hrsvp_uid(e) == uid for e in slot.get("no", []))
            for c in ("yes", "no", "maybe"):
                slot[c] = [e for e in slot.get(c, []) if _hrsvp_uid(e) != uid]
            if not already_no:
                slot["no"].append(uid)
            _hrsvp_save(data)
            await _hrsvp_update_panel(interaction.client)
            if already_no:
                reply = f"↩️ **{self.day}** — your unavailable response has been cleared."
            else:
                reply = f"❌ **{self.day}** — you're marked as unavailable.\n*Changed your mind? Hit ❌ again to clear it.*"
            await interaction.followup.send(reply, ephemeral=True)
        except Exception as _e:
            print(f"[HRSVP] NoBtn callback error: {_e}")
            try:
                await interaction.followup.send("❌ Something went wrong. Try again.", ephemeral=True)
            except Exception:
                pass


def _hrsvp_is_rsvp_msg(msg: discord.Message, bot_id: int) -> bool:
    if msg.author.id != bot_id:
        return False
    for row in msg.components:
        for child in row.children:
            cid = getattr(child, "custom_id", "") or ""
            if cid.startswith("hrsvp_"):
                return True
    return False


async def _hrsvp_resolve_channel(bot_client) -> "discord.TextChannel | None":
    channel = bot_client.get_channel(HOST_RSVP_CHANNEL_ID)
    if not isinstance(channel, discord.TextChannel):
        try:
            channel = await bot_client.fetch_channel(HOST_RSVP_CHANNEL_ID)
        except Exception:
            return None
    return channel if isinstance(channel, discord.TextChannel) else None


async def _hrsvp_render_layout(bot_client, ping: bool = False) -> None:
    """Delete any existing host-availability messages, then post header + one card per meet.
    Only touches messages carrying `hrsvp_` buttons — the Auto Schedule Builder panel
    in the same channel is left alone."""
    channel = await _hrsvp_resolve_channel(bot_client)
    if channel is None:
        return
    bot_id = bot_client.user.id

    data    = _hrsvp_load()
    stored  = [v for v in (data.get("panel_message_ids") or {}).values() if v]
    deleted: set = set()
    for mid in stored:
        try:
            m = await channel.fetch_message(int(mid))
            await m.delete()
            deleted.add(int(mid))
        except Exception:
            pass
    try:
        async for msg in channel.history(limit=40):
            if msg.id in deleted:
                continue
            if _hrsvp_is_rsvp_msg(msg, bot_id):
                try:
                    await msg.delete()
                except Exception:
                    pass
    except Exception:
        pass

    new_ids: dict = {}
    try:
        header = await channel.send(
            content=(f"<@&{HOST_ROLE_ID}>" if ping else None),
            embed=_hrsvp_build_header_embed(),
            view=_HrsvpHeaderView(),
            allowed_mentions=discord.AllowedMentions(roles=True),
        )
        new_ids["header"] = header.id
        for day in _HRSVP_DAYS:
            mm = await channel.send(embed=_hrsvp_build_meet_embed(day), view=_HrsvpMeetView(day))
            new_ids[day] = mm.id
        data = _hrsvp_load()
        data["panel_message_ids"] = new_ids
        _hrsvp_save(data)
    except Exception as e:
        print(f"[HostRSVP] layout post failed: {e}")


async def _hrsvp_update_panel(bot_client) -> None:
    """Edit header + meet cards in place; full (no-ping) repost if anything is missing."""
    channel = await _hrsvp_resolve_channel(bot_client)
    if channel is None:
        return

    data     = _hrsvp_load()
    ids      = data.get("panel_message_ids") or {}
    expected = {"header"} | set(_HRSVP_DAYS)

    if set(ids.keys()) != expected:
        # First rollout / broken layout → fresh post (ping only if nothing existed before).
        await _hrsvp_render_layout(bot_client, ping=not ids)
        return

    try:
        hm = await channel.fetch_message(int(ids["header"]))
        await hm.edit(embed=_hrsvp_build_header_embed(), view=_HrsvpHeaderView())
    except discord.NotFound:
        return await _hrsvp_render_layout(bot_client, ping=False)
    except Exception:
        pass

    for day in _HRSVP_DAYS:
        try:
            mm = await channel.fetch_message(int(ids[day]))
            await mm.edit(embed=_hrsvp_build_meet_embed(day), view=_HrsvpMeetView(day))
        except discord.NotFound:
            return await _hrsvp_render_layout(bot_client, ping=False)
        except Exception:
            pass


