_ASCHED_FILE = os.path.join("diff_data", "diff_auto_schedule.json")
_ASCHED_REFRESH_ID = "diff_auto_sched_refresh"
_ASCHED_REBUILD_ID = "diff_auto_sched_rebuild"
_ASCHED_SUBMIT_ID  = "diff_auto_sched_submit"
_ASCHED_DEFAULT_TEMPLATE = {day: {"class": "TBD", "time": "TBD"} for day in _HRSVP_DAYS}
_ASCHED_ANNOUNCE_CHANNEL_ID = 1485861257708834836


def _asched_default() -> dict:
    return {
        "days": {
            day: {
                "class": _ASCHED_DEFAULT_TEMPLATE[day]["class"],
                "time": _ASCHED_DEFAULT_TEMPLATE[day]["time"],
                "host_id": None,
                "host_status": "unassigned",
            }
            for day in _HRSVP_DAYS
        },
        "updated_at": None,
        "panel_message_id": None,
    }


def _asched_load() -> dict:
    if os.path.exists(_ASCHED_FILE):
        try:
            with open(_ASCHED_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            pass
    return _asched_default()


def _asched_save(data: dict) -> None:
    _atomic_json_save(_ASCHED_FILE, data)


def _asched_pick_host(day: str, rsvp: dict, assigned_counts: dict) -> tuple:
    """Returns (uid, status, day_val, time, theme)."""
    day_data = rsvp.get(day, {})
    yes_entries = list(day_data.get("yes", []))
    maybe_hosts = list(day_data.get("maybe", []))
    if yes_entries:
        yes_entries.sort(key=lambda e: assigned_counts.get(_hrsvp_uid(e), 0))
        chosen = yes_entries[0]
        uid = _hrsvp_uid(chosen)
        assigned_counts[uid] = assigned_counts.get(uid, 0) + 1
        day_val = chosen.get("day", "TBD") if isinstance(chosen, dict) else "TBD"
        time_val = chosen.get("time", "TBD") if isinstance(chosen, dict) else "TBD"
        theme_val = chosen.get("theme", "TBD") if isinstance(chosen, dict) else "TBD"
        return uid, "yes", day_val, time_val, theme_val
    if maybe_hosts:
        maybe_hosts.sort(key=lambda e: assigned_counts.get(_hrsvp_uid(e), 0))
        chosen = maybe_hosts[0]
        uid = _hrsvp_uid(chosen)
        assigned_counts[uid] = assigned_counts.get(uid, 0) + 1
        return uid, "maybe", "TBD", "TBD", "TBD"
    return None, "none", "TBD", "TBD", "TBD"


def _parse_meet_ts(date_val: str, time_val: str) -> int | None:
    """Return a Unix timestamp for a meet's date+time.
    Handles:
      • Discord timestamps — <t:1234567890:F> pasted from hammertime.cyou
      • Weekday names     — "Friday", "sunday", etc. → next occurrence
      • Explicit dates    — "april 12", "Sunday april 12", "april 12, 6:00 PM ET"
      • Numeric dates     — "05/10", "5/10", "MM-DD"
    Returns None on any parse failure.
    """
    import re as _re

    # ── Discord timestamp shortcut (<t:unix:format> from hammertime.cyou) ───────
    for _field in (date_val, time_val):
        _ht = _re.search(r'<t:(\d+)(?::[A-Za-z])?>', _field)
        if _ht:
            return int(_ht.group(1))

    combined = (date_val + " " + time_val).lower()

    # ── Timezone ────────────────────────────────────────────────────────────────
    try:
        from zoneinfo import ZoneInfo as _ZI
        if any(x in combined for x in ("pst", "pdt", "pacific")):
            tz = _ZI("America/Los_Angeles")
        elif any(x in combined for x in ("cst", "cdt", "central")):
            tz = _ZI("America/Chicago")
        elif any(x in combined for x in ("mst", "mdt", "mountain")):
            tz = _ZI("America/Denver")
        else:
            tz = _ZI("America/New_York")   # EST / EDT default
    except Exception:
        return None

    # ── Parse hour / minute ─────────────────────────────────────────────────────
    # Search time_val first so numeric dates in date_val (e.g. "5/14") cannot
    # be mistaken for the hour (regex would otherwise grab "5" from "5/14 8pm").
    _tv = time_val.lower()
    tm = (
        _re.search(r"(\d{1,2})(?::(\d{2}))?\s*(am|pm)", _tv)       # "8pm" / "8:00 PM" with explicit am/pm
        or _re.search(r"(\d{1,2}):(\d{2})", _tv)                    # "20:00" 24-hour with colon
        or _re.search(r"(\d{1,2})(?::(\d{2}))?\s*(am|pm)?", combined)  # fallback: search full combined
    )
    if not tm:
        return None
    hour   = int(tm.group(1))
    minute = int(tm.group(2) or 0)
    try:
        ampm = (tm.group(3) or "").lower()
    except IndexError:
        ampm = ""
    if ampm == "pm" and hour != 12:
        hour += 12
    elif ampm == "am" and hour == 12:
        hour = 0

    now = datetime.now(tz)

    # ── Try explicit month + day first ──────────────────────────────────────────
    _MONTHS = {
        "january": 1, "february": 2, "march": 3, "april": 4,
        "may": 5, "june": 6, "july": 7, "august": 8,
        "september": 9, "october": 10, "november": 11, "december": 12,
    }
    for mname, mnum in _MONTHS.items():
        if mname in combined:
            dm = _re.search(rf"{mname}\s+(\d{{1,2}})", combined)
            if dm:
                day = int(dm.group(1))
                for yr in (now.year, now.year + 1):
                    try:
                        target = datetime(yr, mnum, day, hour, minute, tzinfo=tz)
                        if target >= now - timedelta(hours=3):
                            return int(target.timestamp())
                    except Exception:
                        pass

    # ── Try numeric MM/DD or M/D format (e.g. "05/10", "5/10") ─────────────────
    num_m = _re.search(r'\b(\d{1,2})[/\-](\d{1,2})\b', combined)
    if num_m:
        mnum = int(num_m.group(1))
        day  = int(num_m.group(2))
        if 1 <= mnum <= 12 and 1 <= day <= 31:
            for yr in (now.year, now.year + 1):
                try:
                    target = datetime(yr, mnum, day, hour, minute, tzinfo=tz)
                    if target >= now - timedelta(hours=3):
                        return int(target.timestamp())
                except Exception:
                    pass

    # ── Fall back to weekday-based "next occurrence" ────────────────────────────
    _DAY_MAP = {
        "monday": 0, "tuesday": 1, "wednesday": 2, "thursday": 3,
        "friday": 4, "saturday": 5, "sunday": 6,
    }
    day_num = next((n for k, n in _DAY_MAP.items() if k in combined), None)
    if day_num is None:
        return None
    days_until = (day_num - now.weekday()) % 7
    if days_until == 0 and (now.hour > hour or (now.hour == hour and now.minute >= minute)):
        days_until = 7
    target = now.replace(hour=hour, minute=minute, second=0, microsecond=0) + timedelta(days=days_until)
    return int(target.timestamp())


def _asched_build() -> dict:
    rsvp = _hrsvp_load()
    schedule = _asched_load()
    assigned_counts: dict = {}
    for day in _HRSVP_DAYS:
        slot = schedule["days"].setdefault(day, {})
        if slot.get("locked"):          # 🔒 locked — skip auto-assignment
            continue
        host_id, host_status, day_val, time_val, theme_val = _asched_pick_host(day, rsvp, assigned_counts)
        slot["host_id"]     = int(host_id) if host_id else None
        slot["host_status"] = host_status
        slot["day"]         = day_val
        slot["time"]        = time_val
        slot["class"]       = theme_val
        # New week / reassigned slot: drop the pinned timestamp so identical
        # day/time text (e.g. "Thursday 10 PM" every week) re-parses fresh
        # instead of keeping last week's (now past) pinned date.
        slot.pop("pinned_ts", None)
        slot.pop("pinned_sig", None)
    schedule["updated_at"] = utc_now().isoformat()
    _asched_save(schedule)
    return schedule


def _asched_build_embed() -> discord.Embed:
    schedule = _asched_load()
    rsvp     = _hrsvp_load()

    updated_at = schedule.get("updated_at")
    if updated_at:
        try:
            ts = int(datetime.fromisoformat(updated_at).timestamp())
            rebuilt_str = f"<t:{ts}:R>  (<t:{ts}:f>)"
        except Exception:
            rebuilt_str = "recently"
    else:
        rebuilt_str = "*never — press Rebuild Schedule*"

    # Progress counter + sidebar colour
    filled = sum(1 for d in _HRSVP_DAYS if schedule["days"].get(d, {}).get("host_id"))
    total  = len(_HRSVP_DAYS)
    embed_color = 0x57F287 if filled == total else (0xFEE75C if filled > 0 else 0xEB459E)

    progress_bar = "🟩" * filled + "⬜" * (total - filled)
    progress_str = f"{progress_bar}  **{filled}/{total} slots filled**"

    embed = discord.Embed(
        title="📋 DIFF PS5 Weekly Schedule",
        description=(
            f"*Built automatically from host availability responses.*\n\n"
            f"📊 {progress_str}\n"
            f"🕐 **Last rebuilt:** {rebuilt_str}"
        ),
        color=embed_color,
        timestamp=utc_now(),
    )
    embed.set_author(
        name="Different Meets",
        icon_url=DIFF_LOGO_URL if DIFF_LOGO_URL else discord.utils.MISSING,
    )
    if DIFF_LOGO_URL:
        embed.set_thumbnail(url=DIFF_LOGO_URL)

    _NUMS = ["〔1〕", "〔2〕", "〔3〕"]

    for idx, day in enumerate(_HRSVP_DAYS, start=1):
        entry       = schedule["days"].get(day, {})
        host_id     = entry.get("host_id")
        host_status = entry.get("host_status", "none")
        rsvp_slot   = rsvp.get(day, {})
        class_val   = entry.get("class", "-")
        time_val    = entry.get("time",  "-")
        date_val    = entry.get("day",   "-")
        locked      = entry.get("locked", False)
        lock_tag    = " 🔒" if locked else ""
        num_tag     = _NUMS[idx - 1]

        # Status badge
        if host_id:
            status_tag = "🟢 Confirmed" if host_status != "maybe" else "🟡 Tentative"
            host_val   = _readable_host(None, host_id) + (" *(tentative)*" if host_status == "maybe" else "")
            avail_line = None
        else:
            available = [_hrsvp_uid(e) for e in rsvp_slot.get("yes", [])]
            maybe_av  = [_hrsvp_uid(e) for e in rsvp_slot.get("maybe", [])]
            host_val  = "-"
            if available:
                status_tag = "⏳ Awaiting Assignment"
                avail_line = (
                    f"✅ **Available ({len(available)} host{'s' if len(available) != 1 else ''}):** "
                    + "  ".join(f"<@{u}>" for u in available[:5])
                )
            elif maybe_av:
                status_tag = "❓ Possible Hosts"
                avail_line = (
                    f"❓ **Maybe ({len(maybe_av)}):** "
                    + "  ".join(f"<@{u}>" for u in maybe_av[:5])
                )
            else:
                status_tag = "🔴 Open Slot"
                avail_line = None

        meet_ts = _parse_meet_ts(date_val, time_val)

        if meet_ts:
            when_line = f"📅 <t:{meet_ts}:D>  ·  🕒 <t:{meet_ts}:t>  ·  <t:{meet_ts}:R>"
        else:
            when_line = f"📅 {date_val}  ·  🕒 {time_val}"

        field_lines = [
            f"**{status_tag}**{lock_tag}",
            f"🎮 {class_val}",
            when_line,
            f"👤 **Host:** {host_val}",
        ]
        if avail_line:
            field_lines.append(avail_line)

        embed.add_field(
            name=f"{num_tag}  Meet {idx}",
            value="\n".join(field_lines),
            inline=False,
        )

    embed.add_field(
        name="📌 Important Information",
        value=(
            "*All DIFF Meets are based on the host's work & IRL schedule.*\n"
            "*Meet details are all subject to change.*"
        ),
        inline=False,
    )
    embed.set_footer(text="DIFF • Auto Host Schedule Builder  •  🔒 = slot locked by leadership")
    return embed


