def _asched_build_console_meet_embed(idx: int, day: str) -> discord.Embed:
    """One status card for a single meet slot in the builder console."""
    schedule    = _asched_load()
    rsvp        = _hrsvp_load()
    entry       = schedule["days"].get(day, {})
    host_id     = entry.get("host_id")
    host_status = entry.get("host_status", "none")
    rsvp_slot   = rsvp.get(day, {})
    class_val   = entry.get("class", "-")
    time_val    = entry.get("time",  "-")
    date_val    = entry.get("day",   "-")
    locked      = entry.get("locked", False)
    lock_tag    = " 🔒" if locked else ""

    if host_id:
        status_tag = "🟢 Confirmed" if host_status != "maybe" else "🟡 Tentative"
        host_val   = _readable_host(None, host_id) + (" *(tentative)*" if host_status == "maybe" else "")
        avail_line = None
        color      = 0x57F287 if host_status != "maybe" else 0xFEE75C
    else:
        available = [_hrsvp_uid(e) for e in rsvp_slot.get("yes", [])]
        maybe_av  = [_hrsvp_uid(e) for e in rsvp_slot.get("maybe", [])]
        host_val  = "-"
        if available:
            status_tag = "⏳ Awaiting Assignment"
            avail_line = (
                f"✅ **Available ({len(available)} host{'s' if len(available) != 1 else ''}):** "
                + "  ".join(f"<@{u}>" for u in available[:8])
            )
            color = 0xFEE75C
        elif maybe_av:
            status_tag = "❓ Possible Hosts"
            avail_line = (
                f"❓ **Maybe ({len(maybe_av)}):** "
                + "  ".join(f"<@{u}>" for u in maybe_av[:8])
            )
            color = 0xFEE75C
        else:
            status_tag = "🔴 Open Slot"
            avail_line = None
            color = 0xEB459E

    meet_ts = _parse_meet_ts(date_val, time_val)
    if meet_ts:
        when_line = f"📅 <t:{meet_ts}:D>  ·  🕒 <t:{meet_ts}:t>  ·  <t:{meet_ts}:R>"
    else:
        when_line = f"📅 {date_val}  ·  🕒 {time_val}"

    lines = [
        f"**{status_tag}**{lock_tag}",
        f"🎮 {class_val}",
        when_line,
        f"👤 **Host:** {host_val}",
    ]
    if avail_line:
        lines.append(avail_line)

    embed = discord.Embed(title=f"〔{idx}〕 Meet {idx}", description="\n".join(lines), color=color)
    embed.set_footer(text="DIFF • Auto Host Schedule Builder  •  🔒 = slot locked by leadership")
    return embed


class _ASchedAnnounceView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="Notify", emoji="🔔", style=discord.ButtonStyle.danger, custom_id="diff_asched_announce:notify")
    async def notify_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        is_staff = any(
            r.id in _LEADERSHIP_HOST_ROLE_IDS
            for r in getattr(interaction.user, "roles", [])
        )
        if not is_staff:
            await interaction.response.send_message("Only staff can send schedule notifications.", ephemeral=True)
            return

        guild = interaction.guild
        if not guild:
            await interaction.response.send_message("Could not find guild.", ephemeral=True)
            return

        ping_parts = []
        ps5_role = guild.get_role(PS5_ROLE_ID)
        if ps5_role:
            ping_parts.append(ps5_role.mention)
        notify_role = guild.get_role(NOTIFY_ROLE_ID)
        if notify_role:
            ping_parts.append(notify_role.mention)

        if not ping_parts:
            await interaction.response.send_message("No roles found to ping.", ephemeral=True)
            return

        await interaction.response.send_message("Notification sent.", ephemeral=True)
        try:
            await interaction.channel.send(
                content=" ".join(ping_parts) + " — 📅 **The DIFF Meet Host Schedule has been posted above. Check your meet!**"
            )
        except Exception as e:
            print(f"[AutoSched] Notify ping failed: {e}")


def _asched_attendees(slot: dict) -> list:
    """Current attendee user-ids for a slot, auto-reset when the meet changes."""
    sig = f"{slot.get('class','')}|{slot.get('day','')}|{slot.get('time','')}"
    if slot.get("attendees_sig") != sig:
        slot["attendees"] = []
        slot["attendees_sig"] = sig
    return slot.setdefault("attendees", [])


def _asched_reconcile_attendees(schedule: dict) -> bool:
    """Reset attendee lists whose meet details changed. Returns True if mutated."""
    changed = False
    for key in _HRSVP_DAYS:
        slot = schedule.get("days", {}).get(key)
        if not isinstance(slot, dict):
            continue
        sig = f"{slot.get('class','')}|{slot.get('day','')}|{slot.get('time','')}"
        if slot.get("attendees_sig") != sig:
            slot["attendees"] = []
            slot["attendees_sig"] = sig
            changed = True
    return changed


def _asched_sorted_slots(schedule: dict):
    """Return slot rows sorted soonest-first (future → past → TBD) + now_ts.

    Timestamps are PINNED per slot (`pinned_ts` + `pinned_sig`): weekday-only
    dates like "Thursday" re-parse to NEXT week's occurrence once the meet time
    passes, which made completed meets jump to a random future date instead of
    showing as Completed. The first successful parse is persisted and reused
    until the slot's day/time text changes (sig mismatch), the weekly Rebuild
    clears it, or it goes stale (>6 days past — can't be this week's meet)."""
    now_ts = int(utc_now().timestamp())
    rows = []
    pins_changed = False
    for key in _HRSVP_DAYS:
        entry = schedule.get("days", {}).get(key, {})
        sig = f"{entry.get('day', 'TBD')}|{entry.get('time', 'TBD')}"
        pinned = entry.get("pinned_ts")
        if (
            entry.get("pinned_sig") == sig
            and isinstance(pinned, (int, float))
            and now_ts - int(pinned) < 6 * 86400
        ):
            mt = int(pinned)
        else:
            mt = _parse_meet_ts(entry.get("day", "TBD"), entry.get("time", "TBD"))
            if mt is not None:
                if entry.get("pinned_ts") != mt or entry.get("pinned_sig") != sig:
                    entry["pinned_ts"] = mt
                    entry["pinned_sig"] = sig
                    pins_changed = True
            elif "pinned_ts" in entry or "pinned_sig" in entry:
                entry.pop("pinned_ts", None)
                entry.pop("pinned_sig", None)
                pins_changed = True
        if mt is None:
            cat, sortk = 2, (2, 0)
        elif mt < now_ts:
            cat, sortk = 1, (1, mt)
        else:
            cat, sortk = 0, (0, mt)
        rows.append({"key": key, "entry": entry, "ts": mt, "cat": cat, "sortk": sortk})
    if pins_changed:
        try:
            _asched_save(schedule)
        except Exception:
            pass
    rows.sort(key=lambda r: r["sortk"])
    return rows, now_ts


_THEME_HINTS = [
    (("lowrider", "low rider", "low-rider"), "Lowriders & customs"),
    (("muscle",), "American muscle"),
    (("classic", "vintage", "retro"), "Classics & vintage builds"),
    (("jdm", "import", "japan"), "JDM & imports"),
    (("euro", "european", "german"), "European builds"),
    (("super", "hyper", "exotic"), "Supercars & exotics"),
    (("luxury", "vip"), "Luxury & VIP"),
    (("offroad", "off road", "off-road", "suv", "truck", "4x4"), "Off-road & trucks"),
    (("tuner", "modified", "stance"), "Tuners & modified"),
    (("drift",), "Drift-spec builds"),
    (("song", "music", "playlist"), "Match your car to a song"),
    (("open class", "open"), "Open class — anything goes"),
]


def _theme_detail_hint(theme: str) -> str | None:
    """Best-effort one-line 'what to bring' hint from a freeform theme string."""
    if not theme:
        return None
    t = theme.lower()
    for keys, hint in _THEME_HINTS:
        if any(k in t for k in keys):
            return hint
    return None


def _gcal_url(theme: str, start_ts: int) -> str:
    """Google Calendar quick-add URL for a 2-hour meet block."""
    import urllib.parse as _up
    from datetime import datetime as _dt, timezone as _tz
    _s = _dt.fromtimestamp(start_ts, tz=_tz.utc).strftime("%Y%m%dT%H%M%SZ")
    _e = _dt.fromtimestamp(start_ts + 7200, tz=_tz.utc).strftime("%Y%m%dT%H%M%SZ")
    _params = {
        "action": "TEMPLATE",
        "text": f"DIFF Meets — {theme}",
        "dates": f"{_s}/{_e}",
        "details": "PlayStation GTA car meet hosted by DIFF Meets.",
    }
    return "https://calendar.google.com/calendar/render?" + _up.urlencode(_params)


