def _car_examples_gallery_embeds(count: int = 4) -> list[discord.Embed]:
    """Return a small set of embeds that Discord merges into a single image
    gallery (multiple embeds sharing one `url` collapse into one multi-image
    embed, up to 4 images). The first embed carries the title/description so
    new applicants instantly see the build quality DIFF expects."""
    import random as _rnd
    pool = list(_CAR_EXAMPLE_URLS)
    if not pool:
        return []
    n = max(1, min(count, 4, len(pool)))
    picks = _rnd.sample(pool, n)
    gallery_url = "https://github.com/thomasmilling12/diff-bot"
    embeds: list[discord.Embed] = []
    for idx, img in enumerate(picks):
        emb = discord.Embed(color=0x3B6FE8, url=gallery_url)
        if idx == 0:
            emb.title = "📸 Examples of a DIFF Build"
            emb.description = (
                "Here are a few example builds that meet DIFF standards — clean, "
                "realistic, well-styled PS5 GTA cars. Aim for this level of quality "
                "when you submit your garage photos."
            )
        emb.set_image(url=img)
        embeds.append(emb)
    return embeds


async def _send_car_requirements(channel: "discord.abc.Messageable") -> None:
    """Post the DIFF vehicle requirements embed followed by a 4-image example
    gallery to the given channel. Shared by the join flow and the prefix commands."""
    await channel.send(embed=_diff_vehicle_requirements_embed())
    _ex = _car_examples_gallery_embeds(4)
    if _ex:
        await channel.send(embeds=_ex)


class _CarRequirementsButton(discord.ui.Button):
    """Persistent panel button — shows the DIFF vehicle requirements + example
    builds privately (ephemeral) to whoever clicks. Each panel passes a distinct
    `key` so custom_ids don't collide across separately-registered views."""

    def __init__(self, *, row: int = 0, key: str = ""):
        # Distinct custom_id per panel so each persistent view registers its own
        # dispatch entry (reusing one id across separately-registered persistent
        # views collides in discord.py's ViewStore). Callback logic is shared.
        super().__init__(
            label="Car Requirements",
            style=discord.ButtonStyle.secondary,
            emoji="🚗",
            custom_id=f"diff_car_requirements{('_' + key) if key else ''}",
            row=row,
        )

    async def callback(self, interaction: discord.Interaction):
        try:
            embeds = [_diff_vehicle_requirements_embed()] + _car_examples_gallery_embeds(4)
            await interaction.response.send_message(embeds=embeds, ephemeral=True)
        except Exception as _e:
            _bot_log.warning(f"[carreq-btn] failed: {_e}")
            try:
                if not interaction.response.is_done():
                    await interaction.response.send_message(
                        "⚠️ Couldn't load the requirements right now — please try again shortly.",
                        ephemeral=True,
                    )
            except Exception:
                pass


@bot.command(name="carreqs", aliases=["carrequirements", "vehiclereqs", "carrules", "buildreqs"])
async def carreqs(ctx: commands.Context):
    """Show the DIFF vehicle requirements + example builds in this channel (anyone)."""
    try:
        await _send_car_requirements(ctx.channel)
    except discord.Forbidden:
        await ctx.send("🚫 I need permission to send embeds/links in this channel.")
    except Exception as _e:
        _bot_log.warning(f"[carreqs] failed: {_e}")
        await ctx.send("⚠️ Couldn't post the requirements right now — please try again.")


@bot.command(name="postcarreqs", aliases=["pincarreqs", "postvehiclereqs"])
async def postcarreqs(ctx: commands.Context, channel: discord.TextChannel = None):
    """Leadership: post the vehicle requirements + examples into a channel for pinning.
    Usage: !postcarreqs [#channel] (defaults to the current channel)."""
    if not any(r.id in _LEADERSHIP_ROLE_IDS for r in getattr(ctx.author, "roles", [])):
        return await ctx.send("🚫 Only leadership can post the pinned requirements.")
    target = channel or ctx.channel
    try:
        await _send_car_requirements(target)
    except discord.Forbidden:
        return await ctx.send(f"🚫 I can't send embeds in {getattr(target, 'mention', 'that channel')}.")
    except Exception as _e:
        _bot_log.warning(f"[postcarreqs] failed: {_e}")
        return await ctx.send("⚠️ Couldn't post the requirements right now — please try again.")
    if target.id != ctx.channel.id:
        await ctx.send(f"✅ Posted the vehicle requirements in {target.mention}.")


def _outlook_url(theme: str, start_ts: int) -> str:
    """Outlook web 'add event' deeplink for a 2-hour meet block."""
    import urllib.parse as _up
    from datetime import datetime as _dt, timezone as _tz
    _s = _dt.fromtimestamp(start_ts, tz=_tz.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    _e = _dt.fromtimestamp(start_ts + 7200, tz=_tz.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    _params = {
        "path": "/calendar/action/compose",
        "rru": "addevent",
        "subject": f"DIFF Meets — {theme}",
        "startdt": _s,
        "enddt": _e,
        "body": "PlayStation GTA car meet hosted by DIFF Meets.",
    }
    return "https://outlook.live.com/calendar/0/deeplink/compose?" + _up.urlencode(_params)


async def _asched_build_finalized_embed(guild: discord.Guild | None = None) -> discord.Embed:
    """Clean, community-facing embed for the upcoming-meet channel. No management details."""
    schedule = _asched_load()
    if _asched_reconcile_attendees(schedule):
        try:
            _asched_save(schedule)
        except Exception:
            pass

    embed = discord.Embed(
        title="🗓️ DIFF PS5 Weekly Car Meet Schedule",
        color=0x57F287,
        timestamp=utc_now(),
    )
    embed.set_author(
        name="Different Meets",
        icon_url=DIFF_LOGO_URL if DIFF_LOGO_URL else discord.utils.MISSING,
    )
    if DIFF_LOGO_URL:
        embed.set_thumbnail(url=DIFF_LOGO_URL)

    _NUM_EMOJI = ["1️⃣", "2️⃣", "3️⃣"]

    rows, now_ts = _asched_sorted_slots(schedule)
    next_row = next((r for r in rows if r["cat"] == 0), None)

    # Prominent countdown to the soonest upcoming meet
    if next_row and next_row["ts"]:
        embed.description = f"⏰ **Next meet** <t:{next_row['ts']}:R> — <t:{next_row['ts']}:F>"
    else:
        embed.description = "No upcoming meets scheduled yet — check back soon."

    for pos, row in enumerate(rows, start=1):
        entry     = row["entry"]
        meet_ts   = row["ts"]
        is_past   = row["cat"] == 1
        is_next   = next_row is not None and row is next_row

        host_id   = entry.get("host_id")
        class_val = entry.get("class", "TBD")
        time_val  = entry.get("time",  "TBD")
        date_val  = entry.get("day",   "TBD")

        # Host: PSN name (linked to PSN profile) · Discord mention — matches original format
        host_str = "*TBD*"
        if host_id:
            _psn_id, _psn_url = "", ""
            try:
                for _h in data.get("hosts", []):
                    if _h.get("discord_id") == int(host_id):
                        _purl = (_h.get("profile_url") or "").rstrip("/")
                        if _purl:
                            _psn_url = _purl
                            _psn_id = _purl.split("/")[-1]
                        break
            except Exception:
                pass
            if _psn_id and _psn_url:
                host_str = f"{_psn_id} [↗]({_psn_url}) · {_readable_host(guild, host_id)}"
            else:
                host_str = _readable_host(guild, host_id) or f"<@{host_id}>"

        if meet_ts:
            when_line = f"<t:{meet_ts}:F>  ·  <t:{meet_ts}:R>"
        else:
            when_line = f"📅 {date_val}  🕒 {time_val}"

        badge = _NUM_EMOJI[pos - 1] if pos <= len(_NUM_EMOJI) else f"{pos}\uFE0F\u20E3"
        # Field name: number badge always kept; NEXT/PAST as suffix labels
        if is_past:
            field_name = f"{badge}  ✅  ~~{class_val}~~  ·  *Completed*"
        elif is_next:
            field_name = f"{badge}  🏎️  {class_val}  ·  👉 NEXT UP"
        else:
            field_name = f"{badge}  🏎️  {class_val}"

        # Value: when + host (+ theme hint + RSVP count + calendar links for future meets)
        value_lines = [when_line, f"🎮 {host_str}"]

        hint = _theme_detail_hint(class_val)
        if hint and not is_past:
            value_lines.append(f"-# 🚗 {hint}")

        if not is_past:
            n = len(_asched_attendees(entry))
            if n:
                value_lines.append(f"🙌 **{n}** going")

        if meet_ts and not is_past and class_val and class_val.upper() != "TBD":
            value_lines.append(
                f"📅 Add to Calendar: [Google]({_gcal_url(class_val, meet_ts)}) · "
                f"[Outlook]({_outlook_url(class_val, meet_ts)})"
            )

        embed.add_field(
            name=field_name,
            value="\n".join(value_lines),
            inline=False,
        )

    embed.add_field(
        name="\u200b",
        value="-# *Meets may change based on host availability · Times shown in your local timezone · Tap a button below to RSVP*",
        inline=False,
    )

    _banner = _asched_banner_url()
    if _banner.startswith("http"):
        embed.set_image(url=_banner)

    embed.set_footer(text="DIFF Meets • PlayStation GTA Car Meets")
    return embed


class _ASchedRSVPBtn(discord.ui.Button):
    def __init__(self, slot_key: str, label: str, disabled: bool = False, row: int = 0):
        super().__init__(
            label=label,
            emoji="✅",
            style=discord.ButtonStyle.success,
            custom_id=f"diff_asched_rsvp:{slot_key}",
            disabled=disabled,
            row=row,
        )
        self._slot_key = slot_key

    async def callback(self, interaction: discord.Interaction) -> None:
        await _asched_rsvp_toggle(interaction, self._slot_key)


class _ASchedRSVPView(discord.ui.View):
    """RSVP buttons under the weekly schedule. Built dynamically (live labels +
    counts) when posting/editing; a generic instance is registered on_ready so
    button clicks still route after a restart (matched by custom_id)."""
    def __init__(self, schedule: dict | None = None):
        super().__init__(timeout=None)
        if schedule is None:
            for key in _HRSVP_DAYS:
                self.add_item(_ASchedRSVPBtn(key, f"I'm Going — {key}", row=0))
            return
        layout = _asched_layout_slots(schedule)
        for i, sl in enumerate(layout):
            entry   = sl["entry"]
            is_past = sl["is_past"]
            cls     = entry.get("class", "TBD")
            if is_past:
                label = f"{cls} — closed"
            else:
                n = len(_asched_attendees(entry))
                label = f"{cls} ({n})" if n else f"RSVP: {cls}"
            self.add_item(_ASchedRSVPBtn(sl["key"], label[:80], disabled=is_past, row=i // 5))


def _asched_build_rsvp_view(schedule: dict) -> "_ASchedRSVPView":
    return _ASchedRSVPView(schedule)


# ── Split layout: header card + one roomy card per scheduled meet ──────────────
def _asched_slot_scheduled(entry: dict) -> bool:
    """True when a slot holds a real meet (host, set class, or a parseable time)."""
    if not isinstance(entry, dict):
        return False
    if entry.get("host_id"):
        return True
    cls = (entry.get("class") or "").strip()
    if cls and cls.upper() != "TBD":
        return True
    if _parse_meet_ts(entry.get("day", "TBD"), entry.get("time", "TBD")):
        return True
    return False


def _asched_layout_slots(schedule: dict) -> list[dict]:
    """Ordered (soonest-first) scheduled slots with display flags. Empty TBD slots
    are dropped entirely so the public schedule never shows fake 'TBD' meets."""
    rows, _now = _asched_sorted_slots(schedule)
    scheduled = [r for r in rows if _asched_slot_scheduled(r["entry"])]
    next_key = next((r["key"] for r in scheduled if r["cat"] == 0), None)
    out = []
    for pos, r in enumerate(scheduled, start=1):
        out.append({
            "key": r["key"], "entry": r["entry"], "ts": r["ts"],
            "is_past": r["cat"] == 1, "is_next": r["key"] == next_key, "pos": pos,
        })
    return out


def _asched_host_str(entry: dict) -> str:
    """Clean host label: the host's name shown ONCE, with an optional PSN profile link.
    Drops the old redundant 'PSN-text · display-name · @mention' triple."""
    host_id = entry.get("host_id")
    if not host_id:
        return "*TBD*"
    # Display name (always readable), resolved against the main guild.
    name = None
    try:
        g = bot.get_guild(GUILD_ID)
        m = g.get_member(int(host_id)) if g else None
        if m:
            name = m.display_name
    except Exception:
        name = None
    if not name:
        name = f"<@{host_id}>"
    # Optional PSN profile link.
    _psn_url = ""
    try:
        for _h in data.get("hosts", []):
            if _h.get("discord_id") == int(host_id):
                _psn_url = (_h.get("profile_url") or "").rstrip("/")
                break
    except Exception:
        pass
    if _psn_url:
        return f"**{name}** · [PSN ↗]({_psn_url})"
    return f"**{name}**"


def _asched_build_header_embed(guild: discord.Guild | None = None) -> discord.Embed:
    """Slim header card: week banner + countdown to the next meet (or clean empty state)."""
    schedule = _asched_load()
    if _asched_reconcile_attendees(schedule):
        try:
            _asched_save(schedule)
        except Exception:
            pass

    layout   = _asched_layout_slots(schedule)
    next_row = next((s for s in layout if s["is_next"]), None)

    embed = discord.Embed(
        title="🗓️ DIFF PS5 Weekly Car Meet Schedule",
        color=0x57F287,
        timestamp=utc_now(),
    )
    embed.set_author(
        name="Different Meets",
        icon_url=DIFF_LOGO_URL if DIFF_LOGO_URL else discord.utils.MISSING,
    )
    if not layout:
        embed.description = (
            "**No meets scheduled yet — check back soon.** 🏁\n\n"
            "-# Hosts set each week's meets from their availability. "
            "You'll get pinged here the moment a meet drops."
        )
    elif next_row and next_row["ts"]:
        cnt = len(layout)
        embed.description = (
            f"⏰ **Next meet** <t:{next_row['ts']}:R>\n"
            f"-# {cnt} meet{'s' if cnt != 1 else ''} this week · RSVP with the buttons below 👇"
        )
    else:
        embed.description = "-# RSVP with the buttons below 👇"

    # One field per scheduled meet — the whole schedule lives on this single panel.
    _NUM_EMOJI = ["1️⃣", "2️⃣", "3️⃣"]
    for sl in layout:
        entry     = sl["entry"]
        meet_ts   = sl["ts"]
        is_past   = sl["is_past"]
        is_next   = sl["is_next"]
        pos       = sl["pos"]
        class_val = entry.get("class", "TBD")
        time_val  = entry.get("time",  "TBD")
        date_val  = entry.get("day",   "TBD")
        badge = _NUM_EMOJI[pos - 1] if pos <= len(_NUM_EMOJI) else f"{pos}\uFE0F\u20E3"
        # Mobile-first layout: short field titles (no mid-title wrapping), one fact
        # per line in the value, countdown as small subtext, spacer between meets.
        if is_past:
            fname = f"{badge} ✅ {class_val} — Completed"
        elif is_next:
            fname = f"{badge} 🏎️ {class_val} — NEXT UP 👉"
        else:
            fname = f"{badge} 🏎️ {class_val}"
        if meet_ts:
            flines = [f"🗓️ <t:{meet_ts}:F>"]
        else:
            flines = [f"📅 {date_val} · 🕒 {time_val}"]
        flines.append(f"🎮 {_asched_host_str(entry)}")
        if not is_past:
            sub_bits = []
            if meet_ts:
                sub_bits.append(f"⏳ <t:{meet_ts}:R>")
            hint = _theme_detail_hint(class_val)
            if hint:
                sub_bits.append(f"🚗 {hint}")
            if sub_bits:
                flines.append("-# " + " · ".join(sub_bits))
            n = len(_asched_attendees(entry))
            flines.append(f"🙌 **{n}** going" if n else "-# Be the first to RSVP 👇")
        if pos < len(layout):
            flines.append("\u200b")   # breathing room before the next meet card
        embed.add_field(name=fname[:256], value="\n".join(flines)[:1024], inline=False)

    _banner = _asched_banner_url()
    if _banner.startswith("http"):
        embed.set_image(url=_banner)

    embed.set_footer(text="DIFF Meets • PlayStation GTA Car Meets  ·  Times shown in your local timezone")
    return embed


async def _asched_resolve_announce_channel(bot_client) -> "discord.TextChannel | None":
    ch = bot_client.get_channel(_ASCHED_ANNOUNCE_CHANNEL_ID)
    if not isinstance(ch, discord.TextChannel):
        try:
            ch = await bot_client.fetch_channel(_ASCHED_ANNOUNCE_CHANNEL_ID)
        except Exception:
            return None
    return ch if isinstance(ch, discord.TextChannel) else None


def _asched_get_msg_ids(schedule: dict) -> dict:
    v = schedule.get("panel_message_ids")
    return dict(v) if isinstance(v, dict) else {}


def _asched_is_public_panel_msg(msg: discord.Message, bot_id: int) -> bool:
    """True for a bot-authored public schedule message (header or meet card)."""
    if msg.author.id != bot_id:
        return False
    for row in msg.components:
        for child in getattr(row, "children", []):
            cid = getattr(child, "custom_id", "") or ""
            if cid.startswith("diff_asched_rsvp"):
                return True
    for emb in msg.embeds:
        if emb.title and "Weekly Car Meet Schedule" in emb.title:
            return True
    return False


def _asched_panel_ids(sched: dict) -> dict:
    """Normalize stored panel ids to {'header': id|None, 'cards': [ids...]} from any
    historical format (legacy single id, or legacy {slot_key: id} dict)."""
    raw = sched.get("panel_message_ids")
    header, cards = None, []
    if isinstance(raw, dict):
        header = raw.get("header")
        if isinstance(raw.get("cards"), list):
            cards = [c for c in raw["cards"] if c]
        else:
            cards = [v for k, v in raw.items() if k != "header" and v]
    if not header:
        header = sched.get("panel_message_id")  # legacy single-panel fallback
    return {"header": header, "cards": cards}


_asched_sync_lock = asyncio.Lock()


async def _asched_sync_panel(bot_client, ping_roles: bool = False) -> None:
    """Maintain ONE persistent schedule panel by editing in place — never delete +
    repost the whole thing. The header lives permanently and is only edited; meet
    cards are reused by position (add/trim only the delta). On `ping_roles` a single
    short ping line is posted idempotently — deduped by schedule signature, with the
    stale line replaced only when the schedule actually changed — so the panel itself
    is never re-posted week to week and repeated rebuilds can't re-ping the server.

    Serialized via `_asched_sync_lock` so the 15-min refresh loop, a staff finalize,
    and any manual trigger can never overlap and post a duplicate set of cards."""
    async with _asched_sync_lock:
        await _asched_sync_panel_inner(bot_client, ping_roles=ping_roles)


async def _asched_sync_panel_inner(bot_client, ping_roles: bool = False) -> None:
    channel = await _asched_resolve_announce_channel(bot_client)
    if channel is None:
        return
    guild  = channel.guild
    bot_id = bot_client.user.id

    sched  = _asched_load()
    layout = _asched_layout_slots(sched)
    ids    = _asched_panel_ids(sched)

    # NOTE: the announce ping line is managed exclusively in the finalize-ping block
    # below (dedupe + stale cleanup). Deleting it up-front here used to race with the
    # dedupe logic and could leave zero or duplicate ping lines.

    keep: set = set()

    # ── Header: reuse the permanent message, or create it once ──
    header_msg = None
    if ids["header"]:
        try:
            header_msg = await channel.fetch_message(int(ids["header"]))
        except Exception:
            header_msg = None
    # Single consolidated panel: the whole schedule (all meets as fields) + one RSVP
    # button per meet live on ONE message. No separate per-meet card messages.
    panel_embed = _asched_build_header_embed(guild)
    panel_view  = _asched_build_rsvp_view(sched) if layout else None
    if header_msg is not None:
        try:
            await header_msg.edit(embed=panel_embed, view=panel_view)
        except Exception:
            pass
    else:
        try:
            header_msg = await channel.send(embed=panel_embed, view=panel_view)
        except Exception as e:
            print(f"[AutoSched] panel post failed: {e}")
            return
    keep.add(header_msg.id)

    # Remove any legacy per-meet card messages from the old split layout.
    new_cards: list = []
    for leftover in list(ids["cards"]):
        try:
            m = await channel.fetch_message(int(leftover))
            await m.delete()
        except Exception:
            pass

    # Self-healing cleanup: delete any stray/duplicate bot-authored schedule message
    # (old header, orphaned card from a prior race) that isn't part of the panel we
    # just reconciled. Runs every sync — #upcoming-meet is dedicated to this panel, so
    # a scan is cheap and removes duplicates instead of letting them pile up forever.
    # The tracked announce ping line is kept; UNTRACKED duplicate ping lines (e.g.
    # from a past double-rebuild) are swept too.
    tracked_ping = sched.get("panel_ping_msg_id")
    if tracked_ping:
        try:
            keep.add(int(tracked_ping))
        except Exception:
            pass
    try:
        async for m in channel.history(limit=100):
            if m.id in keep:
                continue
            is_stray_ping = (
                m.author.id == bot_id
                and "DIFF meet schedule is up" in (m.content or "")
            )
            if _asched_is_public_panel_msg(m, bot_id) or is_stray_ping:
                try:
                    await m.delete()
                except Exception:
                    pass
    except Exception:
        pass

    # ── Optional finalize ping: a single short line, not a new panel ──
    # Idempotent: if this exact schedule was already announced, do NOT re-ping the
    # server (a double Rebuild click previously posted two ping lines minutes apart).
    ping_id = None
    ping_sig = ""
    if ping_roles:
        try:
            sig_parts = []
            for d in _HRSVP_DAYS:
                e = sched["days"].get(d, {}) if isinstance(sched.get("days"), dict) else {}
                sig_parts.append(f"{d}:{e.get('day','')}:{e.get('time','')}:{e.get('class','')}:{e.get('host_id','')}")
            ping_sig = "|".join(sig_parts)
        except Exception:
            ping_sig = ""
        prev_sig = sched.get("panel_ping_sig") or ""
        prev_ping_id = sched.get("panel_ping_msg_id")
        existing_ping = None
        if prev_ping_id:
            try:
                existing_ping = await channel.fetch_message(int(prev_ping_id))
            except Exception:
                existing_ping = None
        if ping_sig and existing_ping is not None and ping_sig == prev_sig:
            # Same schedule already announced and the ping line still exists —
            # keep it, no re-ping.
            ping_id = prev_ping_id
        else:
            # Schedule changed / first announce / old ping missing: remove the stale
            # ping line (if any) so only one ever exists, then post a fresh one.
            if existing_ping is not None:
                try:
                    await existing_ping.delete()
                except Exception:
                    pass
            parts = []
            ps5_role    = guild.get_role(PS5_ROLE_ID)
            notify_role = guild.get_role(NOTIFY_ROLE_ID)
            if ps5_role:
                parts.append(ps5_role.mention)
            if notify_role:
                parts.append(notify_role.mention)
            if parts:
                try:
                    ping_msg = await channel.send(
                        content=" ".join(parts) + " — 📅 **This week's DIFF meet schedule is up — RSVP on the panel above!**",
                        allowed_mentions=discord.AllowedMentions(roles=True),
                    )
                    ping_id = ping_msg.id
                except Exception as e:
                    print(f"[AutoSched] finalize ping failed: {e}")

    # ── Persist ids ──
    sched = _asched_load()
    sched["panel_message_id"]  = None
    sched["panel_message_ids"] = {"header": header_msg.id, "cards": new_cards}
    if ping_roles:
        # Only ping runs may touch these — the 15-min refresh (ping_roles=False)
        # previously wiped panel_ping_msg_id every tick, orphaning old ping lines.
        sched["panel_ping_msg_id"] = ping_id
        sched["panel_ping_sig"]    = ping_sig
    sched["panel_legacy_cleanup_done"] = True
    _asched_save(sched)


async def _asched_render_layout(bot_client, ping_roles: bool = False) -> None:
    """New-week / first-post path. Edits the persistent panel in place (no full repost);
    `ping_roles=True` adds a single ping line."""
    await _asched_sync_panel(bot_client, ping_roles=ping_roles)


async def _asched_refresh_layout(bot_client) -> None:
    """Periodic refresh — edits header + meet cards in place, no ping, no repost."""
    await _asched_sync_panel(bot_client, ping_roles=False)


async def _asched_rsvp_toggle(interaction: discord.Interaction, slot_key: str) -> None:
    try:
        await interaction.response.defer(ephemeral=True)
    except Exception:
        pass
    sched = _asched_load()
    slot  = sched.get("days", {}).get(slot_key)
    if not isinstance(slot, dict):
        return await interaction.followup.send("That meet is no longer on the schedule.", ephemeral=True)
    mt = _parse_meet_ts(slot.get("day", "TBD"), slot.get("time", "TBD"))
    if mt and mt < int(utc_now().timestamp()):
        return await interaction.followup.send("That meet has already happened.", ephemeral=True)

    att = _asched_attendees(slot)
    uid = interaction.user.id
    if uid in att:
        att.remove(uid)
        joined = False
    else:
        att.append(uid)
        joined = True
    try:
        _asched_save(sched)
    except Exception:
        pass

    # Live-update the single consolidated panel (counts + button labels)
    try:
        if interaction.message:
            await interaction.message.edit(
                embed=_asched_build_header_embed(interaction.guild),
                view=_asched_build_rsvp_view(sched),
            )
    except Exception:
        pass

    theme = slot.get("class", "the meet")
    when  = f" — <t:{mt}:F>" if mt else ""
    if joined:
        await interaction.followup.send(
            f"✅ You're on the list for **{theme}**{when}. See you there! 🏎️", ephemeral=True
        )
    else:
        await interaction.followup.send(f"Removed you from **{theme}**.", ephemeral=True)


@bot.command(name="setschedulebanner", aliases=["schedulebanner", "setschedbanner"])
async def setschedulebanner(ctx, *, url: str = None):
    """Leadership: set or clear the wide banner image on the weekly schedule embed."""
    if not any(r.id in _LEADERSHIP_HOST_ROLE_IDS for r in getattr(ctx.author, "roles", [])):
        return await ctx.send("🚫 Only leadership can set the schedule banner.")
    arg = (url or "").strip()
    if not arg and ctx.message.attachments:
        arg = ctx.message.attachments[0].url
    if arg.lower() in ("clear", "off", "none", "remove"):
        data["schedule_banner_url"] = ""
        save_data(data)
        await _asched_try_live_refresh()
        return await ctx.send("✅ Custom banner cleared — back to the rotating DIFF meet banners.")
    if not arg.startswith("http"):
        return await ctx.send(
            "Usage: `!setschedulebanner <image URL>` (or `clear` to revert to the rotating defaults).\n"
            "Use a permanent hosted link — Discord attachment URLs expire."
        )
    data["schedule_banner_url"] = arg
    save_data(data)
    await _asched_try_live_refresh()
    await ctx.send("✅ Schedule banner updated — it'll show on the weekly schedule embed.")


async def _asched_try_live_refresh() -> None:
    """Re-edit the live schedule layout immediately, if one is posted."""
    try:
        await _asched_refresh_layout(bot)
    except Exception:
        pass


async def _asched_post_finalized(bot_client) -> None:
    """New-week announce: update the persistent panel in place and drop a single role-ping line."""
    await _asched_render_layout(bot_client, ping_roles=True)


@tasks.loop(minutes=15)
async def _asched_refresh_loop():
    """Re-edit the live weekly schedule layout so NEXT badge + past-meet ticks stay current."""
    try:
        await _asched_refresh_layout(bot)
    except Exception as _e:
        print(f"[AutoSched] refresh loop error: {_e}")


@_asched_refresh_loop.before_loop
async def _asched_refresh_before():
    await bot.wait_until_ready()


class _ASchedReminderBtn(discord.ui.Button):
    def __init__(self):
        super().__init__(
            label="Send Reminders",
            emoji="📣",
            style=discord.ButtonStyle.primary,
            custom_id="diff_auto_sched_remind",
            row=1,
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        is_staff = any(
            r.id in _LEADERSHIP_HOST_ROLE_IDS
            for r in getattr(interaction.user, "roles", [])
        )
        if not is_staff:
            return await interaction.response.send_message("Only staff can send meet reminders.", ephemeral=True)
        schedule = _asched_load()
        lines = []
        for day in _HRSVP_DAYS:
            entry    = schedule["days"].get(day, {})
            host_id  = entry.get("host_id")
            host_str = _readable_host(interaction.guild, host_id) or "*TBD*"
            cls_val  = entry.get('class', 'TBD')
            time_val = entry.get('time', 'TBD')
            date_val = entry.get('day', '')
            meet_ts  = _parse_meet_ts(date_val, time_val) if date_val and time_val != 'TBD' else None
            when_str = f"<t:{meet_ts}:F>  ·  <t:{meet_ts}:R>" if meet_ts else f"🕒 {time_val}"
            lines.append(f"**{day}** — 🎮 {cls_val} | 📅 {when_str} | 👤 {host_str}")
        remind_embed = discord.Embed(
            title="📅 Upcoming DIFF Meets — This Week's Schedule",
            description="\n".join(lines),
            color=discord.Color.blurple(),
            timestamp=utc_now(),
        )
        remind_embed.set_footer(text="DIFF Meets • Check the schedule channel for full details")
        everyone_ch = bot.get_channel(1047335231826436166)
        if isinstance(everyone_ch, discord.TextChannel):
            guild = interaction.guild
            notify_role = guild.get_role(NOTIFY_ROLE_ID) if guild else None
            ping = notify_role.mention if notify_role else ""
            try:
                await everyone_ch.send(content=ping or None, embed=remind_embed)
                await interaction.response.send_message("✅ Meet reminders posted to everyone chat.", ephemeral=True)
            except Exception as _e:
                await interaction.response.send_message(f"Failed to post reminder: {_e}", ephemeral=True)
        else:
            await interaction.response.send_message("Everyone chat channel not found.", ephemeral=True)


class _ASchedSubmitBtn(discord.ui.Button):
    def __init__(self):
        super().__init__(
            label="Submit to Roll Call",
            emoji="📤",
            style=discord.ButtonStyle.success,
            custom_id=_ASCHED_SUBMIT_ID,
            row=2,
        )

    async def callback(self, interaction: discord.Interaction):
        is_staff = any(
            r.id in _LEADERSHIP_ROLE_IDS
            for r in getattr(interaction.user, "roles", [])
        ) or getattr(getattr(interaction.user, "guild_permissions", None), "administrator", False)
        if not is_staff:
            await interaction.response.send_message("Only staff can submit the schedule to the roll call.", ephemeral=True)
            return
        guild = interaction.guild
        if not guild:
            await interaction.response.send_message("Server not found.", ephemeral=True)
            return
        schedule = _asched_load()
        rc_meets = []
        for idx, day in enumerate(_HRSVP_DAYS, 1):
            entry = schedule["days"].get(day, {})
            rc_meets.append({
                "meet_number": idx,
                "class_name": entry.get("class", "TBD"),
                "start_time": entry.get("time", "TBD"),
                "host_id": entry.get("host_id"),
                "date_text": entry.get("day", day),
                "is_finalized": False,
            })
        await _rc_sync_from_schedule(guild, rc_meets)
        await interaction.response.send_message(
            "✅ Schedule submitted to the roll call — class, time, and host updated for all 3 meets.",
            ephemeral=True,
        )


class _ASchedOverrideModal(discord.ui.Modal, title="🛠️ Override Schedule Slot"):
    slot_input = discord.ui.TextInput(
        label="Which slot? (Meet 1 / Meet 2 / Meet 3)",
        placeholder="e.g. Meet 1",
        required=True,
        max_length=10,
    )
    host_input = discord.ui.TextInput(
        label="Host user ID or @mention",
        placeholder="e.g. 123456789012345678",
        required=True,
        max_length=32,
    )
    day_time_input = discord.ui.TextInput(
        label="Day & Time",
        placeholder="e.g. Sunday 8:00 PM ET  or  <t:1234567890:F>",
        required=True,
        max_length=60,
    )
    class_input = discord.ui.TextInput(
        label="Class / Theme (blank = Open Class)",
        placeholder="e.g. JDM  |  Muscle  |  Euro  |  Open Class",
        required=False,
        max_length=100,
    )

    async def on_submit(self, interaction: discord.Interaction) -> None:
        import re as _re
        import traceback as _tb
        try:
            slot_raw  = self.slot_input.value.strip()
            host_raw  = self.host_input.value.strip()
            dt_raw    = self.day_time_input.value.strip()
            class_val = (self.class_input.value or "").strip() or "Open Class"

            slot_name = next((d for d in _HRSVP_DAYS if slot_raw.lower() in d.lower()), None)
            if not slot_name:
                return await interaction.response.send_message(
                    f"❌ Unknown slot '{slot_raw}'. Use: Meet 1, Meet 2, or Meet 3.", ephemeral=True
                )
            m = _re.search(r"(\d{15,20})", host_raw)
            if not m:
                return await interaction.response.send_message(
                    "❌ Couldn't parse a user ID. Paste their ID or @mention.", ephemeral=True
                )
            host_id = int(m.group(1))
            guild   = interaction.guild
            member  = guild.get_member(host_id) if guild else None

            # Defer before any async network calls
            await interaction.response.defer(ephemeral=True)

            if not member:
                try:
                    member = await guild.fetch_member(host_id)
                except Exception:
                    return await interaction.followup.send(
                        f"❌ Member {host_id} not found in this server.", ephemeral=True
                    )

            parts    = dt_raw.split(None, 1)
            day_val  = parts[0].capitalize() if parts else dt_raw
            time_raw = parts[1] if len(parts) > 1 else dt_raw
            time_val = time_raw.strip()

            schedule = _asched_load()
            slot     = schedule["days"].setdefault(slot_name, {})
            slot.update({"host_id": host_id, "host_status": "yes",
                         "day": day_val, "time": time_val, "class": class_val,
                         "host_name": member.display_name if member else None})
            slot["locked"] = True   # lock so Rebuild Schedule doesn't overwrite
            # Manual edit: drop any pinned timestamp so the new (possibly
            # identical-text) day/time re-parses fresh instead of reusing a
            # stale pin from a previous week.
            slot.pop("pinned_ts", None)
            slot.pop("pinned_sig", None)
            schedule["updated_at"] = utc_now().isoformat()
            _asched_save(schedule)

            # ── Inject synthetic HRSVP entry so the availability panel reflects the override ──
            try:
                hrsvp = _hrsvp_load()
                uid_str = str(host_id)
                synthetic = {"uid": uid_str, "day": day_val, "time": time_val, "theme": class_val}
                for day_key in _HRSVP_DAYS:
                    bucket = hrsvp.setdefault(day_key, {"yes": [], "no": [], "maybe": []})
                    # Remove this host from all slots first (clean slate)
                    for b in ("yes", "no", "maybe"):
                        bucket[b] = [e for e in bucket.get(b, [])
                                     if _hrsvp_uid(e) != uid_str]
                # Add as confirmed yes for the overridden slot
                hrsvp.setdefault(slot_name, {"yes": [], "no": [], "maybe": []})["yes"].append(synthetic)
                _hrsvp_save(hrsvp)
            except Exception as _he:
                print(f"[OverrideSlot] HRSVP inject failed: {_he}")

            try:
                await _asched_update_panel(interaction.client)
            except Exception as _pe:
                print(f"[OverrideSlot] Schedule panel update failed: {_pe}")

            try:
                await _hrsvp_update_panel(interaction.client)
            except Exception as _pe:
                print(f"[OverrideSlot] HRSVP panel update failed: {_pe}")

            all_filled = all(schedule["days"].get(d, {}).get("host_id") for d in _HRSVP_DAYS)
            if all_filled:
                try:
                    await _asched_post_finalized(interaction.client)
                except Exception as _fe:
                    print(f"[OverrideSlot] Post finalized failed: {_fe}")

            try:
                _hrel_track_confirmed(str(host_id))
            except Exception:
                pass

            try:
                ov_embed = discord.Embed(
                    title=f"📅 You've Been Manually Assigned — {slot_name}",
                    description="Leadership has assigned you to host this meet slot.",
                    color=discord.Color.blurple(),
                    timestamp=utc_now(),
                )
                ov_embed.add_field(name="🗓 Day",   value=day_val,   inline=True)
                ov_embed.add_field(name="🕒 Time",  value=time_val,  inline=True)
                ov_embed.add_field(name="🎮 Class", value=class_val, inline=True)
                ov_embed.set_footer(text="DIFF Meets • Host Schedule — questions? Contact leadership.")
                await member.send(embed=ov_embed)
            except (discord.Forbidden, Exception):
                pass

            fin_note = "\n📢 All slots confirmed — schedule posted to #upcoming-meet." if all_filled else ""
            await interaction.followup.send(
                f"✅ **{slot_name}** overridden → {member.mention}\n"
                f"📅 {day_val}  🕒 {time_val}  🎮 {class_val}{fin_note}",
                ephemeral=True,
            )
        except Exception as _err:
            print(f"[OverrideSlot] on_submit error: {_err}")
            _tb.print_exc()
            try:
                if not interaction.response.is_done():
                    await interaction.response.send_message(
                        f"❌ Override failed: {_err}", ephemeral=True
                    )
                else:
                    await interaction.followup.send(
                        f"❌ Override failed: {_err}", ephemeral=True
                    )
            except Exception:
                pass

    async def on_error(self, interaction: discord.Interaction, error: Exception) -> None:
        import traceback as _tb
        print(f"[OverrideSlot Modal] on_error: {error}")
        _tb.print_exc()
        try:
            if not interaction.response.is_done():
                await interaction.response.send_message(
                    f"❌ Override failed: {error}", ephemeral=True
                )
            else:
                await interaction.followup.send(
                    f"❌ Override failed: {error}", ephemeral=True
                )
        except Exception:
            pass


class _ASchedOverrideBtn(discord.ui.Button):
    def __init__(self):
        super().__init__(
            label="Override Slot",
            emoji="🛠️",
            style=discord.ButtonStyle.secondary,
            custom_id="diff_asched_override",
            row=1,
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        try:
            user   = interaction.user
            roles  = getattr(user, "roles", [])
            perms  = getattr(user, "guild_permissions", None)
            is_admin = getattr(perms, "administrator", False)
            is_owner = (
                interaction.guild is not None
                and interaction.guild.owner_id == getattr(user, "id", None)
            )
            is_staff = is_admin or is_owner or any(
                r.id in _LEADERSHIP_HOST_ROLE_IDS
                for r in roles
            )
            if not is_staff:
                return await interaction.response.send_message(
                    "Only leadership can override schedule slots.", ephemeral=True
                )
            await interaction.response.send_modal(_ASchedOverrideModal())
        except Exception as _e:
            print(f"[OverrideBtn] callback error: {_e}")
            import traceback as _tb; _tb.print_exc()
            try:
                if not interaction.response.is_done():
                    await interaction.response.send_message(f"❌ Override failed to open: {_e}", ephemeral=True)
                else:
                    await interaction.followup.send(f"❌ Override failed to open: {_e}", ephemeral=True)
            except Exception:
                pass


class _ASchedPingNonRespondersBtn(discord.ui.Button):
    def __init__(self):
        super().__init__(
            label="Ping Non-Responders",
            emoji="📩",
            style=discord.ButtonStyle.secondary,
            custom_id="diff_asched_ping_nonresponders",
            row=2,
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        is_staff = any(
            r.id in _LEADERSHIP_ROLE_IDS
            for r in getattr(interaction.user, "roles", [])
        )
        if not is_staff:
            return await interaction.response.send_message(
                "Only leadership can ping non-responders.", ephemeral=True
            )
        guild = interaction.guild
        if not guild:
            return await interaction.response.send_message("Server not found.", ephemeral=True)

        data   = _hrsvp_load()
        responded_uids: set = set()
        for day in _HRSVP_DAYS:
            slot = data.get(day, {})
            for status in ("yes", "no", "maybe"):
                for e in slot.get(status, []):
                    responded_uids.add(_hrsvp_uid(e))

        host_role = guild.get_role(HOST_ROLE_ID)
        if not host_role:
            return await interaction.response.send_message("Host role not found.", ephemeral=True)

        non_responders = [m for m in host_role.members if str(m.id) not in responded_uids and not m.bot]
        if not non_responders:
            return await interaction.response.send_message(
                "✅ All hosts have submitted their availability this week!", ephemeral=True
            )

        # Defer immediately — DM loop can take several seconds
        await interaction.response.defer(ephemeral=True)

        dm_embed = discord.Embed(
            title="📋 Host Availability Reminder",
            description=(
                "Hey! You haven't submitted your availability for this week's meet schedule yet.\n\n"
                f"Please head to <#{HOST_RSVP_CHANNEL_ID}> and mark your availability "
                "for **Meet 1, Meet 2, and Meet 3**.\n\n"
                "• ✅ **Available** — mark which slots you can host\n"
                "• ❌ **Unavailable** — let leadership know you can't this week\n"
                "• ❓ **Maybe** — note your preference and we'll follow up\n\n"
                "Tap **My Status** on the panel to see what you've already submitted."
            ),
            color=discord.Color.orange(),
            timestamp=utc_now(),
        )
        dm_embed.set_footer(text="DIFF Meets • Host Availability Reminder")

        sent, failed = 0, 0
        for member in non_responders:
            try:
                await member.send(embed=dm_embed)
                sent += 1
                await asyncio.sleep(1)
            except Exception:
                failed += 1

        await interaction.followup.send(
            f"📩 Reminded **{sent}** host{'s' if sent != 1 else ''} via DM."
            + (f" ({failed} had DMs closed)" if failed else ""),
            ephemeral=True,
        )


class AutoScheduleView(discord.ui.View):
    def __init__(self, bot_ref=None):
        super().__init__(timeout=None)
        self._bot_ref = bot_ref
        self.add_item(_ASchedReminderBtn())
        self.add_item(_ASchedOverrideBtn())
        self.add_item(_ASchedPingNonRespondersBtn())
        self.add_item(_ASchedSubmitBtn())

    @discord.ui.button(label="Refresh", emoji="🔄", style=discord.ButtonStyle.secondary, custom_id=_ASCHED_REFRESH_ID)
    async def refresh_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        await _asched_update_panel(interaction.client)
        await interaction.response.send_message("Schedule panel refreshed.", ephemeral=True)

    @discord.ui.button(label="Rebuild Schedule", emoji="🧠", style=discord.ButtonStyle.primary, custom_id=_ASCHED_REBUILD_ID)
    async def rebuild_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        is_staff = any(
            r.id in _LEADERSHIP_HOST_ROLE_IDS
            for r in getattr(interaction.user, "roles", [])
        )
        if not is_staff:
            await interaction.response.send_message("Only staff can rebuild the schedule.", ephemeral=True)
            return
        # Heavy work below (panel rebuild, finalized post, RC sync, per-host DMs)
        # easily exceeds Discord's 3s ack window — defer first, reply via followup.
        await interaction.response.defer(ephemeral=True)
        schedule = _asched_build()
        await _asched_update_panel(interaction.client)
        # Only auto-post to upcoming-meet when every slot has a confirmed host
        all_filled = all(schedule["days"].get(d, {}).get("host_id") for d in _HRSVP_DAYS)
        if all_filled:
            await _asched_post_finalized(interaction.client)
        if interaction.guild:
            rc_meets = []
            for idx, day in enumerate(_HRSVP_DAYS, 1):
                entry = schedule["days"].get(day, {})
                rc_meets.append({
                    "meet_number": idx,
                    "class_name": entry.get("class", "TBD"),
                    "start_time": entry.get("time", "TBD"),
                    "host_id": entry.get("host_id"),
                    "date_text": entry.get("day", "TBD"),
                    "is_finalized": False,
                })
            await _rc_sync_from_schedule(interaction.guild, rc_meets)

            # DM each assigned host their meet details
            for day in _HRSVP_DAYS:
                entry = schedule["days"].get(day, {})
                host_id = entry.get("host_id")
                if not host_id:
                    continue
                host_member = interaction.guild.get_member(int(host_id))
                if not host_member:
                    continue
                # Cache the display name so the public embed never shows a raw ID
                entry["host_name"] = host_member.display_name
                try:
                    dm_embed = discord.Embed(
                        title=f"📅 You've Been Assigned — {day}",
                        description="You have been assigned as the host for the upcoming meet schedule.",
                        color=discord.Color.blurple(),
                        timestamp=utc_now(),
                    )
                    dm_embed.add_field(name="🗓 Day", value=entry.get("day", "TBD"), inline=True)
                    dm_embed.add_field(name="🕒 Time", value=entry.get("time", "TBD"), inline=True)
                    dm_embed.add_field(name="🎮 Class", value=entry.get("class", "TBD"), inline=True)
                    dm_embed.set_footer(text="DIFF Meets • Host Schedule — questions? Contact leadership.")
                    await host_member.send(embed=dm_embed)
                except discord.Forbidden:
                    pass
                except Exception as _dme:
                    print(f"[AutoSched] DM to host {host_id} failed: {_dme}")
                _hrel_track_confirmed(str(host_id))
            _asched_save(schedule)  # persist host_name fields written above

        _slots_filled = sum(1 for d in _HRSVP_DAYS if schedule["days"].get(d, {}).get("host_id"))
        _rebuild_msg = "✅ Schedule rebuilt and hosts have been DM'd their assignments."
        if all_filled:
            _rebuild_msg += f"\n📢 All 3 slots confirmed — schedule auto-posted to <#{UPCOMING_MEET_CHANNEL_ID}>."
        else:
            _rebuild_msg += f"\n⚠️ {_slots_filled}/{len(_HRSVP_DAYS)} slots filled — schedule will auto-post to <#{UPCOMING_MEET_CHANNEL_ID}> once all slots are confirmed."
        await interaction.followup.send(_rebuild_msg, ephemeral=True)


def _asched_is_sched_msg(msg: discord.Message, bot_id: int) -> bool:
    if msg.author.id != bot_id:
        return False
    for row in msg.components:
        for child in row.children:
            cid = getattr(child, "custom_id", "") or ""
            if cid in {_ASCHED_REFRESH_ID, _ASCHED_REBUILD_ID}:
                return True
    return False


async def _asched_resolve_console_channel(bot_client) -> "discord.TextChannel | None":
    channel = bot_client.get_channel(HOST_RSVP_CHANNEL_ID)
    if not isinstance(channel, discord.TextChannel):
        try:
            channel = await bot_client.fetch_channel(HOST_RSVP_CHANNEL_ID)
        except Exception:
            return None
    return channel if isinstance(channel, discord.TextChannel) else None


def _asched_get_console_ids(schedule: dict) -> dict:
    v = schedule.get("console_message_ids")
    return dict(v) if isinstance(v, dict) else {}


async def _asched_render_console(bot_client) -> None:
    """Delete any existing builder messages, then post header (controls) + one card per meet.
    Only touches messages carrying the builder's buttons plus the stored card ids — the Host
    Availability panel in the same channel uses `hrsvp_` ids and is left alone."""
    channel = await _asched_resolve_console_channel(bot_client)
    if channel is None:
        return
    bot_id = bot_client.user.id

    sched   = _asched_load()
    stored  = [v for v in _asched_get_console_ids(sched).values() if v]
    deleted: set = set()
    for mid in stored:
        try:
            m = await channel.fetch_message(int(mid))
            await m.delete()
            deleted.add(int(mid))
        except Exception:
            pass
    try:
        async for msg in channel.history(limit=40):
            if msg.id in deleted:
                continue
            if _asched_is_sched_msg(msg, bot_id):
                try:
                    await msg.delete()
                except Exception:
                    pass
    except Exception:
        pass

    new_ids: dict = {}
    try:
        header = await channel.send(
            embed=_asched_build_console_header_embed(),
            view=AutoScheduleView(bot_client),
        )
        new_ids["header"] = header.id
        for idx, day in enumerate(_HRSVP_DAYS, start=1):
            mm = await channel.send(embed=_asched_build_console_meet_embed(idx, day))
            new_ids[day] = mm.id
        sched = _asched_load()
        sched["console_message_ids"] = new_ids
        _asched_save(sched)
    except Exception as e:
        print(f"[AutoSched] console post failed: {e}")


async def _asched_update_panel(bot_client) -> None:
    """Edit builder header + meet cards in place; full repost if anything is missing."""
    channel = await _asched_resolve_console_channel(bot_client)
    if channel is None:
        return
    try:
        _ = _asched_build_console_header_embed()
    except Exception as _be:
        print(f"[AutoSched] Build embed error: {_be}")
        return

    sched    = _asched_load()
    ids      = _asched_get_console_ids(sched)
    expected = {"header"} | set(_HRSVP_DAYS)

    if set(ids.keys()) != expected:
        await _asched_render_console(bot_client)
        return

    try:
        hm = await channel.fetch_message(int(ids["header"]))
        await hm.edit(embed=_asched_build_console_header_embed(), view=AutoScheduleView(bot_client))
    except discord.NotFound:
        return await _asched_render_console(bot_client)
    except Exception:
        pass

    for idx, day in enumerate(_HRSVP_DAYS, start=1):
        try:
            mm = await channel.fetch_message(int(ids[day]))
            await mm.edit(embed=_asched_build_console_meet_embed(idx, day))
        except discord.NotFound:
            return await _asched_render_console(bot_client)
        except Exception:
            pass


# -------------------------------------------------------
# Weekly host DM reminder — every Sunday at 12 PM ET
# -------------------------------------------------------
_HOST_TEAM_CHANNEL_ID = 1486228191243669646


def _hrsvp_responded_uids() -> set:
    """Return set of user IDs who have responded to any meet slot this week."""
    data = _hrsvp_load()
    uids: set = set()
    for day in _HRSVP_DAYS:
        slot = data.get(day, {})
        for bucket in ("yes", "no", "maybe"):
            for entry in slot.get(bucket, []):
                uids.add(_hrsvp_uid(entry))
    return uids


_weekly_reminder_sent_date: str = ""   # in-memory guard — survives loop restarts but not process restarts
_host_weekly_reminder_first_run: bool = True   # always skip the immediate fire on loop start


async def _do_host_weekly_reminder(force: bool = False) -> bool:
    """Send the weekly host availability reminder.

    Returns True if the reminder was actually sent, False if skipped.
    force=True bypasses the Sunday-noon guard (for manual/staff triggers).
    """
    try:
        from zoneinfo import ZoneInfo
        now_et = datetime.now(ZoneInfo("America/New_York"))
    except Exception:
        return False

    if not force:
        if now_et.weekday() != 6 or now_et.hour < 12:
            return False

    # Deduplicate — one blast per calendar day max (unless forced)
    global _weekly_reminder_sent_date
    today_str = now_et.strftime("%Y-%m-%d")

    # In-memory guard — catches duplicates within the same process lifetime
    if not force and _weekly_reminder_sent_date == today_str:
        return False

    # Persistent guard — catches duplicates across restarts (if data file is intact)
    sched = _asched_load()
    if not force and sched.get("_reminder_last_sent") == today_str:
        _weekly_reminder_sent_date = today_str  # sync the in-memory guard too
        return False

    _weekly_reminder_sent_date = today_str
    sched["_reminder_last_sent"] = today_str
    _asched_save(sched)

    guild = next((g for g in bot.guilds if g.id == GUILD_ID), None)
    if not guild:
        return False
    host_role = guild.get_role(HOST_ROLE_ID)
    if not host_role:
        return False

    panel_url = f"https://discord.com/channels/{GUILD_ID}/{HOST_RSVP_CHANNEL_ID}"

    # Hosts who haven't responded yet
    responded = _hrsvp_responded_uids()
    pending = [m for m in host_role.members if str(m.id) not in {str(u) for u in responded}]

    # ── Channel post ──────────────────────────────────────────
    host_ch = guild.get_channel(_HOST_TEAM_CHANNEL_ID)
    if isinstance(host_ch, discord.TextChannel):
        ch_embed = discord.Embed(
            title="📅 New Week — Mark Your Availability!",
            description=(
                "A new DIFF Meet week has started **(Sunday–Saturday)**.\n\n"
                f"📌 **[Open the Host Availability Panel]({panel_url})**\n\n"
                "Use the buttons to mark:\n"
                "✅ **Available** — include your time, day, and class\n"
                "❌ **Unavailable** — can't host this week\n"
                "❓ **Maybe** — unsure, check back later\n\n"
                "*Leadership will rebuild the schedule once responses are in.*"
            ),
            color=discord.Color.blurple(),
            timestamp=utc_now(),
        )
        ch_embed.set_thumbnail(url=DIFF_LOGO_URL)
        ch_embed.set_footer(text="DIFF Meets • Weekly Host Reminder — Sunday 12 PM ET")
        if pending:
            pending_mentions = " ".join(m.mention for m in pending)
            ch_embed.add_field(
                name="⏳ Still needs to respond",
                value=pending_mentions,
                inline=False,
            )
        try:
            await host_ch.send(embed=ch_embed)
        except Exception as _ce:
            print(f"[HostReminder] Channel post failed: {_ce}")

    # ── DM only hosts who haven't responded ──────────────────
    dm_embed = discord.Embed(
        title="📅 New Week — Mark Your Availability!",
        description=(
            "Hey! A new DIFF Meet week has started **(Sunday–Saturday)**.\n\n"
            "You haven't marked your availability yet — please do so when you can.\n\n"
            f"📌 **[Open the Host Availability Panel]({panel_url})**\n\n"
            "✅ **Available** — include your time, day, and class\n"
            "❌ **Unavailable** — can't host this week\n"
            "❓ **Maybe** — unsure, check back later\n\n"
            "*Leadership will rebuild the schedule once responses are in.*"
        ),
        color=discord.Color.blurple(),
        timestamp=utc_now(),
    )
    dm_embed.set_thumbnail(url=DIFF_LOGO_URL)
    dm_embed.set_footer(text="DIFF Meets • Weekly Host Reminder — Sunday 12 PM ET")

    sent = failed = 0
    for member in pending:
        try:
            await member.send(embed=dm_embed)
            sent += 1
            await asyncio.sleep(1)
        except discord.Forbidden:
            failed += 1
        except Exception as _e:
            print(f"[HostReminder] DM to {member.id} failed: {_e}")
            failed += 1
    print(f"[HostReminder] Weekly reminder — {sent} DMs delivered, {failed} failed, {len(host_role.members) - len(pending)} already responded.")
    if failed > 0:
        try:
            logs_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
            if isinstance(logs_ch, discord.TextChannel):
                await logs_ch.send(embed=discord.Embed(
                    title="⚠️ Host Reminder — DM Failures",
                    description=(
                        f"**{failed}** host(s) could not receive the weekly availability reminder DM "
                        f"(DMs likely closed).\n\n"
                        f"✅ Delivered: {sent} · ❌ Failed: {failed}"
                    ),
                    color=discord.Color.orange(),
                    timestamp=datetime.now(_EST_TZ),
                ).set_footer(text="DIFF Meets • Host Reminder System"))
        except Exception:
            pass

    # ── Color team reminder ───────────────────────────────────
    color_role = guild.get_role(COLOR_TEAM_ROLE_ID)
    color_ch   = guild.get_channel(COLOR_TEAM_POST_CHANNEL_ID)
    color_panel_url = f"https://discord.com/channels/{GUILD_ID}/{COLOR_SUBMISSION_CHANNEL_ID}"

    color_embed = discord.Embed(
        title="🎨 New Week — Submit Your Crew Color!",
        description=(
            "Hey! A new week has started. If you have a color to submit for crew review, now's the time.\n\n"
            f"📌 **[Open the Color Submission Panel]({color_panel_url})**\n\n"
            "**What to include:**\n"
            "• Color name\n"
            "• HEX code (e.g. `#FF9742`)\n"
            "• Image link of your preview car\n\n"
            "Voting goes live **Tuesday ~12 PM ET** and the winner is announced **Monday ~12 PM ET**.\n\n"
            "*Keep it clean, realistic, and meet-ready.*"
        ),
        color=discord.Color.og_blurple(),
        timestamp=utc_now(),
    )
    color_embed.set_thumbnail(url=DIFF_LOGO_URL)
    color_embed.set_footer(text="DIFF Meets • Color Team — Weekly Submission Reminder")

    # Channel post
    if isinstance(color_ch, discord.TextChannel):
        ping = color_role.mention if color_role else ""
        try:
            await color_ch.send(content=ping or None, embed=color_embed)
        except Exception as _cce:
            print(f"[ColorReminder] Channel post failed: {_cce}")

    # DM color team members
    if color_role:
        cs = cd = 0
        for member in color_role.members:
            try:
                await member.send(embed=color_embed)
                cs += 1
                await asyncio.sleep(1)
            except discord.Forbidden:
                cd += 1
            except Exception as _dme:
                print(f"[ColorReminder] DM to {member.id} failed: {_dme}")
                cd += 1
        print(f"[ColorReminder] Weekly reminder — {cs} delivered, {cd} failed.")
    return True


async def __host_weekly_reminder_loop_logic():
    """Every 30 min: check if it's Sunday ≥12 PM ET and send the reminder if not yet sent today."""
    global _host_weekly_reminder_first_run
    if _host_weekly_reminder_first_run:
        _host_weekly_reminder_first_run = False
        return  # always skip the immediate fire when the loop starts on bot startup
    await _do_host_weekly_reminder(force=False)

@tasks.loop(minutes=30)
async def _host_weekly_reminder_loop():
    _loop_success('_host_weekly_reminder_loop')
    try:
        await run_with_timeout('_host_weekly_reminder_loop', __host_weekly_reminder_loop_logic(), timeout=120)
    except Exception as _lte:
        await _handle_loop_error('_host_weekly_reminder_loop', _lte, _host_weekly_reminder_loop)
@_host_weekly_reminder_loop.error
async def __host_weekly_reminder_loop_on_error(error: Exception) -> None:
    await _handle_loop_error('_host_weekly_reminder_loop', error, _host_weekly_reminder_loop)
@_host_weekly_reminder_loop.before_loop
async def _before_host_weekly_reminder():
    await bot.wait_until_ready()


@bot.command(name="sendhostavailabilityreminder", aliases=["hostreminder"])
async def _cmd_send_host_reminder(ctx: commands.Context):
    """Manually trigger the Sunday host availability reminder (staff only)."""
    is_staff = (
        isinstance(ctx.author, discord.Member)
        and (
            ctx.author.guild_permissions.administrator
            or any(r.id in _LEADERSHIP_ROLE_IDS for r in ctx.author.roles)
        )
    )
    if not is_staff:
        await ctx.send("Staff only.", delete_after=6)
        return
    try:
        await ctx.message.delete()
    except Exception:
        pass
    msg = await ctx.send("📤 Sending host availability reminder…")
    sent = await _do_host_weekly_reminder(force=True)
    if sent:
        await msg.edit(content="✅ Host availability reminder sent to the channel and all pending hosts.")
    else:
        await msg.edit(content="⚠️ Reminder couldn't be sent (no guild or host role found).")


# =========================
# HOST AUTOMATION DB
# =========================
_HAUTO_DB_PATH = os.path.join("diff_data", "diff_host_automation.db")
_HAUTO_BLACKLIST_POINT_PENALTY = 10
_HAUTO_NO_SHOW_PENALTY = 3
_HAUTO_SUCCESS_POINTS = 5
_HAUTO_ONTIME_BONUS = 2


class _HostAutoDB:
    def __init__(self):
        os.makedirs("diff_data", exist_ok=True)
        self.conn = sqlite3.connect(_HAUTO_DB_PATH, check_same_thread=False)
        self.conn.row_factory = sqlite3.Row
        self._setup()

    def _setup(self):
        cur = self.conn.cursor()
        cur.execute("""
            CREATE TABLE IF NOT EXISTS blacklist_entries (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                guild_id INTEGER NOT NULL,
                user_id INTEGER,
                discord_tag TEXT,
                psn TEXT,
                reason TEXT NOT NULL,
                evidence TEXT,
                severity TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'active',
                submitted_by_id INTEGER NOT NULL,
                submitted_by_tag TEXT NOT NULL,
                removed_host_role INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS host_points (
                guild_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                points INTEGER NOT NULL DEFAULT 0,
                penalties INTEGER NOT NULL DEFAULT 0,
                last_updated TEXT NOT NULL,
                PRIMARY KEY (guild_id, user_id)
            )
        """)
        self.conn.commit()

    def add_blacklist(self, guild_id, user_id, discord_tag, psn, reason, evidence,
                      severity, submitted_by_id, submitted_by_tag, removed_host_role):
        cur = self.conn.cursor()
        cur.execute("""
            INSERT INTO blacklist_entries
                (guild_id, user_id, discord_tag, psn, reason, evidence, severity, status,
                 submitted_by_id, submitted_by_tag, removed_host_role, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, ?)
        """, (guild_id, user_id, discord_tag, psn, reason, evidence, severity,
              submitted_by_id, submitted_by_tag, 1 if removed_host_role else 0,
              datetime.now(timezone.utc).isoformat()))
        self.conn.commit()
        return int(cur.lastrowid)

    def is_blacklisted(self, guild_id, user_id):
        cur = self.conn.cursor()
        cur.execute("""
            SELECT 1 FROM blacklist_entries
            WHERE guild_id=? AND user_id=? AND status='active' LIMIT 1
        """, (guild_id, user_id))
        return cur.fetchone() is not None

    def get_active_entry(self, guild_id, user_id):
        cur = self.conn.cursor()
        cur.execute("""
            SELECT * FROM blacklist_entries
            WHERE guild_id=? AND user_id=? AND status='active'
            ORDER BY id DESC LIMIT 1
        """, (guild_id, user_id))
        return cur.fetchone()

    def search(self, guild_id, query):
        like = f"%{query.lower()}%"
        cur = self.conn.cursor()
        cur.execute("""
            SELECT * FROM blacklist_entries
            WHERE guild_id=? AND status='active'
            AND (LOWER(COALESCE(discord_tag,'')) LIKE ?
                 OR LOWER(COALESCE(psn,'')) LIKE ?
                 OR LOWER(COALESCE(reason,'')) LIKE ?
                 OR CAST(COALESCE(user_id,0) AS TEXT) LIKE ?)
            ORDER BY id DESC LIMIT 10
        """, (guild_id, like, like, like, like))
        return cur.fetchall()

    def clear_entry(self, guild_id, entry_id):
        cur = self.conn.cursor()
        cur.execute("""
            UPDATE blacklist_entries SET status='cleared'
            WHERE guild_id=? AND id=? AND status='active'
        """, (guild_id, entry_id))
        self.conn.commit()
        return cur.rowcount > 0

    def adjust_points(self, guild_id, user_id, delta, penalty_delta=0):
        cur = self.conn.cursor()
        cur.execute("""
            INSERT INTO host_points (guild_id, user_id, points, penalties, last_updated)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(guild_id, user_id)
            DO UPDATE SET
                points=points+excluded.points,
                penalties=penalties+excluded.penalties,
                last_updated=excluded.last_updated
        """, (guild_id, user_id, delta, penalty_delta, datetime.now(timezone.utc).isoformat()))
        self.conn.commit()
        cur.execute("SELECT points FROM host_points WHERE guild_id=? AND user_id=?",
                    (guild_id, user_id))
        row = cur.fetchone()
        return int(row["points"]) if row else 0

    def top_points(self, guild_id, limit=10):
        cur = self.conn.cursor()
        cur.execute("""
            SELECT user_id, points, penalties FROM host_points
            WHERE guild_id=?
            ORDER BY points DESC, penalties ASC LIMIT ?
        """, (guild_id, limit))
        return cur.fetchall()


_hauto_db = _HostAutoDB()


def host_performance_tier(points: int) -> str:
    if points >= 30:
        return "🟢 Elite Host"
    if points >= 15:
        return "🔵 Active Host"
    if points >= 0:
        return "🟡 Inconsistent"
    return "🔴 At Risk"


async def _hauto_update_leaderboard(guild: discord.Guild) -> None:
    channel = guild.get_channel(LEADERBOARD_CHANNEL_ID)
    if not isinstance(channel, discord.TextChannel):
        return
    rows = _hauto_db.top_points(guild.id, 10)
    lines = []
    medals = {1: "🥇", 2: "🥈", 3: "🥉"}
    for idx, row in enumerate(rows, start=1):
        member = guild.get_member(int(row["user_id"]))
        mention = member.mention if member else f"<@{row['user_id']}>"
        pts = int(row["points"])
        pen = int(row["penalties"])
        tier = host_performance_tier(pts)
        prefix = medals.get(idx, f"**{idx}.**")
        lines.append(f"{prefix} {mention} — {pts} pts | {pen} penalties | {tier}")
    embed = discord.Embed(
        title="🏆 DIFF Host Performance Leaderboard",
        description="\n".join(lines) if lines else "*No host performance data yet.*",
        color=discord.Color.gold(),
        timestamp=datetime.now(timezone.utc),
    )
    embed.set_footer(text="Auto-updated host rankings • DIFF Host System")
    try:
        async for msg in channel.history(limit=10):
            if msg.author.id == bot.user.id and msg.embeds and "Leaderboard" in (msg.embeds[0].title or ""):
                await msg.edit(embed=embed)
                return
        await channel.send(embed=embed)
    except Exception as e:
        print(f"[Leaderboard] update failed: {e}")


