def get_activity(member: discord.Member) -> str:
    if member.activity and getattr(member.activity, "name", None):
        return member.activity.name
    return "Idle"


def build_channel_link(guild_id: int, channel_id: int) -> str:
    return f"https://discord.com/channels/{guild_id}/{channel_id}"


def is_host_or_admin(interaction: discord.Interaction) -> bool:
    if interaction.guild is None or not isinstance(interaction.user, discord.Member):
        return False
    if interaction.user.guild_permissions.administrator:
        return True
    host_role_id = data.get("host_role_id")
    if host_role_id is None:
        return False
    return any(role.id == host_role_id for role in interaction.user.roles)


def get_warning_count(member_id: int) -> int:
    return len(data.get("warnings", {}).get(str(member_id), []))


def _ordinal(n: int) -> str:
    if 11 <= (n % 100) <= 13:
        return f"{n}th"
    return f"{n}" + {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")


def _next_warn_id() -> int:
    data.setdefault("warn_id_counter", 0)
    data["warn_id_counter"] += 1
    save_data(data)
    return data["warn_id_counter"]


def add_warning(member_id: int, moderator_id: int, reason: str, proof: str = "", warn_id: int = 0):
    warnings = data.setdefault("warnings", {})
    member_warnings = warnings.setdefault(str(member_id), [])
    member_warnings.append(
        {
            "warn_id": warn_id,
            "reason": reason,
            "proof": proof,
            "moderator_id": moderator_id,
            "timestamp": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC"),
        }
    )
    save_data(data)


def clear_warnings_for_member(member_id: int):
    warnings = data.setdefault("warnings", {})
    warnings[str(member_id)] = []
    save_data(data)


def get_member_status_emoji(member: discord.Member) -> str:
    if member.status == discord.Status.online:
        return "🟢"
    if member.status == discord.Status.idle:
        return "🌙"
    if member.status == discord.Status.dnd:
        return "⛔"
    return "⚫"


def sort_members_for_hierarchy(members):
    status_order = {
        discord.Status.online: 0,
        discord.Status.idle: 1,
        discord.Status.dnd: 2,
        discord.Status.offline: 3,
    }
    return sorted(
        members,
        key=lambda m: (
            status_order.get(m.status, 4),
            m.display_name.lower(),
        ),
    )


def format_role_member_field(role: discord.Role, label: str) -> tuple:
    """Returns (field_name, field_value) for a role in the hierarchy panel."""
    members = sort_members_for_hierarchy(role.members)

    if not members:
        return label, f"{role.mention}\n*No members assigned yet.*"

    lines = [f"{get_member_status_emoji(m)} {m.mention}" for m in members]

    # Trim to Discord's 1024-char field limit
    trimmed: list[str] = []
    length = 0
    for line in lines:
        cost = len(line) + (1 if trimmed else 0)
        if length + cost > 900:
            trimmed.append(f"*…and {len(lines) - len(trimmed)} more*")
            break
        trimmed.append(line)
        length += cost

    return label, role.mention + "\n" + "\n".join(trimmed)


def format_role_member_lines(role: discord.Role) -> str:
    """Legacy wrapper — kept for any callers outside build_hierarchy_embeds."""
    _, value = format_role_member_field(role, role.mention)
    return role.mention + "\n" + value


def _count_hierarchy_statuses(guild: discord.Guild) -> dict:
    all_role_ids = [
        LEADER_ROLE_ID, CO_LEADER_ROLE_ID, MANAGER_ROLE_ID,
        HOST_ROLE_ID, DESIGNER_TEAM_ROLE_ID, CONTENT_TEAM_ROLE_ID, COLOR_TEAM_ROLE_ID,
    ]
    seen: set = set()
    counts = {"online": 0, "idle": 0, "dnd": 0, "offline": 0}
    for role_id in all_role_ids:
        role = guild.get_role(role_id)
        if not role:
            continue
        for m in role.members:
            if m.id in seen:
                continue
            seen.add(m.id)
            if m.status == discord.Status.online:
                counts["online"] += 1
            elif m.status == discord.Status.idle:
                counts["idle"] += 1
            elif m.status == discord.Status.dnd:
                counts["dnd"] += 1
            else:
                counts["offline"] += 1
    return counts


def build_hierarchy_embeds(guild: discord.Guild):
    role_sections = [
        (
            "👑 DIFF Leadership",
            "Server leadership & management team.",
            [
                (LEADER_ROLE_ID,     "👑 Founder"),
                (CO_LEADER_ROLE_ID,  "🛡️ Executive"),
                (MANAGER_ROLE_ID,    "🔴 Server Operations"),
                (DEVELOPER_ROLE_ID,  "🛠️ Developer"),
            ],
        ),
        (
            "🔨 Moderation Team",
            "Staff who keep the server safe and running.",
            [
                (SENIOR_ADMIN_ROLE_ID,   "⭐ Senior Admin"),
                (ADMINISTRATOR_ROLE_ID,  "🔰 Administrator"),
                (LEAD_MOD_ROLE_ID,       "🔷 Lead Moderator"),
                (MODERATOR_ROLE_ID,      "🔹 Moderator"),
                (JUNIOR_MOD_ROLE_ID,     "🔸 Junior Moderator"),
                (TICKET_SUPPORT_ROLE_ID, "🎫 Ticket Support"),
            ],
        ),
        (
            "🏁 Meet Operations",
            "Host team & meet coordinators.",
            [
                (HOST_ROLE_ID, "🏁 Meet Host"),
            ],
        ),
        (
            "🎨 Creative Teams",
            f"Design, content, and color crew.\nNeed help? Open <#{SUPPORT_TICKETS_CHANNEL_ID}>.",
            [
                (DESIGNER_TEAM_ROLE_ID, "🎨 Designer"),
                (CONTENT_TEAM_ROLE_ID,  "📸 Content Creator"),
                (COLOR_TEAM_ROLE_ID,    "🌈 Color Team"),
            ],
        ),
    ]

    status_counts = _count_hierarchy_statuses(guild)
    status_bar = (
        f"🟢 **{status_counts['online']}** online\u2003"
        f"🌙 **{status_counts['idle']}** idle\u2003"
        f"⛔ **{status_counts['dnd']}** DND\u2003"
        f"⚫ **{status_counts['offline']}** offline"
    )

    embeds = []
    for index, (title, desc, entries) in enumerate(role_sections):
        description = (
            f"{desc}\n━━━━━━━━━━━━━━━━━━━━━━\n{status_bar}"
            if index == 0
            else desc
        )
        embed = discord.Embed(
            title=title,
            description=description,
            color=0xC9A227,
        )
        embed.set_thumbnail(url=DIFF_LOGO_URL)
        if index == 0 and DIFF_BANNER_URL:
            embed.set_image(url=DIFF_BANNER_URL)

        for role_id, label in entries:
            role = guild.get_role(role_id)
            if role is None:
                embed.add_field(name=label, value="*Role not found.*", inline=False)
                continue
            field_name, field_value = format_role_member_field(role, label)
            embed.add_field(name=field_name, value=field_value, inline=False)

        embed.set_footer(text="Different Meets • Hierarchy Panel  |  Live status • Updates every 2 min")
        embed.timestamp = datetime.now(timezone.utc)
        embeds.append(embed)

    return embeds


_HIERARCHY_OLD_TITLE = "🏆 DIFF SERVER HIERARCHY"
_HIERARCHY_FOOTER    = "Different Meets • Hierarchy Panel  |  Live status • Updates every 2 min"
_HIERARCHY_NEW_TITLES = {"👑 DIFF Leadership", "🔨 Moderation Team", "🏁 Meet Operations", "🎨 Creative Teams"}


def _is_hierarchy_msg(msg: discord.Message, bot_user) -> bool:
    if msg.author != bot_user:
        return False
    if not msg.embeds:
        return False
    e = msg.embeds[0]
    footer_text = e.footer.text if e.footer else ""
    return (
        footer_text == _HIERARCHY_FOOTER
        or e.title == _HIERARCHY_OLD_TITLE
        or e.title in _HIERARCHY_NEW_TITLES
    )


async def cleanup_extra_hierarchy_messages(channel: discord.TextChannel, keep_ids: list[int]):
    try:
        async for msg in channel.history(limit=50):
            if msg.id in keep_ids:
                continue
            if _is_hierarchy_msg(msg, bot.user):
                try:
                    await msg.delete()
                except Exception:
                    pass
            elif msg.content and "DIFF Hierarchy Panel" in msg.content:
                try:
                    await msg.delete()
                except Exception:
                    pass
    except Exception:
        pass


async def find_existing_hierarchy_messages(channel: discord.TextChannel, expected_count: int):
    found = []
    try:
        async for msg in channel.history(limit=50, oldest_first=True):
            if _is_hierarchy_msg(msg, bot.user):
                found.append(msg)
                if len(found) == expected_count:
                    break
    except Exception:
        return []
    return found


async def find_existing_status_panel_message(channel: discord.TextChannel):
    try:
        async for msg in channel.history(limit=50, oldest_first=True):
            if msg.author != bot.user:
                continue
            if msg.embeds and any(embed.title == "🏁 DIFF Meets Crew" for embed in msg.embeds):
                return msg
    except Exception:
        return None
    return None


async def cleanup_extra_status_panel_messages(channel: discord.TextChannel, keep_id: int | None):
    try:
        async for msg in channel.history(limit=50):
            if msg.author != bot.user:
                continue
            if keep_id and msg.id == keep_id:
                continue
            if msg.embeds and any(embed.title == "🏁 DIFF Meets Crew" for embed in msg.embeds):
                try:
                    await msg.delete()
                except Exception:
                    pass
    except Exception:
        pass


