async def _host_board_auto_refresh_loop_logic():
    """Edit the Host Activity Board embed every 5 min — never posts new messages."""
    guild = bot.guilds[0] if bot.guilds else None
    if guild is None:
        return
    channel_id = data.get("status_channel_id")
    if not channel_id:
        return
    channel = guild.get_channel(channel_id)
    if not isinstance(channel, discord.TextChannel):
        return

    # PSN integration was removed — Sony's API was unstable enough to freeze
    # the bot's event loop via default-thread-pool starvation, requiring
    # physical Pi reboots.  Board now always renders the static status embed.
    embed = build_status_embed(guild)

    msg_id = data.get("panel_message_id")
    target = None
    if msg_id:
        try:
            target = await channel.fetch_message(int(msg_id))
        except discord.NotFound:
            target = None
    if target is None:
        target = await find_existing_status_panel_message(channel)
    if target is not None:
        try:
            # NOTE: do NOT pass a new view= here. The HostBoardRefreshView is
            # already registered persistently in setup_hook so its custom_id
            # ('diff_host_board_refresh_v1') is bound. Re-attaching a fresh
            # instance every 5 min was potentially accumulating view objects
            # inside discord.py's internal store and was a suspect cause of
            # the bot-freeze that required a physical Pi reboot.
            await target.edit(embed=embed)
        except Exception as _e:
            print(f"[BoardLoop] edit failed: {_e}")

