async def post_or_refresh_hierarchy_panel(guild: discord.Guild):
    channel = guild.get_channel(HIERARCHY_CHANNEL_ID)
    if channel is None:
        return False, "Hierarchy channel not found."

    embeds = build_hierarchy_embeds(guild)
    support_view = build_hierarchy_support_view()
    hierarchy_message_ids = data.get("hierarchy_message_ids", [])

    saved_messages = []
    if hierarchy_message_ids:
        for message_id in hierarchy_message_ids:
            try:
                msg = await channel.fetch_message(message_id)
                saved_messages.append(msg)
            except discord.NotFound:
                saved_messages = []
                break

    if saved_messages and len(saved_messages) == len(embeds):
        for i, (msg, embed) in enumerate(zip(saved_messages, embeds)):
            is_last = i == len(embeds) - 1
            await msg.edit(
                content="## DIFF Hierarchy Panel" if i == 0 else None,
                embed=embed,
                view=support_view if is_last else discord.ui.View(),
            )
        await cleanup_extra_hierarchy_messages(channel, [msg.id for msg in saved_messages])
        return True, channel.mention

    # recover old single-id storage if present
    legacy_message_id = data.get("hierarchy_message_id")
    if not saved_messages and legacy_message_id:
        try:
            legacy_message = await channel.fetch_message(legacy_message_id)
            saved_messages = [legacy_message]
        except discord.NotFound:
            saved_messages = []

    if saved_messages:
        for msg in saved_messages:
            try:
                await msg.delete()
            except Exception:
                pass

    new_ids = []
    for index, embed in enumerate(embeds):
        content = "## DIFF Hierarchy Panel" if index == 0 else None
        is_last = index == len(embeds) - 1
        msg = await channel.send(content=content, embed=embed, view=support_view if is_last else None)
        new_ids.append(msg.id)

    data["hierarchy_message_ids"] = new_ids
    data["hierarchy_message_id"] = new_ids[0] if new_ids else None
    save_data(data)
    await cleanup_extra_hierarchy_messages(channel, new_ids)
    return True, channel.mention


async def _auto_refresh_hierarchy_panel(guild: discord.Guild):
    await asyncio.sleep(15)
    hierarchy_message_ids = data.get("hierarchy_message_ids", [])
    if not hierarchy_message_ids:
        return
    channel = guild.get_channel(HIERARCHY_CHANNEL_ID)
    if channel is None:
        return
    embeds = build_hierarchy_embeds(guild)
    support_view = build_hierarchy_support_view()
    saved_messages = []
    for message_id in hierarchy_message_ids:
        try:
            msg = await channel.fetch_message(message_id)
            saved_messages.append(msg)
        except discord.NotFound:
            return
    if len(saved_messages) != len(embeds):
        return
    for i, (msg, embed) in enumerate(zip(saved_messages, embeds)):
        is_last = i == len(embeds) - 1
        try:
            await msg.edit(
                content="## DIFF Hierarchy Panel" if i == 0 else None,
                embed=embed,
                view=support_view if is_last else discord.ui.View(),
            )
        except Exception:
            pass


class HostBoardRefreshView(discord.ui.View):
    """Persistent view for the Refresh button on the Host Activity Board message."""
    def __init__(self) -> None:
        super().__init__(timeout=None)

    @discord.ui.button(label="Refresh", emoji="🔄", style=discord.ButtonStyle.secondary, custom_id="diff_host_board_refresh_v1")
    async def refresh(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not interaction.guild:
            return await interaction.response.send_message("Guild only.", ephemeral=True)
        await interaction.response.defer(ephemeral=True, thinking=False)
        try:
            embed = build_status_embed(interaction.guild)
            await interaction.message.edit(embed=embed, view=HostBoardRefreshView())
            await interaction.followup.send("✅ Board refreshed.", ephemeral=True)
        except Exception as _e:
            try:
                await interaction.followup.send(f"Refresh failed: {_e}", ephemeral=True)
            except Exception:
                pass


def build_status_embed(guild: discord.Guild) -> discord.Embed:
    gta_hosts:     list[tuple] = []   # (line, last_ts, meets)
    online_hosts:  list[tuple] = []
    offline_hosts: list[tuple] = []

    hp_data    = _hp_load()
    host_stats = hp_data.get("host_stats", {})

    def _last_session_ts(uid: int) -> int:
        s    = host_stats.get(str(uid), {})
        last = s.get("last_session_at")
        if last:
            try:
                return int(datetime.fromisoformat(str(last).replace("Z", "+00:00")).timestamp())
            except Exception:
                pass
        return 0

    def _tier_label(meets: int) -> str:
        if meets >= 15: return "💎 Elite"
        if meets >= 5:  return "🔥 Senior"
        if meets >= 1:  return "⭐ Active"
        return ""  # no tier shown for hosts with 0 career meets

    # ── Weekly session summary from closed HP sessions ────────────────────────
    _now_et     = datetime.now(_EST_TZ)
    _week_start = (_now_et - timedelta(days=_now_et.weekday())).replace(
        hour=0, minute=0, second=0, microsecond=0
    )
    _week_start_ts = _week_start.timestamp()
    _weekly: dict[int, int] = {}
    try:
        for _s in hp_data.get("sessions", {}).values():
            if not _s.get("ended"):
                continue
            _sat = _s.get("started_at", "")
            if not _sat:
                continue
            try:
                _sts = datetime.fromisoformat(str(_sat).replace("Z", "+00:00")).timestamp()
                if _sts >= _week_start_ts:
                    _hid = int(_s.get("host_id", 0))
                    if _hid:
                        _weekly[_hid] = _weekly.get(_hid, 0) + 1
            except Exception:
                pass
    except Exception:
        pass
    _total_week    = sum(_weekly.values())
    _top_host_name = ""
    if _weekly:
        _top_id        = max(_weekly, key=lambda k: _weekly[k])
        _top_m         = guild.get_member(_top_id)
        _top_host_name = _top_m.display_name if _top_m else ""

    # ── Next meet from weekly schedule (for top "Next Meet" field) ───────────
    _next_meet_value = ""
    try:
        _sched = _asched_load()
        _now_ts = int(time.time())
        _candidates = []
        for _day_key in _HRSVP_DAYS:
            _entry = _sched.get("days", {}).get(_day_key, {})
            _mt = _parse_meet_ts(_entry.get("day", "TBD"), _entry.get("time", "TBD"))
            if _mt and _mt > _now_ts:
                _candidates.append((_mt, _entry))
        if _candidates:
            _candidates.sort(key=lambda x: x[0])
            _mt, _entry = _candidates[0]
            _cls = _entry.get("class", "TBD")
            _hid = _entry.get("host_id")
            _host_disp = ""
            if _hid:
                _hm = guild.get_member(int(_hid))
                if _hm:
                    _host_disp = _hm.display_name.split(" | ")[0].strip()
            _next_meet_value = f"🏎️ **{_cls}** · <t:{_mt}:F> (<t:{_mt}:R>)"
            if _host_disp:
                _next_meet_value += f"\n👤 Host: **{_host_disp}**"
    except Exception:
        pass

    # ── Build host rows ───────────────────────────────────────────────────────
    _now_utc_dt = datetime.now(timezone.utc)
    for host in data["hosts"]:
        uid     = host["discord_id"]
        member  = guild.get_member(uid)
        meets   = get_user_stats(uid).get("meets_hosted", 0)
        tier    = _tier_label(meets)
        tier_part  = f" · {tier}" if tier else ""
        last_ts = _last_session_ts(uid)

        # PSN profile link (kept — easy click-through for members)
        profile = host.get("profile_url", "")
        link    = f" [↗]({profile})" if profile else ""

        # Only show meet count when non-zero
        meets_part = f" · **{meets}m**" if meets > 0 else ""

        # No last-active timestamp on rows (was confusing — looked like
        # Discord activity but was actually last HP session / join date).
        last_part = ""

        # 🕸️ inactivity warning: no HP session in 30+ days (only if we have any history)
        inactive_prefix = ""
        if last_ts and (time.time() - last_ts) / 86400 >= 30:
            inactive_prefix = "🕸️ "

        if member:
            is_online = member.status != discord.Status.offline
            activity  = get_activity(member)
            name      = member.display_name
        else:
            is_online = False
            activity  = ""
            name      = host["name"]

        # Strip role suffix (e.g. "Frostyy2003 | Owner" → "Frostyy2003")
        # and box the PSN in a code-block so it pops visually.
        psn_only = name.split(" | ")[0].strip()
        name_md  = f"`{psn_only}`"
        activity_lower = (activity or "").lower()

        if is_online:
            if "grand theft auto" in activity_lower or "gta" in activity_lower:
                line = f"🎮 {name_md}{tier_part}{meets_part}{link}"
                gta_hosts.append((line, last_ts, meets))
            else:
                act_label = (activity[:20] + "…") if len(activity or "") > 22 else (activity or "Online")
                line = f"🟡 {name_md} · `{act_label}`{meets_part}{link}"
                online_hosts.append((line, last_ts, meets))
        else:
            line = f"🔴 {inactive_prefix}{name_md}{tier_part}{meets_part}{last_part}{link}"
            offline_hosts.append((line, last_ts, meets))

    # Sort offline: most recently active first, then by career meets desc
    offline_hosts.sort(key=lambda x: (x[1], x[2]), reverse=True)

    # ── Labelled count header ────────────────────────────────────────────────
    n_gta     = len(gta_hosts)
    n_online  = len(online_hosts)
    n_offline = len(offline_hosts)
    n_total   = n_gta + n_online + n_offline

    pill_line = (
        f"🎮 GTA: **{n_gta}**  ·  🟡 Away: **{n_online}**  ·  "
        f"🔴 Offline: **{n_offline}**  ·  Total: **{n_total}**"
    )

    # Dynamic embed color
    if n_gta > 0:
        color = 0x43B581
    elif n_online > 0:
        color = 0xFAA61A
    else:
        color = 0xED4245

    embed = discord.Embed(
        title="🏁 DIFF Host Activity Board",
        description=pill_line,
        color=color,
    )
    embed.set_thumbnail(url=DIFF_LOGO_URL)

    # Next Meet field (top — ties host board to schedule)
    if _next_meet_value:
        embed.add_field(name="🏁 Next Meet", value=_next_meet_value, inline=False)

    # Always show In GTA (empty state included so absence is obvious)
    if gta_hosts:
        embed.add_field(
            name=f"🎮 In GTA  ({n_gta})",
            value="\n\n".join(l for l, _, _ in gta_hosts),
            inline=False,
        )
    else:
        embed.add_field(
            name="🎮 In GTA  (0)",
            value="*No hosts currently playing GTA.*",
            inline=False,
        )
    if online_hosts:
        embed.add_field(
            name=f"🟡 Away  ({n_online})",
            value="\n\n".join(l for l, _, _ in online_hosts),
            inline=False,
        )
    if offline_hosts:
        embed.add_field(
            name=f"🔴 Offline  ({n_offline})",
            value="\n\n".join(l for l, _, _ in offline_hosts),
            inline=False,
        )

    embed.set_footer(text="DIFF Meets · auto-updates every 5 min · 🕸️ = inactive 30+ days")
    embed.timestamp = datetime.now(timezone.utc)
    return embed


