# =============================================================
# ROLL CALL — PUBLIC REMINDERS + AUTO-STRIKE STATE
# =============================================================
_RC_REMINDER_STATE_FILE = os.path.join("diff_data", "diff_rc_reminder_state.json")
_RC_STRIKE_STATE_FILE   = os.path.join("diff_data", "diff_rc_strike_state.json")
_RC_STRIKE_THRESHOLD    = 2   # consecutive missed weeks before a member becomes a strike candidate


def _rc_reminder_state_load() -> dict:
    try:
        with open(_RC_REMINDER_STATE_FILE) as f:
            return json.load(f)
    except Exception:
        return {}


def _rc_reminder_state_save(data: dict) -> None:
    _atomic_json_save(_RC_REMINDER_STATE_FILE, data)


def _rc_strike_state_load() -> dict:
    try:
        with open(_RC_STRIKE_STATE_FILE) as f:
            return json.load(f)
    except Exception:
        return {}


def _rc_strike_state_save(data: dict) -> None:
    _atomic_json_save(_RC_STRIKE_STATE_FILE, data)


_RC_WEEK_SNAPSHOT_FILE = os.path.join("diff_data", "diff_rc_week_snapshot.json")


def _rc_week_snapshot_load() -> dict:
    try:
        with open(_RC_WEEK_SNAPSHOT_FILE) as f:
            return json.load(f)
    except Exception:
        return {}


def _rc_week_snapshot_save(guild_id: int) -> None:
    """Snapshot the current week's roll-call responses to disk. Called immediately
    BEFORE the weekly reset wipes the DB, so the Monday-00:15 pruning report (which
    runs AFTER the Monday-00:00 wipe) can read the real ending-week data instead of
    an empty table — the wipe-then-report ordering used to mark the ENTIRE crew as
    'no response' every week, zero all streaks, and mass-generate strike candidates."""
    from zoneinfo import ZoneInfo as _ZI
    from datetime import timedelta as _td
    now_est = datetime.now(_ZI("America/New_York"))
    monday  = (now_est - _td(days=now_est.weekday())).strftime("%Y-%m-%d")
    # No fallback here: if the DB read fails we must NOT write an empty snapshot
    # (the report would prefer it and falsely mark everyone no-response). Let the
    # exception propagate — the caller logs it and the report falls back to live DB.
    responses = _rc_db.get_all_responses(guild_id)
    _atomic_json_save(_RC_WEEK_SNAPSHOT_FILE, {
        "guild_id": str(guild_id),
        "week_monday": monday,
        "saved_at": now_est.isoformat(),
        "responses": {str(k): v for k, v in (responses or {}).items()},
    })


def _rc_strike_exempt(member) -> bool:
    """Leadership and hosts are never auto-struck for missing roll call."""
    try:
        rids = {r.id for r in member.roles}
    except Exception:
        return False
    if rids & _LEADERSHIP_ROLE_IDS:
        return True
    if HOST_ROLE_ID in rids:
        return True
    return False


def _rc_compute_non_responders(guild):
    """Returns (crew_role, [members who haven't responded to ANY meet this week])."""
    crew_role = guild.get_role(CREW_MEMBER_ROLE_ID)
    if not crew_role:
        return None, []
    responses = _rc_db.get_all_responses(guild.id)
    responded: set = set()
    for mr in responses.values():
        for uid_list in mr.values():
            responded.update(uid_list)
    non = [m for m in crew_role.members if not m.bot and m.id not in responded]
    return crew_role, non


def _rc_build_public_reminder(guild, tag_individuals: bool = False):
    """Builds (ping_content, embed, non_responders) for a public roll-call nudge,
    or None if every crew member has already responded."""
    crew_role, non = _rc_compute_non_responders(guild)
    if crew_role is None or not non:
        return None
    n = len(non)
    plural = "s" if n != 1 else ""
    rc_url = f"https://discord.com/channels/{GUILD_ID}/{ROLL_CALL_CHANNEL_ID}"
    if tag_individuals:
        mentions = " ".join(m.mention for m in non[:50])
        extra = f" + {n - 50} more" if n > 50 else ""
        ping_content = mentions + extra
    else:
        ping_content = crew_role.mention
    embed = discord.Embed(
        title="⏰ Roll Call Reminder",
        description=(
            f"**{n} crew member{plural}** still haven't done this week's roll call.\n\n"
            f"👉 **[Complete it here]({rc_url})** — it only takes a few seconds.\n\n"
            "Roll call resets **Monday**. Repeatedly missing it may result in a **strike**."
        ),
        color=discord.Color.orange(),
        timestamp=datetime.now(_EST_TZ),
    )
    embed.set_footer(text="DIFF Meets • Roll Call System")
    return ping_content, embed, non


@bot.command(name="warn")
async def cmd_warn(ctx: commands.Context, member: discord.Member = None, *, reason: str = None):
    """Leadership-only: issue a formal warning to a member."""
    if not any(r.id in _LEADERSHIP_ROLE_IDS for r in ctx.author.roles):
        return await ctx.reply("Server Operations+ only.", mention_author=False)
    if member is None or reason is None:
        return await ctx.send("Usage: `!warn @user <reason>`", delete_after=10)
    try:
        await ctx.message.delete()
    except Exception:
        pass

    import uuid as _uuid
    warn_id = str(_uuid.uuid4())[:8].upper()
    ts = datetime.now(_EST_TZ).isoformat()
    data = _warnings_load()
    uid_key = str(member.id)
    data.setdefault(uid_key, []).append({
        "id": warn_id,
        "reason": reason,
        "issued_by": ctx.author.id,
        "issued_by_name": ctx.author.display_name,
        "timestamp": ts,
    })
    _warnings_save(data)

    total = len(data[uid_key])

    # DM the member
    try:
        dm_embed = discord.Embed(
            title="⚠️ You have received a formal warning",
            description=(
                f"**Reason:** {reason}\n\n"
                "If you believe this was issued in error, contact leadership."
            ),
            color=discord.Color.red(),
            timestamp=datetime.now(_EST_TZ),
        )
        dm_embed.add_field(name="Warning ID", value=f"`{warn_id}`", inline=True)
        dm_embed.add_field(name="Total Warnings", value=str(total), inline=True)
        dm_embed.set_footer(text="Different Meets • Formal Warning")
        await member.send(embed=dm_embed)
        dm_status = "✅ DM sent"
    except discord.Forbidden:
        dm_status = "❌ DM failed (closed)"

    # Staff log
    logs_ch = ctx.guild.get_channel(STAFF_LOGS_CHANNEL_ID)
    if isinstance(logs_ch, discord.TextChannel):
        log_embed = discord.Embed(
            title="⚠️ Warning Issued",
            color=discord.Color.red(),
            timestamp=datetime.now(_EST_TZ),
        )
        log_embed.add_field(name="Member", value=member.mention, inline=True)
        log_embed.add_field(name="Issued By", value=ctx.author.mention, inline=True)
        log_embed.add_field(name="Warning ID", value=f"`{warn_id}`", inline=True)
        log_embed.add_field(name="Reason", value=reason, inline=False)
        log_embed.add_field(name="Total Warnings", value=str(total), inline=True)
        log_embed.add_field(name="DM Status", value=dm_status, inline=True)
        log_embed.set_footer(text="Different Meets • Warning System")
        await logs_ch.send(embed=log_embed)

    await ctx.send(
        f"⚠️ Warning `{warn_id}` issued to {member.mention} — total: **{total}** · {dm_status}",
        delete_after=15,
    )


