async def _unified_hosthub_post_or_refresh() -> None:
    channel = bot.get_channel(HOST_HUB_CHANNEL_ID)
    if not isinstance(channel, discord.TextChannel):
        try:
            channel = await bot.fetch_channel(HOST_HUB_CHANNEL_ID)
        except Exception:
            return
    if not isinstance(channel, discord.TextChannel):
        return

    embed = _unified_hosthub_embed()
    view = UnifiedHostHubView()

    unified_msg: discord.Message | None = None
    to_delete: list[discord.Message] = []

    async for msg in channel.history(limit=60):
        if msg.author.id != bot.user.id or not msg.embeds:
            continue
        footer_text = msg.embeds[0].footer.text if msg.embeds[0].footer else ""
        embed_title = msg.embeds[0].title or ""
        is_unified = footer_text.startswith(_UNIFIED_HOSTHUB_TAG)
        is_old = (
            footer_text in _UNIFIED_HOSTHUB_OLD_FOOTER_TAGS
            or embed_title in _UNIFIED_HOSTHUB_OLD_TITLES
        )
        if is_unified and unified_msg is None:
            unified_msg = msg
        elif is_unified or is_old:
            to_delete.append(msg)

    for m in to_delete:
        try:
            await m.delete()
        except Exception:
            pass

    if unified_msg:
        try:
            await unified_msg.edit(embed=embed, view=view)
            return
        except Exception:
            pass

    try:
        await channel.send(embed=embed, view=view)
    except Exception as e:
        print(f"[UnifiedHostHub] Post failed: {e}")


# =========================
# AUTO ROLL CALL SYSTEM
# =========================
_RC_DB_PATH = os.path.join("diff_data", "diff_rollcall.db")
_RC_ADMIN_ROLE_IDS = _LEADERSHIP_ROLE_IDS


class _RollCallDB:
    def __init__(self):
        os.makedirs("diff_data", exist_ok=True)
        self.conn = sqlite3.connect(_RC_DB_PATH, check_same_thread=False)
        self.conn.row_factory = sqlite3.Row
        self._setup()

    def _setup(self):
        cur = self.conn.cursor()
        cur.execute("""
            CREATE TABLE IF NOT EXISTS rollcall_panels (
                guild_id INTEGER PRIMARY KEY,
                channel_id INTEGER NOT NULL,
                message_id INTEGER NOT NULL,
                admin_message_id INTEGER,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS rollcall_meets (
                guild_id INTEGER NOT NULL,
                meet_number INTEGER NOT NULL,
                class_name TEXT NOT NULL DEFAULT 'TBD',
                start_time TEXT NOT NULL DEFAULT 'TBD',
                host_id INTEGER,
                date_text TEXT NOT NULL DEFAULT 'TBD',
                is_finalized INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (guild_id, meet_number)
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS rollcall_responses (
                guild_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                meet_number INTEGER NOT NULL,
                status TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                PRIMARY KEY (guild_id, user_id, meet_number)
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS attendance_actual (
                guild_id INTEGER NOT NULL,
                meet_number INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                recorded_at TEXT NOT NULL,
                PRIMARY KEY (guild_id, meet_number, user_id)
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS attendance_stats (
                guild_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                yes_count INTEGER NOT NULL DEFAULT 0,
                maybe_count INTEGER NOT NULL DEFAULT 0,
                no_count INTEGER NOT NULL DEFAULT 0,
                attended_count INTEGER NOT NULL DEFAULT 0,
                no_show_count INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (guild_id, user_id)
            )
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS meet_state (
                guild_id INTEGER NOT NULL,
                meet_number INTEGER NOT NULL,
                attendance_finalized INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (guild_id, meet_number)
            )
        """)
        # Per-meet message layout: one row per posted message (header / meet1-3 / admin)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS rollcall_messages (
                guild_id INTEGER NOT NULL,
                slot TEXT NOT NULL,
                message_id INTEGER NOT NULL,
                PRIMARY KEY (guild_id, slot)
            )
        """)
        self.conn.commit()

    def upsert_panel(self, guild_id, channel_id, message_id, admin_message_id=None):
        now = datetime.now(timezone.utc).isoformat()
        cur = self.conn.cursor()
        cur.execute("""
            INSERT INTO rollcall_panels (guild_id, channel_id, message_id, admin_message_id, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(guild_id) DO UPDATE SET
                channel_id=excluded.channel_id,
                message_id=excluded.message_id,
                admin_message_id=COALESCE(excluded.admin_message_id, rollcall_panels.admin_message_id),
                updated_at=excluded.updated_at
        """, (guild_id, channel_id, message_id, admin_message_id, now, now))
        self.conn.commit()

    def get_panel(self, guild_id):
        cur = self.conn.cursor()
        cur.execute("SELECT * FROM rollcall_panels WHERE guild_id=?", (guild_id,))
        return cur.fetchone()

    def clear_panel(self, guild_id):
        cur = self.conn.cursor()
        cur.execute("DELETE FROM rollcall_panels WHERE guild_id=?", (guild_id,))
        self.conn.commit()

    def set_message(self, guild_id, slot, message_id):
        cur = self.conn.cursor()
        cur.execute("""
            INSERT INTO rollcall_messages (guild_id, slot, message_id)
            VALUES (?, ?, ?)
            ON CONFLICT(guild_id, slot) DO UPDATE SET message_id=excluded.message_id
        """, (guild_id, slot, message_id))
        self.conn.commit()

    def get_messages(self, guild_id) -> dict:
        """Returns {slot: message_id} for this guild's roll-call layout."""
        cur = self.conn.cursor()
        cur.execute("SELECT slot, message_id FROM rollcall_messages WHERE guild_id=?", (guild_id,))
        return {row["slot"]: row["message_id"] for row in cur.fetchall()}

    def clear_messages(self, guild_id):
        cur = self.conn.cursor()
        cur.execute("DELETE FROM rollcall_messages WHERE guild_id=?", (guild_id,))
        self.conn.commit()

    def reset_week(self, guild_id):
        """Full weekly reset: clears RSVP responses, meet details, finalization state,
        and actual-attendance records for the guild.  Cumulative career stats are kept."""
        cur = self.conn.cursor()
        cur.execute("DELETE FROM rollcall_responses  WHERE guild_id=?", (guild_id,))
        cur.execute("DELETE FROM rollcall_meets       WHERE guild_id=?", (guild_id,))
        cur.execute("DELETE FROM attendance_actual    WHERE guild_id=?", (guild_id,))
        cur.execute("DELETE FROM meet_state           WHERE guild_id=?", (guild_id,))
        cur.execute("DELETE FROM rollcall_panels      WHERE guild_id=?", (guild_id,))
        cur.execute("DELETE FROM rollcall_messages    WHERE guild_id=?", (guild_id,))
        self.conn.commit()

    def upsert_meets(self, guild_id, meets: list):
        cur = self.conn.cursor()
        for m in meets:
            cur.execute("""
                INSERT INTO rollcall_meets (guild_id, meet_number, class_name, start_time, host_id, date_text, is_finalized)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(guild_id, meet_number) DO UPDATE SET
                    class_name=excluded.class_name,
                    start_time=excluded.start_time,
                    host_id=excluded.host_id,
                    date_text=excluded.date_text,
                    is_finalized=excluded.is_finalized
            """, (guild_id, m["meet_number"], m.get("class_name", "TBD"), m.get("start_time", "TBD"),
                  m.get("host_id"), m.get("date_text", "TBD"), 1 if m.get("is_finalized") else 0))
            cur.execute("""
                INSERT OR IGNORE INTO meet_state (guild_id, meet_number, attendance_finalized) VALUES (?, ?, 0)
            """, (guild_id, m["meet_number"]))
        self.conn.commit()

    def get_meets(self, guild_id):
        cur = self.conn.cursor()
        cur.execute("SELECT * FROM rollcall_meets WHERE guild_id=? ORDER BY meet_number ASC", (guild_id,))
        return cur.fetchall()

    def set_response(self, guild_id, user_id, meet_number, status):
        now = datetime.now(timezone.utc).isoformat()
        cur = self.conn.cursor()
        cur.execute("SELECT status FROM rollcall_responses WHERE guild_id=? AND user_id=? AND meet_number=?",
                    (guild_id, user_id, meet_number))
        prev_row = cur.fetchone()
        previous = prev_row[0] if prev_row else None
        cur.execute("""
            INSERT INTO rollcall_responses (guild_id, user_id, meet_number, status, updated_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(guild_id, user_id, meet_number) DO UPDATE SET status=excluded.status, updated_at=excluded.updated_at
        """, (guild_id, user_id, meet_number, status, now))
        cur.execute("INSERT OR IGNORE INTO attendance_stats (guild_id, user_id) VALUES (?, ?)", (guild_id, user_id))
        if previous in ("yes", "maybe", "no"):
            cur.execute(f"UPDATE attendance_stats SET {previous}_count = MAX({previous}_count - 1, 0) WHERE guild_id=? AND user_id=?",
                        (guild_id, user_id))
        if status in ("yes", "maybe", "no"):
            cur.execute(f"UPDATE attendance_stats SET {status}_count = {status}_count + 1 WHERE guild_id=? AND user_id=?",
                        (guild_id, user_id))
        self.conn.commit()
        return previous

    def get_counts(self, guild_id, meet_number):
        cur = self.conn.cursor()
        cur.execute("SELECT status, COUNT(*) AS total FROM rollcall_responses WHERE guild_id=? AND meet_number=? GROUP BY status",
                    (guild_id, meet_number))
        counts = {"yes": 0, "maybe": 0, "no": 0}
        for row in cur.fetchall():
            counts[row[0]] = row[1]
        return counts

    def get_all_counts(self, guild_id):
        return {n: self.get_counts(guild_id, n) for n in (1, 2, 3)}

    def get_all_responses(self, guild_id) -> dict:
        """Returns {meet_number: {status: [user_id, ...]}} for meets 1-3."""
        cur = self.conn.cursor()
        cur.execute(
            "SELECT meet_number, status, user_id FROM rollcall_responses "
            "WHERE guild_id=? ORDER BY meet_number, status, updated_at",
            (guild_id,),
        )
        result: dict = {n: {"yes": [], "maybe": [], "no": []} for n in (1, 2, 3)}
        for row in cur.fetchall():
            n, s, uid = row["meet_number"], row["status"], row["user_id"]
            if n in result and s in result[n]:
                result[n][s].append(uid)
        return result

    def set_actual_attendees(self, guild_id, meet_number, user_ids):
        now = datetime.now(timezone.utc).isoformat()
        cur = self.conn.cursor()
        cur.execute("DELETE FROM attendance_actual WHERE guild_id=? AND meet_number=?", (guild_id, meet_number))
        for uid in user_ids:
            cur.execute("INSERT INTO attendance_actual (guild_id, meet_number, user_id, recorded_at) VALUES (?, ?, ?, ?)",
                        (guild_id, meet_number, uid, now))
            cur.execute("INSERT OR IGNORE INTO attendance_stats (guild_id, user_id) VALUES (?, ?)", (guild_id, uid))
        self.conn.commit()

    def finalize_no_shows(self, guild_id, meet_number):
        cur = self.conn.cursor()
        cur.execute("SELECT attendance_finalized FROM meet_state WHERE guild_id=? AND meet_number=?",
                    (guild_id, meet_number))
        row = cur.fetchone()
        if row and row[0] == 1:
            return [], []
        cur.execute("SELECT user_id FROM attendance_actual WHERE guild_id=? AND meet_number=?", (guild_id, meet_number))
        actual = {r[0] for r in cur.fetchall()}
        cur.execute("SELECT user_id FROM rollcall_responses WHERE guild_id=? AND meet_number=? AND status='yes'",
                    (guild_id, meet_number))
        yes_users = {r[0] for r in cur.fetchall()}
        attended = sorted(actual)
        no_shows = sorted(yes_users - actual)
        for uid in attended:
            cur.execute("INSERT OR IGNORE INTO attendance_stats (guild_id, user_id) VALUES (?, ?)", (guild_id, uid))
            cur.execute("UPDATE attendance_stats SET attended_count=attended_count+1 WHERE guild_id=? AND user_id=?", (guild_id, uid))
        for uid in no_shows:
            cur.execute("INSERT OR IGNORE INTO attendance_stats (guild_id, user_id) VALUES (?, ?)", (guild_id, uid))
            cur.execute("UPDATE attendance_stats SET no_show_count=no_show_count+1 WHERE guild_id=? AND user_id=?", (guild_id, uid))
        cur.execute("""
            INSERT INTO meet_state (guild_id, meet_number, attendance_finalized) VALUES (?, ?, 1)
            ON CONFLICT(guild_id, meet_number) DO UPDATE SET attendance_finalized=1
        """, (guild_id, meet_number))
        self.conn.commit()
        return attended, no_shows

    def get_top_attendance(self, guild_id, limit=10):
        cur = self.conn.cursor()
        cur.execute("""
            SELECT * FROM attendance_stats WHERE guild_id=?
            ORDER BY attended_count DESC, yes_count DESC, no_show_count ASC LIMIT ?
        """, (guild_id, limit))
        return cur.fetchall()

    def get_user_stats_row(self, guild_id, user_id):
        cur = self.conn.cursor()
        cur.execute("SELECT * FROM attendance_stats WHERE guild_id=? AND user_id=?", (guild_id, user_id))
        return cur.fetchone()

    def get_all_stats_rows(self, guild_id):
        cur = self.conn.cursor()
        cur.execute("SELECT * FROM attendance_stats WHERE guild_id=?", (guild_id,))
        return cur.fetchall()

    def get_actual_attendees(self, guild_id, meet_number) -> set:
        cur = self.conn.cursor()
        cur.execute("SELECT user_id FROM attendance_actual WHERE guild_id=? AND meet_number=?",
                    (guild_id, meet_number))
        return {r[0] for r in cur.fetchall()}

    def is_attendance_finalized(self, guild_id, meet_number) -> bool:
        """Source of truth for finalization is meet_state.attendance_finalized
        (what finalize_no_shows checks) — NOT rollcall_meets.is_finalized."""
        cur = self.conn.cursor()
        cur.execute("SELECT attendance_finalized FROM meet_state WHERE guild_id=? AND meet_number=?",
                    (guild_id, meet_number))
        row = cur.fetchone()
        return bool(row and row[0] == 1)


_rc_db = _RollCallDB()


def _rc_is_admin(member) -> bool:
    if not isinstance(member, discord.Member):
        return False
    if member.guild_permissions.administrator:
        return True
    return any(r.id in _RC_ADMIN_ROLE_IDS for r in member.roles)


def _rc_build_rollcall_embed(guild: discord.Guild) -> discord.Embed:
    meets        = _rc_db.get_meets(guild.id)
    meets_by_num = {row["meet_number"]: row for row in meets}
    counts       = _rc_db.get_all_counts(guild.id)

    # ── Week range + reset countdown ─────────────────────────
    from datetime import timedelta as _td
    _now_et  = datetime.now(_EST_TZ)
    _monday  = _now_et - _td(days=_now_et.weekday())
    _sunday  = _monday + _td(days=6)
    _week_str = f"{_monday.strftime('%b %d')} – {_sunday.strftime('%b %d, %Y')}"
    _next_monday = (_monday + _td(days=7)).replace(hour=0, minute=0, second=0, microsecond=0)
    _reset_ts = int(_next_monday.timestamp())
    _now_ts   = int(_now_et.timestamp())

    finalized_count = sum(1 for n in (1, 2, 3)
                          if meets_by_num.get(n) and meets_by_num[n]["is_finalized"])
    all_finalized = finalized_count == 3

    color = (0x57F287 if finalized_count == 3
             else 0xFEE75C if finalized_count > 0
             else 0x5865F2)

    description = (
        f"📅 **Week of {_week_str}**\n\n"
        "**All meets this week have been finalized!** 🎉\n"
        "Attendance has been recorded — see you on the track."
        if all_finalized else
        f"📅 **Week of {_week_str}**  •  🔄 Resets <t:{_reset_ts}:R>\n\n"
        "Mark your attendance for each meet below.\n"
        "*No-shows are tracked — respond even if you can't make it.*"
    )

    embed = discord.Embed(
        title="📋 DIFF Auto Roll Call",
        description=description,
        color=color,
        timestamp=datetime.now(timezone.utc),
    )
    if DIFF_LOGO_URL:
        embed.set_thumbnail(url=DIFF_LOGO_URL)
    embed.set_author(
        name="Different Meets",
        icon_url=DIFF_LOGO_URL if DIFF_LOGO_URL else discord.utils.MISSING,
    )

    for n in (1, 2, 3):
        meet         = meets_by_num.get(n)
        c            = counts[n]
        class_name   = meet["class_name"] if meet else "TBD"
        start_time   = meet["start_time"] if meet else "TBD"
        date_text    = meet["date_text"]  if meet else "TBD"
        host_id      = meet["host_id"]    if meet else None
        host_text    = _readable_host(guild, host_id) or "*No host assigned*"
        is_finalized = bool(meet and meet["is_finalized"])

        if is_finalized:
            field_name = f"🏁 Meet {n} — Closed"
            ts_fin = _parse_meet_ts(date_text, start_time)
            when_fin = f"<t:{ts_fin}:F>" if ts_fin else f"📅 {date_text}  🕒 {start_time}"
            field_lines = [
                f"📅 {when_fin}  🎮 {class_name}",
                f"👤 **Host:** {host_text}",
                f"✅ **{c['yes']}** yes  ·  ❓ **{c['maybe']}** maybe  ·  ❌ **{c['no']}** no",
            ]
        else:
            if class_name == "TBD" or start_time == "TBD":
                status = "⏳ Awaiting schedule"
            else:
                status = "📝 Open for RSVP"

            scale        = max(c["yes"] + c["maybe"] + c["no"], 10)
            yes_blocks   = round(c["yes"]   / scale * 10)
            maybe_blocks = round(c["maybe"] / scale * 10)
            bar          = "🟩" * yes_blocks + "🟨" * maybe_blocks + "⬜" * (10 - yes_blocks - maybe_blocks)

            field_name = f"〔{n}〕 Meet {n}"
            ts = _parse_meet_ts(date_text, start_time)
            if ts and status == "📝 Open for RSVP":
                field_lines = [
                    f"**{status}**",
                    f"⏰ <t:{ts}:F>",
                    f"🕐 <t:{ts}:R>",
                    f"🎮 {class_name}",
                    f"👤 **Host:** {host_text}",
                    f"✅ `{c['yes']}` · ❓ `{c['maybe']}` · ❌ `{c['no']}`\n{bar}",
                ]
            else:
                field_lines = [
                    f"**{status}**",
                    f"📅 {date_text}  🕒 {start_time}  🎮 {class_name}",
                    f"👤 **Host:** {host_text}",
                    f"✅ `{c['yes']}` · ❓ `{c['maybe']}` · ❌ `{c['no']}`\n{bar}",
                ]

        embed.add_field(name=field_name, value="\n".join(field_lines), inline=False)

    if not all_finalized:
        embed.add_field(
            name="\u200b",
            value="🧥 Wear your crew jacket  •  🎙️ Join voice if required  •  ⚠️ No-shows are tracked",
            inline=False,
        )
    embed.set_footer(text=f"DIFF • Auto Roll Call System  •  Updated {_now_et.strftime('%-m/%-d/%Y %-I:%M %p')}  •  Use 📊 My RSVP to see your responses")
    return embed


