def _readable_host(guild, host_id) -> str | None:
    """Readable host label that always shows a name. Embed mentions only resolve on
    clients that have the user cached, so some members saw raw <@id> numbers. We lead
    with the display name (always readable) and keep the clickable mention beside it.
    Pass guild=None to resolve against the main guild automatically."""
    if not host_id:
        return None
    g = guild
    if g is None:
        try:
            g = bot.get_guild(GUILD_ID)
        except Exception:
            g = None
    m = None
    try:
        m = g.get_member(int(host_id)) if g else None
    except (TypeError, ValueError):
        m = None
    if m:
        return f"**{m.display_name}** · {m.mention}"
    return f"<@{host_id}>"


def _rc_build_meet_embed(guild: discord.Guild, n: int) -> discord.Embed:
    """One roomy, readable card for a single meet (replaces the old clumped field)."""
    meets_by_num = {row["meet_number"]: row for row in _rc_db.get_meets(guild.id)}
    meet         = meets_by_num.get(n)
    c            = _rc_db.get_counts(guild.id, n)
    class_name   = meet["class_name"] if meet else "TBD"
    start_time   = meet["start_time"] if meet else "TBD"
    date_text    = meet["date_text"]  if meet else "TBD"
    host_id      = meet["host_id"]    if meet else None
    host_text    = _readable_host(guild, host_id) or "*No host assigned*"
    is_finalized = bool(meet and meet["is_finalized"])
    scheduled    = class_name != "TBD" and start_time != "TBD"
    ts           = _parse_meet_ts(date_text, start_time) if scheduled else None

    if is_finalized:
        color       = 0x57F287
        status_line = "🏁 **Closed** — attendance recorded"
    elif not scheduled:
        color       = 0x5865F2
        status_line = "⏳ **Awaiting schedule**"
    else:
        color       = 0x5865F2
        status_line = "📝 **Open for RSVP**"

    title_class = class_name if class_name != "TBD" else "To be announced"
    embed = discord.Embed(
        title=f"〔 Meet {n} 〕  {title_class}",
        color=color,
    )
    if DIFF_LOGO_URL:
        embed.set_thumbnail(url=DIFF_LOGO_URL)

    if ts:
        when_val = f"📆 <t:{ts}:F>\n🕐 <t:{ts}:R>"
    elif scheduled:
        when_val = f"📆 {date_text}\n🕒 {start_time}"
    else:
        when_val = "📆 *Date & time not posted yet*"

    embed.add_field(name="\u200b", value=status_line, inline=False)
    embed.add_field(name="When", value=when_val, inline=True)
    embed.add_field(name="Host", value=host_text, inline=True)

    total        = c["yes"] + c["maybe"] + c["no"]
    scale        = max(total, 10)
    yes_blocks   = round(c["yes"]   / scale * 10)
    maybe_blocks = round(c["maybe"] / scale * 10)
    bar          = "🟩" * yes_blocks + "🟨" * maybe_blocks + "⬜" * (10 - yes_blocks - maybe_blocks)
    embed.add_field(
        name="Attendance",
        value=(
            f"✅ **{c['yes']}** going    ❓ **{c['maybe']}** maybe    ❌ **{c['no']}** out\n"
            f"{bar}"
        ),
        inline=False,
    )
    embed.set_footer(text=f"Meet {n} of 3  •  Tap a button below to RSVP")
    return embed


class _RcFinalizeModal(discord.ui.Modal):
    attendees = discord.ui.TextInput(
        label="Users who actually attended",
        style=discord.TextStyle.paragraph,
        placeholder="Paste mentions or IDs: <@123> <@456>",
        required=False,
        max_length=4000,
    )

    def __init__(self, meet_number: int):
        super().__init__(title=f"Finalize Meet {meet_number} Attendance")
        self.meet_number = meet_number

    async def on_submit(self, interaction: discord.Interaction):
        if not _rc_is_admin(interaction.user):
            await interaction.response.send_message("Staff only.", ephemeral=True)
            return
        raw = self.attendees.value or ""
        user_ids = sorted({int(m) for m in re.findall(r"\d{15,25}", raw)})
        _rc_db.set_actual_attendees(interaction.guild.id, self.meet_number, user_ids)
        attended, no_shows = _rc_db.finalize_no_shows(interaction.guild.id, self.meet_number)
        await _rc_refresh_panel(interaction.guild)
        await _rc_log_attendance(interaction.guild, self.meet_number, attended, no_shows, interaction.user)
        await interaction.response.send_message(
            f"✅ Meet {self.meet_number} finalized. Present: **{len(attended)}** | No-shows: **{len(no_shows)}**",
            ephemeral=True,
        )


class _RcNoShowDisputeView(discord.ui.View):
    """Persistent view sent via DM when a crew member is marked as a no-show."""
    def __init__(self, meet_number: int) -> None:
        super().__init__(timeout=None)
        self.meet_number = meet_number

    @discord.ui.button(
        label="Dispute No-Show",
        style=discord.ButtonStyle.danger,
        emoji="⚠️",
        custom_id="diff_noshow_dispute",
    )
    async def dispute_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        guild = interaction.client.get_guild(GUILD_ID)
        if not guild:
            return await interaction.response.send_message("Could not reach the server. Contact staff directly.", ephemeral=True)
        member = guild.get_member(interaction.user.id)
        if not member:
            return await interaction.response.send_message("You don't appear to be in the DIFF server.", ephemeral=True)
        logs_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
        if isinstance(logs_ch, discord.TextChannel):
            e = discord.Embed(
                title="⚠️ No-Show Dispute",
                description=(
                    f"{member.mention} is disputing their no-show mark for **Meet {self.meet_number}**.\n\n"
                    "Review attendance records and respond directly to them."
                ),
                color=discord.Color.orange(),
                timestamp=datetime.now(_EST_TZ),
            )
            e.set_author(name=member.display_name, icon_url=member.display_avatar.url)
            e.set_footer(text="Different Meets • No-Show Dispute")
            await logs_ch.send(embed=e)
        button.disabled = True
        button.label = "Dispute Submitted"
        await interaction.response.edit_message(view=self)
        await interaction.followup.send(
            "✅ Your dispute has been flagged to leadership. They will review your attendance and be in touch.",
            ephemeral=True,
        )


class _RcBtn(discord.ui.Button):
    """Pi-compatible button for the roll call RSVP panel."""
    _LABELS  = {"yes": "✅", "maybe": "❓", "no": "❌"}
    _STYLES  = {
        "yes":   discord.ButtonStyle.success,
        "maybe": discord.ButtonStyle.secondary,
        "no":    discord.ButtonStyle.danger,
    }
    _DISPLAY = {
        "yes":   "attending",
        "maybe": "maybe",
        "no":    "not attending",
    }

    def __init__(self, meet_number: int, status: str, row: int) -> None:
        super().__init__(
            label=f"Meet {meet_number} {self._LABELS[status]}",
            style=self._STYLES[status],
            custom_id=f"diff_rollcall:{meet_number}:{status}",
            row=row,
        )
        self.meet_number = meet_number
        self.status = status

    async def callback(self, interaction: discord.Interaction) -> None:
        if not interaction.guild or not isinstance(interaction.user, discord.Member):
            return await interaction.response.send_message("Server only.", ephemeral=True)
        # Defer IMMEDIATELY so we get a 15-minute response window.  Doing the
        # sqlite write first can blow past Discord's hard 3-second interaction
        # deadline on a busy Pi and cause "This interaction failed" errors,
        # which is exactly what members were reporting.
        try:
            await interaction.response.defer(ephemeral=True, thinking=False)
        except discord.InteractionResponded:
            pass
        except Exception as _de:
            print(f"[RcBtn] defer failed for {interaction.user}: {_de}")

        try:
            previous = _rc_db.set_response(
                interaction.guild.id, interaction.user.id, self.meet_number, self.status
            )
        except Exception as e:
            print(f"[RcBtn] DB error for {interaction.user} meet {self.meet_number}: {e}")
            previous = None

        # Build a contextual response message
        prev_clean = previous if previous and previous != "none" else None
        new_icon   = self._LABELS[self.status]
        if prev_clean is None:
            msg = f"{new_icon} Marked as **{self._DISPLAY[self.status]}** for **Meet {self.meet_number}**."
        elif prev_clean == self.status:
            msg = f"Already marked as {new_icon} **{self._DISPLAY[self.status]}** for **Meet {self.meet_number}** — no change."
        else:
            old_icon = self._LABELS.get(prev_clean, "⬜")
            msg = f"Updated **Meet {self.meet_number}**: {old_icon} → {new_icon}"

        try:
            await interaction.followup.send(msg, ephemeral=True)
        except Exception as e:
            print(f"[RcBtn] followup send error for {interaction.user}: {e}")

        try:
            await _rc_refresh_panel(interaction.guild)
            await _rc_log_rsvp(
                interaction.guild, interaction.user,
                self.meet_number, previous or "none", self.status,
            )
        except Exception as e:
            print(f"[RcBtn] Post-response error for {interaction.user}: {e}")

        # --- XP: reward RSVP "yes" once per week+meet ---
        if self.status == "yes":
            try:
                await _xp_apply_award(
                    interaction.guild, interaction.user, _XP_PER_RSVP_YES,
                    kind="rsvp", ref=f"{_xp_week_key()}:{self.meet_number}",
                )
            except Exception:
                pass


class _RcMyRsvpBtn(discord.ui.Button):
    def __init__(self) -> None:
        super().__init__(
            label="My RSVP",
            emoji="📊",
            style=discord.ButtonStyle.secondary,
            custom_id="diff_rollcall:my_rsvp",
            row=3,
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        if not interaction.guild or not isinstance(interaction.user, discord.Member):
            return await interaction.response.send_message("Server only.", ephemeral=True)
        # Defer IMMEDIATELY — building the embed reads sqlite twice and can blow past
        # Discord's 3s ack window on a loaded Pi, causing "This interaction failed."
        try:
            await interaction.response.defer(ephemeral=True, thinking=False)
        except discord.InteractionResponded:
            pass
        except Exception as _de:
            print(f"[RcMyRsvp] defer failed for {interaction.user}: {_de}")
        try:
            uid          = interaction.user.id
            guild        = interaction.guild
            responses    = _rc_db.get_all_responses(guild.id)
            meets_by_num = {row["meet_number"]: row for row in _rc_db.get_meets(guild.id)}

            status_emoji  = {"yes": "✅", "maybe": "❓", "no": "❌"}
            status_label  = {"yes": "Attending", "maybe": "Maybe", "no": "Not Attending"}

            answered = []
            for n in (1, 2, 3):
                r = responses.get(n, {})
                found = next((s for s in ("yes", "maybe", "no") if uid in r.get(s, [])), None)
                answered.append(found)

            # Pick embed colour: green = all yes, orange = any maybe, red = any no, grey = no responses
            if all(a == "yes" for a in answered if a):
                color = discord.Color.green()
            elif any(a == "maybe" for a in answered):
                color = discord.Color.orange()
            elif any(a == "no" for a in answered):
                color = discord.Color.red()
            else:
                color = discord.Color.greyple()

            embed = discord.Embed(
                title="📊 Your Roll Call RSVP",
                description="Here's how you've responded for each meet this week.",
                color=color,
                timestamp=datetime.now(timezone.utc),
            )

            for n, found in zip((1, 2, 3), answered):
                meet  = meets_by_num.get(n)
                cls   = meet["class_name"] if meet else "TBD"
                dt    = meet["date_text"]  if meet else ""
                st    = meet["start_time"] if meet else "TBD"
                ts    = _parse_meet_ts(dt, st) if meet and cls != "TBD" else None

                if ts:
                    when = f"<t:{ts}:F>\n<t:{ts}:R>"
                elif cls != "TBD":
                    when = f"📅 {dt}  🕒 {st}"
                else:
                    when = "*Schedule not posted yet*"

                status_str = (
                    f"{status_emoji[found]} **{status_label[found]}**"
                    if found else "⬜ *No response yet*"
                )

                embed.add_field(
                    name=f"Meet {n}  ·  🎮 {cls}",
                    value=f"{when}\n{status_str}",
                    inline=False,
                )

            embed.set_footer(text="Update anytime by clicking the buttons above  •  Only you can see this")
            await interaction.followup.send(embed=embed, ephemeral=True)
        except discord.InteractionResponded:
            pass
        except Exception as e:
            print(f"[RcMyRsvp] Error for {interaction.user}: {e}")
            import traceback; traceback.print_exc()
            try:
                await interaction.followup.send(
                    "Something went wrong fetching your RSVP. Please try again.", ephemeral=True
                )
            except Exception:
                pass


class _RcRollCallView(discord.ui.View):
    def __init__(self, meets_by_num: dict = None) -> None:
        super().__init__(timeout=None)
        from datetime import date as _date, datetime as _dt, timezone as _tz
        today = _date.today()
        for meet_num, row_idx in ((1, 0), (2, 1), (3, 2)):
            meet = (meets_by_num or {}).get(meet_num)
            # Lock buttons on the event day itself
            lock = False
            if meet:
                ts = _parse_meet_ts(
                    meet["date_text"] if "date_text" in meet.keys() else "",
                    meet["start_time"] if "start_time" in meet.keys() else "",
                )
                if ts:
                    event_date = _dt.fromtimestamp(ts, tz=_tz.utc).date()
                    lock = today >= event_date
            for status in ("yes", "maybe", "no"):
                btn = _RcBtn(meet_num, status, row_idx)
                if lock:
                    btn.disabled = True
                self.add_item(btn)
        self.add_item(_RcMyRsvpBtn())


class _RcMeetView(discord.ui.View):
    """Buttons for a single meet card (✅ / ❓ / ❌ on one row)."""
    def __init__(self, meet_number: int, locked: bool = False) -> None:
        super().__init__(timeout=None)
        for status in ("yes", "maybe", "no"):
            btn = _RcBtn(meet_number, status, 0)
            if locked:
                btn.disabled = True
            self.add_item(btn)


