def _rc_collect_detected_attendees(guild_id: int) -> dict:
    """Map roll-call meet_number -> set(user_id) detected as actually present.

    Source: lobby-picture OCR (ocr.attended) + the poster of each lobby pic,
    matched to each roll-call meet's start time within _LP_MATCH_WINDOW_HOURS.
    OCR is best-effort, so this is a candidate set for staff confirmation only."""
    result = {1: set(), 2: set(), 3: set()}
    try:
        meets = _rc_db.get_meets(guild_id)
    except Exception:
        return result
    meet_ts_by_num = {}
    for row in meets:
        try:
            ts = _parse_meet_ts(row["date_text"] or "", row["start_time"] or "")
            if ts:
                meet_ts_by_num[row["meet_number"]] = ts
        except Exception:
            continue
    if not meet_ts_by_num:
        return result
    window = _LP_MATCH_WINDOW_HOURS * 3600
    try:
        lobby = _lp_load_all() or {}
    except Exception:
        lobby = {}
    for _mid, st in lobby.items():
        if not isinstance(st, dict):
            continue
        if st.get("guild_id") and st.get("guild_id") != guild_id:
            continue
        lts = st.get("meet_ts")
        if not lts:
            continue
        best_n, best_diff = None, window + 1
        for n, mts in meet_ts_by_num.items():
            diff = abs(float(lts) - float(mts))
            if diff <= window and diff < best_diff:
                best_n, best_diff = n, diff
        if best_n is None:
            continue
        poster = st.get("poster_id")
        if poster:
            try:
                result[best_n].add(int(poster))
            except (ValueError, TypeError):
                pass
        for uid in ((st.get("ocr") or {}).get("attended") or []):
            try:
                result[best_n].add(int(uid))
            except (ValueError, TypeError):
                continue
    return result


class _RcAutoAttendView(discord.ui.View):
    """Staff confirm view: applies auto-detected attendance and finalizes no-shows."""
    def __init__(self, detected: dict, finalized: set) -> None:
        super().__init__(timeout=300)
        self.detected = detected
        self.finalized = finalized

    @discord.ui.button(label="Apply & Finalize", style=discord.ButtonStyle.success, emoji="✅")
    async def apply_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not _rc_is_admin(interaction.user):
            return await interaction.response.send_message("Staff only.", ephemeral=True)
        await interaction.response.defer(ephemeral=True, thinking=True)
        gid = interaction.guild.id
        summary, applied = [], 0
        for n in (1, 2, 3):
            det = self.detected.get(n) or set()
            if n in self.finalized or _rc_db.is_attendance_finalized(gid, n):
                summary.append(f"Meet {n}: ⏭️ already finalized — skipped")
                continue
            if not det:
                summary.append(f"Meet {n}: no detections — skipped")
                continue
            existing = _rc_db.get_actual_attendees(gid, n)
            merged = sorted(existing | det)
            _rc_db.set_actual_attendees(gid, n, merged)
            attended, no_shows = _rc_db.finalize_no_shows(gid, n)
            await _rc_log_attendance(interaction.guild, n, attended, no_shows, interaction.user)
            summary.append(f"Meet {n}: ✅ present {len(attended)} · 👻 no-shows {len(no_shows)}")
            applied += 1
        if applied:
            try:
                await _rc_refresh_panel(interaction.guild)
            except Exception:
                pass
        for child in self.children:
            child.disabled = True
        try:
            await interaction.message.edit(view=self)
        except Exception:
            pass
        await interaction.followup.send("\n".join(summary), ephemeral=True)

    @discord.ui.button(label="Cancel", style=discord.ButtonStyle.secondary, emoji="✖️")
    async def cancel_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not _rc_is_admin(interaction.user):
            return await interaction.response.send_message("Staff only.", ephemeral=True)
        for child in self.children:
            child.disabled = True
        await interaction.response.edit_message(content="Cancelled — no changes made.", view=self)


@bot.command(name="autoattend", aliases=["autoattendance", "ocrattend"])
async def cmd_autoattend(ctx: commands.Context):
    """Staff: auto-detect meet attendance from lobby-pic OCR, preview no-shows, then finalize."""
    if not _rc_is_admin(ctx.author):
        return await ctx.reply("Staff only.", mention_author=False)
    gid = ctx.guild.id
    detected = _rc_collect_detected_attendees(gid)
    meets = {row["meet_number"]: row for row in _rc_db.get_meets(gid)}
    responses = _rc_db.get_all_responses(gid)
    finalized = {n for n in (1, 2, 3) if _rc_db.is_attendance_finalized(gid, n)}
    if sum(len(v) for v in detected.values()) == 0:
        return await ctx.reply(
            "No lobby-picture attendance detected yet. Post lobby screenshots with PSNs visible "
            "so OCR can match them to this week's meets, then try again.",
            mention_author=False,
        )
    embed = discord.Embed(
        title="🔎 Auto-Detected Attendance (from lobby pics)",
        description=(
            "Detected from lobby-picture OCR + posters. **OCR can miss people**, so review before "
            "finalizing. Confirm to record attendance and mark no-shows (RSVP'd ✅ but not detected). "
            "Each no-show gets a DM with a dispute button."
        ),
        color=discord.Color.blurple(),
        timestamp=datetime.now(_EST_TZ),
    )
    for n in (1, 2, 3):
        row = meets.get(n)
        det = detected.get(n) or set()
        no_show_cand = sorted(set(responses.get(n, {}).get("yes", [])) - det)
        label = (row["class_name"] if row else "TBD") or "TBD"
        when = (row["date_text"] if row else "") or ""
        when_part = f" ({when})" if when and when != "TBD" else ""
        if n in finalized:
            status = "⏭️ Already finalized"
        elif not det:
            status = "— no detections"
        else:
            status = f"✅ detected **{len(det)}** · 👻 no-show candidates **{len(no_show_cand)}**"
        det_txt = ", ".join(f"<@{u}>" for u in sorted(det)[:15]) or "*none*"
        ns_txt = ", ".join(f"<@{u}>" for u in no_show_cand[:15]) or "*none*"
        embed.add_field(
            name=f"Meet {n} — {label}{when_part}",
            value=f"{status}\n🎮 Detected: {det_txt}\n👻 No-show candidates: {ns_txt}"[:1024],
            inline=False,
        )
    embed.set_footer(text="Different Meets • Confirm to finalize")
    actionable = any((detected.get(n) and n not in finalized) for n in (1, 2, 3))
    view = _RcAutoAttendView(detected, finalized) if actionable else None
    await ctx.send(embed=embed, view=view)


def _rc_classify_msg(msg: discord.Message, bot_id: int) -> str | None:
    """Classify a bot message into its roll-call slot by button custom IDs.
    Returns 'admin', 'meet1'/'meet2'/'meet3', 'header', or None.
    Note: meet buttons are checked before the My-RSVP button so the legacy
    combined panel (which carried both) is still detected (as a meet) and
    therefore cleaned up on the next fresh post."""
    if msg.author.id != bot_id:
        return None
    has_my_rsvp = False
    for row in msg.components:
        for child in row.children:
            cid = getattr(child, "custom_id", "") or ""
            if cid.startswith("diff_rollcall_finalize:"):
                return "admin"
            m = re.match(r"diff_rollcall:([123]):", cid)
            if m:
                return f"meet{m.group(1)}"
            if cid == "diff_rollcall:my_rsvp":
                has_my_rsvp = True
    return "header" if has_my_rsvp else None


async def _rc_scan_and_recover(channel: discord.TextChannel, guild_id: int, bot_id: int) -> dict:
    """Scan channel history for the roll-call layout messages.
    Deletes duplicate copies (keeps newest per slot), saves recovered IDs.
    Returns {slot: message_id} for whatever was found."""
    found: dict[str, list[discord.Message]] = {}
    try:
        async for msg in channel.history(limit=80):
            slot = _rc_classify_msg(msg, bot_id)
            if slot:
                found.setdefault(slot, []).append(msg)
    except Exception:
        return {}

    kept: dict[str, int] = {}
    for slot, msgs in found.items():
        kept[slot] = msgs[0].id            # history is newest-first
        for m in msgs[1:]:                 # delete older duplicates
            try:
                await m.delete()
            except Exception:
                pass

    header_id = kept.get("header")
    admin_id  = kept.get("admin")
    if header_id:
        _rc_db.upsert_panel(guild_id, channel.id, header_id, admin_id)
        _rc_db.set_message(guild_id, "header", header_id)
    if admin_id:
        _rc_db.set_message(guild_id, "admin", admin_id)
    for n in (1, 2, 3):
        if kept.get(f"meet{n}"):
            _rc_db.set_message(guild_id, f"meet{n}", kept[f"meet{n}"])

    return kept


async def _rc_resolve_channel(guild: discord.Guild):
    channel = guild.get_channel(ROLL_CALL_CHANNEL_ID) or bot.get_channel(ROLL_CALL_CHANNEL_ID)
    if not isinstance(channel, discord.TextChannel):
        try:
            channel = await bot.fetch_channel(ROLL_CALL_CHANNEL_ID)
        except Exception as _ce:
            print(f"[RcPanel] cannot resolve roll-call channel: {_ce}")
            return None
    return channel if isinstance(channel, discord.TextChannel) else None


async def _rc_refresh_panel(guild: discord.Guild):
    """Re-render the header + per-meet cards.  Debounced per-guild to prevent rate-limit storms."""
    existing = _rc_refresh_tasks.get(guild.id)
    if existing and not existing.done():
        existing.cancel()

    async def _do_refresh():
        try:
            await asyncio.sleep(0.5)          # coalesce rapid clicks
            channel = await _rc_resolve_channel(guild)
            if channel is None:
                return

            msgs         = _rc_db.get_messages(guild.id)
            meets_by_num = {row["meet_number"]: row for row in _rc_db.get_meets(guild.id)}

            # No stored header → try to recover from channel history
            if not msgs.get("header"):
                await _rc_scan_and_recover(channel, guild.id, guild.me.id)
                msgs = _rc_db.get_messages(guild.id)

            # Still nothing → post a fresh layout
            if not msgs.get("header"):
                print("[RcPanel] no existing layout found — posting fresh")
                await _rc_post_new_panel(guild, ping_roles=False)
                return

            # Edit the header card
            try:
                hm = await channel.fetch_message(msgs["header"])
                await hm.edit(embed=_rc_build_header_embed(guild), view=_RcHeaderView())
            except discord.NotFound:
                print("[RcPanel] header message gone — reposting layout")
                await _rc_post_new_panel(guild, ping_roles=False)
                return
            except Exception as e:
                print(f"[RcPanel] header edit error: {e}")

            # Edit each per-meet card
            for n in (1, 2, 3):
                mid = msgs.get(f"meet{n}")
                if not mid:
                    print(f"[RcPanel] meet{n} message missing — reposting layout")
                    await _rc_post_new_panel(guild, ping_roles=False)
                    return
                try:
                    mm     = await channel.fetch_message(mid)
                    locked = _rc_meet_is_locked(meets_by_num.get(n))
                    await mm.edit(embed=_rc_build_meet_embed(guild, n), view=_RcMeetView(n, locked))
                except discord.NotFound:
                    print(f"[RcPanel] meet{n} message gone — reposting layout")
                    await _rc_post_new_panel(guild, ping_roles=False)
                    return
                except Exception as e:
                    print(f"[RcPanel] meet{n} edit error: {e}")
        except Exception as _task_err:
            print(f"[RcPanel] _do_refresh unhandled error: {_task_err}")
            import traceback as _tb; _tb.print_exc()

    task = asyncio.create_task(_do_refresh())
    _rc_refresh_tasks[guild.id] = task


async def _rc_post_new_panel(guild: discord.Guild, ping_roles: bool = False, reset: bool = False):
    """Re-post the roll-call layout (header card → 3 per-meet cards → staff admin card).

    Deletes any existing roll-call messages first, then posts fresh.
    `reset=True` ALSO wipes the week (responses/meets/finalized) — use ONLY for an
    explicit new-week post (`!postrollcall`). When `reset=False` (recovery/repost),
    existing responses + meets are preserved so a missing card never costs data.
    """
    channel = await _rc_resolve_channel(guild)
    if channel is None:
        return

    # Delete any existing roll-call layout messages before posting fresh
    bot_id = guild.me.id if guild.me else None
    if bot_id:
        try:
            async for msg in channel.history(limit=80):
                if _rc_classify_msg(msg, bot_id) is not None:
                    try:
                        await msg.delete()
                    except Exception:
                        pass
        except Exception:
            pass

    if reset:
        # Snapshot the ending week's responses BEFORE the wipe — the Monday-00:15
        # pruning report reads this snapshot (the live DB is already empty by then).
        _snap_ok = False
        try:
            _rc_week_snapshot_save(guild.id)
            _snap_ok = True
        except Exception as _sne:
            print(f"[RollCall] week snapshot failed: {_sne}")
        _rc_db.reset_week(guild.id)   # wipe responses, meets, finalized flags + message rows → fresh slate
        if _snap_ok:
            # Mark the wipe as completed AFTER it succeeds — the report only prefers
            # the snapshot when this flag is set (if the wipe threw, live DB is still
            # intact and is the better source).
            try:
                _sd = _rc_week_snapshot_load()
                _sd["reset_completed"] = True
                _atomic_json_save(_RC_WEEK_SNAPSHOT_FILE, _sd)
            except Exception:
                pass
    else:
        _rc_db.clear_messages(guild.id)   # only drop stale message-id rows; keep responses + meets

    ping_text = None
    if ping_roles:
        parts = []
        cr = guild.get_role(CREW_MEMBER_ROLE_ID)
        if cr:
            parts.append(cr.mention)
        ps5r = guild.get_role(PS5_ROLE_ID)
        if ps5r:
            parts.append(ps5r.mention)
        if parts:
            ping_text = " ".join(parts)

    try:
        meets_by_num = {row["meet_number"]: row for row in _rc_db.get_meets(guild.id)}

        header_msg = await channel.send(
            content=ping_text,
            embed=_rc_build_header_embed(guild),
            view=_RcHeaderView(),
            allowed_mentions=discord.AllowedMentions(roles=True),
        )
        _rc_db.upsert_panel(guild.id, channel.id, header_msg.id, None)
        _rc_db.set_message(guild.id, "header", header_msg.id)

        for n in (1, 2, 3):
            locked   = _rc_meet_is_locked(meets_by_num.get(n))
            meet_msg = await channel.send(
                embed=_rc_build_meet_embed(guild, n),
                view=_RcMeetView(n, locked),
            )
            _rc_db.set_message(guild.id, f"meet{n}", meet_msg.id)

        admin_msg = await channel.send(embed=_rc_build_admin_embed(), view=_RcAdminView())
        _rc_db.upsert_panel(guild.id, channel.id, header_msg.id, admin_msg.id)
        _rc_db.set_message(guild.id, "admin", admin_msg.id)
    except Exception as e:
        print(f"[RollCall] post failed: {e}")
        import traceback as _tb; _tb.print_exc()


async def _rc_ensure_panel(guild: discord.Guild):
    channel = guild.get_channel(ROLL_CALL_CHANNEL_ID)
    if not isinstance(channel, discord.TextChannel):
        return

    # Try stored header message
    msgs = _rc_db.get_messages(guild.id)
    if msgs.get("header"):
        try:
            await channel.fetch_message(msgs["header"])
            return
        except discord.NotFound:
            pass
        except Exception:
            return

    # Stored ID stale — scan to recover or clean up before posting
    bot_id = guild.me.id if guild.me else None
    if bot_id:
        kept = await _rc_scan_and_recover(channel, guild.id, bot_id)
        if kept.get("header"):
            return  # recovered successfully, no need to post

    await _rc_post_new_panel(guild, ping_roles=True)


_RC_LOG_ICONS: dict[str, str] = {
    "yes": "✅ Yes",
    "maybe": "❓ Maybe",
    "no": "❌ No",
}
_rc_log_buffer:     dict[int, list] = {}
_rc_log_tasks:      dict[int, "asyncio.Task[None]"] = {}
_rc_refresh_tasks:  dict[int, "asyncio.Task[None]"] = {}   # per-guild debounce


async def _rc_flush_log(guild: discord.Guild, member: discord.Member) -> None:
    await asyncio.sleep(3)
    entries = _rc_log_buffer.pop(member.id, [])
    _rc_log_tasks.pop(member.id, None)
    if not entries:
        return
    ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
    if not isinstance(ch, discord.TextChannel):
        return

    statuses = [e[2] for e in entries]
    if "yes" in statuses:
        color = discord.Color.green()
    elif all(s == "no" for s in statuses):
        color = discord.Color.red()
    else:
        color = discord.Color.orange()

    n = len(entries)
    noun = "response" if n == 1 else "responses"
    all_new     = all(not e[1] or e[1] == "none" for e in entries)
    all_changed = all(e[1] and e[1] != "none" for e in entries)
    if all_new:
        action = f"Set initial {noun} for {n} meet{'s' if n > 1 else ''}"
    elif all_changed:
        action = f"Changed {noun} for {n} meet{'s' if n > 1 else ''}"
    else:
        action = f"Updated {noun} for {n} meet{'s' if n > 1 else ''}"

    embed = discord.Embed(
        description=action,
        color=color,
        timestamp=datetime.now(timezone.utc),
    )
    embed.set_author(
        name=f"{member.display_name}  •  Roll Call Update",
        icon_url=member.display_avatar.url,
    )
    for meet_number, previous, new_status in sorted(entries, key=lambda x: x[0]):
        prev_clean = previous if previous and previous != "none" else None
        prev_label = _RC_LOG_ICONS.get(prev_clean, "⬜ None") if prev_clean else "⬜ None"
        new_label  = _RC_LOG_ICONS.get(new_status, new_status.capitalize())
        embed.add_field(
            name=f"Meet {meet_number}",
            value=f"{prev_label} → {new_label}",
            inline=True,
        )
    for _ in range((3 - (n % 3)) % 3):
        embed.add_field(name="\u200b", value="\u200b", inline=True)
    embed.add_field(name="Member", value=f"{member.mention}  `{member}`", inline=False)
    embed.set_footer(text="Roll Call Log  •  Different Meets")
    try:
        await ch.send(embed=embed)
    except Exception:
        pass


async def _rc_log_rsvp(guild: discord.Guild, member: discord.Member, meet_number: int, previous: str, new_status: str) -> None:
    prev_clean = previous if previous and previous != "none" else None
    if prev_clean == new_status:
        return
    if member.id not in _rc_log_buffer:
        _rc_log_buffer[member.id] = []
    _rc_log_buffer[member.id].append((meet_number, previous, new_status))
    existing = _rc_log_tasks.get(member.id)
    if existing and not existing.done():
        existing.cancel()
    _rc_log_tasks[member.id] = asyncio.create_task(_rc_flush_log(guild, member))


async def _rc_log_attendance(guild, meet_number, attended, no_shows, action_by):
    ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
    if not isinstance(ch, discord.TextChannel):
        return
    embed = discord.Embed(
        title=f"📊 Meet {meet_number} — Attendance Finalized",
        color=discord.Color.green(),
        timestamp=datetime.now(timezone.utc),
    )
    embed.set_author(
        name=f"Finalized by {action_by.display_name}",
        icon_url=action_by.display_avatar.url,
    )
    embed.add_field(name="✅ Present",   value=f"**{len(attended)}**",  inline=True)
    embed.add_field(name="⚠️ No-Shows", value=f"**{len(no_shows)}**",  inline=True)
    embed.add_field(name="\u200b",       value="\u200b",                 inline=True)
    attended_text = " ".join(f"<@{uid}>" for uid in attended[:30]) or "*None recorded*"
    no_show_text  = " ".join(f"<@{uid}>" for uid in no_shows[:30]) or "*None*"
    embed.add_field(name="Present Members", value=attended_text[:1024], inline=False)
    if no_shows:
        embed.add_field(name="No-Shows", value=no_show_text[:1024], inline=False)
    embed.set_footer(text="Roll Call Log  •  Different Meets")
    try:
        await ch.send(embed=embed)
    except Exception:
        pass

    # ── DM each no-show with dispute option ──────────────────
    if no_shows:
        for uid in no_shows:
            member_obj = guild.get_member(uid)
            if not member_obj:
                continue
            try:
                dm_e = discord.Embed(
                    title="👻 You were marked as a No-Show",
                    description=(
                        f"You were marked as a **no-show** for **Meet {meet_number}** this week.\n\n"
                        "No-shows are tracked and may affect your standing in the community. "
                        "If you believe this is an error (e.g., you attended but weren't marked), "
                        "tap the button below to flag it to leadership."
                    ),
                    color=discord.Color.red(),
                    timestamp=datetime.now(_EST_TZ),
                )
                dm_e.set_footer(text="Different Meets • Attendance Record")
                await member_obj.send(embed=dm_e, view=_RcNoShowDisputeView(meet_number))
            except discord.Forbidden:
                pass

    # --- XP: award meet attendance once per week+meet ---
    try:
        _xwk = _xp_week_key()
        for _auid in attended:
            _am = guild.get_member(_auid)
            if _am:
                await _xp_apply_award(
                    guild, _am, _XP_PER_MEET_ATTEND,
                    kind="attend", ref=f"{_xwk}:{meet_number}",
                )
                try:
                    await _xp_check_badges(guild, _am)
                except Exception:
                    pass
    except Exception:
        pass


_CREW_CHAT_CHANNEL_ID    = 990097781798613063
_EVERYONE_CHAT_CHANNEL_ID = 1047335231826436166


# =========================
# XP / LEVELS / REWARDS SYSTEM  (Phase 2a)
# =========================
_XP_DB_FILE      = "diff_data/diff_xp.db"
_XP_ROLES_FILE   = "diff_data/diff_xp_roles.json"
_XP_CONFIG_FILE  = "diff_data/diff_xp_config.json"

_XP_PER_MESSAGE         = 5
_XP_MSG_COOLDOWN_SECS   = 60
_XP_PER_RSVP_YES        = 10
_XP_PER_LOBBY_PIC       = 15
_XP_LOBBY_PIC_DAILY_CAP = 3
_XP_PER_MEET_ATTEND     = 50
_XP_PER_VC_TICK         = 5
_XP_VC_TICK_MINUTES     = 10

# level threshold -> auto-created reward role name (only the highest earned is kept)
_XP_ROLE_LADDER = [
    (5,  "DIFF Regular"),
    (10, "DIFF Veteran"),
    (20, "DIFF Elite"),
    (35, "DIFF Legend"),
]

_xp_msg_cooldowns: dict = {}
_xp_roles_lock = asyncio.Lock()


def _xp_level_for(total_xp: int) -> int:
    """Cumulative XP to reach level L is 50*L*(L+1); this is the inverse."""
    if total_xp < 100:
        return 0
    return int((-50 + (2500 + 200 * total_xp) ** 0.5) / 100)


def _xp_to_reach(level: int) -> int:
    if level <= 0:
        return 0
    return 50 * level * (level + 1)


def _xp_week_key(dt=None) -> str:
    d = dt or datetime.now(_EST_TZ)
    iso = d.isocalendar()
    return f"{iso[0]}-W{iso[1]:02d}"


class _XPDB:
    def __init__(self, path: str = _XP_DB_FILE) -> None:
        os.makedirs("diff_data", exist_ok=True)
        self.conn = sqlite3.connect(path)
        self.conn.row_factory = sqlite3.Row
        cur = self.conn.cursor()
        cur.execute(
            "CREATE TABLE IF NOT EXISTS xp ("
            "guild_id INTEGER NOT NULL, user_id INTEGER NOT NULL, "
            "xp INTEGER NOT NULL DEFAULT 0, level INTEGER NOT NULL DEFAULT 0, "
            "week_xp INTEGER NOT NULL DEFAULT 0, updated_at TEXT, "
            "PRIMARY KEY (guild_id, user_id))"
        )
        cur.execute(
            "CREATE TABLE IF NOT EXISTS xp_awards ("
            "guild_id INTEGER NOT NULL, user_id INTEGER NOT NULL, "
            "kind TEXT NOT NULL, ref TEXT NOT NULL, ts TEXT, "
            "PRIMARY KEY (guild_id, user_id, kind, ref))"
        )
        cur.execute(
            "CREATE TABLE IF NOT EXISTS xp_badges ("
            "guild_id INTEGER NOT NULL, user_id INTEGER NOT NULL, "
            "badge_key TEXT NOT NULL, earned_at TEXT, "
            "PRIMARY KEY (guild_id, user_id, badge_key))"
        )
        cur.execute(
            "CREATE INDEX IF NOT EXISTS idx_xp_badges_guild_user "
            "ON xp_badges(guild_id, user_id)"
        )
        cur.execute(
            "CREATE TABLE IF NOT EXISTS xp_week ("
            "guild_id INTEGER NOT NULL, user_id INTEGER NOT NULL, "
            "week_key TEXT NOT NULL, week_xp INTEGER NOT NULL DEFAULT 0, "
            "PRIMARY KEY (guild_id, user_id, week_key))"
        )
        cur.execute(
            "CREATE INDEX IF NOT EXISTS idx_xp_week_lookup "
            "ON xp_week(guild_id, week_key)"
        )
        self.conn.commit()

    def get(self, guild_id, user_id):
        cur = self.conn.cursor()
        cur.execute("SELECT * FROM xp WHERE guild_id=? AND user_id=?", (guild_id, user_id))
        return cur.fetchone()

    def add_xp(self, guild_id, user_id, amount):
        """Add XP (may be negative). Returns (old_level, new_level, new_total)."""
        cur = self.conn.cursor()
        cur.execute("SELECT xp FROM xp WHERE guild_id=? AND user_id=?", (guild_id, user_id))
        row = cur.fetchone()
        old_total = row["xp"] if row else 0
        new_total = max(0, old_total + amount)
        old_level = _xp_level_for(old_total)
        new_level = _xp_level_for(new_total)
        now = datetime.now(timezone.utc).isoformat()
        wk_inc = amount if amount > 0 else 0
        cur.execute(
            "INSERT INTO xp (guild_id, user_id, xp, level, week_xp, updated_at) "
            "VALUES (?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(guild_id, user_id) DO UPDATE SET "
            "xp=excluded.xp, level=excluded.level, "
            "week_xp=xp.week_xp+?, updated_at=excluded.updated_at",
            (guild_id, user_id, new_total, new_level, wk_inc, now, wk_inc),
        )
        # Bucket weekly XP by the week it was earned in (ISO week, ET) so Member of
        # the Week is computed from an exact completed week with no boundary drift.
        if wk_inc > 0:
            wk = _xp_week_key()
            cur.execute(
                "INSERT INTO xp_week (guild_id, user_id, week_key, week_xp) "
                "VALUES (?, ?, ?, ?) "
                "ON CONFLICT(guild_id, user_id, week_key) DO UPDATE SET "
                "week_xp=xp_week.week_xp+?",
                (guild_id, user_id, wk, wk_inc, wk_inc),
            )
        self.conn.commit()
        return old_level, new_level, new_total

    def award_once(self, guild_id, user_id, kind, ref, amount):
        """Insert a dedup marker; if new, add XP. Returns result tuple or None."""
        cur = self.conn.cursor()
        try:
            cur.execute(
                "INSERT INTO xp_awards (guild_id, user_id, kind, ref, ts) VALUES (?, ?, ?, ?, ?)",
                (guild_id, user_id, kind, ref, datetime.now(timezone.utc).isoformat()),
            )
        except sqlite3.IntegrityError:
            return None
        # No commit here on purpose: add_xp() commits the dedup marker and the XP
        # update together in one transaction, so a failure can't leave an award
        # "spent" (marker persisted) with no XP actually granted.
        return self.add_xp(guild_id, user_id, amount)

    def count_awards_like(self, guild_id, user_id, kind, ref_prefix):
        cur = self.conn.cursor()
        cur.execute(
            "SELECT COUNT(*) AS c FROM xp_awards "
            "WHERE guild_id=? AND user_id=? AND kind=? AND ref LIKE ?",
            (guild_id, user_id, kind, ref_prefix),
        )
        r = cur.fetchone()
        return r["c"] if r else 0

    def top(self, guild_id, limit=10):
        cur = self.conn.cursor()
        cur.execute("SELECT * FROM xp WHERE guild_id=? ORDER BY xp DESC LIMIT ?", (guild_id, limit))
        return cur.fetchall()

    def top_week(self, guild_id, limit=10):
        cur = self.conn.cursor()
        cur.execute(
            "SELECT * FROM xp WHERE guild_id=? AND week_xp>0 ORDER BY week_xp DESC LIMIT ?",
            (guild_id, limit),
        )
        return cur.fetchall()

    def reset_week(self, guild_id):
        cur = self.conn.cursor()
        cur.execute("UPDATE xp SET week_xp=0 WHERE guild_id=?", (guild_id,))
        self.conn.commit()

    def week_top(self, guild_id, week_key, limit=10):
        """Top earners for one exact ISO week (from the week-keyed bucket table)."""
        cur = self.conn.cursor()
        cur.execute(
            "SELECT user_id, week_xp FROM xp_week "
            "WHERE guild_id=? AND week_key=? AND week_xp>0 "
            "ORDER BY week_xp DESC LIMIT ?",
            (guild_id, week_key, limit),
        )
        return cur.fetchall()

    def prune_weeks(self, guild_id, before_week_key):
        """Drop weekly buckets older than `before_week_key`. Week keys are
        'YYYY-Wnn' (zero-padded), so lexicographic compare is chronological."""
        cur = self.conn.cursor()
        cur.execute(
            "DELETE FROM xp_week WHERE guild_id=? AND week_key < ?",
            (guild_id, before_week_key),
        )
        self.conn.commit()

    def rank_of(self, guild_id, user_id):
        cur = self.conn.cursor()
        cur.execute("SELECT xp FROM xp WHERE guild_id=? AND user_id=?", (guild_id, user_id))
        row = cur.fetchone()
        if not row:
            return None
        cur.execute("SELECT COUNT(*) AS c FROM xp WHERE guild_id=? AND xp>?", (guild_id, row["xp"]))
        r = cur.fetchone()
        return (r["c"] if r else 0) + 1

    def count_awards(self, guild_id, user_id, kind):
        cur = self.conn.cursor()
        cur.execute(
            "SELECT COUNT(*) AS c FROM xp_awards WHERE guild_id=? AND user_id=? AND kind=?",
            (guild_id, user_id, kind),
        )
        r = cur.fetchone()
        return r["c"] if r else 0

    def add_badge(self, guild_id, user_id, badge_key):
        """Insert a badge; returns True if newly earned, False if already had it."""
        cur = self.conn.cursor()
        try:
            cur.execute(
                "INSERT INTO xp_badges (guild_id, user_id, badge_key, earned_at) VALUES (?, ?, ?, ?)",
                (guild_id, user_id, badge_key, datetime.now(timezone.utc).isoformat()),
            )
            self.conn.commit()
            return True
        except sqlite3.IntegrityError:
            return False

    def get_badges(self, guild_id, user_id):
        cur = self.conn.cursor()
        cur.execute("SELECT badge_key FROM xp_badges WHERE guild_id=? AND user_id=?", (guild_id, user_id))
        return set(r["badge_key"] for r in cur.fetchall())

    def badge_top(self, guild_id, limit=10):
        cur = self.conn.cursor()
        cur.execute(
            "SELECT user_id, COUNT(*) AS c FROM xp_badges WHERE guild_id=? "
            "GROUP BY user_id ORDER BY c DESC LIMIT ?",
            (guild_id, limit),
        )
        return cur.fetchall()


_xp_db = _XPDB()


def _xp_config_load() -> dict:
    if not os.path.exists(_XP_CONFIG_FILE):
        return {}
    try:
        with open(_XP_CONFIG_FILE, "r", encoding="utf-8") as f:
            return json.load(f) or {}
    except Exception:
        return {}


def _xp_config_save(d: dict) -> None:
    os.makedirs("diff_data", exist_ok=True)
    _atomic_json_save(_XP_CONFIG_FILE, d)


def _xp_roles_load() -> dict:
    if not os.path.exists(_XP_ROLES_FILE):
        return {}
    try:
        with open(_XP_ROLES_FILE, "r", encoding="utf-8") as f:
            return json.load(f) or {}
    except Exception:
        return {}


def _xp_roles_save(d: dict) -> None:
    os.makedirs("diff_data", exist_ok=True)
    _atomic_json_save(_XP_ROLES_FILE, d)


async def _xp_ensure_ladder_roles(guild):
    """Return {name: role_id} for every ladder role, creating any that are missing.
    Concurrency-safe so a level-up flood can't create duplicate roles."""
    out = {}
    async with _xp_roles_lock:
        cache = _xp_roles_load()
        changed = False
        for _lvl, name in _XP_ROLE_LADDER:
            rid = cache.get(name)
            role = guild.get_role(int(rid)) if rid else None
            if role is None:
                role = discord.utils.get(guild.roles, name=name)
            if role is None:
                try:
                    role = await guild.create_role(
                        name=name, mentionable=False, reason="Auto-created XP reward role"
                    )
                except Exception:
                    role = None
            if role is not None:
                out[name] = role.id
                if cache.get(name) != role.id:
                    cache[name] = role.id
                    changed = True
        if changed:
            _xp_roles_save(cache)
    return out


async def _xp_sync_reward_roles(guild, member, level):
    """Grant the single highest reward role earned at `level`; strip lower ones.
    Returns the newly-granted role name (if any) for the level-up notice."""
    try:
        ladder_ids = await _xp_ensure_ladder_roles(guild)
    except Exception:
        return None
    earned = [name for lvl, name in _XP_ROLE_LADDER if level >= lvl]
    target = earned[-1] if earned else None
    granted = None
    for name, rid in ladder_ids.items():
        role = guild.get_role(rid)
        if role is None:
            continue
        has = role in member.roles
        if name == target:
            if not has:
                try:
                    await member.add_roles(role, reason="XP reward role earned")
                    granted = name
                except Exception:
                    pass
        elif has:
            try:
                await member.remove_roles(role, reason="XP reward role superseded")
            except Exception:
                pass
    return granted


async def _xp_notify_levelup(guild, member, level, total, granted_role):
    desc = f"You reached **Level {level}** in {guild.name}! 🎉\nTotal XP: **{total:,}**"
    if granted_role:
        desc += f"\n\n🏅 New role unlocked: **{granted_role}**"
    e = discord.Embed(
        title="⬆️ Level Up!", description=desc,
        color=0xF1C40F, timestamp=datetime.now(_EST_TZ),
    )
    e.set_footer(text="Different Meets • Keep showing up")
    try:
        await member.send(embed=e)
    except discord.Forbidden:
        pass
    except Exception:
        pass
    cfg = _xp_config_load()
    ch_id = cfg.get("announce_channel_id")
    if ch_id:
        ch = guild.get_channel(int(ch_id))
        if isinstance(ch, discord.TextChannel):
            extra = f" — unlocked **{granted_role}**" if granted_role else ""
            try:
                await ch.send(f"🎉 {member.mention} just hit **Level {level}**!{extra}")
            except Exception:
                pass


async def _xp_apply_award(guild, member, amount, *, kind=None, ref=None):
    """Central XP award. With kind+ref the award is deduped (granted once only).
    Detects level-ups, syncs reward roles, and notifies the member."""
    if member is None or getattr(member, "bot", False):
        return
    try:
        if kind and ref:
            res = _xp_db.award_once(guild.id, member.id, kind, ref, amount)
            if res is None:
                return
        else:
            res = _xp_db.add_xp(guild.id, member.id, amount)
        old_level, new_level, total = res
    except Exception as _e:
        print(f"[xp] award error: {_e!r}")
        return
    if new_level > old_level:
        try:
            granted = await _xp_sync_reward_roles(guild, member, new_level)
        except Exception:
            granted = None
        await _xp_notify_levelup(guild, member, new_level, total, granted)
        try:
            await _xp_check_badges(guild, member)
        except Exception:
            pass
    elif new_level < old_level:
        # Manual reductions (!takexp) can drop a member below a reward tier — strip
        # any reward roles that are now above their level. No notification on demotion.
        try:
            await _xp_sync_reward_roles(guild, member, new_level)
        except Exception:
            pass


def _xp_progress_bar(total_xp, level, length=12):
    base = _xp_to_reach(level)
    nxt = _xp_to_reach(level + 1)
    span = max(1, nxt - base)
    done = max(0, min(span, total_xp - base))
    filled = int(length * done / span)
    return ("█" * filled) + ("░" * (length - filled)), done, span


def _xp_is_leadership(member) -> bool:
    try:
        if any(r.id in _LEADERSHIP_ROLE_IDS for r in member.roles):
            return True
        return bool(member.guild_permissions.manage_guild)
    except Exception:
        return False


@bot.command(name="rank", aliases=["level", "xp"])
async def cmd_rank(ctx, member: discord.Member = None):
    member = member or ctx.author
    if member.bot:
        return await ctx.reply("Bots don't earn XP.", mention_author=False)
    row = _xp_db.get(ctx.guild.id, member.id)
    total = row["xp"] if row else 0
    level = _xp_level_for(total)
    bar, done, span = _xp_progress_bar(total, level)
    rank = _xp_db.rank_of(ctx.guild.id, member.id)
    e = discord.Embed(
        title=f"🎮 {member.display_name} — Level {level}",
        color=0x5865F2, timestamp=datetime.now(_EST_TZ),
    )
    e.set_thumbnail(url=member.display_avatar.url)
    e.add_field(name="Total XP", value=f"**{total:,}**", inline=True)
    e.add_field(name="Server Rank", value=(f"#{rank}" if rank else "—"), inline=True)
    e.add_field(
        name=f"Progress to Level {level + 1}",
        value=f"{bar}\n{done:,} / {span:,} XP",
        inline=False,
    )
    e.set_footer(text="Different Meets • !rank")
    await ctx.send(embed=e)


@bot.command(name="xpboard", aliases=["xptop", "levels"])
async def cmd_xpboard(ctx):
    rows = _xp_db.top(ctx.guild.id, 10)
    if not rows:
        return await ctx.reply(
            "No XP earned yet. Show up to a meet, chat, or post a lobby pic!",
            mention_author=False,
        )
    medals = ["🥇", "🥈", "🥉"]
    lines = []
    for i, r in enumerate(rows):
        m = ctx.guild.get_member(r["user_id"])
        name = m.display_name if m else f"User {r['user_id']}"
        tag = medals[i] if i < 3 else f"`#{i + 1}`"
        lines.append(f"{tag} **{name}** — Level {_xp_level_for(r['xp'])} · {r['xp']:,} XP")
    e = discord.Embed(
        title="🏆 XP Leaderboard",
        description="\n".join(lines),
        color=0xF1C40F, timestamp=datetime.now(_EST_TZ),
    )
    e.set_footer(text="Different Meets • Top 10 by XP")
    await ctx.send(embed=e)


@bot.command(name="givexp")
async def cmd_givexp(ctx, member: discord.Member, amount: int):
    if not _xp_is_leadership(ctx.author):
        return await ctx.reply("Leadership only.", mention_author=False)
    await _xp_apply_award(ctx.guild, member, amount)
    row = _xp_db.get(ctx.guild.id, member.id)
    total = row["xp"] if row else 0
    await ctx.reply(
        f"✅ Gave **{amount:,}** XP to {member.mention}. "
        f"New total: **{total:,}** (Level {_xp_level_for(total)}).",
        mention_author=False,
    )


@bot.command(name="takexp")
async def cmd_takexp(ctx, member: discord.Member, amount: int):
    if not _xp_is_leadership(ctx.author):
        return await ctx.reply("Leadership only.", mention_author=False)
    await _xp_apply_award(ctx.guild, member, -abs(amount))
    row = _xp_db.get(ctx.guild.id, member.id)
    total = row["xp"] if row else 0
    await ctx.reply(
        f"✅ Removed **{abs(amount):,}** XP from {member.mention}. "
        f"New total: **{total:,}** (Level {_xp_level_for(total)}).",
        mention_author=False,
    )


@bot.command(name="setlevelchannel")
async def cmd_setlevelchannel(ctx, channel: discord.TextChannel = None):
    if not _xp_is_leadership(ctx.author):
        return await ctx.reply("Leadership only.", mention_author=False)
    cfg = _xp_config_load()
    if channel is None:
        cfg.pop("announce_channel_id", None)
        _xp_config_save(cfg)
        return await ctx.reply(
            "✅ Level-up announcements disabled (members still get a DM).",
            mention_author=False,
        )
    cfg["announce_channel_id"] = channel.id
    _xp_config_save(cfg)
    await ctx.reply(f"✅ Level-up announcements will post in {channel.mention}.", mention_author=False)


