_OM_DATA_FILE = os.path.join(DATA_FOLDER, "diff_official_meets.json")
_om_rsvps: dict[int, dict[str, set]] = {}
_om_lock = asyncio.Lock()


@dataclass
class _OmRecord:
    message_id: int
    channel_id: int
    host_id: int
    theme: str
    timestamp: int
    started: bool = False
    ended: bool = False
    one_hour_sent: bool = False
    fifteen_sent: bool = False
    dm_24h_sent: bool = False   # #4 DM-to-RSVPers reminder at T-24h
    dm_1h_sent: bool = False    # #4 DM-to-RSVPers reminder at T-1h
    started_at_ts: int | None = None
    ended_at_ts: int | None = None
    attendance_message_id: int | None = None
    attendance_channel_id: int | None = None
    attendance_all_msg_ids: list = field(default_factory=list)
    rsvp_yes_ids: list = field(default_factory=list)
    rsvp_maybe_ids: list = field(default_factory=list)
    rsvp_no_ids: list = field(default_factory=list)
    checked_in_ids: list = field(default_factory=list)
    late_ids: list = field(default_factory=list)
    unable_ids: list = field(default_factory=list)
    no_show_ids: list = field(default_factory=list)
    unable_reasons: dict = field(default_factory=dict)  # {uid_str: reason}
    reminder_message_ids: list = field(default_factory=list)  # 1h + 15m reminder embed msg ids
    live_message_id: int | None = None                         # "Meet Live" announcement msg id
    close_message_id: int | None = None                        # "DIFF Meet Closed" summary msg id


def _om_load_records() -> dict:
    try:
        with open(_OM_DATA_FILE, "r") as f:
            return json.load(f)
    except Exception:
        return {}


def _om_save_records(data: dict) -> None:
    try:
        with open(_OM_DATA_FILE, "w") as f:
            json.dump(data, f, indent=2)
    except Exception as e:
        print(f"[OfficialMeet] save error: {e}")


def _om_get_record(msg_id: int) -> _OmRecord | None:
    data = _om_load_records()
    raw = data.get(str(msg_id))
    if not raw:
        return None
    try:
        return _OmRecord(**{k: v for k, v in raw.items() if k in _OmRecord.__dataclass_fields__})
    except Exception:
        return None


def _om_upsert_record(record: _OmRecord) -> None:
    data = _om_load_records()
    data[str(record.message_id)] = asdict(record)
    _om_save_records(data)


def _om_get_record_by_attendance_msg(attendance_msg_id: int) -> _OmRecord | None:
    data = _om_load_records()
    for raw in data.values():
        if (raw.get("attendance_message_id") == attendance_msg_id
                or attendance_msg_id in raw.get("attendance_all_msg_ids", [])):
            try:
                return _OmRecord(**{k: v for k, v in raw.items() if k in _OmRecord.__dataclass_fields__})
            except Exception:
                pass
    return None


# ---- Stats store ----
_OM_STATS_FILE = os.path.join(DATA_FOLDER, "diff_om_stats.json")
_OM_LEADERBOARD_CHANNEL_ID = 1485282044392243290


def _om_stats_load() -> dict:
    try:
        with open(_OM_STATS_FILE) as f:
            return json.load(f)
    except Exception:
        return {"members": {}, "hosts": {}}


def _om_stats_save(data: dict) -> None:
    try:
        _atomic_json_save(_OM_STATS_FILE, data)
    except Exception:
        pass


def _om_increment_member_stat(user_id: int, field_name: str, amount: int = 1) -> None:
    data = _om_stats_load()
    members = data.setdefault("members", {})
    entry = members.setdefault(str(user_id), {"user_id": user_id, "attended": 0, "late": 0, "unable": 0, "no_shows": 0})
    entry[field_name] = int(entry.get(field_name, 0)) + amount
    _om_stats_save(data)


def _om_increment_host_stat(user_id: int, field_name: str, amount: int = 1) -> None:
    data = _om_stats_load()
    hosts = data.setdefault("hosts", {})
    entry = hosts.setdefault(str(user_id), {
        "user_id": user_id, "meets_hosted": 0, "meets_completed": 0,
        "total_attendance": 0, "total_late": 0, "total_no_shows": 0,
    })
    entry[field_name] = int(entry.get(field_name, 0)) + amount
    _om_stats_save(data)


_OM_LB_MSG_KEY = "leaderboard_msg_id"


def _build_unified_lb_embed(guild: discord.Guild) -> discord.Embed:
    """Builds the single unified DIFF Activity Leaderboard embed."""
    from datetime import timezone as _tz
    om_data = _om_stats_load()
    medals = {1: "🥇", 2: "🥈", 3: "🥉"}

    # Top Hosts
    host_list = sorted(
        om_data.get("hosts", {}).values(),
        key=lambda x: (x.get("meets_completed", 0), x.get("total_attendance", 0)),
        reverse=True,
    )
    host_lines = []
    for i, s in enumerate(host_list[:5], 1):
        prefix = medals.get(i, f"**{i}.**")
        host_lines.append(
            f"{prefix} {_readable_host(None, s['user_id'])} — "
            f"Hosted: **{s.get('meets_hosted', 0)}** | "
            f"Completed: **{s.get('meets_completed', 0)}** | "
            f"Attend: **{s.get('total_attendance', 0)}** | "
            f"NS: **{s.get('total_no_shows', 0)}**"
        )

    # Top Members (RSVP leaderboard — most active meet attendees)
    rsvp_top = sorted(
        _rsvp_leaderboard.values(),
        key=lambda x: (int(x.get("attendance_count", 0)), int(x.get("hosted_count", 0))),
        reverse=True,
    )[:5]
    member_lines = []
    for i, entry in enumerate(rsvp_top, 1):
        prefix = medals.get(i, f"**{i}.**")
        member_lines.append(
            f"{prefix} <@{entry['user_id']}> — "
            f"Meets: **{entry.get('attendance_count', 0)}** | "
            f"Hosted: **{entry.get('hosted_count', 0)}**"
        )

    # Staff Performance
    staff_rows = _auto_stats.leaderboard()
    staff_lines = []
    top_performer: tuple | None = None
    for idx, (uid, stats) in enumerate(staff_rows[:5], 1):
        m = guild.get_member(uid)
        display = m.mention if m else f"<@{uid}>"
        score = _auto_score(stats)
        staff_lines.append(
            f"**#{idx}** {display} — Score: **{score}** | "
            f"Tickets: **{stats.get('tickets_handled', 0)}** | "
            f"Apps: **{stats.get('applications_reviewed', 0)}** | "
            f"Meets: **{stats.get('meets_hosted', 0)}**"
        )
        if idx == 1:
            top_performer = (uid, stats, score)

    embed = discord.Embed(
        title="🏆 DIFF Activity Leaderboard",
        description=(
            "Live tracking of host performance, member attendance, and staff activity.\n"
            "━━━━━━━━━━━━━━━━━━━━━━"
        ),
        color=discord.Color.gold(),
        timestamp=datetime.now(_EST_TZ),
    )
    embed.add_field(
        name="🎙️ Top Hosts",
        value="\n".join(host_lines) if host_lines else "*No host data yet.*",
        inline=False,
    )
    embed.add_field(
        name="👥 Top Members",
        value="\n".join(member_lines) if member_lines else "*No member data yet.*",
        inline=False,
    )
    embed.add_field(
        name="⚙️ Staff Performance",
        value="\n".join(staff_lines) if staff_lines else "*No staff data yet.*",
        inline=False,
    )
    if top_performer:
        uid, stats, score = top_performer
        m = guild.get_member(uid)
        display = m.mention if m else f"<@{uid}>"
        embed.add_field(
            name="🔥 Top Performer of the Week",
            value=(
                f"{display}\n"
                f"Score: **{score}** | "
                f"Tickets: **{stats.get('tickets_handled', 0)}** | "
                f"Apps: **{stats.get('applications_reviewed', 0)}** | "
                f"Meets: **{stats.get('meets_hosted', 0)}**"
            ),
            inline=False,
        )
    if DIFF_LOGO_URL:
        embed.set_thumbnail(url=DIFF_LOGO_URL)
    if DIFF_BANNER_URL:
        embed.set_image(url=DIFF_BANNER_URL)
    embed.set_footer(text="Different Meets • Automated Tracking")
    return embed


async def _upsert_unified_leaderboard(guild: discord.Guild | None = None) -> None:
    """Post or edit the single unified leaderboard message in the leaderboard channel."""
    if guild is None:
        guild = bot.get_guild(GUILD_ID)
    if guild is None:
        return
    channel = guild.get_channel(_OM_LEADERBOARD_CHANNEL_ID)
    if not isinstance(channel, discord.TextChannel):
        return
    embed = _build_unified_lb_embed(guild)
    data = _om_stats_load()
    msg_id = data.get(_OM_LB_MSG_KEY)
    if msg_id:
        try:
            existing = await channel.fetch_message(int(msg_id))
            await existing.edit(content=None, embed=embed)
            return
        except (discord.NotFound, discord.HTTPException):
            pass
    msg = await channel.send(embed=embed)
    data[_OM_LB_MSG_KEY] = msg.id
    _om_stats_save(data)


async def _om_post_or_update_leaderboard() -> None:
    """Legacy wrapper — delegates to the unified leaderboard upsert."""
    await _upsert_unified_leaderboard()


# Class → emoji map (matches the visual language used elsewhere)
_OM_CLASS_EMOJI = {
    "italian": "🏁", "muscle": "🚗", "supercar": "🏎️", "exotic": "🏎️",
    "gran tour": "🏎️", "gt": "🏎️", "tuner": "🚙", "jdm": "🚙",
    "off-road": "🛻", "offroad": "🛻", "classic": "🚘", "lowrider": "🚓",
}

def _om_class_emoji(theme: str) -> str:
    t = (theme or "").lower()
    for key, emj in _OM_CLASS_EMOJI.items():
        if key in t:
            return emj
    return "🏁"


def _om_psn_only(member: "discord.Member | None", fallback_id: int) -> str:
    """Display the host PSN without the ' | Role' suffix."""
    if member is None:
        return f"<@{fallback_id}>"
    name = member.display_name.split(" | ")[0].strip() or member.display_name
    return f"**{name}**"


def _om_build_attendance_embed(record: "_OmRecord", guild: "discord.Guild | None" = None) -> discord.Embed:
    if guild is None:
        guild = bot.get_guild(GUILD_ID) if bot.guilds else None
    host_member = guild.get_member(record.host_id) if guild else None

    emj           = _om_class_emoji(record.theme)
    host_disp     = _om_psn_only(host_member, record.host_id)
    n_present     = len(set(record.checked_in_ids))
    n_late        = len(set(record.late_ids))
    n_unable      = len(set(record.unable_ids))

    # Headline countdown
    countdown = f"<t:{record.timestamp}:R>"
    color     = 0x57F287 if (record.timestamp - int(time.time())) > 0 else 0xFAA61A

    embed = discord.Embed(
        title=f"📊 DIFF Meet Attendance — {emj} {record.theme}",
        description=f"🕐 **Starts {countdown}** · <t:{record.timestamp}:F>",
        color=color,
        timestamp=datetime.now(timezone.utc),
    )
    embed.add_field(name="🎤 Host", value=host_disp, inline=True)
    embed.add_field(name="\u200b", value="\u200b", inline=True)
    embed.add_field(name="\u200b", value="\u200b", inline=True)

    embed.add_field(
        name="✅ How to Check In",
        value=(
            "• **Present** — you're here\n"
            "• **Late** — joining a bit late\n"
            "• **Unable to Join** — can't make it (you can leave a quick reason)\n"
            "• **Clear my RSVP** — remove your status if it changes"
        ),
        inline=False,
    )

    # Live RSVP tallies — social-proof drives RSVPs
    tally = f"✅ Present: **{n_present}**  ·  🕒 Late: **{n_late}**  ·  ❌ Can't make it: **{n_unable}**"
    embed.add_field(name="📈 Live RSVP", value=tally, inline=False)

    if record.unable_reasons:
        lines = []
        for uid_str, reason in list(record.unable_reasons.items())[:5]:
            try:
                m = guild.get_member(int(uid_str)) if guild else None
                disp = (m.display_name.split(" | ")[0].strip() if m else f"<@{uid_str}>")
            except Exception:
                disp = f"<@{uid_str}>"
            lines.append(f"• **{disp}** — {str(reason)[:80]}")
        embed.add_field(name="📝 Heads up (Can't make it)", value="\n".join(lines), inline=False)

    embed.set_footer(text="Different Meets · Attendance updates live on each click")
    return embed


async def _om_refresh_attendance_panels(record: "_OmRecord") -> None:
    """Edit every attendance panel message with the latest embed + tallies.
    Hardened: per-call timeout (5s total), bounded fetch attempts, never
    re-attaches a fresh view (already registered persistently)."""
    if not bot.guilds:
        return
    guild = bot.guilds[0]
    try:
        embed = _om_build_attendance_embed(record, guild)
    except Exception as _e:
        print(f"[OMAtt] embed build error: {_e}")
        return
    msg_ids = list(record.attendance_all_msg_ids or [])
    if record.attendance_message_id and record.attendance_message_id not in msg_ids:
        msg_ids.append(record.attendance_message_id)
    if not msg_ids:
        return
    ch_candidates = [
        bot.get_channel(_CREW_CHAT_CHANNEL_ID),
        bot.get_channel(_EVERYONE_CHAT_CHANNEL_ID),
    ]

    async def _do_refresh():
        for mid in msg_ids[:4]:  # cap to 4 messages defensively
            for ch in ch_candidates:
                if not isinstance(ch, discord.TextChannel):
                    continue
                try:
                    msg = await ch.fetch_message(int(mid))
                    await msg.edit(embed=embed)  # no view= — already registered persistently
                    break
                except (discord.NotFound, discord.Forbidden):
                    continue
                except Exception:
                    continue

    try:
        await asyncio.wait_for(_do_refresh(), timeout=5.0)
    except asyncio.TimeoutError:
        print("[OMAtt] refresh timed out — skipped to keep loop responsive")
    except Exception as _e:
        print(f"[OMAtt] refresh error: {_e}")


class _OmUnableReasonModal(discord.ui.Modal, title="Why can't you make it? (optional)"):
    reason = discord.ui.TextInput(
        label="Reason (1 line, optional)",
        placeholder="e.g. have to work late, family thing, controller died…",
        required=False,
        max_length=120,
        style=discord.TextStyle.short,
    )

    def __init__(self, attendance_msg_id: int):
        super().__init__(timeout=300)
        self.attendance_msg_id = attendance_msg_id

    async def on_submit(self, interaction: discord.Interaction):
        record = _om_get_record_by_attendance_msg(self.attendance_msg_id)
        if not record or record.ended:
            return await interaction.response.send_message("Meet not found or already ended.", ephemeral=True)
        uid = interaction.user.id
        record.checked_in_ids = [x for x in record.checked_in_ids if x != uid]
        record.late_ids       = [x for x in record.late_ids       if x != uid]
        record.unable_ids     = [x for x in record.unable_ids     if x != uid]
        record.unable_ids.append(uid)
        reason_text = str(self.reason.value or "").strip()
        if reason_text:
            record.unable_reasons[str(uid)] = reason_text
        else:
            record.unable_reasons.pop(str(uid), None)
        _om_upsert_record(record)

        # DM the host if marked unable within 1h of start (gives time to backfill).
        # Fire-and-forget so a slow Discord DM API call NEVER blocks the modal callback.
        try:
            secs_until = record.timestamp - int(time.time())
            if 0 < secs_until <= 3600 and bot.guilds:
                host = bot.guilds[0].get_member(record.host_id)
                if host:
                    note = f' — _"{reason_text}"_' if reason_text else ""
                    msg_text = (
                        f"⚠️ Heads up — **{interaction.user.display_name}** just marked **Unable to Join** "
                        f"for **{record.theme}** (starts <t:{record.timestamp}:R>){note}."
                    )
                    async def _bg_dm():
                        try:
                            await asyncio.wait_for(safe_dm(host, msg_text), timeout=5.0)
                        except Exception:
                            pass
                    asyncio.create_task(_bg_dm())
        except Exception:
            pass

        await interaction.response.send_message(
            f"❌ You've been marked as **Unable to Join**." + (f"\n📝 Reason recorded." if reason_text else ""),
            ephemeral=True,
        )
        try:
            await _om_refresh_attendance_panels(record)
        except Exception:
            pass


class _OmAttendanceView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    async def _handle(self, interaction: discord.Interaction, state: str):
        record = _om_get_record_by_attendance_msg(interaction.message.id)
        if not record:
            await interaction.response.send_message("Meet record not found.", ephemeral=True)
            return
        if record.ended:
            await interaction.response.send_message("This meet has already ended.", ephemeral=True)
            return
        uid = interaction.user.id

        # Unable to Join → open optional reason modal (handles everything itself)
        if state == "unable":
            return await interaction.response.send_modal(_OmUnableReasonModal(interaction.message.id))

        # Clear RSVP → drop from all lists
        record.checked_in_ids = [x for x in record.checked_in_ids if x != uid]
        record.late_ids       = [x for x in record.late_ids       if x != uid]
        record.unable_ids     = [x for x in record.unable_ids     if x != uid]
        record.unable_reasons.pop(str(uid), None)

        if state == "present":
            record.checked_in_ids.append(uid)
            reply = "✅ You've been checked in as **Present**."
        elif state == "late":
            record.late_ids.append(uid)
            reply = "🕐 You've been marked as **Late**."
        elif state == "clear":
            reply = "↻ Your RSVP has been cleared."
        else:
            reply = "Unknown action."
        _om_upsert_record(record)
        await interaction.response.send_message(reply, ephemeral=True)
        try:
            await _om_refresh_attendance_panels(record)
        except Exception:
            pass

    @discord.ui.button(label="Present", style=discord.ButtonStyle.success, emoji="✅", custom_id="diff_om_att:present")
    async def btn_present(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle(interaction, "present")

    @discord.ui.button(label="Late", style=discord.ButtonStyle.secondary, emoji="🕒", custom_id="diff_om_att:late")
    async def btn_late(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle(interaction, "late")

    @discord.ui.button(label="Unable to Join", style=discord.ButtonStyle.danger, emoji="❌", custom_id="diff_om_att:unable")
    async def btn_unable(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle(interaction, "unable")

    @discord.ui.button(label="Clear my RSVP", style=discord.ButtonStyle.secondary, emoji="↻", custom_id="diff_om_att:clear", row=1)
    async def btn_clear(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle(interaction, "clear")


async def _om_create_attendance_panel(record: _OmRecord) -> discord.Message | None:
    att_embed = _om_build_attendance_embed(record)

    all_msgs: list[discord.Message] = []

    # Post to crew chat with @Crew Member ping
    crew_ch = bot.get_channel(_CREW_CHAT_CHANNEL_ID)
    if isinstance(crew_ch, discord.TextChannel):
        try:
            m = await crew_ch.send(
                content=f"<@&{CREW_MEMBER_ROLE_ID}>",
                embed=att_embed,
                view=_OmAttendanceView(),
                allowed_mentions=discord.AllowedMentions(roles=True, users=False),
            )
            all_msgs.append(m)
        except Exception:
            pass

    # Post to everyone chat with @PS5 Member ping
    everyone_ch = bot.get_channel(_EVERYONE_CHAT_CHANNEL_ID)
    if isinstance(everyone_ch, discord.TextChannel):
        try:
            m = await everyone_ch.send(
                content=f"<@&{PS5_ROLE_ID}>",
                embed=att_embed,
                view=_OmAttendanceView(),
                allowed_mentions=discord.AllowedMentions(roles=True, users=False),
            )
            all_msgs.append(m)
        except Exception:
            pass

    return all_msgs[0] if all_msgs else None, all_msgs


def _om_get_counts(msg_id: int) -> dict:
    data = _om_rsvps.get(msg_id, {})
    return {
        "yes": len(data.get("yes", set())),
        "maybe": len(data.get("maybe", set())),
        "no": len(data.get("no", set())),
    }


class _OfficialMeetRSVPView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    async def _handle_rsvp(self, interaction: discord.Interaction, status: str):
        msg_id = interaction.message.id
        uid = interaction.user.id
        if msg_id not in _om_rsvps:
            _om_rsvps[msg_id] = {"yes": set(), "maybe": set(), "no": set()}
        for s in ("yes", "maybe", "no"):
            _om_rsvps[msg_id][s].discard(uid)
        _om_rsvps[msg_id][status].add(uid)

        # Persist RSVP to the saved record so counts survive restarts
        record = _om_get_record(msg_id)
        if record:
            for attr in ("rsvp_yes_ids", "rsvp_maybe_ids", "rsvp_no_ids"):
                lst = getattr(record, attr)
                if uid in lst:
                    lst.remove(uid)
            attr_map = {"yes": "rsvp_yes_ids", "maybe": "rsvp_maybe_ids", "no": "rsvp_no_ids"}
            target = getattr(record, attr_map[status])
            if uid not in target:
                target.append(uid)
            _om_upsert_record(record)

        counts = _om_get_counts(msg_id)
        for child in self.children:
            if isinstance(child, discord.ui.Button):
                if child.custom_id == "diff_om_rsvp:yes":
                    child.label = f"Attending ({counts['yes']})"
                elif child.custom_id == "diff_om_rsvp:maybe":
                    child.label = f"Maybe ({counts['maybe']})"
                elif child.custom_id == "diff_om_rsvp:no":
                    child.label = f"Not Attending ({counts['no']})"
        label_map = {"yes": "Attending", "maybe": "Maybe", "no": "Not Attending"}
        await interaction.response.edit_message(view=self)
        await interaction.followup.send(
            f"You're marked as **{label_map[status]}** for this meet.", ephemeral=True
        )

    async def _handle_ctrl(self, interaction: discord.Interaction, action: str):
        msg_id = interaction.message.id
        record = _om_get_record(msg_id)
        member = interaction.user
        is_staff = (
            isinstance(member, discord.Member)
            and (member.guild_permissions.manage_guild or any(r.id in _JOIN_STAFF_ROLE_IDS for r in member.roles))
        )
        is_host = record and isinstance(member, discord.Member) and member.id == record.host_id
        if not (is_staff or is_host):
            await interaction.response.send_message("Only the assigned host or staff can use this.", ephemeral=True)
            return
        if not record:
            await interaction.response.send_message("Meet record not found.", ephemeral=True)
            return

        if action == "start":
            if record.started:
                await interaction.response.send_message("This meet has already been started.", ephemeral=True)
                return
            if record.ended:
                await interaction.response.send_message("This meet has already ended.", ephemeral=True)
                return
            record.started = True
            record.started_at_ts = int(datetime.now(timezone.utc).timestamp())
            att_msg, att_all_msgs = await _om_create_attendance_panel(record)
            if att_msg:
                record.attendance_message_id = att_msg.id
                record.attendance_channel_id = att_msg.channel.id
                record.attendance_all_msg_ids = [m.id for m in att_all_msgs]
            _om_upsert_record(record)
            _om_increment_host_stat(record.host_id, "meets_hosted")
            ch = bot.get_channel(record.channel_id)
            att_ref = f"<#{_CREW_CHAT_CHANNEL_ID}> and <#{_EVERYONE_CHAT_CHANNEL_ID}>" if att_msg else "#chat"
            if isinstance(ch, discord.TextChannel):
                live_embed = discord.Embed(
                    title="🚨 DIFF Session Is Now Live",
                    description="The meet has officially started. Join up and get in position.",
                    color=0x57F287,
                    timestamp=datetime.now(timezone.utc),
                )
                live_embed.add_field(name="⏰ Started", value=f"<t:{record.timestamp}:R>", inline=True)
                live_embed.add_field(name="🎮 Host", value=_readable_host(None, record.host_id) or f"<@{record.host_id}>", inline=True)
                live_embed.add_field(
                    name="📋 Instructions",
                    value="Add the host on PSN and head to **#chat** for session updates.",
                    inline=False,
                )
                live_embed.add_field(
                    name="📊 Attendance",
                    value=f"Tracking is now open in {att_ref}.\nCheck in with **Present**, **Late**, or **Unable to Join**.",
                    inline=False,
                )
                live_embed.set_thumbnail(url=DIFF_LOGO_URL)
                live_embed.set_footer(text="DIFF Meets • Session Live")
                _sent_live = await ch.send(
                    content=f"<@&{PS5_ROLE_ID}> <@&{NOTIFY_ROLE_ID}>",
                    embed=live_embed,
                    allowed_mentions=discord.AllowedMentions(roles=True, users=True),
                )
                try:
                    record.live_message_id = int(_sent_live.id)
                    _om_upsert_record(record)
                except Exception:
                    pass
            await _om_staff_log("Meet Started", record, interaction.user)
            for child in self.children:
                if isinstance(child, discord.ui.Button) and child.custom_id == "diff_om_ctrl:start":
                    child.disabled = True
            await interaction.response.edit_message(view=self)
            await interaction.followup.send(
                f"Meet marked as **live**. Attendance panel posted in <#{_CREW_CHAT_CHANNEL_ID}> and <#{_EVERYONE_CHAT_CHANNEL_ID}>.",
                ephemeral=True,
            )

        elif action == "end":
            if record.ended:
                await interaction.response.send_message("This meet has already ended.", ephemeral=True)
                return
            # Defer immediately — the end flow does several network calls (close
            # embed, staff log, leaderboard, message cleanup) that can blow past
            # Discord's 3s ack window and throw 10062 Unknown interaction.
            try:
                await interaction.response.defer(ephemeral=True)
            except discord.InteractionResponded:
                pass
            except Exception as _e:
                _bot_log.warning("[EndMeet] defer failed: %s", _e)
            record.ended = True
            record.ended_at_ts = int(datetime.now(timezone.utc).timestamp())
            rsvp_pool = set(record.rsvp_yes_ids) | set(record.rsvp_maybe_ids)
            if not rsvp_pool:
                rsvp_pool = set(x for x in _om_rsvps.get(record.message_id, {}).get("yes", set()))
                rsvp_pool |= set(x for x in _om_rsvps.get(record.message_id, {}).get("maybe", set()))
            present_pool = set(record.checked_in_ids) | set(record.late_ids) | set(record.unable_ids)
            record.no_show_ids = sorted(list(rsvp_pool - present_pool))
            _om_upsert_record(record)
            for uid in set(record.checked_in_ids):
                _om_increment_member_stat(uid, "attended")
            for uid in set(record.late_ids):
                _om_increment_member_stat(uid, "late")
            for uid in set(record.unable_ids):
                _om_increment_member_stat(uid, "unable")
            for uid in set(record.no_show_ids):
                _om_increment_member_stat(uid, "no_shows")
            _om_increment_host_stat(record.host_id, "meets_completed")
            _om_increment_host_stat(record.host_id, "total_attendance", len(set(record.checked_in_ids)))
            _om_increment_host_stat(record.host_id, "total_late", len(set(record.late_ids)))
            _om_increment_host_stat(record.host_id, "total_no_shows", len(set(record.no_show_ids)))
            ch = bot.get_channel(record.channel_id)
            if isinstance(ch, discord.TextChannel):
                _present  = len(set(record.checked_in_ids))
                _late     = len(set(record.late_ids))
                _unable   = len(set(record.unable_ids))
                _no_shows = len(set(record.no_show_ids))
                close_embed = discord.Embed(
                    title="📌 DIFF Meet Closed",
                    description="This session has officially ended. Thanks to everyone who attended.",
                    color=0xED4245,
                    timestamp=datetime.now(timezone.utc),
                )
                close_embed.add_field(name="🎙️ Host", value=_readable_host(None, record.host_id) or f"<@{record.host_id}>", inline=True)
                close_embed.add_field(name="🎨 Theme", value=record.theme, inline=True)
                close_embed.add_field(name="📅 Scheduled", value=f"<t:{record.timestamp}:F>", inline=False)
                close_embed.add_field(
                    name="📊 Attendance Summary",
                    value=(
                        f"✅ Present: **{_present}**\n"
                        f"⏰ Late: **{_late}**\n"
                        f"❌ Unable: **{_unable}**\n"
                        f"👻 No-Shows: **{_no_shows}**"
                    ),
                    inline=False,
                )
                close_embed.set_thumbnail(url=DIFF_LOGO_URL)
                close_embed.set_footer(text="DIFF Meets • Session Closed")
                _close_sent = await ch.send(embed=close_embed)
                try:
                    record.close_message_id = int(_close_sent.id)
                    _om_upsert_record(record)
                except Exception:
                    pass
            await _om_staff_log("Meet Ended", record, interaction.user)
            try:
                await _om_post_or_update_leaderboard()
            except Exception:
                pass
            for child in self.children:
                if isinstance(child, discord.ui.Button) and child.custom_id in (
                    "diff_om_ctrl:start", "diff_om_ctrl:end", "diff_om_ctrl:cancel"
                ):
                    child.disabled = True
            # Already deferred above — edit the message directly (can't use
            # interaction.response.* after a defer).
            try:
                await interaction.message.edit(view=self)
            except Exception:
                pass
            # Auto-cleanup: delete the original meet announcement, the 1h + 15min
            # reminder embeds, the "DIFF Meet Live" announcement (if any), and
            # archive the discussion thread. The "📌 DIFF Meet Closed" summary
            # embed posted just above stays in the channel as the permanent record.
            _deleted = False
            _deleted_extras = 0
            _ch = bot.get_channel(record.channel_id)
            if isinstance(_ch, discord.TextChannel):
                # main announcement + its thread
                try:
                    _msg = await _ch.fetch_message(record.message_id)
                    try:
                        _thr = _msg.thread
                        if _thr is not None:
                            try:
                                await _thr.edit(archived=True, locked=False)
                            except Exception:
                                pass
                    except Exception:
                        pass
                    await _msg.delete()
                    _deleted = True
                except Exception as _de:
                    _bot_log.warning("[OM] end cleanup — delete announcement %s failed: %s",
                                     record.message_id, _de)
                # 1h + 15min reminder embeds
                for _rid in list(record.reminder_message_ids or []):
                    try:
                        _rmsg = await _ch.fetch_message(int(_rid))
                        await _rmsg.delete()
                        _deleted_extras += 1
                    except Exception as _re:
                        _bot_log.warning("[OM] end cleanup — delete reminder %s failed: %s",
                                         _rid, _re)
                # "DIFF Meet Live" announcement, if start was pressed
                if record.live_message_id:
                    try:
                        _live = await _ch.fetch_message(int(record.live_message_id))
                        await _live.delete()
                        _deleted_extras += 1
                    except Exception as _le:
                        _bot_log.warning("[OM] end cleanup — delete live notice %s failed: %s",
                                         record.live_message_id, _le)
            try:
                _g = interaction.guild or bot.get_guild(GUILD_ID)
                if _g:
                    await _om_panel_post_or_refresh(_g, force_repost=True)
            except Exception:
                pass
            _extras_line = ""
            if _deleted_extras:
                _extras_line = f" Plus {_deleted_extras} reminder/live notice{'s' if _deleted_extras != 1 else ''} cleaned up."
            await interaction.followup.send(
                "Meet marked as **ended**. Attendance stats saved and leaderboard updated."
                + ((f"\n🧹 Original announcement deleted; the **DIFF Meet Closed** summary stays in the channel.{_extras_line}")
                   if _deleted else ""),
                ephemeral=True,
            )

    @discord.ui.button(label="Attending (0)", style=discord.ButtonStyle.success, custom_id="diff_om_rsvp:yes", row=0)
    async def btn_yes(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle_rsvp(interaction, "yes")

    @discord.ui.button(label="Maybe (0)", style=discord.ButtonStyle.secondary, custom_id="diff_om_rsvp:maybe", row=0)
    async def btn_maybe(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle_rsvp(interaction, "maybe")

    @discord.ui.button(label="Not Attending (0)", style=discord.ButtonStyle.danger, custom_id="diff_om_rsvp:no", row=0)
    async def btn_no(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle_rsvp(interaction, "no")

    @discord.ui.button(label="▶ Start Meet", style=discord.ButtonStyle.success, custom_id="diff_om_ctrl:start", row=1)
    async def btn_start(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle_ctrl(interaction, "start")

    @discord.ui.button(label="⏹ End Meet", style=discord.ButtonStyle.danger, custom_id="diff_om_ctrl:end", row=1)
    async def btn_end(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle_ctrl(interaction, "end")

    @discord.ui.button(label="🚫 Cancel Meet", style=discord.ButtonStyle.secondary, custom_id="diff_om_ctrl:cancel", row=2)
    async def btn_cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        # BUGFIX: never silently return — always respond to the interaction or
        # Discord shows "This interaction failed" to the user.
        if not isinstance(interaction.user, discord.Member):
            return await interaction.response.send_message(
                "This action must be used inside the server.", ephemeral=True
            )
        try:
            is_staff = (
                interaction.user.guild_permissions.manage_guild
                or any(r.id in _JOIN_STAFF_ROLE_IDS for r in interaction.user.roles)
            )
        except Exception:
            is_staff = False
        if not is_staff:
            return await interaction.response.send_message("Only staff can cancel a meet.", ephemeral=True)
        msg_id = interaction.message.id
        record = _om_get_record(msg_id)
        if not record:
            return await interaction.response.send_message("Meet record not found.", ephemeral=True)
        if record.ended:
            return await interaction.response.send_message("This meet has already ended (or already cancelled).", ephemeral=True)

        # Defer first so we always have ≥15 min to finish even on slow Discord API
        try:
            await interaction.response.defer(ephemeral=True)
        except discord.InteractionResponded:
            pass
        except Exception as _e:
            _bot_log.warning("[CancelMeet] defer failed: %s", _e)

        # Post cancellation notice in the meet channel
        cancel_embed = discord.Embed(
            title="🚫 Official Meet Cancelled",
            description=(
                f"The **{record.theme}** meet scheduled for <t:{record.timestamp}:F> "
                f"has been **cancelled** by {interaction.user.mention}.\n\n"
                "Keep an eye out for the next scheduled meet."
            ),
            color=discord.Color.red(),
            timestamp=datetime.now(timezone.utc),
        )
        cancel_embed.set_thumbnail(url=DIFF_LOGO_URL)
        cancel_embed.set_footer(text="DIFF Meets • Official Session")
        ch = bot.get_channel(record.channel_id) or interaction.channel
        if isinstance(ch, discord.TextChannel):
            try:
                await ch.send(
                    content=f"<@&{PS5_ROLE_ID}>",
                    embed=cancel_embed,
                    allowed_mentions=discord.AllowedMentions(roles=True),
                )
            except Exception:
                pass

        # DM the host
        guild = interaction.guild or bot.get_guild(GUILD_ID)
        if guild:
            host = guild.get_member(record.host_id)
            if host:
                try:
                    dm = discord.Embed(
                        title="🚫 Your Scheduled Meet Was Cancelled",
                        description=(
                            f"Your **{record.theme}** meet (scheduled for <t:{record.timestamp}:F>) "
                            f"has been cancelled by {interaction.user.display_name}."
                        ),
                        color=discord.Color.red(),
                    )
                    dm.set_footer(text="Different Meets • Official Meet System")
                    await host.send(embed=dm)
                except Exception:
                    pass

        # Mark ended so it won't auto-bump or show as next meet
        record.ended = True
        _om_upsert_record(record)

        # Disable all buttons on the original meet post
        for child in self.children:
            child.disabled = True
        try:
            await interaction.message.edit(view=self)
        except Exception:
            pass

        try:
            await _om_staff_log("Meet Cancelled", record, interaction.user)
        except Exception as _e:
            _bot_log.warning("[CancelMeet] staff log failed: %s", _e)

        # ALWAYS send a followup so the interaction resolves cleanly
        try:
            await interaction.followup.send("Meet cancelled and the channel has been notified.", ephemeral=True)
        except Exception as _e:
            _bot_log.warning("[CancelMeet] followup failed: %s", _e)

        # Refresh panel so next-meet field updates (non-critical — never crashes the click)
        if guild:
            try:
                await _om_panel_post_or_refresh(guild, force_repost=False)
            except Exception as _e:
                _bot_log.warning("[CancelMeet] panel refresh failed: %s", _e)


async def _om_staff_log(title: str, record: _OmRecord, acted_by: discord.Member) -> None:
    ch = bot.get_channel(STAFF_LOGS_CHANNEL_ID)
    if not isinstance(ch, discord.TextChannel):
        return
    embed = discord.Embed(title=f"🏁 {title}", color=discord.Color.blurple(), timestamp=datetime.now(timezone.utc))
    embed.add_field(name="Host", value=_readable_host(None, record.host_id) or f"<@{record.host_id}>", inline=True)
    embed.add_field(name="Theme", value=record.theme, inline=True)
    embed.add_field(name="Scheduled", value=f"<t:{record.timestamp}:F>", inline=False)
    embed.add_field(name="Action By", value=acted_by.mention, inline=True)
    try:
        await ch.send(embed=embed)
    except Exception:
        pass


async def _om_reminder_task(msg_id: int, delay_secs: int, reminder_type: str) -> None:
    try:
        if delay_secs > 0:
            await asyncio.sleep(delay_secs)
        record = _om_get_record(msg_id)
        if not record or record.ended:
            return
        if reminder_type == "1h" and record.one_hour_sent:
            return
        if reminder_type == "15m" and record.fifteen_sent:
            return
        ch = bot.get_channel(record.channel_id)
        if isinstance(ch, discord.TextChannel):
            if reminder_type == "1h":
                embed = discord.Embed(
                    title="⏳ DIFF Meet Reminder — 1 Hour to Go",
                    description="The meet is coming up. Get your build ready and check in with the host.",
                    color=0xFEE75C,
                )
                embed.add_field(name="⏰ Starts", value=f"<t:{record.timestamp}:R>", inline=True)
                embed.add_field(
                    name="✅ Before You Join",
                    value="• Send your car photos to the host\n• Check the theme and dress your build\n• Be in the right voice channel",
                    inline=False,
                )
                embed.set_thumbnail(url=DIFF_LOGO_URL)
                embed.set_footer(text="DIFF Meets • 1 Hour Reminder")
                _sent_rem = await ch.send(embed=embed)
                record.one_hour_sent = True
                try:
                    record.reminder_message_ids.append(int(_sent_rem.id))
                except Exception:
                    pass
            else:
                embed = discord.Embed(
                    title="🚨 DIFF Meet Starting Soon — 15 Minutes",
                    description="Final call — the meet is almost live. Make sure everything is ready.",
                    color=0xFF8C00,
                )
                embed.add_field(name="⏰ Starts", value=f"<t:{record.timestamp}:R>", inline=True)
                embed.add_field(
                    name="🔥 Last Checks",
                    value="• Cars loaded and ready\n• Host has your photos\n• You're in the correct VC",
                    inline=False,
                )
                embed.set_thumbnail(url=DIFF_LOGO_URL)
                embed.set_footer(text="DIFF Meets • Starting Soon")
                _sent_rem = await ch.send(embed=embed)
                record.fifteen_sent = True
                try:
                    record.reminder_message_ids.append(int(_sent_rem.id))
                except Exception:
                    pass
            _om_upsert_record(record)
    except asyncio.CancelledError:
        pass
    except Exception as e:
        print(f"[OfficialMeet] reminder error: {e}")


def _om_schedule_reminders(record: _OmRecord) -> None:
    now_ts = int(datetime.now(timezone.utc).timestamp())
    if not record.one_hour_sent:
        delay = record.timestamp - now_ts - 3600
        asyncio.create_task(_om_reminder_task(record.message_id, max(delay, 0), "1h"))
    if not record.fifteen_sent:
        delay = record.timestamp - now_ts - 900
        asyncio.create_task(_om_reminder_task(record.message_id, max(delay, 0), "15m"))


async def _om_restore_on_ready() -> None:
    await bot.wait_until_ready()
    data = _om_load_records()
    now_ts = int(datetime.now(timezone.utc).timestamp())
    for raw in data.values():
        try:
            record = _OmRecord(**{k: v for k, v in raw.items() if k in _OmRecord.__dataclass_fields__})
        except Exception:
            continue
        if record.ended and record.timestamp < now_ts - 86400:
            continue
        _om_schedule_reminders(record)
        if record.started or record.ended:
            ch = bot.get_channel(record.channel_id)
            if isinstance(ch, discord.TextChannel):
                try:
                    msg = await ch.fetch_message(record.message_id)
                    view = _OfficialMeetRSVPView()
                    for child in view.children:
                        if isinstance(child, discord.ui.Button):
                            if child.custom_id == "diff_om_ctrl:start" and (record.started or record.ended):
                                child.disabled = True
                            if child.custom_id == "diff_om_ctrl:end" and record.ended:
                                child.disabled = True
                    await msg.edit(view=view)
                except Exception:
                    pass


