_OM_PANEL_FILE = os.path.join(DATA_FOLDER, "diff_om_panel.json")


def _om_panel_load() -> dict:
    try:
        with open(_OM_PANEL_FILE) as f:
            return json.load(f)
    except Exception:
        return {}


def _om_panel_save(data: dict):
    try:
        _atomic_json_save(_OM_PANEL_FILE, data)
    except Exception:
        pass


def _om_parse_datetime(date_str: str, time_str: str) -> int | None:
    """Parse 'YYYY-MM-DD' + '8pm EST' into a Unix timestamp. Returns None on failure."""
    from datetime import timedelta
    tz_abbr = "EST"
    clean_time = time_str.strip()
    m = re.search(r'([A-Za-z]{2,4})$', clean_time)
    if m:
        tz_abbr = m.group(1).upper()
        clean_time = clean_time[:m.start()].strip()
    tz_name = _POPUP_TZ_MAP.get(tz_abbr, "America/New_York")
    try:
        tz = ZoneInfo(tz_name)
        date_part = datetime.strptime(date_str.strip(), "%Y-%m-%d").date()
        tm = re.match(r'(\d{1,2})(?::(\d{2}))?\s*(am|pm)?', clean_time, re.IGNORECASE)
        if not tm:
            return None
        hour = int(tm.group(1))
        minute = int(tm.group(2)) if tm.group(2) else 0
        meridiem = tm.group(3).lower() if tm.group(3) else None
        if meridiem == "pm" and hour != 12:
            hour += 12
        elif meridiem == "am" and hour == 12:
            hour = 0
        local_dt = datetime(date_part.year, date_part.month, date_part.day, hour, minute, tzinfo=tz)
        return int(local_dt.timestamp())
    except Exception:
        return None


def _om_next_meet() -> "_OmRecord | None":
    """Return the soonest upcoming non-ended meet, or None."""
    data = _om_load_records()
    now_ts = int(datetime.now(timezone.utc).timestamp())
    upcoming: list[_OmRecord] = []
    for raw in data.values():
        try:
            rec = _OmRecord(**{k: v for k, v in raw.items() if k in _OmRecord.__dataclass_fields__})
            if not rec.ended and rec.timestamp > now_ts:
                upcoming.append(rec)
        except Exception:
            pass
    return min(upcoming, key=lambda r: r.timestamp) if upcoming else None


def _om_restore_rsvp_counts():
    """Restore in-memory RSVP dicts from saved records (called on bot startup)."""
    data = _om_load_records()
    for raw in data.values():
        try:
            rec = _OmRecord(**{k: v for k, v in raw.items() if k in _OmRecord.__dataclass_fields__})
            if rec.ended:
                continue
            _om_rsvps[rec.message_id] = {
                "yes":   set(rec.rsvp_yes_ids),
                "maybe": set(rec.rsvp_maybe_ids),
                "no":    set(rec.rsvp_no_ids),
            }
        except Exception:
            pass


_OM_DAY_ORDER = ["sunday","monday","tuesday","wednesday","thursday","friday","saturday"]
_OM_DAY_EMOJI = {"sunday":"🌞","monday":"🌙","tuesday":"🔥","wednesday":"⚡","thursday":"💎","friday":"🎉","saturday":"🚀"}


def _om_panel_lineup_field() -> tuple[str, str] | None:
    """Return (name, value) for a 7-day host lineup field, or None if schedule empty."""
    try:
        sched = _asched_load()
    except Exception:
        return None
    days = sched.get("days", {}) or {}
    if not days:
        return None
    lines = []
    filled = 0
    open_days = []
    for key in _OM_DAY_ORDER:
        slot = days.get(key) or {}
        host_id = slot.get("host_id")
        emoji = _OM_DAY_EMOJI.get(key, "•")
        day_label = key.capitalize()
        if host_id:
            filled += 1
            theme = (slot.get("theme") or "").strip()
            time_val = (slot.get("time") or "").strip()
            extras = []
            if theme and theme.upper() != "TBD":
                extras.append(theme[:24])
            if time_val and time_val.upper() != "TBD":
                extras.append(time_val[:18])
            tail = f" — {' • '.join(extras)}" if extras else ""
            lines.append(f"{emoji} **{day_label}** — {_readable_host(None, host_id)}{tail}")
        else:
            open_days.append(day_label[:3])
    # One compact line for open days instead of seven "open slot" rows
    if open_days:
        if filled == 0:
            lines.append("⚪ All 7 days open — grab a slot!")
        else:
            lines.append(f"⚪ Open: {' · '.join(open_days)}")
    header = f"🗓️ This Week\'s Host Lineup  ({filled}/7 filled)"
    return header, "\n".join(lines)


def _om_panel_stats_field() -> tuple[str, str] | None:
    """Return (name, value) for monthly meet stats, or None if no data."""
    try:
        records = _om_load_records()
    except Exception:
        return None
    if not records:
        return None
    now_ts = int(datetime.now(timezone.utc).timestamp())
    month_ago = now_ts - 30 * 86400
    week_ago  = now_ts - 7 * 86400
    month_count = 0
    week_count  = 0
    total_yes   = 0
    total_attended = 0
    completed   = 0
    for raw in records.values():
        try:
            ts = int(raw.get("timestamp", 0) or 0)
        except Exception:
            ts = 0
        if ts >= month_ago:
            month_count += 1
            if ts >= week_ago:
                week_count += 1
            if raw.get("ended"):
                completed += 1
                total_yes += len(raw.get("rsvp_yes_ids") or [])
                total_attended += len(raw.get("checked_in_ids") or [])
    avg_att = ""
    # Only show attendance % when there's real check-in data — "0% (0/43)"
    # just cluttered the panel and looked broken.
    if total_attended > 0 and total_yes > 0 and completed > 0:
        pct = int(round((total_attended / total_yes) * 100))
        avg_att = f"\n📈 Avg attendance (last 30d): **{pct}%**  ({total_attended}/{total_yes})"
    if month_count == 0 and not avg_att:
        return None
    return (
        "📊 Recent Activity",
        f"🗓️ **{month_count}** meet(s) in the last 30 days  •  **{week_count}** this week{avg_att}",
    )


def _om_panel_recap_field() -> tuple[str, str] | None:
    """If a meet ended in the last 24h, return a (name, value) recap field."""
    try:
        records = _om_load_records()
    except Exception:
        return None
    if not records:
        return None
    now_ts = int(datetime.now(timezone.utc).timestamp())
    cutoff = now_ts - 86400
    recent = None
    for raw in records.values():
        if not raw.get("ended"):
            continue
        ended_at = raw.get("ended_at_ts") or raw.get("timestamp") or 0
        try:
            ended_at = int(ended_at)
        except Exception:
            continue
        if ended_at >= cutoff and (recent is None or ended_at > recent[0]):
            recent = (ended_at, raw)
    if not recent:
        return None
    _, raw = recent
    theme = (raw.get("theme") or "Official Meet")[:60]
    host_id = raw.get("host_id") or 0
    attended = len(raw.get("checked_in_ids") or [])
    yes_count = len(raw.get("rsvp_yes_ids") or [])
    return (
        "🏁 Last Meet Recap",
        (
            f"**{theme}** — hosted by {_readable_host(None, host_id)}\n"
            f"✅ **{attended}** attended  •  📋 **{yes_count}** RSVPed yes  •  ended <t:{int(recent[0])}:R>"
        ),
    )


def _om_panel_build_embed() -> discord.Embed:
    embed = discord.Embed(
        title="🏁 DIFF Official Meet Hub",
        description=f"Live meet dashboard — posts land in <#{_OFFICIAL_MEET_CHANNEL_ID}>.",
        color=discord.Color.from_rgb(241, 196, 15),
    )
    embed.set_thumbnail(url=DIFF_LOGO_URL)

    # ── Next meet ───────────────────────────────────────────────────────
    next_meet = _om_next_meet()
    if next_meet:
        status = "🟢 Live Now" if next_meet.started else "📅 Upcoming"
        embed.add_field(
            name=f"{status} — Next Official Meet",
            value=(
                f"**{next_meet.theme}**\n"
                f"<t:{next_meet.timestamp}:F>  •  <t:{next_meet.timestamp}:R>\n"
                f"🎙️ Host: {_readable_host(None, next_meet.host_id) or '*TBD*'}"
            ),
            inline=False,
        )
    else:
        embed.add_field(
            name="📅 Next Official Meet",
            value="No meet currently scheduled — staff can use the button below to post one.",
            inline=False,
        )

    # ── 7-day host lineup ──────────────────────────────────────────────
    lineup = _om_panel_lineup_field()
    if lineup:
        embed.add_field(name=lineup[0], value=lineup[1], inline=False)

    # ── Last meet recap (only if ended in last 24h) ────────────────────
    recap = _om_panel_recap_field()
    if recap:
        embed.add_field(name=recap[0], value=recap[1], inline=False)

    # ── Recent activity stats ──────────────────────────────────────────
    stats = _om_panel_stats_field()
    if stats:
        embed.add_field(name=stats[0], value=stats[1], inline=False)

    embed.set_footer(text="📋 Schedule Official Meet to post one • Members can RSVP on any meet • Refreshes hourly")
    embed.timestamp = datetime.now(timezone.utc)
    return embed


def _om_parse_combined_datetime(text: str) -> int | None:
    """Parse a natural-language 'Date & Time' string into a Unix timestamp.

    Layered strategy:
      1. Try the popup smart-parser first — handles relative ("in 30 min", "+45m",
         "in 2 hours"), shorthand ("tonight 9", "tomorrow 7pm CT"), and bare clock
         times ("8pm", "20:00").
      2. Fall through to explicit absolute formats ("April 5 9:00 PM EST",
         "04/05 9PM CST", "2026-04-05 21:00 UTC").
    """
    text = (text or "").strip()
    if not text:
        return None

    _ht = re.search(r'<t:(\d+)(?::[A-Za-z])?>', text)
    if _ht:
        try:
            return int(_ht.group(1))
        except Exception:
            pass

    try:
        parsed = _popup_parse_time(text)
        if parsed and parsed != text:
            _ht2 = re.search(r'<t:(\d+)(?::[A-Za-z])?>', parsed)
            if _ht2:
                return int(_ht2.group(1))
    except Exception:
        pass

    tz_name = "America/New_York"
    m = re.search(r'\b([A-Za-z]{2,5})$', text)
    if m:
        abbr = m.group(1).upper()
        if abbr in _POPUP_TZ_MAP:
            tz_name = _POPUP_TZ_MAP[abbr]
            text = text[:m.start()].strip()
    try:
        tz = ZoneInfo(tz_name)
    except Exception:
        tz = ZoneInfo("America/New_York")
    text = re.sub(r'(\d)(am|pm)', r'\1 \2', text, flags=re.IGNORECASE)
    text = re.sub(r'\s+', ' ', text).strip()
    if not re.search(r'\b(202\d|203\d)\b', text):
        text = f"{text} {datetime.now(timezone.utc).year}"
    fmts = [
        "%B %d %Y %I:%M %p", "%B %d %Y %I %p",
        "%B %d, %Y %I:%M %p", "%B %d, %Y %I %p",
        "%m/%d/%Y %I:%M %p", "%m/%d/%Y %I %p",
        "%m/%d %I:%M %p %Y", "%m/%d %I %p %Y",
        "%Y-%m-%d %H:%M",    "%Y-%m-%d %I:%M %p",
        "%Y-%m-%d %I %p",
    ]
    for fmt in fmts:
        try:
            naive = datetime.strptime(text, fmt)
            return int(naive.replace(tzinfo=tz).timestamp())
        except ValueError:
            continue
    return None


