def _popup_meet_col(meet, col: str):
    """Safe-read a column from a sqlite3.Row that might not yet have the col
    (older rows pre-migration). Returns 0 / None on missing or KeyError."""
    try:
        return meet[col]
    except Exception:
        return 0


def _popup_parse_capacity(raw: str) -> int:
    """Parse a capacity field. 0 = unlimited. Clamps to 1..50 when valid."""
    if not raw:
        return 0
    import re
    m = re.search(r"\d{1,3}", str(raw))
    if not m:
        return 0
    n = int(m.group(0))
    if n <= 0:
        return 0
    return min(50, n)


def _popup_sanitize(text: str) -> str:
    """Defang @everyone / @here so a host can't mass-ping via the modal."""
    if not text:
        return text
    return (text
            .replace("@everyone", "@\u200beveryone")
            .replace("@here", "@\u200bhere"))


def _popup_parse_time(raw: str) -> str:
    """Convert a flexible time string into a Discord timestamp pair (`<t:..:F> — <t:..:R>`).
    Falls back to the original string if parsing fails.

    Accepts:
      • Existing Discord timestamps: `<t:1234567890:F>` → preserved
      • Relative: `now`, `in 30 min`, `in 2 hours`, `in 1h`, `+45m`
      • Absolute clock: `8pm`, `8:30pm`, `20:00`, `8pm ET`, `8:30pm CST`
      • With "tonight" / "tomorrow" prefix: `tonight 9`, `tomorrow 7pm ET`
      • If past today and no "tomorrow" hint, auto-rolls to tomorrow.
    """
    import re
    from datetime import timedelta
    s = (raw or "").strip()
    if not s:
        return raw

    # Pass-through any existing Discord timestamp
    if re.search(r"<t:\d+(?::[a-zA-Z])?>", s):
        return s

    sl = s.lower()

    # "now"
    if sl in ("now", "right now", "asap"):
        ts = int(datetime.now(timezone.utc).timestamp())
        return f"<t:{ts}:F> — <t:{ts}:R>"

    # Relative: "in 30 min", "in 2 hours", "in 1h", "+45m", "+2h"
    m_rel = re.match(
        r"^(?:in\s+|\+)\s*(\d{1,3})\s*(m|min|mins|minute|minutes|h|hr|hrs|hour|hours)\.?$",
        sl,
    )
    if m_rel:
        n = int(m_rel.group(1))
        unit = m_rel.group(2)
        delta = timedelta(hours=n) if unit.startswith("h") else timedelta(minutes=n)
        ts = int((datetime.now(timezone.utc) + delta).timestamp())
        return f"<t:{ts}:F> — <t:{ts}:R>"

    # "tonight" / "tomorrow" prefix
    day_offset = 0
    force_pm = False
    s_strip = sl
    if s_strip.startswith("tomorrow"):
        day_offset = 1
        s_strip = s_strip[len("tomorrow"):].strip(" ,")
    elif s_strip.startswith("tonight"):
        force_pm = True
        s_strip = s_strip[len("tonight"):].strip(" ,")

    # Absolute clock: (H)(:MM)? (am|pm)? (TZ)?
    m = re.search(
        r"(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\s*([A-Za-z]{2,4})?",
        s_strip, re.IGNORECASE,
    )
    if not m:
        return raw
    hour = int(m.group(1))
    minute = int(m.group(2)) if m.group(2) else 0
    meridiem = m.group(3).lower() if m.group(3) else None
    tz_abbr = m.group(4).upper() if m.group(4) else "ET"
    tz_name = _POPUP_TZ_MAP.get(tz_abbr, "America/New_York")

    if meridiem == "pm" and hour != 12:
        hour += 12
    elif meridiem == "am" and hour == 12:
        hour = 0
    elif force_pm and hour < 12 and meridiem is None:
        # "tonight 9" → 9pm
        hour += 12
    if hour > 23 or minute > 59:
        return raw

    try:
        tz = ZoneInfo(tz_name)
        now = datetime.now(tz)
        local_dt = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
        if day_offset:
            local_dt += timedelta(days=day_offset)
        elif local_dt <= now:
            local_dt += timedelta(days=1)
        ts = int(local_dt.timestamp())
        return f"<t:{ts}:F> — <t:{ts}:R>"
    except Exception:
        return raw


_POPUP_STAFF_ROLES = _LEADERSHIP_ROLE_IDS


def _popup_build_meet_embed(
    theme: str,
    location: str,
    time_text: str,
    notes: str,
    meet_id: int,
    host_id: int,
    host_display_name: str,
    host_avatar_url: str | None,
    pullup_count: int = 0,
    cantmake_count: int = 0,
    is_ended: bool = False,
    voice_channel_id: int = 0,
    capacity: int = 0,
    waitlist_count: int = 0,
    is_started: bool = False,
) -> discord.Embed:
    if is_ended:
        title = "🛑 DIFF Pop-Up Meet — Ended"
        color = discord.Color.from_rgb(231, 76, 60)
        attendance_line = f"**{pullup_count}** member{'s' if pullup_count != 1 else ''} pulled up"
        if cantmake_count:
            attendance_line += f"  •  {cantmake_count} couldn't make it"
        description = f"This meet has ended. Hosted by {_readable_host(None, host_id)}.\n{attendance_line}"
    elif is_started:
        title = "🟢 DIFF Pop-Up Meet — LIVE NOW"
        color = discord.Color.from_rgb(46, 204, 113)
        description = f"The meet is live — {_readable_host(None, host_id)} is hosting. Pull up now!"
    else:
        title = "⚡ DIFF Pop-Up Meet"
        color = discord.Color.from_rgb(255, 140, 0)
        description = f"{_readable_host(None, host_id)} is hosting a pop-up meet. Pull up!"

    embed = discord.Embed(
        title=title,
        color=color,
        description=description,
        timestamp=datetime.now(timezone.utc),
    )
    if host_avatar_url:
        embed.set_thumbnail(url=host_avatar_url)

    # Row 1: Theme + Location (2 columns, no spacer needed)
    embed.add_field(name="🎨 Theme",    value=theme or "Open Class", inline=True)
    embed.add_field(name="📍 Location", value=(location or "_TBD — ask host_"), inline=True)
    # Row 2: Time + Host + Pulling Up (3 columns)
    embed.add_field(name="🕒 Time",  value=time_text,         inline=True)
    embed.add_field(name="👤 Host",  value=_readable_host(None, host_id) or f"<@{host_id}>",   inline=True)
    if capacity and capacity > 0:
        _cap_str = f"**{pullup_count}/{capacity}** confirmed"
    else:
        _cap_str = f"**{pullup_count}** confirmed"
    if cantmake_count:
        _cap_str += f"  •  {cantmake_count} can\'t make it"
    if waitlist_count:
        _cap_str += f"  •  📋 {waitlist_count} on waitlist"
    embed.add_field(name="🚗 Pulling Up", value=_cap_str, inline=True)
    if voice_channel_id:
        embed.add_field(name="🔊 Voice", value=f"<#{int(voice_channel_id)}>", inline=True)
    if notes:
        embed.add_field(name="📝 Notes", value=notes, inline=False)

    if not is_ended:
        guide = _get_theme_guide(theme or "")
        if guide:
            _display_name, _accepted = guide
            embed.add_field(
                name=f"✅ Accepted Cars — {_display_name}",
                value=_accepted,
                inline=False,
            )

    footer = f"DIFF Pop-Up Meet #{meet_id}"
    if is_ended:
        footer += " • Ended"
    elif is_started:
        footer += " • Live now — pull up!"
    else:
        footer += " • Click below to RSVP"
    embed.set_footer(text=footer)
    return embed


# ── Pop-Up Meet RSVP buttons (Pi-compatible Button subclasses) ────────────────

class _PopupPullUpBtn(discord.ui.Button):
    def __init__(self, meet_id: int):
        super().__init__(
            label="🚗 Pulling Up!",
            style=discord.ButtonStyle.success,
            custom_id=f"diff_popup:{meet_id}:pullup",
            row=0,
        )
        self.meet_id = meet_id

    async def callback(self, interaction: discord.Interaction) -> None:
        if not interaction.guild or not isinstance(interaction.user, discord.Member):
            return await interaction.response.send_message("Server only.", ephemeral=True)
        meet = _popup_db.get_meet(self.meet_id)
        if not meet or meet["is_ended"]:
            return await interaction.response.send_message("This meet has already ended.", ephemeral=True)

        existing = _popup_db.get_user_rsvp(interaction.guild.id, self.meet_id, interaction.user.id)
        cap = int(_popup_meet_col(meet, "capacity") or 0)
        if existing in ("pullup", "waitlist"):
            _popup_db.remove_rsvp(interaction.guild.id, self.meet_id, interaction.user.id)
            reply = "Removed your RSVP."
            # If a pullup spot opened up and capacity is enforced, promote next waitlister
            if existing == "pullup" and cap > 0:
                promoted = _popup_db.promote_oldest_waitlist(interaction.guild.id, self.meet_id)
                if promoted:
                    try:
                        promoted_mem = interaction.guild.get_member(promoted)
                        if promoted_mem:
                            await promoted_mem.send(
                                f"🎉 A spot opened up on pop-up meet #{self.meet_id} — you\'re now confirmed!"
                            )
                    except Exception:
                        pass
        else:
            # Capacity check: at-or-over → waitlist
            if cap > 0:
                _cnt = _popup_db.get_rsvp_counts(interaction.guild.id, self.meet_id)
                if _cnt.get("pullup", 0) >= cap:
                    _popup_db.set_rsvp(interaction.guild.id, self.meet_id, interaction.user.id, "waitlist")
                    reply = f"📋 Meet is full ({cap}/{cap}) — you\'re on the waitlist. We\'ll DM you if a spot opens."
                else:
                    _popup_db.set_rsvp(interaction.guild.id, self.meet_id, interaction.user.id, "pullup")
                    reply = "🚗 You\'re pulling up! See you there."
            else:
                _popup_db.set_rsvp(interaction.guild.id, self.meet_id, interaction.user.id, "pullup")
                reply = "🚗 You\'re pulling up! See you there."

        counts  = _popup_db.get_rsvp_counts(interaction.guild.id, self.meet_id)
        new_emb = _popup_build_meet_embed(
            meet["theme"] or "", meet["location"], meet["time_text"],
            meet["extra_notes"] or "", self.meet_id, meet["host_user_id"],
            meet["host_display_name"] or "", meet["host_avatar_url"],
            counts["pullup"], counts["cantmake"],
            voice_channel_id=_popup_meet_col(meet, "voice_channel_id"),
            capacity=_popup_meet_col(meet, "capacity"),
            waitlist_count=counts.get("waitlist", 0),
        )
        await interaction.response.edit_message(embed=new_emb)
        await interaction.followup.send(reply, ephemeral=True)


