class _PopupStartMeetBtn(discord.ui.Button):
    """Marks a Pop-Up Meet as live — posts a 🟢 LIVE announcement in the meet
    channel (with the original PS5 / Car Meet pings the host selected), DMs
    every member who clicked Pulling Up, and swaps the meet embed to its
    green LIVE state. Host or staff only."""
    def __init__(self, meet_id: int):
        super().__init__(
            label="🟢 Start Meet",
            style=discord.ButtonStyle.success,
            custom_id=f"diff_popup:{meet_id}:start",
            row=1,
        )
        self.meet_id = meet_id

    async def callback(self, interaction: discord.Interaction) -> None:
        if not interaction.guild or not isinstance(interaction.user, discord.Member):
            return await interaction.response.send_message("Server only.", ephemeral=True)
        meet = _popup_db.get_meet(self.meet_id)
        if not meet:
            return await interaction.response.send_message("Meet not found.", ephemeral=True)
        if meet["is_ended"]:
            return await interaction.response.send_message("This meet has already ended.", ephemeral=True)
        try:
            if int(_popup_meet_col(meet, "is_started") or 0) == 1:
                return await interaction.response.send_message("This meet is already live.", ephemeral=True)
        except Exception:
            pass

        is_host  = interaction.user.id == meet["host_user_id"]
        is_staff = interaction.user.guild_permissions.administrator or \
                   any(r.id in _POPUP_STAFF_ROLES for r in interaction.user.roles)
        if not (is_host or is_staff):
            return await interaction.response.send_message(
                "Only the host or staff can start this meet.", ephemeral=True
            )

        await interaction.response.defer(ephemeral=True, thinking=False)
        _popup_db.start_meet(self.meet_id)

        # Refresh embed → green LIVE state
        counts = _popup_db.get_rsvp_counts(interaction.guild.id, self.meet_id)
        live_emb = _popup_build_meet_embed(
            meet["theme"] or "", meet["location"], meet["time_text"],
            meet["extra_notes"] or "", self.meet_id, meet["host_user_id"],
            meet["host_display_name"] or "", meet["host_avatar_url"],
            counts["pullup"], counts["cantmake"], is_ended=False, is_started=True,
            voice_channel_id=_popup_meet_col(meet, "voice_channel_id"),
            capacity=_popup_meet_col(meet, "capacity"),
            waitlist_count=counts.get("waitlist", 0),
        )
        new_view = _PopupMeetView(self.meet_id, is_started=True, is_ended=False)
        try:
            await interaction.message.edit(embed=live_emb, view=new_view)
        except Exception:
            pass

        # Post a 🟢 LIVE announcement in the meet channel with the originally
        # requested pings (ping_playstation → PS5 role, ping_carmeet → Car Meet
        # Notifications role). Falls back silently if channel access is gone.
        ping_parts = []
        try:
            if int(meet["ping_playstation"] or 0) == 1:
                ping_parts.append(f"<@&{PS5_ROLE_ID}>")
        except Exception:
            pass
        try:
            if int(meet["ping_carmeet"] or 0) == 1:
                ping_parts.append(f"<@&{NOTIFY_ROLE_ID}>")
        except Exception:
            pass
        live_announce = discord.Embed(
            title="🟢 Pop-Up Meet — LIVE NOW",
            description=(f"{_readable_host(None, meet['host_user_id'])} just started the pop-up meet. "
                         f"**Pull up!**"),
            color=discord.Color.from_rgb(46, 204, 113),
            timestamp=datetime.now(timezone.utc),
        )
        live_announce.add_field(name="🎨 Theme",    value=meet["theme"] or "Open Class", inline=True)
        live_announce.add_field(name="📍 Location", value=(meet["location"] or "TBD — ask host"), inline=True)
        _vc_id = _popup_meet_col(meet, "voice_channel_id")
        if _vc_id:
            live_announce.add_field(name="🔊 Voice", value=f"<#{int(_vc_id)}>", inline=True)
        live_announce.set_footer(text=f"DIFF Pop-Up Meet #{self.meet_id} • Live now")
        if meet["host_avatar_url"]:
            live_announce.set_thumbnail(url=meet["host_avatar_url"])
        try:
            ch = interaction.channel
            if isinstance(ch, discord.TextChannel):
                _sent_live = await ch.send(
                    content=(" ".join(ping_parts) if ping_parts else None),
                    embed=live_announce,
                    allowed_mentions=discord.AllowedMentions(roles=True, users=False),
                )
                try:
                    _popup_db.set_live_message_id(self.meet_id, int(_sent_live.id))
                except Exception:
                    pass
        except Exception as _le:
            try:
                _bot_log.warning("[Popup] start: live announce send failed for #%s: %s",
                                 self.meet_id, _le)
            except Exception:
                pass

        # DM every member who RSVPd "pullup" (waitlist excluded — they aren't in)
        _dm_ok, _dm_fail = 0, 0
        try:
            pullup_ids = _popup_db.get_rsvp_user_ids(interaction.guild.id, self.meet_id, "pullup")
        except Exception:
            pullup_ids = []
        dm_embed = discord.Embed(
            title="🟢 The pop-up meet is LIVE",
            description=(f"{_readable_host(None, meet['host_user_id'])} just started **{meet['theme'] or 'the pop-up meet'}**. "
                         f"Pull up now!"),
            color=discord.Color.from_rgb(46, 204, 113),
        )
        dm_embed.add_field(name="📍 Location", value=(meet["location"] or "TBD — ask host"), inline=True)
        if _vc_id:
            dm_embed.add_field(name="🔊 Voice", value=f"<#{int(_vc_id)}>", inline=True)
        dm_embed.set_footer(text=f"DIFF Pop-Up Meet #{self.meet_id}")
        for uid in pullup_ids:
            if int(uid) == int(meet["host_user_id"]):
                continue
            try:
                member = interaction.guild.get_member(int(uid)) or await interaction.guild.fetch_member(int(uid))
                if member and not member.bot:
                    await member.send(embed=dm_embed)
                    _dm_ok += 1
            except Exception:
                _dm_fail += 1

        try:
            await interaction.followup.send(
                f"Meet marked as **LIVE** 🟢\n"
                f"📣 Announcement posted with {len(ping_parts)} role ping(s).\n"
                f"📬 DMs sent: **{_dm_ok}** delivered, {_dm_fail} failed.",
                ephemeral=True,
            )
        except Exception:
            pass


class _PopupEndMeetBtn(discord.ui.Button):
    def __init__(self, meet_id: int):
        super().__init__(
            label="🏁 End Meet",
            style=discord.ButtonStyle.danger,
            custom_id=f"diff_popup:{meet_id}:end",
            row=1,
        )
        self.meet_id = meet_id

    async def callback(self, interaction: discord.Interaction) -> None:
        if not interaction.guild or not isinstance(interaction.user, discord.Member):
            return await interaction.response.send_message("Server only.", ephemeral=True)
        meet = _popup_db.get_meet(self.meet_id)
        if not meet:
            return await interaction.response.send_message("Meet not found.", ephemeral=True)
        if meet["is_ended"]:
            return await interaction.response.send_message("Already ended.", ephemeral=True)

        is_host  = interaction.user.id == meet["host_user_id"]
        is_staff = interaction.user.guild_permissions.administrator or \
                   any(r.id in _POPUP_STAFF_ROLES for r in interaction.user.roles)
        if not (is_host or is_staff):
            return await interaction.response.send_message(
                "Only the host or staff can end this meet.", ephemeral=True
            )

        _popup_db.end_meet(self.meet_id)
        counts  = _popup_db.get_rsvp_counts(interaction.guild.id, self.meet_id)
        end_emb = _popup_build_meet_embed(
            meet["theme"] or "", meet["location"], meet["time_text"],
            meet["extra_notes"] or "", self.meet_id, meet["host_user_id"],
            meet["host_display_name"] or "", meet["host_avatar_url"],
            counts["pullup"], counts["cantmake"], is_ended=True,
            voice_channel_id=_popup_meet_col(meet, "voice_channel_id"),
            capacity=_popup_meet_col(meet, "capacity"),
            waitlist_count=counts.get("waitlist", 0),
        )
        await interaction.response.edit_message(embed=end_emb, view=None)
        # Auto-unpin if we pinned it
        try:
            await interaction.message.unpin(reason=f"Pop-up meet #{self.meet_id} ended")
        except Exception:
            pass
        # If the meet was started, also delete the 🟢 LIVE announcement message
        _live_id = _popup_meet_col(meet, "live_message_id")
        if _live_id:
            try:
                ch = interaction.channel
                if isinstance(ch, discord.TextChannel):
                    _live_msg = await ch.fetch_message(int(_live_id))
                    await _live_msg.delete()
            except Exception:
                pass

        # Auto-cleanup: after a 60s grace window (so people see the red "Ended"
        # state) delete the original embed + archive its discussion thread.
        # All attendance info is preserved in the thread summary already posted.
        _meet_id_cap = self.meet_id
        _chan_id_cap = interaction.channel.id if interaction.channel else 0
        _msg_id_cap  = interaction.message.id if interaction.message else 0
        _thread_id_cap = int(_popup_meet_col(meet, "thread_id") or 0)
        async def _popup_end_cleanup_task():
            try:
                await asyncio.sleep(60)
                ch = bot.get_channel(_chan_id_cap)
                if isinstance(ch, discord.TextChannel) and _msg_id_cap:
                    try:
                        _emsg = await ch.fetch_message(int(_msg_id_cap))
                        await _emsg.delete()
                    except Exception as _de:
                        try:
                            _bot_log.warning("[Popup] end cleanup — delete embed %s failed: %s",
                                             _msg_id_cap, _de)
                        except Exception:
                            pass
                if _thread_id_cap:
                    try:
                        _thr = bot.get_channel(int(_thread_id_cap))
                        if isinstance(_thr, discord.Thread):
                            await _thr.edit(archived=True, locked=False)
                    except Exception:
                        pass
            except Exception:
                pass
        asyncio.create_task(_popup_end_cleanup_task())
        # Post a thank-you summary in the discussion thread if one exists
        await _popup_post_thread_summary(
            interaction.guild, meet, self.meet_id, counts, reason="manually ended"
        )


def _popup_is_host_or_staff(meet, member) -> bool:
    if not isinstance(member, discord.Member):
        return False
    if member.id == meet["host_user_id"]:
        return True
    if member.guild_permissions.administrator:
        return True
    return any(r.id in _POPUP_STAFF_ROLES for r in member.roles)


class _PopupEditModal(discord.ui.Modal, title="✏️ Edit Pop-Up Meet"):
    def __init__(self, meet_id: int, meet_row):
        super().__init__()
        self.meet_id = meet_id
        self.theme_in = discord.ui.TextInput(
            label="Theme",
            default=(meet_row["theme"] or "")[:100],
            required=False, max_length=100,
        )
        self.location_in = discord.ui.TextInput(
            label="Location",
            default=(meet_row["location"] or "")[:100],
            required=True, max_length=100,
        )
        self.time_in = discord.ui.TextInput(
            label="Time",
            default=(meet_row["time_text"] or "")[:100],
            required=True, max_length=100,
        )
        self.notes_in = discord.ui.TextInput(
            label="Notes (optional)",
            style=discord.TextStyle.paragraph,
            default=(meet_row["extra_notes"] or "")[:500],
            required=False, max_length=500,
        )
        for f in (self.theme_in, self.location_in, self.time_in, self.notes_in):
            self.add_item(f)

    async def on_submit(self, interaction):
        meet = _popup_db.get_meet(self.meet_id)
        if not meet or meet["is_ended"]:
            return await interaction.response.send_message("Meet not found or already ended.", ephemeral=True)
        theme     = _popup_sanitize(self.theme_in.value.strip())
        location  = _popup_sanitize(self.location_in.value.strip())
        time_text = _popup_sanitize(_popup_parse_time(self.time_in.value.strip()))
        notes     = _popup_sanitize(self.notes_in.value.strip())
        _popup_db.update_meet_fields(
            self.meet_id, theme=theme, location=location, time_text=time_text, extra_notes=notes,
        )
        meet = _popup_db.get_meet(self.meet_id)
        counts = _popup_db.get_rsvp_counts(interaction.guild.id, self.meet_id)
        new_emb = _popup_build_meet_embed(
            theme, location, time_text, notes, self.meet_id, meet["host_user_id"],
            meet["host_display_name"] or "", meet["host_avatar_url"],
            counts["pullup"], counts["cantmake"],
            voice_channel_id=_popup_meet_col(meet, "voice_channel_id"),
            capacity=_popup_meet_col(meet, "capacity"),
            waitlist_count=counts.get("waitlist", 0),
        )
        try:
            ch = interaction.guild.get_channel(_POPUP_PANEL_CHANNEL_ID)
            if isinstance(ch, discord.TextChannel) and meet["message_id"]:
                msg = await ch.fetch_message(int(meet["message_id"]))
                await msg.edit(embed=new_emb)
        except Exception as _e:
            _bot_log.warning("[Popup] edit refresh failed for #%s: %s", self.meet_id, _e)
        await interaction.response.send_message("✅ Meet updated.", ephemeral=True)


class _PopupEditBtn(discord.ui.Button):
    def __init__(self, meet_id: int):
        super().__init__(
            label="✏️ Edit", style=discord.ButtonStyle.secondary,
            custom_id=f"diff_popup:{meet_id}:edit", row=1,
        )
        self.meet_id = meet_id

    async def callback(self, interaction):
        meet = _popup_db.get_meet(self.meet_id)
        if not meet or meet["is_ended"]:
            return await interaction.response.send_message("Meet not found or already ended.", ephemeral=True)
        if not _popup_is_host_or_staff(meet, interaction.user):
            return await interaction.response.send_message("Only the host or staff can edit this meet.", ephemeral=True)
        await interaction.response.send_modal(_PopupEditModal(self.meet_id, meet))


class _PopupDMAttendeesModal(discord.ui.Modal, title="📣 Message Attendees"):
    def __init__(self, meet_id: int):
        super().__init__()
        self.meet_id = meet_id
        self.body_in = discord.ui.TextInput(
            label="Message to confirmed attendees",
            style=discord.TextStyle.paragraph,
            placeholder="e.g. Lobby is up — search 'DIFF JDM' on PS5. See you in 5!",
            required=True, max_length=1500,
        )
        self.add_item(self.body_in)

    async def on_submit(self, interaction):
        meet = _popup_db.get_meet(self.meet_id)
        if not meet:
            return await interaction.response.send_message("Meet not found.", ephemeral=True)
        attendees = _popup_db.get_rsvps_by_status(interaction.guild.id, self.meet_id, "pullup")
        if not attendees:
            return await interaction.response.send_message(
                "No confirmed attendees to DM yet.", ephemeral=True
            )
        await interaction.response.defer(ephemeral=True, thinking=True)
        body = _popup_sanitize(self.body_in.value.strip())
        prefix = f"📣 **Pop-Up Meet #{self.meet_id} — message from host <@{meet['host_user_id']}>:**\n\n"
        sent, failed = 0, 0
        for uid in attendees:
            mem = interaction.guild.get_member(uid)
            if not mem:
                failed += 1
                continue
            try:
                await mem.send(prefix + body)
                sent += 1
            except Exception:
                failed += 1
            await asyncio.sleep(0.25)
        msg = f"✅ DMed **{sent}** of {sent + failed} confirmed attendees"
        if failed:
            msg += f" ({failed} couldn't be reached)."
        else:
            msg += "."
        await interaction.followup.send(msg, ephemeral=True)


class _PopupDMAttendeesBtn(discord.ui.Button):
    def __init__(self, meet_id: int):
        super().__init__(
            label="📣 DM Attendees", style=discord.ButtonStyle.primary,
            custom_id=f"diff_popup:{meet_id}:dm", row=1,
        )
        self.meet_id = meet_id

    async def callback(self, interaction):
        meet = _popup_db.get_meet(self.meet_id)
        if not meet or meet["is_ended"]:
            return await interaction.response.send_message("Meet not found or already ended.", ephemeral=True)
        if not _popup_is_host_or_staff(meet, interaction.user):
            return await interaction.response.send_message("Only the host or staff can message attendees.", ephemeral=True)
        await interaction.response.send_modal(_PopupDMAttendeesModal(self.meet_id))


class _PopupMeetView(discord.ui.View):
    """Persistent per-meet RSVP view.  meet_id is encoded in each button's custom_id.
    The 🟢 Start Meet button is included only while the meet hasn't been started
    or ended — once a meet is live, it's removed (the LIVE state speaks for itself)."""
    def __init__(self, meet_id: int, *, is_started: bool = False, is_ended: bool = False):
        super().__init__(timeout=None)
        self.add_item(_PopupPullUpBtn(meet_id))
        self.add_item(_PopupCantMakeBtn(meet_id))
        self.add_item(_PopupEditBtn(meet_id))
        self.add_item(_PopupDMAttendeesBtn(meet_id))
        if not is_started and not is_ended:
            self.add_item(_PopupStartMeetBtn(meet_id))
        self.add_item(_PopupEndMeetBtn(meet_id))


class _PopupMeetModal(discord.ui.Modal, title="⚡ Create Pop-Up Meet"):
    theme_field = discord.ui.TextInput(
        label="Meet Theme",
        placeholder="e.g. JDM Night / Clean Euros / Under 1M",
        required=True,
        max_length=100,
    )
    location_field = discord.ui.TextInput(
        label="Location (optional)",
        placeholder="e.g. LS Car Meet / City / Sandy Shores — leave blank if TBD",
        required=False,
        max_length=100,
    )
    time_field = discord.ui.TextInput(
        label="Time",
        placeholder="8pm ET  •  in 30 min  •  tonight 9  •  tomorrow 7pm CT",
        required=True,
        max_length=300,
    )
    notes_field = discord.ui.TextInput(
        label="Meet Notes (optional)",
        style=discord.TextStyle.paragraph,
        placeholder="e.g. Clean builds only / first come first served / lowered cars only",
        required=False,
        max_length=500,
    )
    capacity_field = discord.ui.TextInput(
        label="Capacity (optional, blank = unlimited)",
        placeholder="e.g. 12  (max 50)",
        required=False,
        max_length=3,
    )

    def __init__(self, notify_target: str = "both", theme_key: str = "custom",
                 voice_channel_id: int = 0):
        super().__init__()
        self.notify_target = notify_target if notify_target in {"both","ps5","carmeet","none"} else "both"
        self.theme_key = theme_key if theme_key in {k for k,_ in _POPUP_THEME_OPTIONS} else "custom"
        self.voice_channel_id = int(voice_channel_id or 0)
        # Pre-fill the (now-required) theme field with whatever was picked in the
        # pre-modal dropdown so hosts can just hit Submit when the preset is fine.
        _preset = _POPUP_THEME_LABEL_FROM_KEY.get(self.theme_key, "")
        if _preset:
            self.theme_field.default = _preset

    async def on_submit(self, interaction: discord.Interaction):
        guild = interaction.guild
        user = interaction.user
        if guild is None or not isinstance(user, discord.Member):
            await interaction.response.send_message("This can only be used inside the server.", ephemeral=True)
            return
        host_role = guild.get_role(HOST_ROLE_ID)
        if not user.guild_permissions.administrator and (not host_role or host_role not in user.roles):
            await interaction.response.send_message("Only users with the Host role can create pop-up meets.", ephemeral=True)
            return
        panel_ch = guild.get_channel(_POPUP_PANEL_CHANNEL_ID)
        if not isinstance(panel_ch, discord.TextChannel):
            await interaction.response.send_message("Pop-up meet channel not found.", ephemeral=True)
            return

        # Active pop-up cap (anti-spam / channel-flood protection)
        try:
            active_count = len(_popup_db.get_active_meets(guild.id))
        except Exception:
            active_count = 0
        if active_count >= _POPUP_MAX_ACTIVE:
            return await interaction.response.send_message(
                f"⚠️ The server already has **{active_count} active pop-ups** "
                f"(cap is {_POPUP_MAX_ACTIVE}). Wait for one to end before starting another.",
                ephemeral=True,
            )

        # Host cooldown: one active pop-up per host (also pre-checked at panel-click)
        try:
            existing_for_host = _popup_db.get_host_active_meet(guild.id, user.id)
        except Exception:
            existing_for_host = None
        if existing_for_host:
            return await interaction.response.send_message(
                f"⚠️ You already have an active pop-up (#{existing_for_host[0]}). End it first.",
                ephemeral=True,
            )

        nt = self.notify_target
        ping_ps = nt in ("both", "ps5")
        ping_cm = nt in ("both", "carmeet")

        # Theme: typed value in modal overrides dropdown pick
        typed_theme = _popup_sanitize(self.theme_field.value.strip())
        if typed_theme:
            theme = typed_theme
        elif self.theme_key in _POPUP_THEME_LABEL_FROM_KEY:
            theme = _POPUP_THEME_LABEL_FROM_KEY[self.theme_key]
        else:
            theme = ""

        location  = _popup_sanitize(self.location_field.value.strip())
        time_text = _popup_sanitize(_popup_parse_time(self.time_field.value.strip()))
        notes     = _popup_sanitize(self.notes_field.value.strip())
        capacity  = _popup_parse_capacity(self.capacity_field.value)

        avatar_url = str(user.display_avatar.url)
        meet_id = _popup_db.add_meet(
            guild.id, user.id, theme, location, time_text, notes, ping_ps, ping_cm,
            host_display_name=user.display_name,
            host_avatar_url=avatar_url,
            voice_channel_id=self.voice_channel_id,
            capacity=capacity,
        )
        # Auto-add the host as a confirmed pullup — they\'re always going to
        # their own meet. Safe to swallow errors; the host can still re-RSVP.
        try:
            _popup_db.set_rsvp(guild.id, meet_id, user.id, "pullup")
        except Exception as _re:
            _bot_log.warning("[Popup] host auto-RSVP failed for #%s: %s", meet_id, _re)

        ping_parts = []
        if ping_ps:
            r = guild.get_role(PS5_ROLE_ID)
            ping_parts.append(r.mention if r else "@PlayStation")
        if ping_cm:
            r = guild.get_role(NOTIFY_ROLE_ID)
            ping_parts.append(r.mention if r else "@CarMeet")
        ping_text = " ".join(ping_parts) or None

        meet_view = _PopupMeetView(meet_id, is_started=False, is_ended=False)
        bot.add_view(meet_view)   # register immediately so buttons work after restart

        embed = _popup_build_meet_embed(
            theme, location, time_text, notes, meet_id,
            user.id, user.display_name, avatar_url,
            pullup_count=1, cantmake_count=0,
            voice_channel_id=self.voice_channel_id,
            capacity=capacity,
            waitlist_count=0,
        )

        meet_msg = await panel_ch.send(
            content=ping_text,
            embed=embed,
            view=meet_view,
            allowed_mentions=discord.AllowedMentions(
                roles=True, users=False, everyone=False
            ),
        )
        _popup_db.set_message_id(meet_id, meet_msg.id)
        # Auto-pin the live meet so it stays visible at the top of the channel.
        try:
            await meet_msg.pin(reason=f"Pop-up meet #{meet_id} live")
        except Exception as _pe:
            _bot_log.warning("[Popup] pin failed for #%s: %s", meet_id, _pe)
        # Auto-create a discussion thread off the meet message so chat doesn't
        # clutter #popup-meets. 1-day auto-archive after last message.
        try:
            thread = await meet_msg.create_thread(
                name=f"💬 Pop-Up #{meet_id} — {(theme or 'Open Class')[:40]}",
                auto_archive_duration=1440,
                reason=f"Pop-up meet #{meet_id} discussion",
            )
            _popup_db.set_thread_id(meet_id, thread.id)
        except Exception as _te:
            _bot_log.warning("[Popup] thread create failed for #%s: %s", meet_id, _te)

        log_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
        if isinstance(log_ch, discord.TextChannel):
            log_embed = discord.Embed(
                title="📋 Pop-Up Meet Created",
                color=discord.Color.green(),
                timestamp=datetime.now(timezone.utc),
                description=f"{user.mention} created a new pop-up meet.",
            )
            log_embed.add_field(name="Meet ID",   value=str(meet_id),       inline=True)
            log_embed.add_field(name="Location",  value=(location or "TBD"), inline=True)
            log_embed.add_field(name="Theme",     value=theme or "Open Class", inline=True)
            try:
                await log_ch.send(embed=log_embed)
            except Exception:
                pass

        await interaction.response.send_message(
            f"✅ Pop-up meet #{meet_id} posted! Members can now click **🚗 Pulling Up!** to RSVP.",
            ephemeral=True,
        )


class _PopupCreateBtn(discord.ui.Button):
    def __init__(self):
        super().__init__(
            label="⚡ Create Pop-Up Meet",
            style=discord.ButtonStyle.success,
            custom_id="diff_popup:create",
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        user = interaction.user
        if not isinstance(user, discord.Member):
            return await interaction.response.send_message("Server only.", ephemeral=True)
        host_role = interaction.guild.get_role(HOST_ROLE_ID) if interaction.guild else None
        if not user.guild_permissions.administrator and (not host_role or host_role not in user.roles):
            return await interaction.response.send_message(
                "Only users with the **Host** role can create pop-up meets.", ephemeral=True
            )
        try:
            existing = _popup_db.get_host_active_meet(interaction.guild.id, user.id) if interaction.guild else None
        except Exception:
            existing = None
        if existing:
            return await interaction.response.send_message(
                f"⚠️ You already have an active pop-up (#{existing[0]}). End it first before starting another.",
                ephemeral=True,
            )
        view = _PopupNotifySelectView(user.id, interaction.guild)
        await interaction.response.send_message(
            "**Step 1 of 2 — Set up the pings, theme, and optional voice channel.**\nDefaults are fine for most meets — just tap **Continue** when ready.",
            view=view,
            ephemeral=True,
        )


class _PopupNotifySelect(discord.ui.Select):
    def __init__(self):
        options = [
            discord.SelectOption(label=lbl, value=val, default=(val == "both"))
            for val, lbl in _POPUP_NOTIFY_OPTIONS
        ]
        super().__init__(
            placeholder="🔔 Who to notify…", options=options,
            min_values=1, max_values=1, row=0,
            custom_id="diff_popup:notify_select",
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        if isinstance(self.view, _PopupNotifySelectView):
            self.view.notify_target = self.values[0]
        try:
            await interaction.response.defer(ephemeral=True)
        except Exception:
            pass


class _PopupThemeSelect(discord.ui.Select):
    def __init__(self):
        options = [
            discord.SelectOption(label=lbl, value=val, default=(val == "custom"))
            for val, lbl in _POPUP_THEME_OPTIONS[:25]
        ]
        super().__init__(
            placeholder="🎨 Theme (quick-pick)…", options=options,
            min_values=1, max_values=1, row=1,
            custom_id="diff_popup:theme_select",
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        if isinstance(self.view, _PopupNotifySelectView):
            self.view.theme_key = self.values[0]
        try:
            await interaction.response.defer(ephemeral=True)
        except Exception:
            pass


class _PopupVCSelect(discord.ui.Select):
    """Voice channel dropdown — populated dynamically from the guild's VCs."""
    def __init__(self, guild):
        opts = [discord.SelectOption(label="🚫 No voice channel", value="0", default=True)]
        seen = 0
        for vc in (guild.voice_channels if guild else []):
            if seen >= 24:
                break
            opts.append(discord.SelectOption(label=f"🔊 {vc.name[:90]}", value=str(vc.id)))
            seen += 1
        super().__init__(
            placeholder="🔊 Attach a voice channel (optional)…", options=opts,
            min_values=1, max_values=1, row=2,
            custom_id="diff_popup:vc_select",
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        if isinstance(self.view, _PopupNotifySelectView):
            try:
                self.view.voice_channel_id = int(self.values[0])
            except Exception:
                self.view.voice_channel_id = 0
        try:
            await interaction.response.defer(ephemeral=True)
        except Exception:
            pass


class _PopupNotifyContinueBtn(discord.ui.Button):
    def __init__(self):
        super().__init__(
            label="Continue →", style=discord.ButtonStyle.success,
            custom_id="diff_popup:notify_continue", row=3,
        )

    async def callback(self, interaction: discord.Interaction) -> None:
        view = self.view
        if isinstance(view, _PopupNotifySelectView) and interaction.user.id != view.invoker_id:
            return await interaction.response.send_message(
                "Only the host who opened this can continue.", ephemeral=True
            )
        nt  = getattr(view, "notify_target", "both") or "both"
        thk = getattr(view, "theme_key", "custom") or "custom"
        vc  = int(getattr(view, "voice_channel_id", 0) or 0)
        try:
            await interaction.response.send_modal(
                _PopupMeetModal(notify_target=nt, theme_key=thk, voice_channel_id=vc)
            )
        except Exception as _e:
            _bot_log.warning("[Popup] send_modal failed: %s", _e)
            try:
                await interaction.followup.send(
                    "Couldn't open the form. Try clicking Create Pop-Up Meet again.",
                    ephemeral=True,
                )
            except Exception:
                pass


class _PopupNotifySelectView(discord.ui.View):
    """Ephemeral pre-modal config: Notify + Theme + VC + Continue.
    NOT persistent — 3 min timeout to avoid leaking views on bot restart."""
    def __init__(self, invoker_id: int, guild=None):
        super().__init__(timeout=180)
        self.invoker_id = invoker_id
        self.notify_target = "both"
        self.theme_key = "custom"
        self.voice_channel_id = 0
        self.add_item(_PopupNotifySelect())
        self.add_item(_PopupThemeSelect())
        self.add_item(_PopupVCSelect(guild))
        self.add_item(_PopupNotifyContinueBtn())


class _PopupMeetPanelView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)
        self.add_item(_PopupCreateBtn())


def _popup_build_panel_embed() -> discord.Embed:
    embed = discord.Embed(
        title="⚡ DIFF Pop-Up Meets Hub",
        description="Spontaneous PS5 meets hosted by approved DIFF hosts — no schedule, no warning, just drop and pull up.",
        color=discord.Color.from_rgb(255, 140, 0),
    )
    embed.set_thumbnail(url=DIFF_LOGO_URL)
    embed.add_field(
        name="🚗 Members",
        value=(
            "Tap **🚗 Pulling Up!** on any meet card to RSVP — full meets waitlist you and auto-promote (with a DM) when a spot opens. "
            "Each meet gets its own 💬 thread. Want pings? Grab the roles in " + f"<#{JOIN_MEETS_CHANNEL_ID}>."
        ),
        inline=False,
    )
    embed.add_field(
        name="🛠️ Hosts",
        value=(
            "Tap **⚡ Create Pop-Up Meet** below — the form walks you through pings, theme, time, and capacity. "
            "Manage the live card with **✏️ Edit**, **📣 DM Attendees**, and **🏁 End Meet**."
        ),
        inline=False,
    )
    embed.add_field(
        name="⚠️ Rules & Limits",
        value=(
            "PS5 only • clean builds • no crashing or griefing • be ready when you RSVP (repeat no-shows get flagged)\n"
            "Hosts: 1 active pop-up each • 5 per server max"
        ),
        inline=False,
    )
    embed.set_footer(text="DIFF Pop-Up Meet System")
    embed.timestamp = datetime.now(timezone.utc)
    return embed


_popup_lastcall_sent: set = set()  # meet_ids we've already DMed a last-call for

async def _popup_auto_end_loop() -> None:
    """Every 10 min: (a) DM host a 'last call' ~30 min before auto-close, then
    (b) end any pop-up meet older than _POPUP_AUTO_END_HOURS. Edits the meet
    message in place (greyed out, ended state) and DMs the host."""
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            now_utc = datetime.now(timezone.utc)
            for g in bot.guilds:
                try:
                    actives = _popup_db.get_active_meets(g.id)
                except Exception:
                    continue
                for meet in actives:
                    # Decide which clock to measure against:
                    #   • Live meets  → started_at + _POPUP_AUTO_END_HOURS (3h)
                    #   • Never-started → created_at + _POPUP_ABANDON_HOURS (24h)
                    # This stops meets scheduled hours in advance from being killed
                    # before their scheduled start time.
                    try:
                        is_started = int(_popup_meet_col(meet, "is_started") or 0) == 1
                        if is_started:
                            anchor_iso = _popup_meet_col(meet, "started_at") or meet["created_at"]
                            cap_hours  = _POPUP_AUTO_END_HOURS
                            close_reason_h = _POPUP_AUTO_END_HOURS
                        else:
                            anchor_iso = meet["created_at"]
                            cap_hours  = _POPUP_ABANDON_HOURS
                            close_reason_h = _POPUP_ABANDON_HOURS
                        anchor = datetime.fromisoformat(anchor_iso)
                        if anchor.tzinfo is None:
                            anchor = anchor.replace(tzinfo=timezone.utc)
                    except Exception:
                        continue
                    age_h = (now_utc - anchor).total_seconds() / 3600.0
                    # Last-call DM ~30 min before auto-close (once per meet, live meets only)
                    if is_started and (cap_hours - 0.5) <= age_h < cap_hours:
                        mid = int(meet["id"])
                        if mid not in _popup_lastcall_sent:
                            _popup_lastcall_sent.add(mid)
                            try:
                                host_mem = g.get_member(int(meet["host_user_id"]))
                                if host_mem:
                                    await host_mem.send(
                                        f"⏰ **Last call** — your pop-up meet (#{mid}) will auto-close "
                                        f"in ~30 minutes ({cap_hours}h cap). "
                                        f"Hit **🏁 End Meet** when you're done, or just let it auto-close."
                                    )
                            except Exception:
                                pass
                    if age_h < cap_hours:
                        continue
                    _popup_lastcall_sent.discard(int(meet["id"]))
                    meet_id = int(meet["id"])
                    try:
                        _popup_db.end_meet(meet_id)
                        counts = _popup_db.get_rsvp_counts(g.id, meet_id)
                        ended_embed = _popup_build_meet_embed(
                            meet["theme"] or "", meet["location"], meet["time_text"],
                            meet["extra_notes"] or "", meet_id, meet["host_user_id"],
                            meet["host_display_name"] or "", meet["host_avatar_url"],
                            counts["pullup"], counts["cantmake"], is_ended=True,
                            voice_channel_id=_popup_meet_col(meet, "voice_channel_id"),
                            capacity=_popup_meet_col(meet, "capacity"),
                            waitlist_count=counts.get("waitlist", 0),
                        )
                        ch = g.get_channel(_POPUP_PANEL_CHANNEL_ID)
                        if isinstance(ch, discord.TextChannel) and meet["message_id"]:
                            try:
                                msg = await ch.fetch_message(int(meet["message_id"]))
                                await msg.edit(embed=ended_embed, view=None)
                                try:
                                    await msg.unpin(reason=f"Pop-up meet #{meet_id} auto-ended")
                                except Exception:
                                    pass
                            except Exception:
                                pass
                        # Thread thank-you for auto-ended meets too
                        _reason_txt = (
                            f"auto-closed after {close_reason_h}h"
                            if is_started else
                            f"auto-closed — never started within {close_reason_h}h of being posted"
                        )
                        await _popup_post_thread_summary(
                            g, meet, meet_id, counts, reason=_reason_txt
                        )
                        # DM the host so they know it auto-closed
                        try:
                            host_mem = g.get_member(int(meet["host_user_id"]))
                            if host_mem:
                                if is_started:
                                    _dm = (
                                        f"⏱ Your pop-up meet (ID #{meet_id}) was auto-closed after "
                                        f"{close_reason_h} hours. "
                                        f"Final RSVPs: {counts['pullup']} pulled up, {counts['cantmake']} couldn't make it."
                                    )
                                else:
                                    _dm = (
                                        f"⏱ Your pop-up meet (ID #{meet_id}) was auto-closed because it "
                                        f"was never started within {close_reason_h} hours of being posted. "
                                        f"Final RSVPs: {counts['pullup']} pulled up, {counts['cantmake']} couldn't make it."
                                    )
                                await host_mem.send(_dm)
                        except Exception:
                            pass
                    except Exception as _ie:
                        _bot_log.warning("[PopupAutoEnd] meet %s: %s", meet["id"], _ie)
        except Exception as _le:
            _bot_log.warning("[PopupAutoEnd] loop error: %s", _le)
        await asyncio.sleep(600)  # 10 min


@bot.command(name="popupinfo", aliases=["popup", "popupmembers"])
async def popupinfo_cmd(ctx, meet_id: int = 0):
    """!popupinfo <id> — full attendee + waitlist + can't-make breakdown.
    Host of that meet OR any staff member can use it."""
    if not ctx.guild or meet_id <= 0:
        return await ctx.reply("Usage: `!popupinfo <meet_id>`", mention_author=False)
    meet = _popup_db.get_meet(meet_id)
    if not meet or meet["guild_id"] != ctx.guild.id:
        return await ctx.reply(f"No pop-up meet found with ID `#{meet_id}`.", mention_author=False)
    if not _popup_is_host_or_staff(meet, ctx.author):
        return await ctx.reply("Only the host of this meet or staff can view its info.", mention_author=False)

    counts    = _popup_db.get_rsvp_counts(ctx.guild.id, meet_id)
    pullups   = _popup_db.get_rsvps_by_status(ctx.guild.id, meet_id, "pullup")
    waitlist  = _popup_db.get_rsvps_by_status(ctx.guild.id, meet_id, "waitlist")
    cantmakes = _popup_db.get_rsvps_by_status(ctx.guild.id, meet_id, "cantmake")

    def _fmt(uids, cap_n: int = 30) -> str:
        if not uids:
            return "_None_"
        shown = [f"<@{u}>" for u in uids[:cap_n]]
        more  = len(uids) - cap_n
        s = ", ".join(shown)
        if more > 0:
            s += f"  …and **{more}** more"
        return s

    cap     = int(_popup_meet_col(meet, "capacity") or 0)
    vc_id   = int(_popup_meet_col(meet, "voice_channel_id") or 0)
    status  = "🛑 Ended" if meet["is_ended"] else "🟢 Live"
    cap_str = f"{counts['pullup']}/{cap}" if cap > 0 else f"{counts['pullup']}"

    emb = discord.Embed(
        title=f"📋 Pop-Up Meet #{meet_id} — {status}",
        color=discord.Color.greyple() if meet["is_ended"] else discord.Color.green(),
    )
    emb.add_field(name="🎨 Theme",    value=(meet["theme"] or "Open Class"), inline=True)
    emb.add_field(name="📍 Location", value=meet["location"] or "—",         inline=True)
    emb.add_field(name="🕒 Time",     value=meet["time_text"] or "—",        inline=True)
    emb.add_field(name="👤 Host",     value=_readable_host(None, meet['host_user_id']) or f"<@{meet['host_user_id']}>",    inline=True)
    if vc_id:
        emb.add_field(name="🔊 Voice", value=f"<#{vc_id}>", inline=True)
    emb.add_field(name="🚗 Confirmed", value=cap_str, inline=True)
    emb.add_field(name=f"✅ Pulling Up ({counts['pullup']})", value=_fmt(pullups), inline=False)
    if waitlist:
        emb.add_field(name=f"📋 Waitlist ({counts['waitlist']})", value=_fmt(waitlist), inline=False)
    if cantmakes:
        emb.add_field(name=f"❌ Can't Make It ({counts['cantmake']})", value=_fmt(cantmakes), inline=False)
    emb.set_footer(text=f"Created {meet['created_at'][:19].replace('T',' ')} UTC")
    await ctx.reply(embed=emb, mention_author=False)


async def _popup_post_thread_summary(guild, meet, meet_id: int, counts: dict, reason: str = "ended"):
    """Post a thank-you summary inside the meet\'s discussion thread, if it has one.
    Silent no-op if the thread is gone, archived, or never existed."""
    thread_id = int(_popup_meet_col(meet, "thread_id") or 0)
    if not thread_id or not guild:
        return
    try:
        thread = guild.get_thread(thread_id) or await guild.fetch_channel(thread_id)
    except Exception:
        return
    if not isinstance(thread, discord.Thread):
        return
    try:
        if thread.archived:
            await thread.edit(archived=False)
    except Exception:
        pass
    summary = discord.Embed(
        title=f"🏁 Pop-Up Meet #{meet_id} — wrapped",
        color=discord.Color.from_rgb(231, 76, 60),
        description=(
            f"Thanks to everyone who pulled up! Meet **{reason}**.\n\n"
            f"🚗 **{counts.get('pullup',0)}** confirmed  •  "
            f"❌ **{counts.get('cantmake',0)}** couldn\'t make it  •  "
            f"📋 **{counts.get('waitlist',0)}** on waitlist"
        ),
        timestamp=datetime.now(timezone.utc),
    )
    summary.set_footer(text="DIFF Pop-Up Meets — drop feedback in this thread")
    try:
        await thread.send(embed=summary)
    except Exception as _se:
        _bot_log.warning("[Popup] thread summary failed for #%s: %s", meet_id, _se)


def _popup_is_staff(member) -> bool:
    if not isinstance(member, discord.Member):
        return False
    if member.guild_permissions.administrator:
        return True
    return any(r.id in _POPUP_STAFF_ROLES for r in member.roles)


@bot.command(name="endpopup", aliases=["forceendpopup", "killpopup"])
async def endpopup_cmd(ctx, meet_id: int = 0):
    """!endpopup <id> — staff: force-end a pop-up meet from anywhere.
    Useful when the host has gone offline without ending."""
    if not ctx.guild or meet_id <= 0:
        return await ctx.reply("Usage: `!endpopup <meet_id>`", mention_author=False)
    if not _popup_is_staff(ctx.author):
        return await ctx.reply("Staff only.", mention_author=False)
    meet = _popup_db.get_meet(meet_id)
    if not meet or meet["guild_id"] != ctx.guild.id:
        return await ctx.reply(f"No pop-up meet found with ID `#{meet_id}`.", mention_author=False)
    if meet["is_ended"]:
        return await ctx.reply(f"Pop-up #{meet_id} is already ended.", mention_author=False)

    _popup_db.end_meet(meet_id)
    counts = _popup_db.get_rsvp_counts(ctx.guild.id, meet_id)
    end_emb = _popup_build_meet_embed(
        meet["theme"] or "", meet["location"], meet["time_text"],
        meet["extra_notes"] or "", meet_id, meet["host_user_id"],
        meet["host_display_name"] or "", meet["host_avatar_url"],
        counts["pullup"], counts["cantmake"], is_ended=True,
        voice_channel_id=_popup_meet_col(meet, "voice_channel_id"),
        capacity=_popup_meet_col(meet, "capacity"),
        waitlist_count=counts.get("waitlist", 0),
    )
    # Edit the panel message + unpin
    ch = ctx.guild.get_channel(_POPUP_PANEL_CHANNEL_ID)
    if isinstance(ch, discord.TextChannel) and meet["message_id"]:
        try:
            msg = await ch.fetch_message(int(meet["message_id"]))
            await msg.edit(embed=end_emb, view=None)
            try:
                await msg.unpin(reason=f"Pop-up #{meet_id} force-ended by {ctx.author}")
            except Exception:
                pass
        except Exception as _e:
            _bot_log.warning("[Popup] endpopup edit failed for #%s: %s", meet_id, _e)

    await _popup_post_thread_summary(
        ctx.guild, meet, meet_id, counts, reason=f"force-ended by {ctx.author.display_name}"
    )
    # DM the host so they know
    try:
        host_mem = ctx.guild.get_member(int(meet["host_user_id"]))
        if host_mem and host_mem.id != ctx.author.id:
            await host_mem.send(
                f"ℹ️ Staff member **{ctx.author.display_name}** ended your pop-up meet (#{meet_id}). "
                f"Final RSVPs: {counts['pullup']} pulled up, {counts['cantmake']} couldn\'t make it."
            )
    except Exception:
        pass
    await ctx.reply(f"✅ Pop-up #{meet_id} ended. {counts['pullup']} confirmed attendees.", mention_author=False)


@bot.command(name="popuplist", aliases=["popups", "activepopups"])
async def popuplist_cmd(ctx):
    """!popuplist — staff: list all currently-active pop-up meets in this guild."""
    if not ctx.guild:
        return
    if not _popup_is_staff(ctx.author):
        return await ctx.reply("Staff only.", mention_author=False)
    actives = _popup_db.get_active_meets(ctx.guild.id)
    if not actives:
        return await ctx.reply("No active pop-up meets right now.", mention_author=False)
    emb = discord.Embed(
        title=f"⚡ Active Pop-Up Meets ({len(actives)})",
        color=discord.Color.orange(),
        timestamp=datetime.now(timezone.utc),
    )
    for m in actives[:15]:
        mid    = int(m["id"])
        counts = _popup_db.get_rsvp_counts(ctx.guild.id, mid)
        cap    = int(_popup_meet_col(m, "capacity") or 0)
        cap_str = f"{counts['pullup']}/{cap}" if cap > 0 else f"{counts['pullup']}"
        try:
            created = datetime.fromisoformat(m["created_at"])
            if created.tzinfo is None:
                created = created.replace(tzinfo=timezone.utc)
            age_min = int((datetime.now(timezone.utc) - created).total_seconds() / 60)
            age_str = f"{age_min}m old" if age_min < 60 else f"{age_min // 60}h {age_min % 60}m old"
        except Exception:
            age_str = "—"
        emb.add_field(
            name=f"#{mid} — {(m['theme'] or 'Open Class')[:40]}",
            value=(
                f"👤 {_readable_host(None, m['host_user_id'])}  •  📍 {(m['location'] or 'TBD')[:60]}\n"
                f"🕒 {(m['time_text'] or '—')[:80]}\n"
                f"🚗 {cap_str} confirmed  •  📋 {counts.get('waitlist',0)} waitlist  •  ⏱ {age_str}"
            ),
            inline=False,
        )
    if len(actives) > 15:
        emb.set_footer(text=f"…and {len(actives) - 15} more")
    await ctx.reply(embed=emb, mention_author=False)


async def _popup_post_or_refresh(guild: discord.Guild):
    channel = guild.get_channel(_POPUP_PANEL_CHANNEL_ID)
    if not isinstance(channel, discord.TextChannel):
        return
    row = _popup_db.get_panel(guild.id)
    if row:
        try:
            msg = await channel.fetch_message(row["message_id"])
            await msg.edit(embed=_popup_build_panel_embed(), view=_PopupMeetPanelView())
            return
        except discord.NotFound:
            pass
        except Exception:
            return
    msg = await channel.send(embed=_popup_build_panel_embed(), view=_PopupMeetPanelView())
    _popup_db.save_panel(guild.id, channel.id, msg.id)


@bot.command(name="postpopuppanel")
async def _cmd_postpopuppanel(ctx: commands.Context):
    is_owner = ctx.guild and ctx.guild.owner_id == ctx.author.id
    is_admin = ctx.author.guild_permissions.administrator
    is_staff = any(r.id in _JOIN_STAFF_ROLE_IDS for r in getattr(ctx.author, "roles", []))
    if not (is_owner or is_admin or is_staff):
        await ctx.send("You need a staff role to use this command.", delete_after=8)
        return
    try:
        await ctx.message.delete()
    except Exception:
        pass
    await _popup_post_or_refresh(ctx.guild)


# =========================
# ROTATING BOT STATUS
# =========================
_presence_index = 0

def _status_next_meet_label() -> str | None:
    """Return a short 'Next Meet: Day • Time' string from the schedule, or None."""
    try:
        schedule = _asched_load()
        from zoneinfo import ZoneInfo as _ZI
        now = datetime.now(_ZI("America/New_York"))
        best_ts  = None
        best_lbl = None
        for day_key, slot in schedule.get("days", {}).items():
            if not slot.get("host_id"):
                continue
            day_val  = slot.get("day", "")
            time_val = slot.get("time", "")
            if not day_val or not time_val:
                continue
            ts = _parse_meet_ts(day_val, time_val)
            if ts and ts > now.timestamp():
                if best_ts is None or ts < best_ts:
                    best_ts  = ts
                    best_lbl = f"Next Meet: {day_val} • {time_val}"
        return best_lbl
    except Exception:
        return None

async def __rotating_presence_loop_logic():
    global _presence_index
    guild        = bot.get_guild(GUILD_ID)
    member_count = guild.member_count if guild else 0
    next_meet    = _status_next_meet_label()

    # ── Live signals ─────────────────────────────────────────────────────────
    active_session_count = 0
    lifetime_meets       = 0
    try:
        _hp = _hp_load()
        for _s in _hp.get("sessions", {}).values():
            if not _s.get("ended"):
                active_session_count += 1
        for _u in _hp.get("host_stats", {}).values():
            lifetime_meets += int(_u.get("meets_hosted", 0) or 0)
    except Exception:
        pass

    hosts_online = 0
    try:
        if guild:
            for _h in data.get("hosts", []):
                _m = guild.get_member(_h.get("discord_id", 0))
                if _m and _m.status != discord.Status.offline:
                    hosts_online += 1
    except Exception:
        pass

    week_meets_confirmed = 0
    try:
        _sched = _asched_load()
        for _d in _sched.get("days", {}).values():
            if _d.get("host_id"):
                week_meets_confirmed += 1
    except Exception:
        pass

    # ── Status color: red during active sessions, idle at night, online otherwise
    try:
        from datetime import datetime as _dt
        _hr_et = _dt.now(_EST_TZ).hour
    except Exception:
        _hr_et = 12
    if active_session_count > 0:
        presence_status = discord.Status.dnd
    elif 2 <= _hr_et < 8:
        presence_status = discord.Status.idle
    else:
        presence_status = discord.Status.online

    # ── Build activity rotation ──────────────────────────────────────────────
    activities = [
        discord.Streaming(
            name="🏁 DIFF Car Meets | PS5 GTA V",
            url="https://www.twitch.tv/directory/game/Grand%20Theft%20Auto%20V",
        ),
        discord.Activity(type=discord.ActivityType.watching,  name=f"over {member_count:,} members"),
        discord.Activity(type=discord.ActivityType.competing, name="DIFF Host Meets"),
        discord.Activity(type=discord.ActivityType.listening, name="the DIFF community"),
        discord.Activity(type=discord.ActivityType.watching,  name="🚗 Host Flow • Crew Management"),
        discord.Activity(type=discord.ActivityType.listening, name="!mystats for your standing"),
    ]

    if active_session_count > 0:
        activities.insert(0, discord.Activity(
            type=discord.ActivityType.playing,
            name=f"🏁 LIVE: {active_session_count} meet{'s' if active_session_count != 1 else ''} in progress",
        ))

    if hosts_online > 0:
        activities.append(discord.Activity(
            type=discord.ActivityType.watching,
            name=f"🟢 {hosts_online} host{'s' if hosts_online != 1 else ''} online now",
        ))

    if week_meets_confirmed > 0:
        activities.append(discord.Activity(
            type=discord.ActivityType.competing,
            name=f"📅 {week_meets_confirmed} meet{'s' if week_meets_confirmed != 1 else ''} this week",
        ))

    if lifetime_meets > 0:
        activities.append(discord.Activity(
            type=discord.ActivityType.watching,
            name=f"🏆 {lifetime_meets:,} car meets hosted all-time",
        ))

    if next_meet:
        activities.insert(2, discord.Activity(
            type=discord.ActivityType.playing,
            name=f"📅 {next_meet}",
        ))

    activity = activities[_presence_index % len(activities)]
    _presence_index += 1
    try:
        await bot.change_presence(status=presence_status, activity=activity)
    except Exception:
        pass

@tasks.loop(seconds=45)
async def _rotating_presence_loop():
    _loop_success('_rotating_presence_loop')
    try:
        await run_with_timeout('_rotating_presence_loop', __rotating_presence_loop_logic(), timeout=30)
    except Exception as _lte:
        await _handle_loop_error('_rotating_presence_loop', _lte, _rotating_presence_loop)
@_rotating_presence_loop.error
async def __rotating_presence_loop_on_error(error: Exception) -> None:
    await _handle_loop_error('_rotating_presence_loop', error, _rotating_presence_loop)
# =========================
# JOIN TICKET AUTO-BUMP (escalating: 2h → 6h → 24h → 72h auto-close)
# =========================

async def __join_auto_bump_loop_logic():
    """Escalating staff pings after photos submitted with no decision: 2h / 6h / 24h / 72h auto-close."""
    try:
        guild = bot.get_guild(GUILD_ID)
        if not guild:
            return
        category = guild.get_channel(JOIN_TICKET_CATEGORY_ID)
        if not isinstance(category, discord.CategoryChannel):
            return
        extra = _join_extra_load()
        changed = False
        now_utc = datetime.now(timezone.utc)
        ts_role  = guild.get_role(TICKET_SUPPORT_ROLE_ID)
        mgr_role = guild.get_role(MANAGER_ROLE_ID)
        lead     = guild.get_role(LEADER_ROLE_ID)
        co       = guild.get_role(CO_LEADER_ROLE_ID)
        for ch in category.text_channels:
            topic = ch.topic or ""
            if "JOIN_USER:" not in topic:
                continue
            ch_key = str(ch.id)
            entry = extra.get(ch_key, {})
            # Backward-compat: old bump_sent=True means already reached level 3
            if entry.get("bump_sent") and "bump_level" not in entry:
                entry["bump_level"] = 3
            bump_level = entry.get("bump_level", 0)
            if bump_level >= 4:
                extra[ch_key] = entry
                continue
            # Skip 2h and 6h escalations if a staff member already claimed the ticket,
            # or if the application is on hold. We still escalate at 24h if truly abandoned.
            if ("join_claimed_by=" in topic or entry.get("on_hold")) and bump_level < 2:
                extra[ch_key] = entry
                continue
            photos_ts = entry.get("photos_complete_at")
            if not photos_ts:
                extra[ch_key] = entry
                continue
            try:
                complete_at = datetime.fromisoformat(photos_ts)
                if complete_at.tzinfo is None:
                    complete_at = complete_at.replace(tzinfo=timezone.utc)
            except Exception:
                continue
            hours = (now_utc - complete_at).total_seconds() / 3600

            if bump_level < 1 and hours >= 2:
                # Level 1 — 2h: ping Ticket Support in ticket
                ts_mention = ts_role.mention if ts_role else ""
                emb = discord.Embed(
                    title="⏰ Review Needed — 2h",
                    description=(
                        "All required photos have been submitted for **over 2 hours** "
                        "with no decision yet.\n\nPlease review this application."
                    ),
                    color=discord.Color.yellow(),
                    timestamp=now_utc,
                )
                emb.set_footer(text="Different Meets • Join Hub Auto-Bump")
                try:
                    await ch.send(
                        content=ts_mention or None,
                        embed=emb,
                        allowed_mentions=discord.AllowedMentions(roles=True),
                    )
                    entry["bump_level"] = 1
                    changed = True
                except Exception:
                    pass

            elif bump_level < 2 and hours >= 6:
                # Level 2 — 6h: ping Ticket Support + Server Operations
                mentions = " ".join(r.mention for r in [ts_role, mgr_role] if r)
                emb = discord.Embed(
                    title="⏰ Review Needed — 6h",
                    description=(
                        "This application has been waiting for a decision for **over 6 hours**.\n\n"
                        "Ticket Support and Server Operations — please review and action this ticket."
                    ),
                    color=discord.Color.orange(),
                    timestamp=now_utc,
                )
                emb.set_footer(text="Different Meets • Join Hub Auto-Bump")
                try:
                    await ch.send(
                        content=mentions or None,
                        embed=emb,
                        allowed_mentions=discord.AllowedMentions(roles=True),
                    )
                    entry["bump_level"] = 2
                    changed = True
                except Exception:
                    pass

            elif bump_level < 3 and hours >= 24:
                # Level 3 — 24h: ping Founder + Executive + Server Operations
                mentions = " ".join(r.mention for r in [lead, co, mgr_role] if r)
                emb = discord.Embed(
                    title="🚨 Application Still Unresolved — 24h",
                    description=(
                        "This join application has had all required photos for **over 24 hours** "
                        "with no accept or deny decision.\n\n"
                        "This needs to be resolved immediately."
                    ),
                    color=discord.Color.red(),
                    timestamp=now_utc,
                )
                emb.set_footer(text="Different Meets • Join Hub Auto-Bump")
                try:
                    await ch.send(
                        content=mentions or None,
                        embed=emb,
                        allowed_mentions=discord.AllowedMentions(roles=True),
                    )
                    entry["bump_level"] = 3
                    entry["bump_sent"] = True  # backward-compat flag
                    changed = True
                except Exception:
                    pass

            elif bump_level < 4 and hours >= 72:
                # Level 4 — 72h: auto-close ticket, DM applicant
                uid_raw = _join_parse_user_id(topic)
                applicant = guild.get_member(int(uid_raw)) if uid_raw and uid_raw.isdigit() else None
                if applicant:
                    try:
                        await safe_dm(
                            applicant,
                            "**DIFF Join Application Update**\n\n"
                            "Your join application ticket was automatically closed after **72 hours** "
                            "because our review team was unable to action it in time.\n\n"
                            "This is **not a rejection** — you are welcome to reapply when our team "
                            "is available. We apologise for the delay.",
                        )
                    except Exception:
                        pass
                try:
                    await ch.send(embed=discord.Embed(
                        title="🔒 Auto-Closed — 72h No Decision",
                        description=(
                            "This ticket has been automatically closed after **72 hours** "
                            "of staff inactivity. The applicant has been notified and may reapply."
                        ),
                        color=discord.Color.dark_grey(),
                        timestamp=now_utc,
                    ))
                except Exception:
                    pass
                try:
                    new_name = f"closed-{ch.name}"[:90]
                    await ch.edit(name=new_name)
                    await ch.set_permissions(guild.default_role, view_channel=False)
                    if applicant:
                        await ch.set_permissions(applicant, view_channel=False)
                except Exception:
                    pass
                entry["bump_level"] = 4
                entry["bump_sent"] = True
                changed = True

            extra[ch_key] = entry
        if changed:
            _join_extra_save(extra)
    except Exception as _e:
        print(f"[JoinAutoBump] Error: {_e}")

@tasks.loop(minutes=30)
async def _join_auto_bump_loop():
    _loop_success('_join_auto_bump_loop')
    try:
        await run_with_timeout('_join_auto_bump_loop', __join_auto_bump_loop_logic(), timeout=120)
    except Exception as _lte:
        await _handle_loop_error('_join_auto_bump_loop', _lte, _join_auto_bump_loop)
@_join_auto_bump_loop.error
async def __join_auto_bump_loop_on_error(error: Exception) -> None:
    await _handle_loop_error('_join_auto_bump_loop', error, _join_auto_bump_loop)

# =========================
# JOIN TICKET MICRO-BUMP (every 10 min after photos complete, until claimed)
# =========================

_JOIN_MICRO_BUMP_MAX = 3   # max pings before handing off to escalating system (3 × 30 min = 90 min)

async def __join_micro_bump_logic():
    """Ping @Ticket Support every 10 min in-ticket after photos are complete, until someone claims the review."""
    try:
        guild = bot.get_guild(GUILD_ID)
        if not guild:
            return
        category = guild.get_channel(JOIN_TICKET_CATEGORY_ID)
        if not isinstance(category, discord.CategoryChannel):
            return
        ts_role = guild.get_role(TICKET_SUPPORT_ROLE_ID)
        extra = _join_extra_load()
        changed = False
        now_utc = datetime.now(timezone.utc)
        for ch in category.text_channels:
            topic = ch.topic or ""
            if "JOIN_USER:" not in topic:
                continue
            ch_key = str(ch.id)
            entry = extra.get(ch_key, {})
            if entry.get("bump_level", 0) >= 4:
                continue

            # ── Applicant idle ping: fires even on claimed tickets ─────────────
            _info_ts_str = entry.get("last_info_requested_at")
            if _info_ts_str and not entry.get("info_idle_pinged"):
                try:
                    _info_dt = datetime.fromisoformat(_info_ts_str)
                    if _info_dt.tzinfo is None:
                        _info_dt = _info_dt.replace(tzinfo=timezone.utc)
                    _info_age = (now_utc - _info_dt).total_seconds()
                    _app_responded = False
                    _app_msg_str = entry.get("last_applicant_msg_at")
                    if _app_msg_str:
                        _app_dt = datetime.fromisoformat(_app_msg_str)
                        if _app_dt.tzinfo is None:
                            _app_dt = _app_dt.replace(tzinfo=timezone.utc)
                        _app_responded = _app_dt > _info_dt
                    if _info_age >= 86400 and not _app_responded:   # 24 hours
                        _uid_idle = _join_parse_user_id(topic)
                        _app_ping  = f"<@{_uid_idle}>" if _uid_idle else ""
                        _idle_emb  = discord.Embed(
                            title="⏰ Reminder — Response Needed",
                            description=(
                                f"{_app_ping}, staff are waiting for your reply to their last message.\n\n"
                                "Please respond here to keep your application active. "
                                "If there's no response soon, your ticket may be closed."
                            ),
                            color=discord.Color.orange(),
                            timestamp=now_utc,
                        )
                        _idle_emb.set_footer(text="Different Meets • Join Hub")
                        try:
                            await ch.send(
                                content=_app_ping or None,
                                embed=_idle_emb,
                                allowed_mentions=discord.AllowedMentions(users=True),
                            )
                            entry["info_idle_pinged"] = True
                            extra[ch_key] = entry
                            changed = True
                        except Exception:
                            pass
                except Exception:
                    pass
            # ──────────────────────────────────────────────────────────────────

            # Stop if already claimed or auto-closed
            if "join_claimed_by=" in topic:
                continue
            # Only fire after photos are complete
            if not entry.get("photos_complete_at"):
                continue
            # Skip if application is on hold — staff is aware and will action it.
            if entry.get("on_hold"):
                continue
            # Stop after max pings — escalating system takes over
            micro_count = entry.get("micro_bump_count", 0)
            if micro_count >= _JOIN_MICRO_BUMP_MAX:
                continue
            # First reminder waits until photos have been complete for at least 30 min
            # so staff get a real chance to action it without instant pinging.
            if micro_count == 0:
                try:
                    _pc_dt = datetime.fromisoformat(entry["photos_complete_at"])
                    if _pc_dt.tzinfo is None:
                        _pc_dt = _pc_dt.replace(tzinfo=timezone.utc)
                    if (now_utc - _pc_dt).total_seconds() < 1800:
                        continue
                except Exception:
                    pass
            # Rate-limit: at least 9 minutes since last micro ping (buffer for loop jitter)
            last_micro = entry.get("micro_last_ping")
            if last_micro:
                try:
                    last_dt = datetime.fromisoformat(last_micro)
                    if last_dt.tzinfo is None:
                        last_dt = last_dt.replace(tzinfo=timezone.utc)
                    if (now_utc - last_dt).total_seconds() < 1500:
                        continue
                except Exception:
                    pass
            # First reminder is silent (bumps the channel). 2nd and 3rd ping @Ticket Support.
            ping_mention = (ts_role.mention if ts_role else None) if micro_count >= 1 else None
            # On the 2nd reminder, also DM the least-busy reviewer personally so
            # the workload gets routed instead of just spammed at the role.
            if micro_count == 1 and not entry.get("rr_dm_sent"):
                try:
                    _rr_picked = _ti_pick_least_busy_staff(guild)
                    if _rr_picked:
                        _rr_emb = discord.Embed(
                            title="🙏 Review Nudge — Join Application",
                            description=(
                                f"You're the least-busy reviewer right now. A join application in {ch.mention} "
                                "has been waiting for action and needs a fresh pair of eyes.\n\n"
                                "Click **Claim Review** in the ticket to take it."
                            ),
                            color=discord.Color.blurple(),
                            timestamp=now_utc,
                        )
                        _rr_emb.set_footer(text="Different Meets • Round-Robin Reviewer")
                        try:
                            await _rr_picked.send(embed=_rr_emb)
                            entry["rr_dm_sent"] = True
                            entry["rr_dm_target"] = _rr_picked.id
                        except Exception:
                            pass
                except Exception:
                    pass
            emb = discord.Embed(
                title="🔔 Review Reminder",
                description=(
                    "All required photos have been submitted and this application is "
                    "**waiting for a decision**.\n\nClick **Claim Review** to take this ticket, then Accept or Deny."
                ),
                color=discord.Color.blurple(),
                timestamp=now_utc,
            )
            emb.set_footer(text=f"Different Meets • Reminder {micro_count + 1}/{_JOIN_MICRO_BUMP_MAX}")
            try:
                await ch.send(
                    content=ping_mention,
                    embed=emb,
                    allowed_mentions=discord.AllowedMentions(roles=True),
                )
                entry["micro_bump_count"] = micro_count + 1
                entry["micro_last_ping"] = now_utc.isoformat()
                extra[ch_key] = entry
                changed = True
            except Exception:
                pass
        if changed:
            _join_extra_save(extra)
    except Exception as _e:
        print(f"[JoinMicroBump] Error: {_e}")

@tasks.loop(minutes=30)
async def _join_micro_bump_loop():
    _loop_success("_join_micro_bump_loop")
    try:
        await run_with_timeout("_join_micro_bump_loop", __join_micro_bump_logic(), timeout=60)
    except Exception as _lte:
        await _handle_loop_error("_join_micro_bump_loop", _lte, _join_micro_bump_loop)
@_join_micro_bump_loop.error
async def __join_micro_bump_loop_on_error(error: Exception) -> None:
    await _handle_loop_error("_join_micro_bump_loop", error, _join_micro_bump_loop)
@_join_micro_bump_loop.before_loop
async def _before_join_micro_bump():
    await bot.wait_until_ready()

# =========================
# HOST POSTERS — persistent state + role-gated multi-action view
# (upgrade May 26 2026: persistence, role-gate, theme/host/thumbnail, T-2h DM
# + T-30m staff escalation, !editposter, user-ID tracking. Legacy custom_id
# "diff_postmeet_received" kept for back-compat with messages from before the
# upgrade — clicks on those are now treated as "Attending".)
# =========================
_HOST_POSTERS_FILE = os.path.join(DATA_FOLDER, "diff_host_posters.json")
_HOST_POSTER_RETENTION_HOURS = 48  # prune entries N hours after meet starts

def _hp_load_all() -> dict:
    try:
        with open(_HOST_POSTERS_FILE) as _f:
            return json.load(_f) or {}
    except FileNotFoundError:
        return {}
    except (json.JSONDecodeError, ValueError, TypeError, OSError) as _e:
        print(f"[host-posters] state load failed ({_e!r}); starting fresh")
        return {}

def _hp_save_all(data: dict) -> None:
    try:
        _atomic_json_save(_HOST_POSTERS_FILE, data)
    except Exception as _e:
        print(f"[host-posters] failed to persist state: {_e!r}")

def _hp_get(msg_id: int) -> dict | None:
    return _hp_load_all().get(str(msg_id))

def _hp_put(msg_id: int, state: dict) -> None:
    data = _hp_load_all()
    data[str(msg_id)] = state
    _hp_save_all(data)

def _hp_update(msg_id, mutator) -> dict | None:
    """Atomic load-mutate-save for a single record. Accepts int or str msg_id."""
    data = _hp_load_all()
    key = str(msg_id)
    if key not in data:
        return None
    mutator(data[key])
    _hp_save_all(data)
    return data[key]

def _hp_delete(msg_id) -> None:
    """Atomic delete of a single record."""
    data = _hp_load_all()
    if data.pop(str(msg_id), None) is not None:
        _hp_save_all(data)

def _hp_is_authorized(member) -> bool:
    if not isinstance(member, discord.Member):
        return False
    ids = {r.id for r in member.roles}
    return HOST_ROLE_ID in ids or bool(ids & _LEADERSHIP_HOST_ROLE_IDS)

def _hp_render_embed(state: dict) -> discord.Embed:
    resp = state.get("responses", {}) or {}
    statuses = {v.get("status") for v in resp.values()}
    if "help" in statuses:
        color = 0xF1C40F
    elif "attending" in statuses:
        color = 0x2ECC71
    else:
        color = state.get("color", 0xE91E63)

    emb = discord.Embed(title="🏁 DIFF Host Posters", color=color)
    theme = state.get("theme") or ""
    if theme:
        emb.description = f"**{theme}**"

    ts = state.get("meet_ts")
    if ts:
        emb.add_field(name="📅 Date & Time", value=f"<t:{ts}:F>\n<t:{ts}:R>", inline=False)
    else:
        emb.add_field(name="📅 Date & Time", value=state.get("dt_value", "See poster"), inline=False)

    host_ids = state.get("assigned_host_ids", []) or []
    if host_ids:
        emb.add_field(
            name="🎤 Hosts",
            value=" ".join(_readable_host(None, hid) or f"<@{hid}>" for hid in host_ids),
            inline=False,
        )

    attending = [uid for uid, v in resp.items() if v.get("status") == "attending"]
    declined  = [uid for uid, v in resp.items() if v.get("status") == "declined"]
    helping   = [uid for uid, v in resp.items() if v.get("status") == "help"]

    def _fmt(ids):
        return ", ".join(f"<@{i}>" for i in ids) if ids else "—"

    emb.add_field(name=f"✅ Attending ({len(attending)})", value=_fmt(attending), inline=True)
    emb.add_field(name=f"❌ Can't attend ({len(declined)})", value=_fmt(declined), inline=True)
    emb.add_field(name=f"🆘 Need help ({len(helping)})", value=_fmt(helping), inline=True)

    img = state.get("poster_url")
    if img:
        emb.set_image(url=img)
    emb.set_thumbnail(url=_POSTMEET_LOGO_URL)

    footer_bits = ["DIFF Meets • Host Poster"]
    if state.get("edited_at"):
        footer_bits.append("edited")
    emb.set_footer(text=" • ".join(footer_bits))
    return emb

async def _hp_record_response(interaction: discord.Interaction, status: str) -> None:
    member = interaction.user
    if not _hp_is_authorized(member):
        try:
            await interaction.response.send_message(
                "Only Hosts and leadership can respond to host posters.", ephemeral=True
            )
        except Exception:
            pass
        return

    msg_id = interaction.message.id
    now_iso = datetime.now(timezone.utc).isoformat()
    uid = str(member.id)

    def _mut(state: dict) -> None:
        resp = state.setdefault("responses", {})
        resp[uid] = {
            "status": status,
            "name": getattr(member, "display_name", str(member)),
            "ts": now_iso,
            "via": "button",
        }

    state = _hp_update(msg_id, _mut)
    if state is None:
        # Bootstrap for a message we don't know about (legacy / pre-upgrade post)
        state = {
            "guild_id": getattr(interaction.guild, "id", GUILD_ID),
            "channel_id": getattr(interaction.channel, "id", _POSTMEET_HOST_POSTERS_ID),
            "bot_msg_id": msg_id,
            "responses": {uid: {"status": status, "name": getattr(member, "display_name", str(member)), "ts": now_iso, "via": "button"}},
            "created_at": now_iso,
            "assigned_host_ids": [],
        }
        if interaction.message.embeds:
            old = interaction.message.embeds[0]
            if old.image and old.image.url:
                state["poster_url"] = old.image.url
        _hp_put(msg_id, state)

    new_embed = _hp_render_embed(state)
    try:
        await interaction.response.edit_message(embed=new_embed, view=_HostPosterActionsView())
    except Exception as _e:
        print(f"[host-posters] edit_message failed: {_e!r}")

    if status == "help":
        try:
            guild = interaction.guild
            staff_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID) if guild else None
            if isinstance(staff_ch, discord.TextChannel):
                jump = interaction.message.jump_url
                await staff_ch.send(
                    f"🆘 **Host needs help** — {member.mention} requested help on a host poster.\n{jump}"
                )
        except Exception as _e:
            print(f"[host-posters] staff help-ping failed: {_e!r}")


