@bot.event
async def on_guild_join(guild: discord.Guild):
    """Immediately leave any server that isn't the authorised DIFF server."""
    if guild.id != GUILD_ID:
        print(f"[ServerLock] Joined unauthorised guild {guild.name} ({guild.id}) — leaving.")
        try:
            await guild.leave()
        except Exception as _e:
            print(f"[ServerLock] Could not leave {guild.id}: {_e}")


# =========================
# ROLL CALL AUTO-ARCHIVE LOOP
# =========================
_rc_archive_last_ran: str = ""

async def _rc_auto_archive_loop() -> None:
    """Every Monday at 12:05 AM ET: post a final roll call summary for the week to staff logs."""
    await bot.wait_until_ready()
    global _rc_archive_last_ran
    while not bot.is_closed():
        await asyncio.sleep(60)
        try:
            now = datetime.now(_EST_TZ)
            # Monday (weekday 0), 12:05 AM
            if now.weekday() != 0 or now.hour != 0 or now.minute != 5:
                continue
            today_key = now.strftime("%Y-%m-%d")
            if _rc_archive_last_ran == today_key:
                continue
            _rc_archive_last_ran = today_key

            guild = bot.get_guild(GUILD_ID)
            if not guild:
                continue
            logs_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
            if not isinstance(logs_ch, discord.TextChannel):
                continue

            meets = _rc_db.get_meets(guild.id)
            responses = _rc_db.get_all_responses(guild.id)
            crew_role = guild.get_role(CREW_MEMBER_ROLE_ID)
            total_crew = len([m for m in crew_role.members if not m.bot]) if crew_role else 0

            embed = discord.Embed(
                title="📋 Weekly Roll Call Archive",
                description=f"Automatic end-of-week snapshot for **{now.strftime('%B %d, %Y')}**",
                color=discord.Color.blurple(),
                timestamp=now,
            )
            if not meets:
                embed.add_field(name="No meets this week", value="Roll call was not active.", inline=False)
            else:
                for meet_row in meets:
                    mn = meet_row["meet_number"]
                    meet_responses = responses.get(mn, {})
                    yes_ids  = meet_responses.get("yes",   [])
                    no_ids   = meet_responses.get("no",    [])
                    maybe_ids = meet_responses.get("maybe", [])
                    total_resp = len(yes_ids) + len(no_ids) + len(maybe_ids)
                    host_id = meet_row["host_id"]
                    host_mention = _readable_host(None, host_id) or "Unassigned"
                    embed.add_field(
                        name=f"Meet {mn} — {meet_row['class_name'] or 'TBD'} ({meet_row['date_text'] or 'TBD'})",
                        value=(
                            f"Host: {host_mention}\n"
                            f"✅ Yes: **{len(yes_ids)}** · ❌ No: **{len(no_ids)}** · "
                            f"❓ Maybe: **{len(maybe_ids)}**\n"
                            f"Total responses: **{total_resp}** / {total_crew} crew"
                        ),
                        inline=False,
                    )
            embed.set_footer(text="Different Meets • Roll Call Auto-Archive")
            await logs_ch.send(embed=embed)
        except Exception as _e:
            print(f"[RollCall] Auto-archive error: {_e}")


# =========================
# ROLL CALL SATURDAY REMINDER LOOP
# =========================
_rc_saturday_reminder_last_ran: str = ""

async def _rc_saturday_reminder_loop() -> None:
    """Every Saturday at 12:00 PM ET: DM crew members who haven't responded to any meet."""
    await bot.wait_until_ready()
    global _rc_saturday_reminder_last_ran
    while not bot.is_closed():
        await asyncio.sleep(60)
        try:
            now = datetime.now(_EST_TZ)
            # Saturday (weekday 5), noon
            if now.weekday() != 5 or now.hour != 12 or now.minute != 0:
                continue
            today_key = now.strftime("%Y-%m-%d")
            if _rc_saturday_reminder_last_ran == today_key:
                continue
            _rc_saturday_reminder_last_ran = today_key

            guild = bot.get_guild(GUILD_ID)
            if not guild:
                continue
            meets = _rc_db.get_meets(guild.id)
            if not meets:
                continue
            responses = _rc_db.get_all_responses(guild.id)
            crew_role = guild.get_role(CREW_MEMBER_ROLE_ID)
            if not crew_role:
                continue

            # All user IDs who have responded to at least one meet
            responded: set = set()
            for mr in responses.values():
                for uid_list in mr.values():
                    responded.update(uid_list)

            pending = [m for m in crew_role.members if not m.bot and m.id not in responded]
            if not pending:
                continue

            rc_url = f"https://discord.com/channels/{GUILD_ID}/{ROLL_CALL_CHANNEL_ID}"
            dm_embed = discord.Embed(
                title="📋 Don't forget — Roll Call closes soon!",
                description=(
                    "Hey! You haven't responded to this week's **DIFF Meet roll call** yet.\n\n"
                    f"📌 **[Open the Roll Call]({rc_url})**\n\n"
                    "Let the crew know if you're coming — it takes 10 seconds.\n"
                    "The roll call resets every Monday."
                ),
                color=discord.Color.orange(),
                timestamp=now,
            )
            dm_embed.set_footer(text="DIFF Meets • Saturday Roll Call Reminder")

            sent = failed = 0
            for m in pending:
                try:
                    await m.send(embed=dm_embed)
                    sent += 1
                    await asyncio.sleep(1)
                except discord.Forbidden:
                    failed += 1
                except Exception as _de:
                    print(f"[RcReminder] DM to {m.id} failed: {_de}")
                    failed += 1

            print(f"[RcReminder] Saturday reminder — {sent} DMs sent, {failed} failed, {len(responded)} already responded.")
            if failed > 0:
                logs_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
                if isinstance(logs_ch, discord.TextChannel):
                    await logs_ch.send(embed=discord.Embed(
                        title="⚠️ Roll Call Reminder — DM Failures",
                        description=f"**{failed}** crew member(s) couldn't be DM'd for the Saturday roll call reminder.\n\n✅ Sent: {sent} · ❌ Failed: {failed}",
                        color=discord.Color.orange(),
                        timestamp=now,
                    ).set_footer(text="DIFF Meets • Roll Call Reminder System"))
        except Exception as _e:
            print(f"[RcReminder] Loop error: {_e}")


_rc_strike_action_lock = asyncio.Lock()


class _RCStrikeConfirmView(discord.ui.View):
    """Persistent staff-confirm view on the weekly roll-call strike-candidate report.
    Candidates are loaded from disk state keyed by message id, so buttons survive restarts."""
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="Issue Strikes", style=discord.ButtonStyle.danger, custom_id="diff_rc_strike_issue")
    async def _issue_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle(interaction, issue=True)

    @discord.ui.button(label="Dismiss", style=discord.ButtonStyle.secondary, custom_id="diff_rc_strike_dismiss")
    async def _dismiss_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._handle(interaction, issue=False)

    async def _handle(self, interaction: discord.Interaction, issue: bool):
        roles = getattr(interaction.user, "roles", [])
        if not any(r.id in _LEADERSHIP_ROLE_IDS for r in roles):
            return await interaction.response.send_message("Leadership only.", ephemeral=True)
        await interaction.response.defer()

        # Consume the pending entry + persist all data mutations under a lock so two
        # near-simultaneous leadership clicks can't both issue strikes / double-write
        # warnings. Slow network work (DMs, embed edit) happens AFTER the lock releases.
        async with _rc_strike_action_lock:
            state = _rc_strike_state_load()
            pending = state.setdefault("pending", {})
            entry = pending.pop(str(interaction.message.id), None)
            if entry is None:
                return await interaction.followup.send("This strike review is no longer active.", ephemeral=True)
            cand_ids = entry.get("candidates", [])
            if issue:
                import uuid as _uuid
                wdata = _warnings_load()
                miss = state.setdefault("miss_streaks", {})
                for uid in cand_ids:
                    warn_id = str(_uuid.uuid4())[:8].upper()
                    wdata.setdefault(str(uid), []).append({
                        "id": warn_id,
                        "reason": "Repeatedly missed the weekly roll call",
                        "issued_by": interaction.user.id,
                        "issued_by_name": interaction.user.display_name,
                        "timestamp": datetime.now(_EST_TZ).isoformat(),
                    })
                    miss[str(uid)] = 0
                _warnings_save(wdata)
            _rc_strike_state_save(state)

        guild = interaction.guild

        if not issue:
            try:
                emb = interaction.message.embeds[0]
                emb.color = discord.Color.greyple()
                emb.title = "⚪ Roll Call Strikes — Dismissed"
                emb.set_footer(text=f"Dismissed by {interaction.user.display_name}")
                await interaction.message.edit(embed=emb, view=None)
            except Exception:
                pass
            return await interaction.followup.send("Dismissed — no strikes issued.", ephemeral=True)

        # Warnings already persisted under the lock; now DM each member (slow / network).
        issued = 0
        for uid in cand_ids:
            issued += 1
            member = guild.get_member(uid) if guild else None
            if member:
                try:
                    await member.send(embed=discord.Embed(
                        title="⚠️ You have received a formal warning",
                        description=(
                            "**Reason:** Repeatedly missing the weekly DIFF roll call.\n\n"
                            f"👉 [Open the roll call](https://discord.com/channels/{GUILD_ID}/{ROLL_CALL_CHANNEL_ID}) "
                            "and respond each week to avoid further strikes.\n\n"
                            "If you believe this was issued in error, contact leadership."
                        ),
                        color=discord.Color.red(),
                        timestamp=datetime.now(_EST_TZ),
                    ).set_footer(text="Different Meets • Formal Warning"))
                except Exception:
                    pass
                await asyncio.sleep(0.5)
        try:
            emb = interaction.message.embeds[0]
            emb.color = discord.Color.green()
            emb.title = "✅ Roll Call Strikes — Issued"
            emb.set_footer(text=f"{issued} strike(s) issued by {interaction.user.display_name}")
            await interaction.message.edit(embed=emb, view=None)
        except Exception:
            pass
        await interaction.followup.send(f"✅ Issued **{issued}** strike(s) — each member was DM'd.", ephemeral=True)


async def _rc_public_reminder_loop() -> None:
    """Sunday 6 PM ET: post a public roll-call reminder in the roll-call channel pinging @Crew Members.
    Disk-persisted (diff_rc_reminder_state.json) so a redeploy can't re-fire it the same week."""
    await bot.wait_until_ready()
    while not bot.is_closed():
        await asyncio.sleep(60)
        try:
            now = datetime.now(_EST_TZ)
            # Sunday (weekday 6), 6 PM ET — the day before the Monday reset
            if now.weekday() != 6 or now.hour != 18 or now.minute != 0:
                continue
            today_key = now.strftime("%Y-%m-%d")
            st = _rc_reminder_state_load()
            if st.get("last_public_reminder") == today_key:
                continue
            guild = bot.get_guild(GUILD_ID)
            if not guild:
                continue
            built = _rc_build_public_reminder(guild, tag_individuals=False)
            if not built:
                st["last_public_reminder"] = today_key
                _rc_reminder_state_save(st)
                continue
            ping_content, embed, _non = built
            ch = guild.get_channel(ROLL_CALL_CHANNEL_ID)
            if not isinstance(ch, discord.TextChannel):
                continue
            await ch.send(
                content=ping_content,
                embed=embed,
                allowed_mentions=discord.AllowedMentions(roles=True, users=True, everyone=False),
            )
            st["last_public_reminder"] = today_key
            _rc_reminder_state_save(st)
        except Exception as _e:
            print(f"[RcPublicReminder] Loop error: {_e}")


# =========================
# CREW ATTENDANCE PRUNING REPORT LOOP
# =========================
_rc_pruning_report_last_ran: str = ""

async def _rc_pruning_report_loop() -> None:
    """Every Monday at 12:15 AM ET: post a pruning report of crew with zero yes responses this week."""
    await bot.wait_until_ready()
    global _rc_pruning_report_last_ran
    while not bot.is_closed():
        await asyncio.sleep(60)
        try:
            now = datetime.now(_EST_TZ)
            # Monday (weekday 0), 12:15 AM
            if now.weekday() != 0 or now.hour != 0 or now.minute != 15:
                continue
            today_key = now.strftime("%Y-%m-%d")
            if _rc_pruning_report_last_ran == today_key:
                continue
            _rc_pruning_report_last_ran = today_key

            guild = bot.get_guild(GUILD_ID)
            if not guild:
                continue
            logs_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
            if not isinstance(logs_ch, discord.TextChannel):
                continue

            crew_role = guild.get_role(CREW_MEMBER_ROLE_ID)
            if not crew_role:
                continue

            crew_members = [m for m in crew_role.members if not m.bot]
            # Prefer the pre-wipe snapshot: the Monday-00:00 weekly reset wipes the
            # live DB 15 minutes before this report runs, so live data is empty here.
            # The snapshot (written just before the wipe) holds the real ending week.
            responses = _rc_db.get_all_responses(guild.id)
            try:
                _snap = _rc_week_snapshot_load()
                if (
                    _snap.get("week_monday") == today_key
                    and str(_snap.get("guild_id")) == str(guild.id)
                    and isinstance(_snap.get("responses"), dict)
                    and _snap.get("reset_completed") is True
                ):
                    responses = _snap["responses"]
            except Exception as _sne:
                print(f"[PruningReport] snapshot read failed ({_sne}) — using live DB")

            # Build per-member response map for this week
            yes_responders:  set = set()
            any_responders:  set = set()
            no_only: list = []

            for mr in responses.values():
                yes_responders.update(mr.get("yes", []))
                for uid_list in mr.values():
                    any_responders.update(uid_list)

            no_response = [m for m in crew_members if m.id not in any_responders]
            no_only_members = [m for m in crew_members if m.id in any_responders and m.id not in yes_responders]

            embed = discord.Embed(
                title="🔍 Weekly Crew Attendance Pruning Report",
                description=f"Week ending **{now.strftime('%B %d, %Y')}** — {len(crew_members)} total crew",
                color=discord.Color.red(),
                timestamp=now,
            )

            if no_response:
                sample = " ".join(m.mention for m in no_response[:20])
                suffix = f" + {len(no_response) - 20} more" if len(no_response) > 20 else ""
                embed.add_field(
                    name=f"⬜ No Response At All ({len(no_response)})",
                    value=sample + suffix,
                    inline=False,
                )
            else:
                embed.add_field(name="⬜ No Response At All", value="Everyone responded this week ✅", inline=False)

            if no_only_members:
                sample2 = " ".join(m.mention for m in no_only_members[:20])
                suffix2 = f" + {len(no_only_members) - 20} more" if len(no_only_members) > 20 else ""
                embed.add_field(
                    name=f"❌ Responded 'No' to All Meets ({len(no_only_members)})",
                    value=sample2 + suffix2,
                    inline=False,
                )

            embed.add_field(
                name="📊 Summary",
                value=(
                    f"✅ Responded yes to ≥1 meet: **{len(yes_responders)}**\n"
                    f"❌ All no / maybe: **{len(no_only_members)}**\n"
                    f"⬜ No response: **{len(no_response)}**"
                ),
                inline=False,
            )
            embed.set_footer(text="Different Meets • Crew Pruning Report")
            await logs_ch.send(embed=embed)

            # ── Update roll call streaks ──────────────────────────────
            try:
                streaks = _rc_streaks_load()
                milestone_dms: list[tuple[discord.Member, int]] = []
                for cm in crew_members:
                    uid_key = str(cm.id)
                    entry = streaks.setdefault(uid_key, {"streak": 0, "best": 0})
                    if cm.id in yes_responders:
                        entry["streak"] += 1
                        if entry["streak"] > entry["best"]:
                            entry["best"] = entry["streak"]
                        if entry["streak"] in (4, 8, 12, 26, 52):
                            milestone_dms.append((cm, entry["streak"]))
                    else:
                        entry["streak"] = 0
                _rc_streaks_save(streaks)

                # Streak badges may have just become eligible — grant immediately
                # for anyone who responded yes (instead of waiting for !badges).
                for cm in crew_members:
                    if cm.id in yes_responders:
                        try:
                            await _xp_check_badges(guild, cm)
                        except Exception:
                            pass

                # Send milestone DMs
                for (cm, wks) in milestone_dms:
                    try:
                        await cm.send(embed=discord.Embed(
                            title="🔥 Roll Call Streak Milestone!",
                            description=(
                                f"You've responded **Yes** to the roll call for "
                                f"**{wks} consecutive week{'s' if wks != 1 else ''}** — keep it up!\n\n"
                                "Your streak is tracked in your crew stats."
                            ),
                            color=discord.Color.orange(),
                            timestamp=now,
                        ).set_footer(text="Different Meets • Crew Streaks"))
                        await asyncio.sleep(1)
                    except Exception:
                        pass
            except Exception as _se:
                print(f"[PruningReport] Streak update error: {_se}")

            # ── Auto-strike candidate tracking (repeat no-response weeks) ──
            # Persisted weekly guard (last_strike_week) so a restart near Mon 00:15
            # can't re-run the increment and double-count misses for the same week.
            try:
                strike_state = _rc_strike_state_load()
                week_key = now.strftime("%Y-%m-%d")
                if strike_state.get("last_strike_week") != week_key:
                    strike_state["last_strike_week"] = week_key
                    miss = strike_state.setdefault("miss_streaks", {})
                    no_response_ids = {m.id for m in no_response}
                    candidates: list = []
                    for cm in crew_members:
                        if _rc_strike_exempt(cm):
                            miss.pop(str(cm.id), None)
                            continue
                        key = str(cm.id)
                        if cm.id in no_response_ids:
                            miss[key] = int(miss.get(key, 0)) + 1
                        else:
                            miss[key] = 0
                        if miss[key] >= _RC_STRIKE_THRESHOLD:
                            candidates.append((cm, miss[key]))
                    _rc_strike_state_save(strike_state)

                    if candidates:
                        cand_lines = "\n".join(
                            f"{m.mention} — missed **{c}** weeks in a row" for (m, c) in candidates[:25]
                        )
                        more = f"\n…and {len(candidates) - 25} more" if len(candidates) > 25 else ""
                        strike_embed = discord.Embed(
                            title="⚠️ Roll Call Strike Candidates",
                            description=(
                                f"These crew members have missed roll call **{_RC_STRIKE_THRESHOLD}+ weeks in a row**:\n\n"
                                f"{cand_lines}{more}\n\n"
                                "Leadership — click **Issue Strikes** to give each a formal warning (they'll be DM'd), "
                                "or **Dismiss** to skip this week."
                            ),
                            color=discord.Color.dark_red(),
                            timestamp=now,
                        )
                        strike_embed.set_footer(text="DIFF Meets • Roll Call Strike Review")
                        strike_msg = await logs_ch.send(embed=strike_embed, view=_RCStrikeConfirmView())
                        strike_state.setdefault("pending", {})[str(strike_msg.id)] = {
                            "candidates": [m.id for (m, _c) in candidates],
                            "created": now.isoformat(),
                        }
                        _rc_strike_state_save(strike_state)
            except Exception as _str_e:
                print(f"[RcStrike] candidate tracking error: {_str_e}")
        except Exception as _e:
            print(f"[PruningReport] Loop error: {_e}")


# =========================
# HP SESSION CLEANUP LOOP
# =========================
_HP_ARCHIVE_FILE = os.path.join("diff_data", "diff_hp_session_archive.json")

async def _hp_session_cleanup_loop() -> None:
    """Hourly: auto-close stale sessions (24h+). Daily at 3 AM: archive sessions older than 60 days."""
    await bot.wait_until_ready()
    while not bot.is_closed():
        await asyncio.sleep(3600)
        try:
            from datetime import timedelta as _td
            now = datetime.now(_EST_TZ)

            # ── Stale session auto-close (24h+) ──────────────────────
            hp_data = _hp_load()
            stale_closed = 0
            for sid, s in hp_data.get("active_sessions", {}).items():
                if s.get("ended"):
                    continue
                started_raw = s.get("started_at", "")
                if not started_raw:
                    continue
                try:
                    started_dt = datetime.fromisoformat(started_raw).astimezone(_EST_TZ)
                    if (now - started_dt).total_seconds() >= 86400:
                        s["ended"] = True
                        s["ended_at"] = now.isoformat()
                        s["auto_closed"] = True
                        stale_closed += 1
                except Exception:
                    pass
            if stale_closed:
                _hp_save(hp_data)
                guild = bot.get_guild(GUILD_ID)
                if guild:
                    logs_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
                    if isinstance(logs_ch, discord.TextChannel):
                        await logs_ch.send(embed=discord.Embed(
                            title="⏱ Stale HP Sessions Auto-Closed",
                            description=f"**{stale_closed}** session(s) were open for 24+ hours with no End action and have been automatically closed.",
                            color=discord.Color.orange(),
                            timestamp=now,
                        ).set_footer(text="Different Meets • HP Session Cleanup"))
                print(f"[HpCleanup] Auto-closed {stale_closed} stale session(s).")

            if now.hour != 3:
                continue

            hp_data = _hp_load()
            sessions = hp_data.get("active_sessions", {})
            cutoff = now - _td(days=60)
            cutoff_str = cutoff.isoformat()

            to_archive = {}
            to_keep = {}
            for sid, s in sessions.items():
                ended_at = s.get("ended_at") or ""
                if s.get("ended") and ended_at and ended_at < cutoff_str:
                    to_archive[sid] = s
                else:
                    to_keep[sid] = s

            if not to_archive:
                continue

            # Load existing archive and append
            try:
                with open(_HP_ARCHIVE_FILE) as _af:
                    archive = json.load(_af)
            except Exception:
                archive = {}
            archive.update(to_archive)
            _atomic_json_save(_HP_ARCHIVE_FILE, archive)

            hp_data["active_sessions"] = to_keep
            _hp_save(hp_data)
            print(f"[HpCleanup] Archived {len(to_archive)} old session(s). {len(to_keep)} remain active.")
        except Exception as _e:
            print(f"[HpCleanup] Loop error: {_e}")


# =========================
# HRSVP AUTO-RESET LOOP
# =========================
async def _hrsvp_auto_reset_loop() -> None:
    """Checks every 60 s: wipe RSVP panel once per week when a new Monday (EST) begins,
    ping @Meet Hosts. On startup, immediately catches up any missed Monday reset."""
    await bot.wait_until_ready()
    from zoneinfo import ZoneInfo as _ZI
    from datetime import timedelta as _td

    # ── Startup catch-up: reset if this week's Monday reset was missed ───────
    try:
        now_est = datetime.now(_ZI("America/New_York"))
        days_since_monday = now_est.weekday()            # 0=Mon … 6=Sun
        most_recent_monday = (now_est - _td(days=days_since_monday)).strftime("%Y-%m-%d")
        if _hrsvp_reset_ts_load() != most_recent_monday:
            _hrsvp_reset()
            _hrsvp_reset_ts_save(most_recent_monday)
            await _hrsvp_update_panel(bot)
            # Reset notice goes to #host-team chat (not the panel channel)
            ch = bot.get_channel(_HOST_TEAM_CHANNEL_ID)
            if isinstance(ch, discord.TextChannel):
                host_role = ch.guild.get_role(HOST_ROLE_ID) if ch.guild else None
                ping      = host_role.mention if host_role else "@Meet Hosts"
                await ch.send(
                    f"{ping} 📋 **New week — availability panel reset!**\n"
                    f"Please mark your availability for Meet 1, Meet 2, and Meet 3 in <#{HOST_RSVP_CHANNEL_ID}>. "
                    "Leadership builds the schedule from your responses."
                )
            print("[HRSVP] Startup catch-up reset applied.")
    except Exception as _e:
        print(f"[HRSVP] Startup catch-up error: {_e}")

    # ── Ongoing loop: reset promptly whenever a new week (Monday EST) begins ──
    # Mirrors the startup catch-up logic (compare stored vs. most-recent Monday)
    # instead of gating on hour==0, so a missed midnight tick can't leave the
    # panel stale for up to half an hour — it resets within ~60 s of Monday 00:00.
    while not bot.is_closed():
        await asyncio.sleep(60)
        try:
            now_est            = datetime.now(_ZI("America/New_York"))
            most_recent_monday = (now_est - _td(days=now_est.weekday())).strftime("%Y-%m-%d")
            if _hrsvp_reset_ts_load() == most_recent_monday:
                continue
            _hrsvp_reset()
            _hrsvp_reset_ts_save(most_recent_monday)
            await _hrsvp_update_panel(bot)
            # Reset notice goes to #host-team chat (not the panel channel)
            ch = bot.get_channel(_HOST_TEAM_CHANNEL_ID)
            if isinstance(ch, discord.TextChannel):
                host_role = ch.guild.get_role(HOST_ROLE_ID) if ch.guild else None
                ping      = host_role.mention if host_role else "@Meet Hosts"
                await ch.send(
                    f"{ping} 📋 **New week — availability panel reset!**\n"
                    f"Please mark your availability for Meet 1, Meet 2, and Meet 3 in <#{HOST_RSVP_CHANNEL_ID}>. "
                    "Leadership builds the schedule from your responses."
                )
        except Exception as _e:
            print(f"[HRSVP AutoReset] {_e}")


# =========================
# ROLL CALL WEEKLY AUTO-RESET LOOP
# =========================
async def _rc_weekly_reset_loop() -> None:
    """Once per week, when a new Monday (EST) begins, wipe last week's roll-call
    responses/meets and post a fresh roll-call panel (pings crew) — mirrors the host
    availability panel's auto-reset. Checks every 60 s; on startup immediately catches
    up if this week's Monday reset was missed. The once-per-week guard
    (`last_weekly_reset` in the rc reminder-state file) is persisted to disk so a
    redeploy can't re-fire the same week."""
    await bot.wait_until_ready()
    from zoneinfo import ZoneInfo as _ZI
    from datetime import timedelta as _td

    async def _do_reset(monday_str: str) -> None:
        guild = bot.get_guild(GUILD_ID)
        if guild is None:
            return
        await _rc_post_new_panel(guild, ping_roles=True, reset=True)
        st = _rc_reminder_state_load()
        st["last_weekly_reset"] = monday_str
        _rc_reminder_state_save(st)
        print(f"[RcWeeklyReset] Reset + reposted roll call for week of {monday_str}.")

    # ── Startup catch-up ───────
    # Reset is destructive (wipes responses/meets), so on the VERY first run (or if the
    # state file was lost) we SEED the marker without wiping — a mid-week deploy must
    # never destroy an in-progress week. Auto-reset then begins at the next Monday.
    # Only an actually-missed Monday boundary (stored marker older than this week) wipes.
    try:
        now_est            = datetime.now(_ZI("America/New_York"))
        most_recent_monday = (now_est - _td(days=now_est.weekday())).strftime("%Y-%m-%d")
        st     = _rc_reminder_state_load()
        stored = st.get("last_weekly_reset")
        if stored is None:
            st["last_weekly_reset"] = most_recent_monday
            _rc_reminder_state_save(st)
            print("[RcWeeklyReset] First run — seeded weekly marker (no reset).")
        elif stored != most_recent_monday:
            await _do_reset(most_recent_monday)
            print("[RcWeeklyReset] Startup catch-up reset applied (missed Monday).")
    except Exception as _e:
        print(f"[RcWeeklyReset] Startup catch-up error: {_e}")

    # ── Ongoing loop: reset within ~60 s of Monday 00:00 EST ──
    while not bot.is_closed():
        await asyncio.sleep(60)
        try:
            now_est            = datetime.now(_ZI("America/New_York"))
            most_recent_monday = (now_est - _td(days=now_est.weekday())).strftime("%Y-%m-%d")
            if _rc_reminder_state_load().get("last_weekly_reset") == most_recent_monday:
                continue
            await _do_reset(most_recent_monday)
        except Exception as _e:
            print(f"[RcWeeklyReset] {_e}")


# =========================
# HRSVP ESCALATION LOOP
# =========================
_HRSVP_ESCALATED: set = set()   # tracks which slots have already been alerted this week


async def _hrsvp_escalation_loop() -> None:
    """Every 6 h: if a meet slot is ≤3 days away with no host, alert #host-team."""
    await bot.wait_until_ready()
    while not bot.is_closed():
        await asyncio.sleep(21600)
        try:
            schedule = _asched_load()
            guild    = discord.utils.get(bot.guilds, id=GUILD_ID)
            if not guild:
                continue
            ch = bot.get_channel(_HOST_TEAM_CHANNEL_ID)
            if not isinstance(ch, discord.TextChannel):
                continue
            rsvp = _hrsvp_load()
            for day in _HRSVP_DAYS:
                entry = schedule["days"].get(day, {})
                if entry.get("host_id"):
                    _HRSVP_ESCALATED.discard(day)
                    continue
                ts = _parse_meet_ts(entry.get("day", ""), entry.get("time", ""))
                if not ts:
                    continue
                days_until = (ts - int(utc_now().timestamp())) / 86400
                if days_until <= 3 and day not in _HRSVP_ESCALATED:
                    _HRSVP_ESCALATED.add(day)
                    slot_data  = rsvp.get(day, {})
                    maybe_ents = slot_data.get("maybe", [])
                    maybe_tags = (
                        "  ".join(f"<@{_hrsvp_uid(e)}>" for e in maybe_ents[:4])
                        if maybe_ents else "*none*"
                    )
                    leader_role = guild.get_role(LEADER_ROLE_ID)
                    ping        = leader_role.mention if leader_role else "@Leadership"
                    await ch.send(
                        f"⚠️ {ping} **{day} has no confirmed host** and is "
                        f"**{int(days_until)} day(s)** away!\n"
                        f"❓ Maybe hosts: {maybe_tags}\n"
                        f"Override a slot in <#{HOST_RSVP_CHANNEL_ID}> using the "
                        f"**Override Slot** button."
                    )
        except Exception as _e:
            print(f"[HRSVP Escalation] {_e}")


# =========================
# APPLICATION TIMEOUT LOOP
# =========================
async def application_timeout_loop():
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            app_data = load_apps()
            for app_id, record in app_data.get("applications", {}).items():
                if record.get("status") not in {"Pending", "More Info Requested"}:
                    continue
                submitted_at = record.get("submitted_at")
                if not submitted_at:
                    continue
                try:
                    submitted_dt = datetime.fromisoformat(submitted_at)
                except Exception:
                    continue
                if utc_now() - submitted_dt < timedelta(hours=GARAGE_TIMEOUT_HOURS):
                    continue
                guild = bot.get_guild(GUILD_ID)
                if not guild:
                    continue
                ticket_channel = guild.get_channel(record.get("ticket_channel_id")) if record.get("ticket_channel_id") else None
                photo_count = 0
                if isinstance(ticket_channel, discord.TextChannel):
                    messages = [m async for m in ticket_channel.history(limit=200)]
                    photo_count = count_message_attachments(messages)
                if photo_count >= MIN_GARAGE_PHOTOS:
                    continue
                update_app(
                    app_id,
                    status="Timed Out",
                    reviewed_at=utc_now().isoformat(),
                    decision_reason=f"Timed out before uploading the required {MIN_GARAGE_PHOTOS} garage photos.",
                    ticket_closed=True,
                    closed_at=utc_now().isoformat(),
                )
                applicant = guild.get_member(record["user_id"])
                if applicant:
                    await safe_dm(
                        applicant,
                        f"Your DIFF application **#{app_id}** timed out because the required **{MIN_GARAGE_PHOTOS}** garage photos "
                        f"were not uploaded within **{GARAGE_TIMEOUT_HOURS} hours**.",
                    )
                tracker_channel = guild.get_channel(APPLICATION_TRACKER_CHANNEL_ID)
                if isinstance(tracker_channel, discord.TextChannel) and record.get("tracker_message_id"):
                    try:
                        tracker_msg = await tracker_channel.fetch_message(record["tracker_message_id"])
                        tracker_embed = build_tracker_embed(
                            app_id,
                            applicant or guild.me,
                            record,
                            "Timed Out",
                            "System Auto Timeout",
                        )
                        await tracker_msg.edit(embed=tracker_embed, view=None)
                    except Exception:
                        pass
                if isinstance(ticket_channel, discord.TextChannel):
                    try:
                        await ticket_channel.send(embed=discord.Embed(
                            title="Application Timed Out",
                            description=(
                                f"This application timed out because at least **{MIN_GARAGE_PHOTOS}** garage photos "
                                f"were not uploaded within **{GARAGE_TIMEOUT_HOURS} hours**."
                            ),
                            color=discord.Color.dark_orange(),
                            timestamp=utc_now(),
                        ))
                    except Exception:
                        pass
                    try:
                        _tcn = ticket_channel.name
                        await ticket_channel.edit(name=_tcn if _tcn.startswith("closed-") else f"closed-{_tcn[:80]}")
                    except Exception:
                        pass
                    try:
                        await ticket_channel.set_permissions(guild.default_role, view_channel=False)
                    except Exception:
                        pass
                    if applicant:
                        try:
                            await ticket_channel.set_permissions(applicant, overwrite=None)
                        except Exception:
                            pass
        except Exception:
            pass
        await asyncio.sleep(600)


