@bot.tree.command(name="force-color-winner", description="Manually close the vote and post the winner (leadership only)")
async def force_color_winner(interaction: discord.Interaction):
    if not isinstance(interaction.user, discord.Member) or not _cs_is_color_admin(interaction.user):
        return await interaction.response.send_message("Founders, Executives, and Server Operations only.", ephemeral=True)
    await interaction.response.defer(ephemeral=True)
    # Snapshot state before attempting close so we can tell the difference between
    # "no vote was ever active" and "vote was stuck and we just unstuck it".
    _pre = _cs_load().get("current_vote")
    success = await _cs_try_close_vote(interaction.guild)
    if success:
        await interaction.followup.send("Vote closed and winner posted.", ephemeral=True)
    else:
        _post = _cs_load().get("current_vote")
        if _pre and not _post:
            # Orphan recovery happened
            await interaction.followup.send(
                "⚠️ Vote message was missing — the stuck vote record has been **cleared**. "
                "You can now run `/force-color-vote` to start a fresh vote.",
                ephemeral=True,
            )
        else:
            await interaction.followup.send("No active vote to close.", ephemeral=True)


@bot.command(name="rebuildcolorvote", aliases=["fixcolorvote", "refreshcolorvote"])
@commands.guild_only()
async def _cmd_rebuild_color_vote(ctx: commands.Context):
    """Leadership only: re-render the ACTIVE vote message in place with a fresh 2x2
    collage — votes already cast are preserved (reactions survive message edits).
    Use when the collage failed to render (e.g. an expired image URL)."""
    if not isinstance(ctx.author, discord.Member) or not _cs_is_color_admin(ctx.author):
        await ctx.send("Founders, Executives, and Server Operations only.", delete_after=6)
        return
    data = _cs_load()
    current_vote = data.get("current_vote")
    if not current_vote or current_vote.get("closed", False):
        await ctx.send("No active color vote to rebuild.", delete_after=10)
        return
    try:
        channel = await _cs_fetch_channel(int(current_vote["channel_id"]))
        vote_msg = await channel.fetch_message(int(current_vote["message_id"]))
    except Exception:
        await ctx.send(
            "⚠️ Could not fetch the active vote message (deleted?). "
            "Use `/force-color-winner` to clear the stuck vote, then `/force-color-vote`.",
            delete_after=15,
        )
        return
    candidate_ids = current_vote.get("candidate_submission_ids", [])
    candidates = [data["submissions"].get(cid) for cid in candidate_ids]
    candidates = [c for c in candidates if c][:4]
    if not candidates:
        await ctx.send("⚠️ The active vote has no resolvable candidates.", delete_after=10)
        return
    async with ctx.typing():
        collage = await _cs_build_vote_collage(candidates)
    if collage is None:
        await ctx.send("⚠️ Collage could not be built (image tooling unavailable on this host).", delete_after=10)
        return
    # Rebuild the message body exactly like the original announcement.
    crew_role = ctx.guild.get_role(CREW_MEMBER_ROLE_ID)
    ping = crew_role.mention if crew_role else ""
    lines = []
    if ping:
        lines += [ping, ""]
    lines += [
        "*Crew Color will be voted on this week.*", "",
        "*The color with the most votes will be the crew color for the following week.*", "",
    ]
    for idx, c in enumerate(candidates):
        lines.append(f"{['1️⃣', '2️⃣', '3️⃣', '4️⃣'][idx]} **{c['color_name']}** — `{c['hex_code']}`")
    lines += ["", "*Color order starts from left to right.*", "", "*Please choose one color below* 👇"]
    _now_v = datetime.now(COLOR_TZ)
    _days_until_mon = (7 - _now_v.weekday()) % 7 or 7
    _deadline = (_now_v + timedelta(days=_days_until_mon)).replace(
        hour=COLOR_SCHEDULE_HOUR, minute=0, second=0, microsecond=0
    )
    _dl_ts = int(_deadline.timestamp())
    embed = discord.Embed(color=discord.Color.blurple(), timestamp=datetime.now(COLOR_TZ))
    embed.add_field(
        name="⏰ Voting Closes",
        value=f"<t:{_dl_ts}:F>  (<t:{_dl_ts}:R>)",
        inline=False,
    )
    embed.set_image(url="attachment://diff_color_vote.png")
    embed.set_footer(text="DIFF • Weekly Crew Color Vote")
    try:
        await vote_msg.edit(content="\n".join(lines), embed=embed, attachments=[collage])
    except Exception as _ee:
        await ctx.send(f"⚠️ Failed to edit the vote message: {_ee}", delete_after=15)
        return
    # Best-effort: make sure the number reactions are present (edits keep them anyway).
    for emoji in NUMBER_EMOJIS[:len(candidates)]:
        try:
            await vote_msg.add_reaction(emoji)
        except Exception:
            pass
    await ctx.send("✅ Vote message rebuilt — the 2x2 color collage is back. All existing votes were preserved.", delete_after=20)


@bot.command(name="setcolorwinner", aliases=["manualcolorwinner", "pickcolorwinner", "colorwinner"])
@commands.guild_only()
async def _cmd_set_color_winner(ctx: commands.Context, *, color_name: str):
    """Leadership only: manually declare a color the weekly winner by name.
    Falls back to gtacolors.com when submission data is missing.
    Example: !setcolorwinner Rolex Blue
    """
    if not isinstance(ctx.author, discord.Member) or not _cs_is_color_admin(ctx.author):
        await ctx.send("Leadership only.", delete_after=6)
        return
    try:
        await ctx.message.delete()
    except Exception:
        pass

    data = _cs_load()

    # ── 1. Search stored submissions (exact then partial) ────────────────────
    match = None
    for sub in data["submissions"].values():
        if sub.get("color_name", "").lower() == color_name.lower():
            match = sub
            break
    if not match:
        for sub in data["submissions"].values():
            if color_name.lower() in sub.get("color_name", "").lower():
                match = sub
                break

    # ── 2. Fallback: look up from gtacolors.com ──────────────────────────────
    if not match:
        thinking = await ctx.send("🎨 No local submission found — searching gtacolors.com…")
        pool = await _cs_fetch_gta_color_pool()
        gta_hit = None
        if pool:
            # Exact name match first
            for c in pool:
                if c.get("color", "").lower() == color_name.lower():
                    gta_hit = c
                    break
            # Partial match fallback
            if not gta_hit:
                for c in pool:
                    if color_name.lower() in c.get("color", "").lower():
                        gta_hit = c
                        break
        if not gta_hit:
            await thinking.edit(
                content=(
                    f"❌ **{color_name}** not found in local submissions or on gtacolors.com.\n"
                    "Use `!setcolorwinner <exact color name>` — check https://gtacolors.com for the exact spelling."
                )
            )
            return
        # Build a synthetic submission dict from the gtacolors.com data
        hex_val = f"#{gta_hit['hex'].upper().lstrip('#')}"
        img_url = f"https://gtacolors.com/{gta_hit['image_url']}.jpg"
        match = {
            "message_id":  f"gtac_{gta_hit['ID']}",
            "channel_id":  "0",
            "author_id":   str(bot.user.id),
            "author_name": f"{gta_hit.get('manufacturer', 'gtacolors.com')} (Manual Override)",
            "manufacturer": gta_hit.get("manufacturer", ""),
            "color_name":  gta_hit["color"],
            "hex_code":    hex_val,
            "image_url":   img_url,
            "status":      "won",
            "submitted_at": _cs_utc_now(),
            "source":       "gtacolors.com",
        }
        await thinking.delete()

    # ── 3. Post winner announcement ──────────────────────────────────────────
    guild = ctx.guild
    await _cs_post_winner_announcement(guild, match, manual=True)

    # ── 4. Update data file ──────────────────────────────────────────────────
    fake_id = match.get("message_id", f"manual_{_cs_utc_now()}")
    match["status"] = "won"
    match["won_at"]  = _cs_utc_now()
    data["submissions"][fake_id] = match

    # Close out any lingering current_vote
    current_vote = data.get("current_vote")
    if current_vote and not current_vote.get("closed", False):
        candidate_ids = current_vote.get("candidate_submission_ids", [])
        for cid in candidate_ids:
            c = data["submissions"].get(cid)
            if c and c.get("message_id") != fake_id:
                c["status"] = "locked"
                c["locked_at"] = _cs_utc_now()
        current_vote["closed"]    = True
        current_vote["closed_at"] = _cs_utc_now()
        current_vote["winner_submission_id"] = fake_id

    data["history"].append({
        "closed_at":   _cs_utc_now(),
        "winner_name": match["color_name"],
        "hex_code":    match.get("hex_code", ""),
        "image_url":   match.get("image_url", ""),
        "author_name": match.get("author_name", ""),
        "votes": {},
    })
    data["current_vote"] = None
    data["schedule"]["last_winner_post_date"] = datetime.now(COLOR_TZ).date().isoformat()
    _cs_save(data)

    await ctx.send(
        f"✅ **{match['color_name']}** declared as this week's crew color winner!",
        delete_after=15,
    )


@bot.command(name="pullgtacolors", aliases=["gtacolors", "autocolor", "pickcolors"])
async def _cmd_pull_gta_colors(ctx: commands.Context, count: int = 4):
    """Leadership only: preview 4 diverse colors from gtacolors.com, then confirm or reroll before posting."""
    if not isinstance(ctx.author, discord.Member) or not _cs_is_color_admin(ctx.author):
        await ctx.send("Leadership only.", delete_after=6)
        return
    count = max(1, min(count, 8))
    try:
        await ctx.message.delete()
    except Exception:
        pass

    thinking = await ctx.send("🎨 Fetching colors from gtacolors.com…")

    all_colors = await _cs_fetch_gta_color_pool()
    if not all_colors:
        await thinking.edit(content="❌ Could not reach gtacolors.com — try again in a moment.")
        return

    data = _cs_load()
    used_hexes = {s.get("hex_code", "").upper().lstrip("#") for s in data["submissions"].values()}
    pool = [c for c in all_colors if c.get("image_url") and c.get("hex", "").upper().lstrip("#") not in used_hexes]
    if len(pool) < count:
        pool = [c for c in all_colors if c.get("image_url")]
    if len(pool) < count:
        await thinking.edit(content="❌ Not enough colors available from gtacolors.com.")
        return

    picks = _cs_diverse_picks(pool, count)
    embeds = _cs_build_preview_embeds(picks)
    view = GtaColorPreviewView(picks=picks, all_colors=all_colors, invoker_id=ctx.author.id, guild=ctx.guild)
    await thinking.edit(
        content="🎨 **Preview — confirm to post the vote, or reroll for different colors:**",
        embeds=embeds,
        view=view,
    )


@bot.command(name="colorhistory", aliases=["colorwins", "pastcolors"])
async def _cmd_color_history(ctx: commands.Context):
    """Show the last 10 crew color winners."""
    if not isinstance(ctx.author, discord.Member) or not _cs_is_color_admin(ctx.author):
        await ctx.send("Leadership only.", delete_after=6)
        return
    try:
        await ctx.message.delete()
    except Exception:
        pass

    data = _cs_load()
    history = data.get("history", [])
    if not history:
        await ctx.send("No color vote history yet.", delete_after=10)
        return

    recent = list(reversed(history))[:10]
    embed = discord.Embed(
        title="🎨 Crew Color History",
        description=f"Last {len(recent)} winning colors",
        color=0x2F3136,
        timestamp=datetime.now(_EST_TZ),
    )
    for i, entry in enumerate(recent, 1):
        hex_code = entry.get("hex_code", "")
        author = entry.get("author_name", "")
        closed = entry.get("closed_at", "")
        date_str = ""
        if closed:
            try:
                date_str = datetime.fromisoformat(closed).astimezone(_EST_TZ).strftime("%b %d, %Y")
            except Exception:
                pass
        value_parts = []
        if hex_code:
            value_parts.append(f"`{hex_code}`")
        if author:
            value_parts.append(f"by {author}")
        if date_str:
            value_parts.append(date_str)
        embed.add_field(
            name=f"{i}. {entry.get('winner_name', 'Unknown')}",
            value=" • ".join(value_parts) if value_parts else "—",
            inline=False,
        )
    embed.set_footer(text="Different Meets • Crew Color System")
    await ctx.send(embed=embed)


