def _esc(text: str) -> str:
    return str(text).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")


def _md(text: str, mention_map: dict | None = None) -> str:
    import re
    t = _esc(text)
    t = re.sub(r"```(?:\w+)?\n?([\s\S]*?)```", lambda m: f"<pre><code>{m.group(1)}</code></pre>", t)
    t = re.sub(r"`([^`]+)`", r"<code>\1</code>", t)
    t = re.sub(r"\*\*\*(.+?)\*\*\*", r"<strong><em>\1</em></strong>", t)
    t = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", t)
    t = re.sub(r"\*(.+?)\*", r"<em>\1</em>", t)
    t = re.sub(r"__(.+?)__", r"<u>\1</u>", t)
    t = re.sub(r"~~(.+?)~~", r"<s>\1</s>", t)
    def _resolve_user(m):
        uid = int(m.group(1))
        name = (mention_map or {}).get(uid) or str(uid)
        return f'<span class="mention">@{_esc(name)}</span>'
    t = re.sub(r"&lt;@!?(\d+)&gt;", _resolve_user, t)
    t = re.sub(r"&lt;#(\d+)&gt;", r'<span class="mention">#\1</span>', t)
    t = re.sub(r"&lt;@&amp;(\d+)&gt;", r'<span class="mention">@role</span>', t)
    t = t.replace("\n", "<br>")
    return t


def _size_label(b: int) -> str:
    if b >= 1_048_576:
        return f"{b/1_048_576:.1f} MB"
    return f"{b/1024:.0f} KB"


def _color_css(c) -> str:
    if c is None or c == discord.Colour.default():
        return "#5865f2"
    return f"#{c.value:06x}"


def _render_embed(emb: discord.Embed, mention_map: dict | None = None) -> str:
    color = _color_css(emb.colour)
    parts = [f'<div class="embed" style="border-color:{color}">']
    if emb.author and emb.author.name:
        icon = f'<img src="{_esc(emb.author.icon_url)}" onerror="this.style.display=\'none\'">' if emb.author.icon_url else ""
        parts.append(f'<div class="embed-author">{icon}{_esc(emb.author.name)}</div>')
    if emb.thumbnail and emb.thumbnail.url:
        parts.append(f'<div class="embed-thumbnail"><img src="{_esc(emb.thumbnail.url)}" onerror="this.style.display=\'none\'"></div>')
    if emb.title:
        url_open = f'<a href="{_esc(emb.url)}" target="_blank" style="text-decoration:none">' if emb.url else ""
        url_close = "</a>" if emb.url else ""
        parts.append(f'<div class="embed-title">{url_open}{_esc(emb.title)}{url_close}</div>')
    if emb.description:
        parts.append(f'<div class="embed-description">{_md(emb.description, mention_map)}</div>')
    if emb.fields:
        parts.append('<div class="embed-fields">')
        for field in emb.fields:
            cls = "embed-field inline" if field.inline else "embed-field"
            parts.append(f'<div class="{cls}"><div class="embed-field-name">{_esc(field.name)}</div>'
                         f'<div class="embed-field-value">{_md(field.value, mention_map)}</div></div>')
        parts.append("</div>")
    if emb.image and emb.image.url:
        parts.append(f'<img src="{_esc(emb.image.url)}" style="max-width:400px;max-height:300px;border-radius:4px;margin-top:8px;display:block" onerror="this.style.display=\'none\'">')
    if emb.footer and emb.footer.text:
        ficon = f'<img src="{_esc(emb.footer.icon_url)}" style="width:16px;height:16px;border-radius:50%" onerror="this.style.display=\'none\'">' if emb.footer.icon_url else ""
        parts.append(f'<div class="embed-footer">{ficon}{_esc(emb.footer.text)}</div>')
    parts.append("</div>")
    return "".join(parts)


def _avatar_html(author) -> str:
    url = getattr(author, "display_avatar", None)
    if url:
        return f'<img src="{_esc(url.url)}" onerror="this.src=\'\';" alt="">'
    letter = (author.display_name or str(author) or "?")[0].upper()
    return f'<div class="avatar-fallback">{letter}</div>'


def _author_class(author) -> str:
    if getattr(author, "bot", False):
        return "bot"
    if isinstance(author, discord.Member):
        staff_ids = {850391095845584937, 850391378559238235, 990011447193006101, 1055823929358430248}
        if any(r.id in staff_ids for r in author.roles):
            return "staff"
    return "normal"


# Image/video extension fallback for transcript attachment rendering.
# Discord sometimes returns att.content_type as None (especially when messages
# are re-fetched from history), which caused photos to render as generic file
# icons in saved transcripts.  Filename-extension check is a reliable fallback.
_IMG_EXTS = (".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".heic", ".heif", ".avif", ".tif", ".tiff")
_VID_EXTS = (".mp4", ".mov", ".webm", ".mkv", ".avi", ".m4v")

def _att_is_image(att) -> bool:
    ct = (getattr(att, "content_type", None) or "").lower()
    if ct.startswith("image/"):
        return True
    fn = (getattr(att, "filename", "") or "").lower()
    return fn.endswith(_IMG_EXTS)

def _att_is_video(att) -> bool:
    ct = (getattr(att, "content_type", None) or "").lower()
    if ct.startswith("video/"):
        return True
    fn = (getattr(att, "filename", "") or "").lower()
    return fn.endswith(_VID_EXTS)


async def _att_to_data_uri(att, *, max_bytes: int = 2 * 1024 * 1024) -> str | None:
    """Download an image attachment and return a self-contained data: URI so
    saved transcripts survive Discord CDN URL expiry and source-channel
    deletion (join tickets are removed right after accept/deny).  Returns
    None on failure or if the file exceeds max_bytes."""
    try:
        if att.size and att.size > max_bytes:
            return None
        if aiohttp is None:
            return None
        timeout = aiohttp.ClientTimeout(total=15)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.get(att.url) as resp:
                if resp.status != 200:
                    return None
                data = await resp.read()
        if len(data) > max_bytes:
            return None
        ct = (getattr(att, "content_type", None) or "").lower()
        if not ct.startswith("image/"):
            fn = (getattr(att, "filename", "") or "").lower()
            if   fn.endswith(".png"):                ct = "image/png"
            elif fn.endswith(".gif"):                ct = "image/gif"
            elif fn.endswith(".webp"):               ct = "image/webp"
            elif fn.endswith((".heic", ".heif")):    ct = "image/heic"
            elif fn.endswith(".avif"):               ct = "image/avif"
            else:                                    ct = "image/jpeg"
        import base64 as _b64
        return f"data:{ct};base64," + _b64.b64encode(data).decode("ascii")
    except Exception as _e:
        print(f"[Transcript] image fetch failed for {getattr(att, 'filename', '?')}: {_e}")
        return None


async def _prepare_image_cache(
    msgs,
    *,
    total_budget: int = 18 * 1024 * 1024,
    per_image:    int = 2  * 1024 * 1024,
) -> dict:
    """Pre-fetch every image attachment in parallel and return
    {att.id: data_uri} for those that fit budget."""
    img_atts = [att for msg in msgs for att in msg.attachments if _att_is_image(att)]
    if not img_atts:
        return {}
    results = await asyncio.gather(
        *[_att_to_data_uri(a, max_bytes=per_image) for a in img_atts],
        return_exceptions=True,
    )
    cache: dict = {}
    total = 0
    for att, res in zip(img_atts, results):
        if isinstance(res, Exception) or not res:
            continue
        if total + len(res) > total_budget:
            continue
        cache[att.id] = res
        total += len(res)
    print(f"[Transcript] inlined {len(cache)}/{len(img_atts)} images "
          f"({total/1024/1024:.1f} MB) into transcript")
    return cache


