def _faq_load_entries() -> "list":
    """Load FAQ entries from disk; fall back to hardcoded defaults if file is missing/broken.
    Returns a list of (title, emoji, body) tuples."""
    try:
        with open(_FAQ_FILE, "r") as _f:
            _raw = json.load(_f)
        _out: "list" = []
        for _e in _raw:
            if isinstance(_e, dict) and "title" in _e and "body" in _e:
                _out.append((str(_e["title"]), str(_e.get("emoji", "❓")), str(_e["body"])))
            elif isinstance(_e, (list, tuple)) and len(_e) >= 3:
                _out.append((str(_e[0]), str(_e[1]), str(_e[2])))
        if _out:
            return _out
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        pass
    return list(_FAQ_DEFAULTS)

def _faq_save_entries(entries: "list") -> None:
    try:
        _atomic_json_save(_FAQ_FILE, [
            {"title": t, "emoji": e, "body": b} for (t, e, b) in entries
        ])
    except Exception:
        pass

_FAQ_DEFLECT_ENTRIES: "list" = _faq_load_entries()


class _FaqDeflectAnswerButton(discord.ui.Button):
    def __init__(self, index: int, title: str, emoji: str):
        super().__init__(label=title[:75], emoji=emoji,
                         style=discord.ButtonStyle.secondary, row=index // 3)
        self._idx = index

    async def callback(self, interaction: discord.Interaction):
        if self._idx < 0 or self._idx >= len(_FAQ_DEFLECT_ENTRIES):
            return await interaction.response.send_message("FAQ not found.", ephemeral=True)
        _title, _emoji, _body = _FAQ_DEFLECT_ENTRIES[self._idx]
        _embed = discord.Embed(
            title=f"{_emoji} {_title}",
            description=_body,
            color=discord.Color.blurple(),
        )
        _embed.set_footer(text="Different Meets • FAQ — if this didn't help, click 'Open Ticket Anyway'.")
        await interaction.response.send_message(embed=_embed, ephemeral=True)


class _FaqDeflectOpenTicketButton(discord.ui.Button):
    def __init__(self):
        super().__init__(label="Open Ticket Anyway", emoji="🎫",
                         style=discord.ButtonStyle.primary, row=2)

    async def callback(self, interaction: discord.Interaction):
        # AI-first: if OpenAI is available, ask the user to describe their question
        # in a modal so we can attempt an instant answer before creating a ticket.
        # Falls back silently to the plain ticket open if AI is disabled.
        try:
            if _ai_enabled():
                return await interaction.response.send_modal(_AiAskQuestionModal())
        except Exception:
            pass
        await _supp_open_ticket_flow(interaction, "support")


class _FaqDeflectAppealButton(discord.ui.Button):
    def __init__(self):
        super().__init__(label="Open Warning Appeal", emoji="⚖️",
                         style=discord.ButtonStyle.danger, row=2)

    async def callback(self, interaction: discord.Interaction):
        _ticket = _TICKET_TYPES.get("warning")
        if not _ticket or not interaction.guild or not isinstance(interaction.user, discord.Member):
            return await interaction.response.send_message(
                "Use the **Appeals** dropdown on the support panel to file a warning appeal.",
                ephemeral=True,
            )
        try:
            await interaction.response.defer(ephemeral=True)
        except discord.NotFound:
            return

        # Same cooldown check as AppealDropdown (don't allow bypass via this button)
        _remaining_cd = _appeal_denial_check(interaction.user.id, "warning")
        if _remaining_cd is not None:
            _days_left = int(_remaining_cd.total_seconds() // 86400) + 1
            return await interaction.followup.send(
                f"⏳ Your **{_ticket.label}** was recently denied.\n"
                f"You may resubmit in **{_days_left} day(s)**.\n"
                "If you believe this is a mistake, contact a DIFF leader directly.",
                ephemeral=True,
            )

        _existing = await _supp_find_any_open_ticket(interaction.guild, interaction.user, appeal_only=True)
        if _existing:
            return await interaction.followup.send(
                f"You already have an open appeal: {_existing.mention}", ephemeral=True
            )
        _channel = await _supp_create_ticket_channel(interaction, _ticket)
        if not _channel:
            return
        _ping = " ".join(filter(None, [interaction.user.mention, _supp_role_mention(_ticket.ping_role_id)]))
        await _channel.send(content=_ping or None,
                            embed=_supp_build_ticket_embed(_ticket, interaction.user),
                            view=SupportCloseButton())
        try:
            await _channel.send(embed=_supp_build_member_context_embed(interaction.user))
        except Exception:
            pass
        try:
            await _channel.send(embed=_supp_build_appeal_review_embed(_ticket, interaction.user),
                                view=_AppealActionView())
        except Exception:
            pass

        # Log to staff-logs (parity with AppealDropdown)
        _logs_ch = interaction.guild.get_channel(STAFF_LOGS_CHANNEL_ID)
        if isinstance(_logs_ch, discord.TextChannel):
            try:
                await _logs_ch.send(embed=_supp_build_log_embed("Opened", interaction.user, _ticket, _channel))
            except discord.HTTPException:
                pass

        # Mod-hub alert (parity with AppealDropdown)
        _mod_hub = interaction.guild.get_channel(MOD_HUB_CHANNEL_ID)
        if isinstance(_mod_hub, discord.TextChannel):
            try:
                _leader_mention = f"<@&{LEADER_ROLE_ID}>"
                _alert = discord.Embed(
                    title=f"⚖️ New {_ticket.label} Submitted",
                    description=(
                        f"{interaction.user.mention} has opened a **{_ticket.label}**.\n\n"
                        f"Review it here: {_channel.mention}"
                    ),
                    color=_TICKET_COLORS.get(_ticket.key, discord.Color.orange()),
                    timestamp=datetime.now(_EST_TZ),
                )
                _alert.add_field(name="👤 Member", value=f"{interaction.user.mention} (`{interaction.user.id}`)", inline=True)
                _alert.add_field(name="📋 Type", value=_ticket.label, inline=True)
                _alert.set_footer(text="Different Meets • Appeal System")
                await _mod_hub.send(content=_leader_mention, embed=_alert)
            except Exception:
                pass

        await interaction.followup.send(f"⚖️ Warning appeal opened: {_channel.mention}", ephemeral=True)


class _FaqDeflectView(discord.ui.View):
    def __init__(self, *, show_appeal_suggestion: bool = False):
        super().__init__(timeout=180)
        for _i, (_title, _emoji, _body) in enumerate(_FAQ_DEFLECT_ENTRIES[:6]):
            self.add_item(_FaqDeflectAnswerButton(_i, _title, _emoji))
        if show_appeal_suggestion:
            self.add_item(_FaqDeflectAppealButton())
        self.add_item(_FaqDeflectOpenTicketButton())


