# ── !staffload command ──────────────────────────────────────────────────────
@bot.command(name="staffload")
async def _staffload_cmd(ctx: commands.Context) -> None:
    """Show open-ticket workload + lifetime avg close time per staff member."""
    if not isinstance(ctx.author, discord.Member):
        return
    if not any(r.id in _LEADERSHIP_HOST_ROLE_IDS for r in ctx.author.roles):
        return await ctx.reply("This command is staff-only.", mention_author=False)
    guild = ctx.guild
    if guild is None:
        return
    loads = _ti_staff_open_loads(guild)
    tp = _tperf_load()
    rows: list[tuple] = []
    seen: set = set()
    role_ids = {TICKET_SUPPORT_ROLE_ID, LEADER_ROLE_ID, CO_LEADER_ROLE_ID, MANAGER_ROLE_ID}
    role_ids = {r for r in role_ids if r}
    for m in guild.members:
        if m.bot:
            continue
        if not any(r.id in role_ids for r in m.roles):
            continue
        sid = m.id
        seen.add(sid)
        s = tp.get(str(sid), {})
        closed = int(s.get("closed", 0))
        total_s = int(s.get("total_seconds", 0))
        avg_m = (total_s / closed / 60) if closed else None
        rows.append((loads.get(sid, 0), -closed, m.display_name, sid, closed, avg_m))
    # also include staff in tperf who lost the role
    for sid_s, s in tp.items():
        if not sid_s.isdigit():
            continue
        sid = int(sid_s)
        if sid in seen:
            continue
        closed = int(s.get("closed", 0))
        total_s = int(s.get("total_seconds", 0))
        avg_m = (total_s / closed / 60) if closed else None
        rows.append((loads.get(sid, 0), -closed, f"<@{sid}>", sid, closed, avg_m))
    rows.sort(reverse=True)
    if not rows:
        return await ctx.reply("No staff data available.", mention_author=False)
    lines = []
    for open_n, _neg_closed, name, sid, closed, avg_m in rows[:25]:
        avg_str = f"{avg_m:.0f}m" if avg_m else "—"
        lines.append(f"• **{name}** — `{open_n}` open · `{closed}` closed lifetime · avg `{avg_str}`")
    total_open = sum(r[0] for r in rows)
    emb = discord.Embed(
        title="🧑‍✈️ Staff Ticket Load",
        description=f"**{total_open}** ticket(s) currently claimed across **{len([r for r in rows if r[0] > 0])}** staff.\n\n" + "\n".join(lines),
        color=discord.Color.blurple(),
        timestamp=datetime.now(timezone.utc),
    )
    emb.set_footer(text="Different Meets • Ticket Workload")
    await ctx.reply(embed=emb, mention_author=False, allowed_mentions=discord.AllowedMentions.none())



async def __ticket_daily_digest_logic():
    now_est = datetime.now(_EST_TZ)
    if now_est.hour != 9:
        return
    now_ts = now_est.timestamp()
    last_ts = _digest_load_ts()
    if now_ts - last_ts < 12 * 3600:  # already ran this morning
        return

    guild = bot.get_guild(GUILD_ID)
    if not guild:
        return
    logs = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
    if not isinstance(logs, discord.TextChannel):
        return

    open_tickets: list[dict] = []
    for ch in guild.text_channels:
        topic = ch.topic or ""
        if "ticket_owner=" not in topic or "ticket_type=" not in topic:
            continue
        owner_id_s = _supp_parse_topic(topic, "ticket_owner") or "?"
        ticket_key = _supp_parse_topic(topic, "ticket_type") or "?"
        claimer_id = _supp_parse_topic(topic, "ticket_claimed_by")
        ticket_obj = _TICKET_TYPES.get(ticket_key)
        label = ticket_obj.label if ticket_obj else ticket_key
        emoji = ticket_obj.emoji if ticket_obj else "🎫"
        try:
            age_hrs = (datetime.now(timezone.utc) - ch.created_at).total_seconds() / 3600
        except Exception:
            age_hrs = 0.0
        last_active_hrs: "float | None" = None
        try:
            async for m in ch.history(limit=1):
                _dt = m.created_at
                if _dt.tzinfo is None:
                    _dt = _dt.replace(tzinfo=timezone.utc)
                last_active_hrs = (datetime.now(timezone.utc) - _dt).total_seconds() / 3600
        except Exception:
            pass
        open_tickets.append({
            "ch": ch,
            "owner_id": owner_id_s,
            "label": label,
            "emoji": emoji,
            "claimed": bool(claimer_id),
            "claimer_id": claimer_id,
            "age_hrs": age_hrs,
            "last_active_hrs": last_active_hrs,
        })

    open_tickets.sort(key=lambda t: t["age_hrs"], reverse=True)
    unclaimed = [t for t in open_tickets if not t["claimed"]]
    claimed = [t for t in open_tickets if t["claimed"]]

    embed = discord.Embed(
        title="📊 Daily Ticket Digest",
        description=(
            f"**{len(open_tickets)}** open ticket(s) — "
            f"**{len(unclaimed)}** unclaimed, **{len(claimed)}** claimed."
            if open_tickets else "🎉 No open tickets right now."
        ),
        color=discord.Color.gold(),
        timestamp=datetime.now(timezone.utc),
    )

    def _fmt(t: dict) -> str:
        age_str = f"{t['age_hrs']:.0f}h old"
        if t["last_active_hrs"] is not None:
            age_str += f", last reply {t['last_active_hrs']:.0f}h ago"
        claim_str = f" • claimed by <@{t['claimer_id']}>" if t["claimed"] else " • **unclaimed**"
        return f"{t['emoji']} {t['ch'].mention} <@{t['owner_id']}> — {age_str}{claim_str}"

    if unclaimed:
        embed.add_field(
            name=f"🕳️ Unclaimed ({len(unclaimed)})",
            value="\n".join(_fmt(t) for t in unclaimed[:10]) or "*None*",
            inline=False,
        )
    if claimed:
        embed.add_field(
            name=f"🙋 Claimed ({len(claimed)})",
            value="\n".join(_fmt(t) for t in claimed[:10]) or "*None*",
            inline=False,
        )

    stale = [t for t in open_tickets if (t["last_active_hrs"] or 0) >= 24]
    if stale:
        def _stale_fmt(t):
            who = f" — claimed by <@{t['claimer_id']}>" if t.get("claimed") and t.get("claimer_id") else " — **unclaimed**"
            return f"{t['ch'].mention} ({t['last_active_hrs']:.0f}h){who}"
        embed.add_field(
            name=f"⏰ Stale (24h+ silent) — {len(stale)}",
            value="\n".join(_stale_fmt(t) for t in stale[:8]),
            inline=False,
        )

    embed.set_footer(text="Different Meets • Daily Ticket Digest • 9 AM EST")

    try:
        await logs.send(
            embed=embed,
            allowed_mentions=discord.AllowedMentions.none(),
        )
        _digest_save_ts(now_ts)
    except Exception:
        pass

@tasks.loop(minutes=15)
async def _ticket_daily_digest_loop() -> None:
    _loop_success('_ticket_daily_digest_loop')
    try:
        await run_with_timeout('_ticket_daily_digest_loop', __ticket_daily_digest_logic(), timeout=120)
    except Exception as _lte:
        await _handle_loop_error('_ticket_daily_digest_loop', _lte, _ticket_daily_digest_loop)

@_ticket_daily_digest_loop.error
async def __ticket_daily_digest_on_error(error: Exception) -> None:
    await _handle_loop_error('_ticket_daily_digest_loop', error, _ticket_daily_digest_loop)

@_ticket_daily_digest_loop.before_loop
async def _before_ticket_daily_digest():
    await bot.wait_until_ready()


# ── Ticket stats command ──────────────────────────────────────────────────────

@bot.command(name="ticketstats")
async def _ticket_stats_cmd(ctx: commands.Context) -> None:
    """Show a count of all currently open tickets by type."""
    if not isinstance(ctx.author, discord.Member):
        return
    is_staff = any(r.id in _LEADERSHIP_HOST_ROLE_IDS for r in ctx.author.roles)
    if not is_staff:
        return
    try:
        await ctx.message.delete()
    except Exception:
        pass

    guild = ctx.guild
    if not guild:
        return

    counts: dict[str, int] = {k: 0 for k in _TICKET_TYPES}
    total = 0
    for channel in guild.text_channels:
        topic = channel.topic or ""
        if "ticket_owner=" not in topic or "ticket_type=" not in topic:
            continue
        for key in _TICKET_TYPES:
            if f"ticket_type={key}" in topic:
                counts[key] += 1
                total += 1
                break

    from datetime import timezone as _tz
    embed = discord.Embed(
        title="📊 DIFF Open Ticket Stats",
        color=discord.Color.blurple(),
        timestamp=datetime.now(_EST_TZ),
    )

    support_lines = []
    appeal_lines = []
    for key, count in counts.items():
        if count == 0:
            continue
        t = _TICKET_TYPES[key]
        line = f"{t.emoji} **{t.label}** — `{count}`"
        if key in _APPEAL_TYPE_KEYS:
            appeal_lines.append(line)
        else:
            support_lines.append(line)

    embed.add_field(
        name="📋 Support Tickets",
        value="\n".join(support_lines) or "*None open*",
        inline=False,
    )
    embed.add_field(
        name="⚖️ Appeal Tickets",
        value="\n".join(appeal_lines) or "*None open*",
        inline=False,
    )
    embed.add_field(name="🔢 Total Open", value=f"`{total}`", inline=True)

    # ── SLA / staff performance block ────────────────────────────────────────
    try:
        _perf = _tperf_load()
        _staff_rows: list = []
        _total_claimed = 0
        _total_closed = 0
        _total_seconds = 0.0
        for _sid, _payload in _perf.items():
            _c = int(_payload.get("claimed", 0) or 0)
            _x = int(_payload.get("closed", 0) or 0)
            _ts = float(_payload.get("total_seconds", 0) or 0)
            if _x <= 0 and _c <= 0:
                continue
            _avg = (_ts / _x) if _x > 0 else 0.0
            _staff_rows.append((_sid, _c, _x, _avg))
            _total_claimed += _c
            _total_closed += _x
            _total_seconds += _ts
        if _staff_rows:
            _global_avg = (_total_seconds / _total_closed) if _total_closed > 0 else 0.0
            def _fmt_dur(_s: float) -> str:
                if _s <= 0:
                    return "—"
                _h = _s / 3600
                if _h >= 1:
                    return f"{_h:.1f}h"
                _m = _s / 60
                return f"{_m:.0f}m"
            embed.add_field(
                name="⏱️ SLA Snapshot",
                value=(
                    f"All-time claims: **{_total_claimed}** · closes: **{_total_closed}**\n"
                    f"Avg claim→close: **{_fmt_dur(_global_avg)}**"
                ),
                inline=False,
            )
            _staff_rows.sort(key=lambda r: r[2], reverse=True)
            _top = _staff_rows[:5]
            _staff_lines = [
                f"<@{_sid}> — claimed {_c}, closed {_x} · avg {_fmt_dur(_avg)}"
                for _sid, _c, _x, _avg in _top
            ]
            embed.add_field(
                name=f"🏆 Top Staff (by closes) — {len(_top)}",
                value="\n".join(_staff_lines) or "*No data yet*",
                inline=False,
            )
    except Exception:
        pass

    embed.set_footer(text="Different Meets • Support System")
    if DIFF_LOGO_URL:
        embed.set_thumbnail(url=DIFF_LOGO_URL)

    await ctx.send(embed=embed, delete_after=120, allowed_mentions=discord.AllowedMentions.none())


# ── Canned replies (staff prefix) ────────────────────────────────────────────
_CANNED_REPLIES_FILE = os.path.join(DATA_FOLDER, "diff_canned_replies.json")

def _canned_load() -> dict:
    try:
        with open(_CANNED_REPLIES_FILE, "r") as _f:
            return json.load(_f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def _canned_save(_d: dict) -> None:
    try:
        _atomic_json_save(_CANNED_REPLIES_FILE, _d)
    except Exception:
        pass

_CANNED_DEFAULTS = {
    "verify":   "👋 To get verified, post your PSN ID in the verification channel and follow the prompts. Staff will review within a few hours.",
    "rules":    "📜 Full rules are pinned in the rules channel. Quick highlights: PS5 only, no overpowered builds at chill meets, always read the meet description.",
    "appeal":   "⚖️ Warnings can be appealed via the **⚖️ Appeals** dropdown in the support channel. Be honest, give context, and don't argue the original reason.",
    "schedule": "📅 Meets are announced weekly in the announcements / host-call-out channels. Check pinned messages there for the current week's schedule.",
    "patience": "🙏 Thanks for your patience — a staff member will respond as soon as possible. If this is urgent, use the 🚨 Urgent button on the support panel.",
}

def _canned_is_staff(member: "discord.Member") -> bool:
    return any(r.id in _LEADERSHIP_HOST_ROLE_IDS for r in member.roles)

@bot.command(name="canned", aliases=("c", "reply"))
async def _canned_send_cmd(ctx: commands.Context, key: "str | None" = None) -> None:
    """Send a canned reply by key. Usage: !canned <key>"""
    if not isinstance(ctx.author, discord.Member) or not _canned_is_staff(ctx.author):
        return
    try:
        await ctx.message.delete()
    except Exception:
        pass
    _data = _canned_load() or dict(_CANNED_DEFAULTS)
    if not key:
        return await ctx.send(
            f"Usage: `!canned <key>` — try `!cannedlist` to see all keys.",
            delete_after=15,
        )
    _txt = _data.get(key.lower())
    if not _txt:
        return await ctx.send(
            f"No canned reply for `{key}`. Use `!cannedlist` to see available keys, or `!cannedadd {key} <text>` to add one.",
            delete_after=15,
        )
    await ctx.send(_txt, allowed_mentions=discord.AllowedMentions.none())

@bot.command(name="cannedlist", aliases=("clist",))
async def _canned_list_cmd(ctx: commands.Context) -> None:
    """List all canned reply keys."""
    if not isinstance(ctx.author, discord.Member) or not _canned_is_staff(ctx.author):
        return
    try:
        await ctx.message.delete()
    except Exception:
        pass
    _data = _canned_load() or dict(_CANNED_DEFAULTS)
    if not _data:
        return await ctx.send("No canned replies defined yet.", delete_after=30)
    _lines = []
    for _k in sorted(_data.keys()):
        _preview = (_data[_k] or "")[:80].replace("\n", " ")
        _lines.append(f"• **{_k}** — {_preview}{'…' if len(_data[_k]) > 80 else ''}")
    embed = discord.Embed(
        title="💬 Canned Replies",
        description="\n".join(_lines),
        color=discord.Color.blurple(),
        timestamp=datetime.now(timezone.utc),
    )
    embed.set_footer(text="Use `!canned <key>` to send · `!cannedadd <key> <text>` to add")
    await ctx.send(embed=embed, delete_after=120)

@bot.command(name="cannedadd", aliases=("caddreply", "addcanned"))
async def _canned_add_cmd(ctx: commands.Context, key: "str | None" = None, *, text: "str | None" = None) -> None:
    """Add or overwrite a canned reply. Usage: !cannedadd <key> <text>"""
    if not isinstance(ctx.author, discord.Member) or not _canned_is_staff(ctx.author):
        return
    try:
        await ctx.message.delete()
    except Exception:
        pass
    if not key or not text:
        return await ctx.send("Usage: `!cannedadd <key> <text>`", delete_after=15)
    if len(text) > 1900:
        return await ctx.send("Reply text must be 1900 characters or fewer.", delete_after=15)
    _data = _canned_load() or dict(_CANNED_DEFAULTS)
    _data[key.lower()] = text
    _canned_save(_data)
    await ctx.send(f"✅ Canned reply `{key.lower()}` saved.", delete_after=15)

@bot.command(name="canneddel", aliases=("cdelreply", "removecanned"))
async def _canned_del_cmd(ctx: commands.Context, key: "str | None" = None) -> None:
    """Delete a canned reply by key."""
    if not isinstance(ctx.author, discord.Member) or not _canned_is_staff(ctx.author):
        return
    try:
        await ctx.message.delete()
    except Exception:
        pass
    if not key:
        return await ctx.send("Usage: `!canneddel <key>`", delete_after=15)
    _data = _canned_load() or dict(_CANNED_DEFAULTS)
    if key.lower() not in _data:
        return await ctx.send(f"No canned reply for `{key}`.", delete_after=15)
    del _data[key.lower()]
    _canned_save(_data)
    await ctx.send(f"🗑️ Canned reply `{key.lower()}` removed.", delete_after=15)


