# =========================
# DIFF AUTO TRACKING — WEEKLY REPORT SYSTEM
# =========================

_AUTO_STATS_FILE = "diff_data/diff_auto_staff_stats.json"
_AUTO_CACHE_FILE = "diff_data/diff_ticket_activity_cache.json"
_AUTO_WEEKLY_WEEKDAY = 0      # Monday
_AUTO_WEEKLY_HOUR_UTC = 16    # 12 PM ET / 16 UTC
_AUTO_WEEKLY_MINUTE_UTC = 0
_AUTO_MIN_MSG_TO_COUNT = 1
_last_weekly_reset_ts: float = 0.0   # prevents double-fire after Pi restart


class _AutoStatsStore:
    def __init__(self, file_path: str) -> None:
        from pathlib import Path as _Path
        self.path = _Path(file_path)
        self.data = self._load()

    def _default(self) -> dict:
        from datetime import timezone as _tz
        return {"users": {}, "weekly_history": [], "last_reset": datetime.now(_EST_TZ).isoformat()}

    def _load(self) -> dict:
        if not self.path.exists():
            d = self._default()
            self.path.write_text(json.dumps(d, indent=2), encoding="utf-8")
            return d
        try:
            return json.loads(self.path.read_text(encoding="utf-8"))
        except Exception:
            d = self._default()
            self.path.write_text(json.dumps(d, indent=2), encoding="utf-8")
            return d

    def save(self) -> None:
        self.path.write_text(json.dumps(self.data, indent=2), encoding="utf-8")

    def ensure_user(self, user_id: int) -> dict:
        from datetime import timezone as _tz
        key = str(user_id)
        if key not in self.data["users"]:
            self.data["users"][key] = {
                "tickets_handled": 0,
                "applications_reviewed": 0,
                "meets_hosted": 0,
                "reports_resolved": 0,
                "appeals_reviewed": 0,
                "accepted_apps": 0,
                "denied_apps": 0,
                "messages_in_tickets": 0,
                "last_updated": datetime.now(_EST_TZ).isoformat(),
            }
        return self.data["users"][key]

    def add_stat(self, user_id: int, field: str, amount: int = 1) -> dict:
        from datetime import timezone as _tz
        user = self.ensure_user(user_id)
        user[field] = int(user.get(field, 0)) + amount
        user["last_updated"] = datetime.now(_EST_TZ).isoformat()
        self.save()
        return user

    def leaderboard(self) -> list[tuple[int, dict]]:
        rows = [(int(uid), s) for uid, s in self.data["users"].items()]
        rows.sort(key=lambda x: _auto_score(x[1]), reverse=True)
        return rows

    def archive_and_reset(self) -> None:
        from datetime import timezone as _tz
        snapshot = {"ended_at": datetime.now(_EST_TZ).isoformat(), "leaderboard": self.leaderboard()[:10]}
        self.data["weekly_history"].append(snapshot)
        self.data["users"] = {}
        self.data["last_reset"] = datetime.now(_EST_TZ).isoformat()
        self.save()


class _TicketActivityStore:
    def __init__(self, file_path: str) -> None:
        from pathlib import Path as _Path
        self.path = _Path(file_path)
        self.data = self._load()

    def _default(self) -> dict:
        return {"tickets": {}}

    def _load(self) -> dict:
        if not self.path.exists():
            d = self._default()
            self.path.write_text(json.dumps(d, indent=2), encoding="utf-8")
            return d
        try:
            return json.loads(self.path.read_text(encoding="utf-8"))
        except Exception:
            d = self._default()
            self.path.write_text(json.dumps(d, indent=2), encoding="utf-8")
            return d

    def save(self) -> None:
        self.path.write_text(json.dumps(self.data, indent=2), encoding="utf-8")

    def add_staff_message(self, channel_id: int, channel_name: str, ticket_type: str, owner_id: str | None, user_id: int) -> None:
        from datetime import timezone as _tz
        key = str(channel_id)
        if key not in self.data["tickets"]:
            self.data["tickets"][key] = {
                "channel_name": channel_name,
                "ticket_type": ticket_type,
                "owner_id": owner_id,
                "staff_messages": {},
                "created_at": datetime.now(_EST_TZ).isoformat(),
                "last_seen_at": datetime.now(_EST_TZ).isoformat(),
            }
        ticket = self.data["tickets"][key]
        uid = str(user_id)
        ticket["staff_messages"][uid] = int(ticket["staff_messages"].get(uid, 0)) + 1
        ticket["last_seen_at"] = datetime.now(_EST_TZ).isoformat()
        self.save()

    def pop_ticket(self, channel_id: int) -> dict | None:
        key = str(channel_id)
        ticket = self.data["tickets"].pop(key, None)
        if ticket is not None:
            self.save()
        return ticket


_auto_stats = _AutoStatsStore(_AUTO_STATS_FILE)
_ticket_cache = _TicketActivityStore(_AUTO_CACHE_FILE)


def _auto_score(stats: dict) -> int:
    return (
        stats.get("tickets_handled", 0) * 2
        + stats.get("applications_reviewed", 0) * 3
        + stats.get("meets_hosted", 0) * 2
        + stats.get("reports_resolved", 0) * 2
        + stats.get("appeals_reviewed", 0) * 2
        + stats.get("accepted_apps", 0) * 1
    )


def _auto_is_ticket_channel(channel: discord.TextChannel) -> bool:
    return bool(channel.topic and "ticket_owner=" in channel.topic and "ticket_type=" in channel.topic)


def _auto_build_weekly_embed(guild: discord.Guild, rows: list[tuple[int, dict]]) -> discord.Embed:
    from datetime import timezone as _tz
    embed = discord.Embed(
        title="🏆 Weekly DIFF Staff Report",
        description="Automatic weekly recap for DIFF staff performance.",
        color=discord.Color.gold(),
        timestamp=datetime.now(_EST_TZ),
    )
    if not rows:
        embed.add_field(name="No Activity Logged", value="No staff activity was recorded this week.", inline=False)
    else:
        lines: list[str] = []
        for idx, (uid, stats) in enumerate(rows[:10], 1):
            m = guild.get_member(uid)
            display = m.mention if m else f"<@{uid}>"
            lines.append(
                f"**#{idx}** {display}\n"
                f"Score: **{_auto_score(stats)}** | "
                f"Tickets: **{stats.get('tickets_handled', 0)}** | "
                f"Apps: **{stats.get('applications_reviewed', 0)}** | "
                f"Meets: **{stats.get('meets_hosted', 0)}**"
            )
        embed.add_field(name="Leaderboard", value="\n\n".join(lines), inline=False)
        top_uid, top_stats = rows[0]
        top_m = guild.get_member(top_uid)
        top_display = top_m.mention if top_m else f"<@{top_uid}>"
        embed.add_field(
            name="🔥 Top Performer of the Week",
            value=(
                f"{top_display}\n"
                f"Score: **{_auto_score(top_stats)}**\n"
                f"Tickets Handled: **{top_stats.get('tickets_handled', 0)}**\n"
                f"Applications Reviewed: **{top_stats.get('applications_reviewed', 0)}**\n"
                f"Meets Hosted: **{top_stats.get('meets_hosted', 0)}**"
            ),
            inline=False,
        )
    if DIFF_LOGO_URL:
        embed.set_thumbnail(url=DIFF_LOGO_URL)
    if DIFF_BANNER_URL:
        embed.set_image(url=DIFF_BANNER_URL)
    embed.set_footer(text="Different Meets • Automated Tracking")
    return embed


async def _auto_check_promotion(guild: discord.Guild, member: discord.Member) -> None:
    from datetime import timezone as _tz
    stats = _auto_stats.ensure_user(member.id)
    score = _auto_score(stats)
    meets = (
        stats.get("tickets_handled", 0) >= _PROMOTION_THRESHOLDS["tickets_handled"]
        or stats.get("applications_reviewed", 0) >= _PROMOTION_THRESHOLDS["applications_reviewed"]
        or stats.get("meets_hosted", 0) >= _PROMOTION_THRESHOLDS["meets_hosted"]
        or score >= _PROMOTION_THRESHOLDS["score"]
    )
    if not meets:
        return
    next_role_id = _staff_next_promo_role(member)
    if not next_role_id:
        return
    next_role = guild.get_role(next_role_id)
    if not next_role:
        return
    log_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
    if not isinstance(log_ch, discord.TextChannel):
        return
    now = datetime.now(_EST_TZ)
    embed = discord.Embed(
        title="📈 Promotion Suggestion (Auto)",
        description=(
            f"User: {member.mention}\n"
            f"Suggested Next Role: {next_role.mention}\n\n"
            "This staff member reached the automated promotion review threshold."
        ),
        color=discord.Color.green(),
        timestamp=now,
    )
    embed.add_field(name="Tickets Handled", value=str(stats.get("tickets_handled", 0)), inline=True)
    embed.add_field(name="Apps Reviewed", value=str(stats.get("applications_reviewed", 0)), inline=True)
    embed.add_field(name="Meets Hosted", value=str(stats.get("meets_hosted", 0)), inline=True)
    embed.add_field(name="Activity Score", value=str(score), inline=True)
    if DIFF_LOGO_URL:
        embed.set_thumbnail(url=DIFF_LOGO_URL)
    embed.set_footer(text="Different Meets • Automated Tracking")
    try:
        await log_ch.send(embed=embed)
    except discord.HTTPException:
        pass


async def _auto_finalize_ticket(guild: discord.Guild, channel_id: int) -> None:
    from datetime import timezone as _tz
    ticket = _ticket_cache.pop_ticket(channel_id)
    if not ticket:
        return
    ticket_type = ticket.get("ticket_type", "support")
    staff_messages: dict = ticket.get("staff_messages", {})
    awarded: list[tuple[discord.Member, int]] = []

    for uid_str, count in staff_messages.items():
        if int(count) < _AUTO_MIN_MSG_TO_COUNT:
            continue
        m = guild.get_member(int(uid_str))
        if not m:
            continue
        _auto_stats.add_stat(int(uid_str), "messages_in_tickets", int(count))
        _auto_stats.add_stat(int(uid_str), "tickets_handled", 1)
        if ticket_type == "report":
            _auto_stats.add_stat(int(uid_str), "reports_resolved", 1)
        elif ticket_type == "appeal":
            _auto_stats.add_stat(int(uid_str), "appeals_reviewed", 1)
        awarded.append((m, int(count)))
        await _auto_check_promotion(guild, m)

    if awarded:
        now = datetime.now(_EST_TZ)
        lines = [f"{m.mention} — {cnt} message(s)" for m, cnt in awarded]
        embed = discord.Embed(
            title="🎫 Ticket Auto Tracking Complete",
            description=(
                f"Ticket: `{ticket.get('channel_name', 'unknown')}`\n"
                f"Type: **{ticket_type}**\n"
                "Tracked Staff:\n" + "\n".join(lines)
            ),
            color=discord.Color.blurple(),
            timestamp=now,
        )
        if DIFF_LOGO_URL:
            embed.set_thumbnail(url=DIFF_LOGO_URL)
        embed.set_footer(text="Different Meets • Automated Tracking")
        log_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
        if isinstance(log_ch, discord.TextChannel):
            try:
                await log_ch.send(embed=embed)
            except discord.HTTPException:
                pass


def _auto_seconds_until_weekly() -> float:
    from datetime import timezone as _tz, timedelta as _td
    now = datetime.now(_EST_TZ)
    target = now.replace(hour=_AUTO_WEEKLY_HOUR_UTC, minute=_AUTO_WEEKLY_MINUTE_UTC, second=0, microsecond=0)
    days_ahead = (_AUTO_WEEKLY_WEEKDAY - now.weekday()) % 7
    if days_ahead == 0 and target <= now:
        days_ahead = 7
    target = target + _td(days=days_ahead)
    return max((target - now).total_seconds(), 30.0)


async def _auto_weekly_loop() -> None:
    global _last_weekly_reset_ts
    from datetime import timezone as _tz
    await bot.wait_until_ready()
    while not bot.is_closed():
        await asyncio.sleep(_auto_seconds_until_weekly())
        # Dedup guard — skip if we already ran within the last 6 hours.
        # Prevents a double-fire when the Pi restarts near the scheduled time.
        import time as _time
        now_mono = _time.monotonic()
        if now_mono - _last_weekly_reset_ts < 6 * 3600:
            continue
        _last_weekly_reset_ts = now_mono
        guild = bot.get_guild(GUILD_ID)
        if guild is None:
            continue
        report_channel = guild.get_channel(LEADERBOARD_CHANNEL_ID)
        rows = _auto_stats.leaderboard()
        if isinstance(report_channel, discord.TextChannel):
            try:
                await _upsert_unified_leaderboard(guild)
            except Exception:
                pass
            try:
                hub_embed = _build_crew_hub_embed()
                state = _load_diff_json(CREW_HUB_STATE_FILE) or {}
                msg_id = state.get("message_id")
                ch_id = state.get("channel_id")
                if msg_id and ch_id:
                    ch = guild.get_channel(ch_id)
                    if isinstance(ch, discord.TextChannel):
                        try:
                            existing = await ch.fetch_message(msg_id)
                            await existing.edit(embed=hub_embed, view=CrewHubView())
                        except discord.NotFound:
                            pass
            except Exception:
                pass
        for entry in _rsvp_leaderboard.values():
            entry["last_attendance_count"] = int(entry.get("attendance_count", 0))
        _rsvp_save_all()

        _auto_stats.archive_and_reset()
        now = datetime.now(_EST_TZ)
        log_ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
        if isinstance(log_ch, discord.TextChannel):
            try:
                reset_embed = discord.Embed(
                    title="🔄 Weekly Staff Stats Reset",
                    description=f"Weekly report posted and stats reset at <t:{int(now.timestamp())}:F>",
                    color=discord.Color.orange(),
                    timestamp=now,
                )
                reset_embed.set_footer(text="Different Meets • Automated Tracking")
                await log_ch.send(embed=reset_embed)
            except discord.HTTPException:
                pass


@bot.event
async def on_member_update(before: discord.Member, after: discord.Member):
    before_ids = {r.id for r in before.roles}
    after_ids = {r.id for r in after.roles}
    if HOST_ROLE_ID not in before_ids and HOST_ROLE_ID in after_ids:
        if _hauto_db.is_blacklisted(after.guild.id, after.id):
            host_role = after.guild.get_role(HOST_ROLE_ID)
            if host_role:
                try:
                    await after.remove_roles(host_role, reason="Blacklisted user cannot hold the host role")
                except Exception:
                    return
                entry = _hauto_db.get_active_entry(after.guild.id, after.id)
                embed = discord.Embed(
                    title="⛔ Host Role Auto-Removed",
                    description="A blacklisted user was automatically prevented from holding the host role.",
                    color=discord.Color.red(),
                    timestamp=datetime.now(timezone.utc),
                )
                embed.add_field(name="User", value=after.mention, inline=False)
                if entry:
                    embed.add_field(name="Blacklist Entry", value=f"#{entry['id']}", inline=True)
                    embed.add_field(name="Severity", value=entry["severity"], inline=True)
                log_ch = after.guild.get_channel(STAFF_LOGS_CHANNEL_ID)
                if isinstance(log_ch, discord.TextChannel):
                    try:
                        await log_ch.send(embed=embed)
                    except Exception:
                        pass


@bot.event
async def on_command_error(ctx: commands.Context, error: commands.CommandError) -> None:
    """Global prefix-command error handler."""
    if isinstance(error, commands.CommandNotFound):
        return
    if isinstance(error, commands.CheckFailure):
        return
    if isinstance(error, commands.CommandOnCooldown):
        mins, secs = divmod(int(error.retry_after), 60)
        wait = f"{mins}m {secs}s" if mins else f"{secs}s"
        return await ctx.send(f"⏳ Slow down! You can use this again in **{wait}**.", delete_after=10)
    if isinstance(error, commands.MissingPermissions):
        return await ctx.send("❌ You don't have permission to use that command.", delete_after=8)
    if isinstance(error, commands.MissingRequiredArgument):
        return await ctx.send(
            f"❌ Missing argument: `{error.param.name}`. Check `!help {ctx.command}` for usage.",
            delete_after=12,
        )
    if isinstance(error, commands.BadArgument):
        return await ctx.send("❌ Invalid argument. Check `!help` for correct usage.", delete_after=10)
    if isinstance(error, commands.BotMissingPermissions):
        return await ctx.send(
            f"❌ I'm missing permissions to do that: `{', '.join(error.missing_permissions)}`",
            delete_after=10,
        )
    import traceback as _tb
    tb_str = "".join(_tb.format_exception(type(error), error, error.__traceback__))
    try:
        _bot_log.error("[CommandError] %s: %s", ctx.message.content[:300], tb_str)
    except Exception:
        pass
    # Everything below is best-effort logging — must never raise (a DMChannel has no
    # .mention, which previously bubbled up as an unhandled on_command_error event).
    try:
        log_ch = bot.get_channel(1485265848099799163)
        if isinstance(log_ch, discord.TextChannel):
            ch_val = getattr(ctx.channel, "mention", None) or f"`{ctx.channel}`"
            embed = discord.Embed(
                title="⚠️ Unhandled Command Error",
                color=discord.Color.red(),
                timestamp=discord.utils.utcnow(),
            )
            embed.add_field(name="Command", value=f"`{ctx.message.content[:300]}`", inline=False)
            embed.add_field(name="User",    value=f"{ctx.author} (`{ctx.author.id}`)", inline=True)
            embed.add_field(name="Channel", value=ch_val, inline=True)
            embed.add_field(name="Error",   value=f"```{str(error)[:900]}```",         inline=False)
            embed.set_footer(text="DIFF Meets • Error Logger")
            await log_ch.send(embed=embed)
    except Exception:
        pass


async def _update_join_ticket_complete(channel: discord.TextChannel) -> None:
    """Edit the pinned ticket embed to show all steps complete when photos reach the minimum."""
    try:
        async for msg in channel.history(oldest_first=True, limit=8):
            if msg.author.id != bot.user.id or not msg.embeds:
                continue
            emb = msg.embeds[0]
            if not emb.title or "PlayStation Join Application" not in emb.title:
                continue
            updated = discord.Embed(
                title=emb.title,
                description=emb.description,
                color=discord.Color.green(),
                timestamp=emb.timestamp,
            )
            a = emb.author
            if a.name:
                updated.set_author(name=a.name, icon_url=a.icon_url)
            if emb.thumbnail.url:
                updated.set_thumbnail(url=emb.thumbnail.url)
            for f in emb.fields:
                if "Steps to Complete" in (f.name or ""):
                    updated.add_field(
                        name=f.name,
                        value=(
                            f"✅ PSN submitted\n"
                            f"✅ **{MIN_GARAGE_PHOTOS}/{MIN_GARAGE_PHOTOS} photos received**\n"
                            f"⏳ Staff review & decision — *staff have been notified*"
                        ),
                        inline=f.inline,
                    )
                else:
                    updated.add_field(
                        name=f.name or "\u200b",
                        value=f.value or "\u200b",
                        inline=f.inline,
                    )
            ft = emb.footer
            if ft.text:
                updated.set_footer(text=ft.text, icon_url=ft.icon_url)
            await msg.edit(embed=updated)
            # Record timestamp when photos became complete (used by auto-bump)
            try:
                _pc_extra = _join_extra_load()
                _pc_entry = _pc_extra.setdefault(str(channel.id), {})
                if not _pc_entry.get("photos_complete_at"):
                    _pc_entry["photos_complete_at"] = datetime.now(timezone.utc).isoformat()
                    _join_extra_save(_pc_extra)
            except Exception:
                pass
            return
    except Exception:
        pass


# ===================== AI Moderation Assist (Phase 3c) =====================
# Advisory ONLY — never deletes, warns, or punishes. Two entry points:
#  (1) automatic cheap pre-filter on messages → spends an AI call only on
#      suspicious text (gated by per-user cooldown + global hourly cap) → posts
#      a flag embed to staff for human review. OFF by default (staff opt-in).
#  (2) on-demand !modcheck for staff to get an AI risk read on any message/text.
# All silent-fallback: if AI is off/unparseable, nothing happens.
_AIMOD_STATE_FILE         = "diff_data/diff_aimod_state.json"
_AIMOD_MIN_LEN            = 8
_AIMOD_USER_COOLDOWN_S    = 120     # min gap between AI mod calls per user
_AIMOD_GLOBAL_HOURLY_CAP  = 40      # hard ceiling on auto AI mod calls per rolling hour
_AIMOD_MAX_MENTIONS       = 6       # mass-mention heuristic

_AIMOD_LINK_RE   = re.compile(r"(discord\.gg/|https?://)", re.I)
_AIMOD_SCAM_TERMS = (
    "free nitro", "nitro gift", "steam gift", "free robux", "airdrop",
    "claim your", "crypto giveaway", "free giveaway", "click here", "onlyfans",
    "@everyone", "@here",
)
# High-signal hate tokens (non-exhaustive — the AI makes the real judgment;
# this only decides whether to SPEND an AI call).
_AIMOD_HATE_TERMS = ("faggot", "nigger", "n1gger", "retard", "kys", "kill yourself", "tranny")

_aimod_user_cd: dict[int, float] = {}
_aimod_call_times: list[float] = []
_aimod_state_cache: "dict|None" = None   # in-memory cache — message hot-path must never touch disk


def _aimod_load(force: bool = False) -> dict:
    """Cached read. The per-message scan path consults this, so disk is only hit
    once (or on explicit force) — never on every message."""
    global _aimod_state_cache
    if _aimod_state_cache is not None and not force:
        return _aimod_state_cache
    d = {}
    if os.path.exists(_AIMOD_STATE_FILE):
        try:
            with open(_AIMOD_STATE_FILE, "r", encoding="utf-8") as f:
                d = json.load(f) or {}
        except Exception:
            d = {}
    d.setdefault("enabled", False)
    d.setdefault("channel_id", None)
    _aimod_state_cache = d
    return d


def _aimod_save(d: dict) -> None:
    global _aimod_state_cache
    d.setdefault("enabled", False)
    d.setdefault("channel_id", None)
    _aimod_state_cache = d
    os.makedirs("diff_data", exist_ok=True)
    _atomic_json_save(_AIMOD_STATE_FILE, d)


try:
    _aimod_load()  # warm the cache at import so the message hot-path never reads disk
except Exception:
    pass


def _aimod_enabled() -> bool:
    return bool(_aimod_load().get("enabled"))


def _aimod_flag_channel(guild):
    cid = _aimod_load().get("channel_id")
    if cid:
        try:
            ch = guild.get_channel(int(cid))
            if isinstance(ch, discord.TextChannel):
                return ch
        except (ValueError, TypeError):
            pass
    ch = guild.get_channel(STAFF_LOGS_CHANNEL_ID)
    return ch if isinstance(ch, discord.TextChannel) else None


def _aimod_is_staff(member) -> bool:
    try:
        if _xp_is_leadership(member):
            return True
        rids = {r.id for r in getattr(member, "roles", [])}
        return bool(rids & _ALL_MOD_ROLE_IDS)
    except Exception:
        return False


def _aimod_prefilter(text: str, mention_ct: int) -> "str|None":
    """Cheap, AI-free triage. Returns a reason tag if the message warrants an AI
    call, else None. Keeps cost near-zero on normal chatter."""
    if not text or len(text) < _AIMOD_MIN_LEN:
        return None
    low = text.lower()
    for w in _AIMOD_HATE_TERMS:
        if w in low:
            return "possible_hate"
    if _AIMOD_LINK_RE.search(text) and any(t in low for t in _AIMOD_SCAM_TERMS):
        return "possible_scam"
    if "@everyone" in low or "@here" in low:
        return "mass_mention"
    if mention_ct >= _AIMOD_MAX_MENTIONS:
        return "mass_mention"
    return None


def _aimod_allow_call(user_id: int) -> bool:
    """Per-user cooldown + global rolling-hour cap so auto-scanning can't run up
    cost. Records the call only when it is actually allowed."""
    now = time.monotonic()
    if now - _aimod_user_cd.get(user_id, 0) < _AIMOD_USER_COOLDOWN_S:
        return False
    wall = time.time()
    cutoff = wall - 3600
    _aimod_call_times[:] = [t for t in _aimod_call_times if t > cutoff]
    if len(_aimod_call_times) >= _AIMOD_GLOBAL_HOURLY_CAP:
        return False
    _aimod_user_cd[user_id] = now
    _aimod_call_times.append(wall)
    return True


async def _aimod_assess(text: str) -> "dict|None":
    """AI risk read. Returns {flag, category, severity, reason} or None on failure."""
    if not _ai_enabled():
        return None
    sys = (
        f"You are a conservative content-moderation assistant for DIFF Meets.\n{_AI_BASE_CTX}\n\n"
        "Assess ONLY the user message for genuine rule violations: hate speech / slurs / "
        "harassment, scams or phishing, NSFW content, threats or self-harm, or spam/advertising. "
        "Casual banter, ordinary profanity used non-abusively, and car/GTA trash-talk are NOT "
        "violations. You ADVISE staff only and never take action. When unsure, do not flag. "
        "Reply ONLY with JSON: {\"flag\": bool, \"category\": string, "
        "\"severity\": \"low\"|\"medium\"|\"high\", \"reason\": string}."
    )
    raw = await _ai_chat(sys, text, json_mode=True, max_tokens=160)
    if not raw:
        return None
    try:
        d = json.loads(raw)
    except Exception:
        return None
    sev = str(d.get("severity") or "low").lower()
    if sev not in ("low", "medium", "high"):
        sev = "low"
    return {
        "flag": _ai_parse_bool(d.get("flag", False), default=False),
        "category": str(d.get("category") or "unknown")[:40],
        "severity": sev,
        "reason": str(d.get("reason") or "")[:600],
    }


_AIMOD_SEV_COLOR = {"low": 0xF1C40F, "medium": 0xE67E22, "high": 0xE74C3C}


def _aimod_build_embed(message, reason, verdict, *, on_demand=False):
    sev = verdict.get("severity", "low")
    e = discord.Embed(
        title=("🔎 Mod Check" if on_demand else "🚨 AI Mod Flag"),
        description=verdict.get("reason") or "(no reason given)",
        color=_AIMOD_SEV_COLOR.get(sev, 0xF1C40F),
        timestamp=datetime.now(_EST_TZ),
    )
    try:
        e.add_field(name="Member", value=f"{message.author.mention} (`{message.author.id}`)", inline=True)
    except Exception:
        pass
    e.add_field(name="Category", value=verdict.get("category", "unknown"), inline=True)
    e.add_field(name="Severity", value=sev.capitalize(), inline=True)
    excerpt = (message.content or "")[:900] or "(no text)"
    e.add_field(name="Message", value=excerpt, inline=False)
    try:
        e.add_field(name="Jump", value=f"[Go to message]({message.jump_url})", inline=True)
    except Exception:
        pass
    e.add_field(name="Pre-filter", value=reason, inline=True)
    e.set_footer(text="Different Meets • AI Moderation (advisory only — review manually)")
    return e


async def _aimod_scan_message(message) -> None:
    """Automatic path: cheap pre-filter → gated AI call → staff flag. Never acts."""
    try:
        if not _aimod_enabled() or not _ai_enabled():
            return
        if not message.guild or message.author.bot:
            return
        if isinstance(message.author, discord.Member) and _aimod_is_staff(message.author):
            return
        content = message.content or ""
        if content.startswith("!"):
            return
        mention_ct = len(getattr(message, "mentions", []) or [])
        if "@everyone" in content or "@here" in content:
            mention_ct += 1
        reason = _aimod_prefilter(content, mention_ct)
        if not reason:
            return
        if not _aimod_allow_call(message.author.id):
            return
        verdict = await _aimod_assess(content)
        if not verdict or not verdict.get("flag"):
            return
        ch = _aimod_flag_channel(message.guild)
        if ch is None:
            return
        await ch.send(embed=_aimod_build_embed(message, reason, verdict))
    except Exception as _e:
        print(f"[aimod] scan error: {_e!r}")


@bot.command(name="aimod")
@commands.guild_only()
async def cmd_aimod(ctx, action: str = None, channel: discord.TextChannel = None):
    """Leadership: !aimod (status) • !aimod on/off • !aimod channel #ch."""
    if not _xp_is_leadership(ctx.author):
        return await ctx.reply("Leadership only.", mention_author=False)
    state = _aimod_load()
    act = (action or "").lower()
    if act in ("on", "enable", "start"):
        state["enabled"] = True
        _aimod_save(state)
        return await ctx.reply(
            "✅ AI moderation auto-scan **ON**. Suspicious messages will be flagged to "
            f"{(_aimod_flag_channel(ctx.guild).mention if _aimod_flag_channel(ctx.guild) else 'staff logs')} "
            "for review (never auto-actioned).", mention_author=False,
        )
    if act in ("off", "disable", "stop"):
        state["enabled"] = False
        _aimod_save(state)
        return await ctx.reply("🛑 AI moderation auto-scan **OFF**. `!modcheck` still works on demand.", mention_author=False)
    if act in ("channel", "setchannel") and channel is not None:
        state["channel_id"] = channel.id
        _aimod_save(state)
        return await ctx.reply(f"✅ AI mod flags will post to {channel.mention}.", mention_author=False)
    cur = _aimod_flag_channel(ctx.guild)
    wall = time.time()
    used = len([t for t in _aimod_call_times if t > wall - 3600])
    await ctx.reply(
        "**AI Moderation Assist**\n"
        f"• Auto-scan: {'🟢 ON' if state.get('enabled') else '🔴 OFF'}\n"
        f"• Flag channel: {cur.mention if cur else 'staff logs (default)'}\n"
        f"• AI available: {'yes' if _ai_enabled() else 'no (OPENAI_API_KEY missing)'}\n"
        f"• Auto calls this hour: {used}/{_AIMOD_GLOBAL_HOURLY_CAP}\n"
        "Usage: `!aimod on` · `!aimod off` · `!aimod channel #ch` · `!modcheck` (reply to a message).",
        mention_author=False,
    )


@bot.command(name="modcheck", aliases=["aicheck"])
@commands.guild_only()
async def cmd_modcheck(ctx, *, text: str = None):
    """Staff: AI risk read on a message. Reply to a message, or pass text inline."""
    if not _aimod_is_staff(ctx.author):
        return await ctx.reply("Staff only.", mention_author=False)
    if not _ai_enabled():
        return await ctx.reply("AI is not configured (OPENAI_API_KEY missing).", mention_author=False)
    target = ctx.message
    content = text
    ref = getattr(ctx.message, "reference", None)
    if ref is not None and getattr(ref, "message_id", None):
        try:
            target = await ctx.channel.fetch_message(ref.message_id)
            content = target.content or text
        except Exception:
            target = ctx.message
    if not content:
        return await ctx.reply(
            "Reply to a message with `!modcheck`, or `!modcheck <text to assess>`.",
            mention_author=False,
        )
    async with ctx.typing():
        verdict = await _aimod_assess(content)
    if not verdict:
        return await ctx.reply("Couldn't get an AI read (try again shortly).", mention_author=False)
    if not verdict.get("flag"):
        return await ctx.reply(
            f"✅ No clear violation detected (AI category: {verdict.get('category', 'n/a')}).",
            mention_author=False,
        )
    await ctx.reply(embed=_aimod_build_embed(target, "on_demand", verdict, on_demand=True), mention_author=False)


@bot.event
async def on_message(message: discord.Message) -> None:
    await bot.process_commands(message)

    if not message.guild or message.author.bot:
        return
    if not isinstance(message.author, discord.Member):
        return
    if not isinstance(message.channel, discord.TextChannel):
        return

    # Track last message timestamp for inactivity system
    try:
        _activity_upsert(message.author.id, last_message=time.time())
    except Exception:
        pass

    # --- XP: message activity (cooldown-gated, skips commands) ---
    try:
        if not message.content.startswith("!"):
            _xnow = time.monotonic()
            if _xnow - _xp_msg_cooldowns.get(message.author.id, 0) >= _XP_MSG_COOLDOWN_SECS:
                _xp_msg_cooldowns[message.author.id] = _xnow
                await _xp_apply_award(message.guild, message.author, _XP_PER_MESSAGE)
    except Exception:
        pass

    # --- AI moderation assist (cost-aware pre-filter → staff flag; never acts) ---
    try:
        asyncio.create_task(_aimod_scan_message(message))
    except Exception:
        pass

    # --- Lobby-pictures: full pipeline (match meet, OCR, watermark, gate) ---
    if message.channel.id == LOBBY_PICTURES_CHANNEL_ID:
        try:
            await _lp_handle_lobby_post(message)
        except Exception as _lp_err:
            print(f"[lobby-pics] handler error: {_lp_err!r}")
        return

    # --- Everyone-chat meet Q&A auto-responder ---
    if message.channel.id == EVERYONE_CHAT_CHANNEL_ID:
        import time as _time_mod
        content_lower = message.content.lower()
        if any(trigger in content_lower for trigger in _MEET_QA_TRIGGERS):
            uid = message.author.id
            now_ts = _time_mod.monotonic()
            last = _MEET_QA_COOLDOWNS.get(uid, 0)
            if now_ts - last >= _MEET_QA_COOLDOWN_SECS:
                _MEET_QA_COOLDOWNS[uid] = now_ts
                reply = (
                    f"{message.author.mention} Check the channels below for everything meet-related:\n\n"
                    f"📣 **Announcements** → <#{MEET_ANNOUNCEMENT_CHANNEL_ID}>\n"
                    f"📅 **Upcoming Meets** → <#{UPCOMING_MEET_CHANNEL_ID}>\n"
                    f"📘 **Meet Info & Rules** → <#{MEET_INFO_CHANNEL_ID}>\n"
                    f"🎮 **Live Meet Updates** → <#{MEET_FLOW_CHANNEL_ID}>"
                )
                try:
                    bot_reply = await message.reply(reply, mention_author=False)
                    await asyncio.sleep(45)
                    await bot_reply.delete()
                except Exception:
                    pass

    # --- Everyone-chat new-member confusion auto-responder ---
    if message.channel.id == EVERYONE_CHAT_CHANNEL_ID and not message.author.bot:
        import time as _time_mod2
        _content_lc = message.content.lower()
        if any(t in _content_lc for t in _NEWMEMBER_TRIGGERS):
            _uid2    = message.author.id
            _now2    = _time_mod2.monotonic()
            _last2   = _NEWMEMBER_COOLDOWNS.get(_uid2, 0)
            if _now2 - _last2 >= _NEWMEMBER_COOLDOWN_SECS:
                _NEWMEMBER_COOLDOWNS[_uid2] = _now2
                _nm_embed = discord.Embed(
                    title="👋 Quick Server Guide",
                    description=(
                        f"Hey {message.author.mention}! Here's everything you need to get started:"
                    ),
                    color=0x5865F2,
                )
                _nm_embed.add_field(
                    name="✅ Step 1 — Get Verified",
                    value=(
                        f"Go to <#{RULES_CHANNEL_ID}>, read the rules, and click the button "
                        "to unlock the server."
                    ),
                    inline=False,
                )
                _nm_embed.add_field(
                    name="🎮 Step 2 — Claim Your PS5 Role",
                    value=(
                        f"Head to <#{JOIN_MEETS_CHANNEL_ID}> to confirm your platform "
                        "and update your name — required before joining meets."
                    ),
                    inline=False,
                )
                _nm_embed.add_field(
                    name="📅 Step 3 — Find the Meets",
                    value=(
                        f"• <#{MEET_ANNOUNCEMENT_CHANNEL_ID}> — official announcements\n"
                        f"• <#{MEET_INFO_CHANNEL_ID}> — rules & info\n"
                        f"• <#{UPCOMING_MEET_CHANNEL_ID}> — upcoming meets\n"
                        f"• <#{DIFF_HOSTS_CHANNEL_ID}> — host schedule"
                    ),
                    inline=False,
                )
                _nm_embed.set_footer(text="This message auto-deletes in 60 seconds • Different Meets")
                try:
                    _nm_reply = await message.reply(embed=_nm_embed, mention_author=False)
                    await asyncio.sleep(60)
                    await _nm_reply.delete()
                except Exception:
                    pass

    # --- Host posters auto-embed + multi-action view + DM mirror ---
    if message.channel.id == _POSTMEET_HOST_POSTERS_ID:
        _pm_images = [
            a for a in message.attachments
            if (a.content_type and a.content_type.startswith("image/"))
            or any(a.filename.lower().endswith(ext) for ext in (".png", ".jpg", ".jpeg", ".gif", ".webp"))
        ]
        if _pm_images and not message.content.startswith("!"):
            _pm_caption = message.content.strip()
            _pm_parts   = [p.strip() for p in _pm_caption.split("|")] if _pm_caption else []
            _pm_date    = _pm_parts[0] if _pm_parts else ""
            _pm_time    = _pm_parts[1] if len(_pm_parts) > 1 else ""
            _pm_theme   = _pm_parts[2] if len(_pm_parts) > 2 else ""
            import re as _re_pm
            _pm_ts = None
            _m_ts_token = _re_pm.search(r"<t:(\d+)(?::[tTdDfFR])?>", _pm_caption)
            if _m_ts_token:
                try:
                    _pm_ts = int(_m_ts_token.group(1))
                except Exception:
                    _pm_ts = None
            elif _pm_date and _pm_time:
                _pm_date_clean = _re_pm.sub(r"(\d+)(st|nd|rd|th)\b", r"\1", _pm_date, flags=_re_pm.IGNORECASE)
                _pm_ts = _parse_meet_ts(_pm_date_clean, _pm_time)
            _pm_dt_value = (
                f"<t:{_pm_ts}:F>\n<t:{_pm_ts}:R>" if _pm_ts
                else (_pm_caption or "See poster")
            )

            # Assigned hosts = users mentioned in the original message;
            # if nobody was mentioned, fall back to the person who posted.
            _assigned_ids = [m.id for m in (message.mentions or []) if not m.bot]
            if not _assigned_ids:
                _assigned_ids = [message.author.id]

            _state = {
                "guild_id": message.guild.id if message.guild else GUILD_ID,
                "channel_id": message.channel.id,
                "host_msg_id": message.id,
                "poster_url": _pm_images[0].url,
                "poster_proxy_url": _pm_images[0].proxy_url,
                "raw_caption": _pm_caption,
                "theme": _pm_theme,
                "meet_ts": _pm_ts,
                "dt_value": _pm_dt_value,
                "assigned_host_ids": _assigned_ids,
                "poster_user_id": message.author.id,
                "responses": {},
                "reminded_t2h": False,
                "escalated_t30m": False,
                "dm_sent_to": [],
                "created_at": datetime.now(timezone.utc).isoformat(),
                "color": _POSTMEET_EMBED_COLOR,
            }
            try:
                _pm_reply = await message.reply(
                    embed=_hp_render_embed(_state),
                    view=_HostPosterActionsView(),
                    mention_author=False,
                )
                _state["bot_msg_id"] = _pm_reply.id
                _hp_put(_pm_reply.id, _state)
                # Fire-and-forget DM mirror to assigned hosts
                asyncio.create_task(_hp_dm_mirror(message.guild, _state, _pm_reply.jump_url))
            except Exception as _pm_err:
                print(f"[host-posters] reply error: {_pm_err}")
        return

    # --- Social feed auto-post (Instagram / TikTok / YouTube) ---
    if message.channel.id == _IG_CHANNEL_ID:
        _ig_m = _IG_LINK_RE.search(message.content)
        if _ig_m:
            await _social_handle_drop(message.channel, _ig_m.group(1), "instagram")
            return
        _tt_m = _TT_LINK_RE.search(message.content)
        if _tt_m:
            await _social_handle_drop(message.channel, _tt_m.group(1), "tiktok")
            return
        _yt_m = _YT_LINK_RE.search(message.content)
        if _yt_m:
            await _social_handle_drop(message.channel, _yt_m.group(1), "youtube")
            return
        return

    # --- Join channel photo progress tracking ---
    topic = message.channel.topic
    join_user_id = _join_parse_user_id(topic)
    if join_user_id and str(message.author.id) == join_user_id:
        # Track the last time the applicant sent any message (used by idle-ping logic)
        try:
            _am_extra = _join_extra_load()
            _am_entry = _am_extra.setdefault(str(message.channel.id), {})
            _am_entry["last_applicant_msg_at"] = datetime.now(timezone.utc).isoformat()
            _am_extra[str(message.channel.id)] = _am_entry
            _join_extra_save(_am_extra)
        except Exception:
            pass
        raw_images = [a for a in message.attachments if a.content_type and a.content_type.startswith("image/")]
        if raw_images:
            async with _join_photo_lock(message.channel.id):
                spam_ignored = max(0, len(raw_images) - 5)
                candidates = raw_images[:5]

                photo_hashes = _photo_hashes_load()
                user_hashes: list = photo_hashes.setdefault(join_user_id, [])
                accepted = 0
                dupes = 0
                for att in candidates:
                    h = _attachment_hash(att)
                    if h in user_hashes:
                        dupes += 1
                    else:
                        user_hashes.append(h)
                        accepted += 1
                _photo_hashes_save(photo_hashes)

                history = [m async for m in message.channel.history(limit=200)]
                total_images = sum(
                    len([a for a in m.attachments if a.content_type and a.content_type.startswith("image/")])
                    for m in history
                    if m.author.id == message.author.id
                )
                prev_total = total_images - len(raw_images)
                capped = min(total_images, MIN_GARAGE_PHOTOS)

                total_unique   = len(user_hashes)
                remaining      = max(0, MIN_GARAGE_PHOTOS - capped)
                complete       = capped >= MIN_GARAGE_PHOTOS
                progress_color = discord.Color.green() if complete else discord.Color.blue()

                bar = "🟦" * capped + "⬛" * remaining

                title = (
                    "📸 Photo Progress — ✅ Complete!"
                    if complete
                    else f"📸 Photo Progress — {capped}/{MIN_GARAGE_PHOTOS}"
                )
                desc_parts = [f"**{message.author.mention}** is submitting their garage photos."]
                if complete:
                    desc_parts.append("🎉 All required photos have been received!")

                progress_embed = discord.Embed(
                    title       = title,
                    description = "\n".join(desc_parts),
                    color       = progress_color,
                    timestamp   = utc_now(),
                )
                progress_embed.set_thumbnail(url=message.author.display_avatar.url)

                progress_embed.add_field(
                    name  = f"📊 {capped}/{MIN_GARAGE_PHOTOS} submitted",
                    value = bar,
                    inline=False,
                )

                if accepted:
                    progress_embed.add_field(name="✅ New This Batch",   value=str(accepted),     inline=True)
                if dupes:
                    progress_embed.add_field(name="🔁 Duplicates",       value=str(dupes),        inline=True)
                if spam_ignored:
                    progress_embed.add_field(name="⚠️ Over Limit",       value=str(spam_ignored), inline=True)

                if total_unique > accepted or total_images > len(raw_images):
                    progress_embed.add_field(name="📸 Total Unique",     value=str(total_unique), inline=True)

                if not complete:
                    progress_embed.add_field(name="📌 Still Needed",     value=f"{remaining} more photo{'s' if remaining != 1 else ''}", inline=True)

                progress_embed.set_footer(text="Different Meets • Photo Review System")

                prev_progress = next(
                    (m for m in history
                     if m.author.id == bot.user.id
                     and m.embeds
                     and "Photo Progress" in (m.embeds[0].title or "")),
                    None,
                )
                if prev_progress:
                    try:
                        await prev_progress.edit(embed=progress_embed)
                    except Exception:
                        await message.channel.send(embed=progress_embed)
                else:
                    await message.channel.send(embed=progress_embed)

                already_notified = any(
                    m.author.id == bot.user.id
                    and m.embeds
                    and m.embeds[0].title == "✅ Application Ready for Review"
                    for m in history
                )

                if not already_notified and prev_total < MIN_GARAGE_PHOTOS <= total_images:
                    ticket_support_role = message.guild.get_role(TICKET_SUPPORT_ROLE_ID)
                    mentions = ticket_support_role.mention if ticket_support_role else None

                    review_embed = discord.Embed(
                        title       = "✅ Application Ready for Review",
                        description = f"{message.author.mention} has submitted all **{MIN_GARAGE_PHOTOS}** required photos and is ready to be reviewed.",
                        color       = discord.Color.green(),
                        timestamp   = utc_now(),
                    )
                    review_embed.add_field(name="📸 Valid Photos",  value=f"{capped}/{MIN_GARAGE_PHOTOS}", inline=True)
                    review_embed.add_field(name="📋 Channel",       value=message.channel.mention,        inline=True)
                    # Auto pre-screen: cheap metadata-only quality stats so reviewers
                    # know upfront if photos are likely usable.
                    try:
                        _all_imgs = []
                        for _hm in history:
                            if _hm.author.id == message.author.id:
                                for _a in _hm.attachments:
                                    if _a.content_type and _a.content_type.startswith("image/"):
                                        _all_imgs.append(_a)
                        _sizes_kb = [int(getattr(a, "size", 0) or 0) // 1024 for a in _all_imgs]
                        _dims = [(getattr(a, "width", 0) or 0, getattr(a, "height", 0) or 0) for a in _all_imgs]
                        _tiny_kb   = sum(1 for s in _sizes_kb if 0 < s < 50)
                        _small_dim = sum(1 for w, h in _dims if w and h and (w < 400 or h < 400))
                        _avg_kb    = (sum(_sizes_kb) // len(_sizes_kb)) if _sizes_kb else 0
                        _quality_bits = [f"avg `{_avg_kb} KB`"]
                        if _tiny_kb:   _quality_bits.append(f"⚠️ {_tiny_kb} tiny file{'s' if _tiny_kb != 1 else ''}")
                        if _small_dim: _quality_bits.append(f"⚠️ {_small_dim} low-res")
                        if not _tiny_kb and not _small_dim:
                            _quality_bits.append("✅ no auto flags")
                        review_embed.add_field(
                            name="🔍 Auto Pre-Screen",
                            value=" · ".join(_quality_bits),
                            inline=False,
                        )
                    except Exception:
                        pass
                    review_embed.set_thumbnail(url=message.author.display_avatar.url)
                    review_embed.set_footer(text="Different Meets • Application System")
                    await message.channel.send(
                        content=mentions if mentions else None,
                        embed=review_embed,
                        allowed_mentions=discord.AllowedMentions(roles=True),
                    )
                    log_ch = message.guild.get_channel(STAFF_LOGS_CHANNEL_ID)
                    if isinstance(log_ch, discord.TextChannel):
                        try:
                            await log_ch.send(embed=discord.Embed(
                                title="✅ Application Ready For Review",
                                description="\n".join([
                                    f"**User:** <@{join_user_id}>",
                                    f"**Channel:** {message.channel.mention}",
                                    f"**Valid Photos:** {capped}/{MIN_GARAGE_PHOTOS}",
                                ]),
                                color=discord.Color.green(),
                                timestamp=utc_now(),
                            ))
                        except Exception:
                            pass
                    await _update_join_ticket_complete(message.channel)
        return

    # --- Staff ticket message tracking ---
    if not _auto_is_ticket_channel(message.channel):
        return
    if not is_staff_reviewer(message.author):
        return
    ticket_type = _supp_parse_topic(message.channel.topic, "ticket_type") or "support"
    owner_id = _supp_parse_topic(message.channel.topic, "ticket_owner")
    _ticket_cache.add_staff_message(
        channel_id=message.channel.id,
        channel_name=message.channel.name,
        ticket_type=ticket_type,
        owner_id=owner_id,
        user_id=message.author.id,
    )


@bot.event
async def on_guild_channel_delete(channel: discord.abc.GuildChannel) -> None:
    if not isinstance(channel, discord.TextChannel):
        return
    if channel.guild.id != GUILD_ID:
        return
    try:
        await _auto_finalize_ticket(channel.guild, channel.id)
    except Exception as _e:
        _bot_log.error("[ChannelDelete] _auto_finalize_ticket error: %s", _e, exc_info=True)


@bot.event
async def on_interaction(interaction: discord.Interaction) -> None:
    if not interaction.guild or not isinstance(interaction.user, discord.Member):
        return
    if interaction.guild.id != GUILD_ID:
        return
    if not interaction.data:
        return
    custom_id = interaction.data.get("custom_id")
    if not isinstance(custom_id, str):
        return
    if not isinstance(interaction.channel, discord.TextChannel):
        return
    if not _auto_is_ticket_channel(interaction.channel):
        return
    if not any(r.id in _LEADERSHIP_ROLE_IDS for r in interaction.user.roles) \
            and not interaction.user.guild_permissions.manage_guild:
        return
    lowered = custom_id.lower()
    if "accept" not in lowered and "deny" not in lowered:
        return
    _auto_stats.add_stat(interaction.user.id, "applications_reviewed", 1)
    if "accept" in lowered:
        _auto_stats.add_stat(interaction.user.id, "accepted_apps", 1)
        decision = "Approved"
    else:
        _auto_stats.add_stat(interaction.user.id, "denied_apps", 1)
        decision = "Denied"
    from datetime import timezone as _tz
    now = datetime.now(_EST_TZ)
    log_ch = interaction.guild.get_channel(STAFF_LOGS_CHANNEL_ID)
    if isinstance(log_ch, discord.TextChannel):
        embed = discord.Embed(
            title="🧾 Application Auto Tracking",
            description=(
                f"Reviewer: {interaction.user.mention}\n"
                f"Decision: **{decision}**\n"
                f"Channel: {interaction.channel.mention}\n"
                f"Time: <t:{int(now.timestamp())}:F>"
            ),
            color=discord.Color.green() if decision == "Approved" else discord.Color.red(),
            timestamp=now,
        )
        if DIFF_LOGO_URL:
            embed.set_thumbnail(url=DIFF_LOGO_URL)
        embed.set_footer(text="Different Meets • Automated Tracking")
        try:
            await log_ch.send(embed=embed)
        except discord.HTTPException:
            pass
    await _auto_check_promotion(interaction.guild, interaction.user)


@bot.event
async def on_voice_state_update(
    member: discord.Member,
    before: discord.VoiceState,
    after: discord.VoiceState,
) -> None:
    """Track last VC join for inactivity system."""
    if member.bot:
        return
    if after.channel and not before.channel:
        try:
            _activity_upsert(member.id, last_vc=time.time())
        except Exception:
            pass

    # Session VC real-time idle tracking — update immediately instead of waiting for the 5-min loop
    try:
        hp_data = _hp_load()
        _hp_changed = False
        _now_ts = datetime.now(timezone.utc).timestamp()
        for _sess in hp_data.get("active_sessions", {}).values():
            if _sess.get("ended"):
                continue
            _vc_id = _sess.get("voice_channel_id")
            if not _vc_id:
                continue
            if before.channel and before.channel.id == _vc_id:
                # Member just left this session VC
                _remaining = [m for m in before.channel.members if not m.bot]
                if len(_remaining) == 0 and _sess.get("vc_empty_since") is None:
                    _sess["vc_empty_since"] = _now_ts
                    _hp_changed = True
            if after.channel and after.channel.id == _vc_id:
                # Member just joined — reset idle timer
                if _sess.get("vc_empty_since") is not None or _sess.get("vc_idle_alert_sent"):
                    _sess["vc_empty_since"] = None
                    _sess["vc_idle_alert_sent"] = False
                    _hp_changed = True
        if _hp_changed:
            _hp_save(hp_data)
    except Exception:
        pass


