def _pp_build_log_embed(
    action: str,
    app: dict,
    reviewer: discord.Member | discord.User,
    reason: str | None = None,
) -> discord.Embed:
    icons  = {"accepted": "✅", "denied": "❌", "changes_requested": "🔄", "blacklisted": "🚫"}
