class _PartnerPanelView(discord.ui.View):
    """Persistent public partner panel — dropdown + Apply + Rules buttons."""
    def __init__(self, partners: list | None = None) -> None:
        super().__init__(timeout=None)
        if partners is None:
            partners = _pp_get_partners()
