_IG_LINK_RE = re.compile(
    r"(https?://(?:www\.)?(?:instagram\.com|instagr\.am)/[^\s]+)",
    re.IGNORECASE,
)
_TT_LINK_RE = re.compile(
    r"(https?://(?:www\.)?(?:tiktok\.com|vm\.tiktok\.com)/[^\s]+)",
    re.IGNORECASE,
)
_YT_LINK_RE = re.compile(
    r"(https?://(?:www\.)?(?:youtube\.com/(?:watch|shorts|live)|youtu\.be)/[^\s]+)",
    re.IGNORECASE,
)


def _ig_panel_load() -> dict:
    try:
        with open(_IG_PANEL_FILE) as f:
            return json.load(f)
    except Exception:
        return {}


def _ig_panel_save(data: dict):
    try:
        with open(_IG_PANEL_FILE, "w") as f:
            json.dump(data, f, indent=2)
    except Exception:
        pass


