    try:
        await run_with_timeout('_mgmt_alert_loop', __mgmt_alert_loop_logic(), timeout=180)
    except Exception as _lte:
        await _handle_loop_error('_mgmt_alert_loop', _lte, _mgmt_alert_loop)
